{
  "mcpServers": {
    "elevenlabs": {
      "description": "Official ElevenLabs MCP for text-to-speech, voice cloning, audio processing, and transcription. Generate AI voices, design custom voices, isolate audio, create sound effects, and more.",
      "command": "uvx",
      "args": ["elevenlabs-mcp@0.12.2"],
      "env": {
        "ELEVENLABS_API_KEY": "<your-api-key>",
        "ELEVENLABS_MCP_BASE_PATH": "~/Desktop",
        "ELEVENLABS_MCP_OUTPUT_MODE": "files"
      }
    }
  }
}

{
  "mcpServers": {
    "sync": {
      "description": "Official sync. labs MCP: lipsync a video to new audio or a typed script, translate and dub videos into other languages with matching lips, generate speech previews, clone voices, and manage assets and projects. Streamable HTTP, OAuth sign-in with a sync. account in the browser, no API key. Paid steps such as dubbing and voice clones are quoted before they start.",
      "type": "http",
      "url": "https://mcp.sync.so/mcp"
    }
  }
}

{
  "mcpServers": {
    "browser-server": {
      "description": "An MCP server that enables AI agents to control web browsers using browser-use.",
      "command": "browser-use-mcp-server",
      "args": [
        "run",
        "server",
        "--port",
        "8000",
        "--stdio",
        "--proxy-port",
        "9000"
      ],
      "env": {
        "OPENAI_API_KEY": "your-api-key"
      }
    }
  }
}

{
  "mcpServers": {
