/**
 * policy-ceiling: turn an organization's limits into ceilings and floors over
 * the merged settings. Pure functions of the layers and the merge, no `$`.
 */
import type { Row } from '../types'

export type { Row } from '../types'
export type Settings = Record<string, unknown>
export interface Layer { source: string; settings: Settings }

export const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'] as const
export type Effort = (typeof EFFORTS)[number]

export interface Rules {
  maxCleanupPeriodDays?: number
  deniedModels: readonly string[]
  fallbackModel?: string
  maxEffort?: Effort
  forbiddenModes: readonly string[]
  requireSandbox: boolean
}

export const PLUGIN = 'policy-ceiling'

function list(value: unknown): string[] {
  if (Array.isArray(value)) return value.filter((v): v is string => typeof v === 'string').map(s => s.trim()).filter(Boolean)
  if (typeof value === 'string') return value.split(',').map(s => s.trim()).filter(Boolean)
  return []
}

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

/**
 * The rules, read from the managed (`policy`) layer only: its
 * `pluginConfigs["policy-ceiling…"].options`. A person's own settings never
 * set or loosen them, whatever they put under pluginConfigs.
 */
export function rulesFrom(layers: readonly Layer[]): Rules | undefined {
  const policy = layers.find(l => l.source === 'policy')?.settings
  const configs = policy && isObject(policy.pluginConfigs) ? policy.pluginConfigs : undefined
  if (!configs) return undefined
  const key = Object.keys(configs).find(k => k === PLUGIN || k.startsWith(`${PLUGIN}@`))
  const entry = key ? configs[key] : undefined
  const o = isObject(entry) && isObject(entry.options) ? entry.options : undefined
  if (!o) return undefined
  const days = typeof o.maxCleanupPeriodDays === 'number' && o.maxCleanupPeriodDays > 0 ? o.maxCleanupPeriodDays : undefined
  const effort = typeof o.maxEffort === 'string' && (EFFORTS as readonly string[]).includes(o.maxEffort) ? (o.maxEffort as Effort) : undefined
  const rules: Rules = {
    maxCleanupPeriodDays: days,
    deniedModels: list(o.deniedModels),
    fallbackModel: typeof o.fallbackModel === 'string' && o.fallbackModel.trim() ? o.fallbackModel.trim() : undefined,
    maxEffort: effort,
    forbiddenModes: list(o.forbiddenModes),
    requireSandbox: o.requireSandbox === true,
  }
  // Options left at their defaults set no ceiling: report that, not an empty pane.
  const active = rules.maxCleanupPeriodDays !== undefined || rules.deniedModels.length > 0 || rules.maxEffort !== undefined
    || rules.forbiddenModes.length > 0 || rules.requireSandbox
  return active ? rules : undefined
}

const show = (v: unknown) => (v === undefined ? '—' : typeof v === 'string' ? v : JSON.stringify(v))

/** Any value above the ceiling, or one that is not a known level (`"MAX"`, `"ultra"`, a number), becomes the ceiling. */
function lowerEffort(value: unknown, max: Effort): unknown {
  const at = typeof value === 'string' ? EFFORTS.indexOf(value as Effort) : -1
  return at === -1 || at > EFFORTS.indexOf(max) ? max : value
}

/** Environment variables that pick a model behind `model`'s back. */
const MODEL_ENV = ['ANTHROPIC_MODEL', 'ANTHROPIC_DEFAULT_OPUS_MODEL', 'ANTHROPIC_DEFAULT_SONNET_MODEL', 'ANTHROPIC_DEFAULT_HAIKU_MODEL', 'ANTHROPIC_SMALL_FAST_MODEL', 'CLAUDE_CODE_SUBAGENT_MODEL']

/** A denied model matches by exact name, with a `[1m]`-style suffix, or with a date suffix (`claude-opus-4-8` denies `claude-opus-4-8-20260101`). */
export function isDenied(model: string, denied: readonly string[]): boolean {
  return denied.some(d => model === d || model.startsWith(`${d}[`) || model.startsWith(`${d}-20`))
}

/**
 * Applies the rules to the merged settings. Returns the new merge and one row
 * per rule for /policy. Never adds a key the rule does not name, never
 * loosens a value.
 */
export function apply(merged: Settings, rules: Rules): { settings: Settings; rows: Row[] } {
  const out: Settings = { ...merged }
  const rows: Row[] = []

  if (rules.maxCleanupPeriodDays !== undefined) {
    const asked = merged.cleanupPeriodDays
    const max = rules.maxCleanupPeriodDays
    // Absent means Claude Code's default (30 days); only a larger value or the default above max is clamped.
    const effective = typeof asked === 'number' ? asked : 30
    const clamped = effective > max
    if (clamped) out.cleanupPeriodDays = max
    rows.push({ setting: 'cleanupPeriodDays', requested: show(asked ?? '30 (default)'), limit: `≤ ${max}`, result: show(clamped ? max : effective), state: clamped ? 'clamped' : 'within' })
  }

  if (rules.deniedModels.length > 0) {
    const asked = merged.model
    const denied = typeof asked === 'string' && isDenied(asked, rules.deniedModels)
    // A fallback that is itself denied is no fallback.
    const fallback = rules.fallbackModel && !isDenied(rules.fallbackModel, rules.deniedModels) ? rules.fallbackModel : undefined
    if (denied) {
      if (fallback) out.model = fallback
      else delete out.model
    }
    if (isObject(merged.env)) {
      const env: Record<string, unknown> = { ...merged.env }
      for (const key of MODEL_ENV) if (typeof env[key] === 'string' && isDenied(env[key] as string, rules.deniedModels)) delete env[key]
      out.env = env
    }
    rows.push({
      setting: 'model',
      requested: show(asked),
      limit: `not ${rules.deniedModels.join(', ')}`,
      result: denied ? show(fallback ?? 'default') : show(asked ?? 'default'),
      state: denied ? 'clamped' : asked === undefined ? 'unset' : 'within',
    })
  }

  if (rules.maxEffort) {
    const max = rules.maxEffort
    const asked = merged.effortLevel
    let clamped = false
    const askedParts: string[] = []
    const resultParts: string[] = []
    if (asked !== undefined) {
      const lowered = lowerEffort(asked, max)
      if (lowered !== asked) { out.effortLevel = lowered; clamped = true }
      askedParts.push(show(asked))
      resultParts.push(show(lowered))
    }
    // Opus/Sonnet 5.5+ read effort per model: modelSettings[id].effortLevel.
    if (isObject(merged.modelSettings)) {
      const next: Record<string, unknown> = {}
      for (const [id, s] of Object.entries(merged.modelSettings)) {
        if (isObject(s) && s.effortLevel !== undefined) {
          const lowered = lowerEffort(s.effortLevel, max)
          if (lowered !== s.effortLevel) clamped = true
          next[id] = { ...s, effortLevel: lowered }
          askedParts.push(`${id}: ${show(s.effortLevel)}`)
          resultParts.push(`${id}: ${show(lowered)}`)
        } else next[id] = s
      }
      out.modelSettings = next
    }
    rows.push({
      setting: 'effortLevel',
      requested: askedParts.length > 0 ? askedParts.join(', ') : show(undefined),
      limit: `≤ ${max}`,
      result: resultParts.length > 0 ? resultParts.join(', ') : show(undefined),
      state: clamped ? 'clamped' : askedParts.length === 0 ? 'unset' : 'within',
    })
  }

  if (rules.forbiddenModes.length > 0) {
    const perms = isObject(merged.permissions) ? merged.permissions : {}
    const asked = perms.defaultMode
    const forbidden = typeof asked === 'string' && rules.forbiddenModes.includes(asked)
    if (forbidden) out.permissions = { ...perms, defaultMode: 'default' }
    rows.push({ setting: 'permissions.defaultMode', requested: show(asked), limit: `not ${rules.forbiddenModes.join(', ')}`, result: forbidden ? 'default' : show(asked ?? 'default'), state: forbidden ? 'clamped' : asked === undefined ? 'unset' : 'within' })
  }

  if (rules.requireSandbox) {
    const sandbox = isObject(merged.sandbox) ? merged.sandbox : {}
    const asked = sandbox.enabled
    const forced = asked !== true
    // A floor with an escape hatch is no floor: commands may not ask to run outside it.
    const hatch = sandbox.allowUnsandboxedCommands !== false
    if (forced || hatch) out.sandbox = { ...sandbox, enabled: true, allowUnsandboxedCommands: false }
    rows.push({ setting: 'sandbox.enabled', requested: show(asked), limit: 'true, no bypass', result: 'true', state: forced || hatch ? 'forced' : 'within' })
  }

  return { settings: out, rows }
}

{
  "description": "Makes an organization's managed limits act as ceilings and floors over each person's settings (retention, model, effort, permission mode, sandbox) instead of fixed values, and shows in /policy what each layer asked and what the session runs with.",
  "modules": [
    "./policy-ceiling.tsx"
  ]
}

/**
 * policy-ceiling — Claude Mod (install through managed settings)
 *
 * Managed settings normally replace a person's value. This mod makes some of
 * them limits instead: a person keeps their own value while it stays inside
 * the organization's ceiling or floor.
 *
 *   cleanupPeriodDays        ≤ maxCleanupPeriodDays
 *   model                    not in deniedModels (falls back to fallbackModel)
 *   effortLevel              ≤ maxEffort, top-level and per model (modelSettings)
 *   permissions.defaultMode  not in forbiddenModes (falls back to default)
 *   sandbox.enabled          true when requireSandbox
 *
 * Hooks `settings.read`, which since Claude Code 2.1.304 carries every layer
 * and rewrites the merged settings every reader sees. The rules are read from
 * the managed layer only (`pluginConfigs["policy-ceiling…"].options` in
 * managed-settings.json), so a person's own pluginConfigs cannot loosen them.
 * `/policy` shows each rule: what was asked, the limit and the result.
 */
import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'
import type { Row, Snapshot } from '../types'
import { apply, rulesFrom } from './ceiling.ts'

const PANE = 'policy-ceiling'
const snapshot = atom({ plugin: 'policy-ceiling', key: 'snapshot' } as const, { rows: [], hasRules: false, layers: [] } as Snapshot, { shape: 'snapshot-1' })

// Theme keys, so the pane reads on light and dark themes; in Claude's own theme `claude` is the Anthropic orange.
const ORANGE = 'claude'
const IVORY = 'text'
const GRAY = 'subtle'
const DIM = 'inactive'

/** Fixed-width cell with non-breaking spaces, so Desktop keeps the columns. */
const cell = (text: string, width: number) => {
  const t = text.length > width - 1 ? `${text.slice(0, width - 2)}…` : text
  return t.padEnd(width, ' ')
}

const LABEL: Record<Row['state'], string> = { clamped: '▲ clamped', forced: '▲ forced', within: '✓ within', unset: '· not set' }

export const register: Register = on => {
  let last = ''

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'policy', description: "Show the organization's ceilings and what this session runs with" })
    return next(e)
  })

  on('command.run', { command: 'policy' }, async $ => {
    // A read of our own raises settings.read through this mod's hook, so the rows are current.
    await $.settings.read().catch(() => undefined)
    const opened = await $.ui.open({ id: PANE, title: 'Organization policy' }).catch(() => ({ isPlaced: false }))
    if (opened.isPlaced) return { text: 'Policy pane opened.' }
    const { rows, hasRules } = await read($, snapshot)
    if (!hasRules) return { text: 'policy-ceiling: no ceilings applied. Install it as a managed plugin in prependPlugins and set pluginConfigs["policy-ceiling"].options in managed settings.' }
    return { text: rows.map(r => `${r.setting}: asked ${r.requested}, limit ${r.limit}, runs ${r.result} (${LABEL[r.state]})`).join('\n') }
  })

  on('settings.read', async ($, e, next) => {
    const answer = await next(e)
    // A read of one source answers that file as loaded: never rewrite it.
    if (e.source || answer.deny !== undefined) return answer
    const rules = rulesFrom(e.layers)
    const result = rules ? apply(answer.value, rules) : { settings: answer.value, rows: [] as Row[] }
    const snap: Snapshot = { rows: result.rows, hasRules: rules !== undefined, layers: e.layers.map(l => l.source) }
    const key = JSON.stringify(snap)
    if (key !== last) {
      last = key
      // Awaited, so a `/policy` right after this read sees these rows.
      await update($, snapshot, () => snap).catch(() => undefined)
    }
    return { value: result.settings }
  }).catch(async ($, e, next) => {
    // The ceilings could not be applied: the files' own merge stands, and the log says so.
    $.ui.log('[policy-ceiling] could not apply the ceilings; the settings are read as written', { to: 'debug' })
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const snap = await read($, snapshot)
    let who = ''
    try {
      const id = await $.session.identity()
      who = id.email ? `${id.email.split('@')[1] ?? ''} · ${id.kind}` : (id.kind ?? '')
    } catch {
      who = ''
    }

    if (!snap.hasRules) {
      return (
        <Box flexDirection="column" gap="sm">
          <Text weight="semibold" color={IVORY}>Organization policy</Text>
          <Text color={GRAY}>No ceilings applied. They take effect when an administrator installs this mod as a managed plugin (prependPlugins) and sets</Text>
          <Text mono color={IVORY}>pluginConfigs["policy-ceiling"].options</Text>
        </Box>
      )
    }

    // Columns sized to the pane (a docked pane is at most 45% of the terminal): setting, asked, limit, result, then the state label.
    const avail = Math.max(50, (e.props.bodyColumns ?? 90) - 11)
    const first = Math.min(24, Math.max(14, Math.floor(avail * 0.3)))
    const rest = Math.max(8, Math.floor((avail - first) / 3))
    const W = [first, rest, rest, rest]
    return (
      <Box flexDirection="column" gap="sm">
        <Box flexDirection="row" justifyContent="space-between">
          <Text weight="semibold" color={IVORY}>Organization policy</Text>
          {who && <Text color={DIM}>{who}</Text>}
        </Box>
        <Box flexDirection="column">
          <Text mono color={GRAY}>{cell('setting', W[0])}{cell('you asked', W[1])}{cell('org limit', W[2])}{cell('runs with', W[3])}</Text>
          {snap.rows.map(r => {
            const hit = r.state === 'clamped' || r.state === 'forced'
            return (
              <Box flexDirection="row">
                <Text mono color={IVORY}>{cell(r.setting, W[0])}</Text>
                <Text mono color={GRAY}>{cell(r.requested, W[1])}</Text>
                <Text mono color={GRAY}>{cell(r.limit, W[2])}</Text>
                <Text mono weight={hit ? 'semibold' : 'regular'} color={hit ? ORANGE : IVORY}>{cell(r.result, W[3])}</Text>
                <Text mono color={hit ? ORANGE : DIM}>{LABEL[r.state]}</Text>
              </Box>
            )
          })}
        </Box>
        <Text color={DIM}>Layers read: {snap.layers.join(' · ') || 'none'}</Text>
      </Box>
    )
  })
}

// Run with: claude plugin test enterprise/policy-ceiling
import { describe, expect, test } from 'claude-code/testing'
import { apply, rulesFrom, type Layer } from '../hooks/ceiling.ts'

const policy = (options: Record<string, unknown>, extra: Record<string, unknown> = {}): Layer => ({
  source: 'policy',
  settings: { pluginConfigs: { 'policy-ceiling@acme': { options } }, ...extra },
})
const user = (settings: Record<string, unknown>): Layer => ({ source: 'user', settings })

describe('rules', () => {
  test('come from the managed layer only', () => {
    const fromUser: Layer = { source: 'user', settings: { pluginConfigs: { 'policy-ceiling': { options: { maxCleanupPeriodDays: 999 } } } } }
    expect(rulesFrom([fromUser])).toBe(undefined)
    expect(rulesFrom([fromUser, policy({ maxCleanupPeriodDays: 30 })])?.maxCleanupPeriodDays).toBe(30)
    expect(rulesFrom([policy({ maxCleanupPeriodDays: 0, deniedModels: '', requireSandbox: false })])).toBe(undefined)
  })

  test('an unknown effort is ignored', () => {
    expect(rulesFrom([policy({ maxEffort: 'ultra' })])?.maxEffort).toBe(undefined)
  })
})

describe('apply', () => {
  const rules = rulesFrom([policy({
    maxCleanupPeriodDays: 30,
    deniedModels: 'opus[1m],claude-opus-4-8',
    fallbackModel: 'opus',
    maxEffort: 'xhigh',
    forbiddenModes: 'bypassPermissions',
    requireSandbox: true,
  })])!

  test('clamps values above the ceiling and keeps the rest', () => {
    const merged = {
      cleanupPeriodDays: 365,
      model: 'opus[1m]',
      effortLevel: 'max',
      modelSettings: { 'claude-opus-5-5': { effortLevel: 'max' }, 'claude-haiku-5-5': { effortLevel: 'low' } },
      permissions: { defaultMode: 'bypassPermissions', allow: ['Bash(ls)'] },
      sandbox: { enabled: false, network: { allowedDomains: ['x.com'] } },
      theme: 'dark',
    }
    const { settings, rows } = apply(merged, rules)
    expect(settings.cleanupPeriodDays).toBe(30)
    expect(settings.model).toBe('opus')
    expect(settings.effortLevel).toBe('xhigh')
    expect(settings.modelSettings).toEqual({ 'claude-opus-5-5': { effortLevel: 'xhigh' }, 'claude-haiku-5-5': { effortLevel: 'low' } })
    expect(settings.permissions).toEqual({ defaultMode: 'default', allow: ['Bash(ls)'] })
    expect(settings.sandbox).toEqual({ enabled: true, allowUnsandboxedCommands: false, network: { allowedDomains: ['x.com'] } })
    expect(settings.theme).toBe('dark')
    expect(rows.map(r => r.state)).toEqual(['clamped', 'clamped', 'clamped', 'clamped', 'forced'])
  })

  test('the effort row shows per-model values, also with no top-level effort', () => {
    const { rows } = apply({ modelSettings: { 'claude-opus-5-5': { effortLevel: 'max' } } }, rules)
    const effort = rows.find(r => r.setting === 'effortLevel')!
    expect(effort).toMatchObject({ requested: 'claude-opus-5-5: max', result: 'claude-opus-5-5: xhigh', state: 'clamped' })
  })

  test('values inside the limits are untouched', () => {
    const merged = { cleanupPeriodDays: 7, model: 'sonnet', effortLevel: 'medium', permissions: { defaultMode: 'acceptEdits' }, sandbox: { enabled: true, allowUnsandboxedCommands: false } }
    const { settings, rows } = apply(merged, rules)
    expect(settings).toEqual(merged)
    expect(rows.every(r => r.state === 'within')).toBe(true)
  })

  test('the 30-day default counts as within a 30-day ceiling and is clamped by a lower one', () => {
    expect(apply({}, rules).settings.cleanupPeriodDays).toBe(undefined)
    const tight = rulesFrom([policy({ maxCleanupPeriodDays: 14 })])!
    expect(apply({}, tight).settings.cleanupPeriodDays).toBe(14)
  })

  test('model environment variables, a denied fallback and unknown efforts cannot get around the limits', () => {
    const r = rulesFrom([policy({ deniedModels: 'opus[1m],claude-opus-4-8', fallbackModel: 'claude-opus-4-8', maxEffort: 'high' })])!
    const { settings } = apply({ model: 'opus[1m]', effortLevel: 'MAX', env: { ANTHROPIC_MODEL: 'opus[1m]', ANTHROPIC_DEFAULT_OPUS_MODEL: 'claude-opus-4-8', OTHER: '1' } }, r)
    expect(settings.model).toBe(undefined)
    expect(settings.env).toEqual({ OTHER: '1' })
    expect(settings.effortLevel).toBe('high')
  })

  test('the sandbox floor closes the unsandboxed escape hatch', () => {
    const r = rulesFrom([policy({ requireSandbox: true })])!
    const { settings, rows } = apply({ sandbox: { enabled: true } }, r)
    expect(settings.sandbox).toEqual({ enabled: true, allowUnsandboxedCommands: false })
    expect(rows[0].state).toBe('forced')
    expect(apply({ sandbox: { enabled: true, allowUnsandboxedCommands: false } }, r).rows[0].state).toBe('within')
  })

  test('a dated id of a denied model is denied too', () => {
    expect(apply({ model: 'claude-opus-4-8-20260101' }, rules).settings.model).toBe('opus')
    expect(apply({ model: 'claude-opus-4-8x' }, rules).settings.model).toBe('claude-opus-4-8x')
  })
})

