export type RowState = 'clamped' | 'within' | 'forced' | 'unset'

/** One line of /policy: what was asked, the limit, and what the session runs with. */
export type Row = { setting: string; requested: string; limit: string; result: string; state: RowState }

export type Snapshot = { rows: Row[]; hasRules: boolean; layers: string[] }

declare module 'claude-code' {
  interface PluginState {
    'policy-ceiling': { snapshot: Shaped<Snapshot> }
  }
}

/* @jsx h */
import type { ClientElements, ClientSurface } from 'claude-code'

// Shared by every board. A board is a surface module: it runs on the drawing thread with its own
// frame clock, keys (after a click gives it focus; Esc gives the prompt back) and mouse.
//
// Never name a local `h` in a board file: every JSX tag compiles to a call of `h`.

export type Props = { best?: number; done?: number; safe?: boolean } | undefined
export type Base = { playing: boolean; banner: boolean; seenDone: number }
export type Paint = readonly [glyph: string, color?: string, bg?: string]
type TextTag = ClientElements['Text']

export const base = (props: Props): Base => ({ playing: false, banner: false, seenDone: props?.done ?? 0 })

// the hooks module bumps props.done when Claude finishes a turn: pause and say so, once per turn
export function claudeDone<S extends Base>(props: Props, surface: ClientSurface<S>) {
  const s = surface.state
  const done = props?.done ?? 0
  if (s && done !== s.seenDone) surface.setState({ ...s, seenDone: done, banner: true, playing: false })
}

export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

export type Run = [text: string, color?: string, bg?: string]

// one run per stretch of cells sharing both colors. A drawing the engine cannot fit in its node
// budget is worse than a coarser one, so maxRuns folds neighbours together, pair by pair, until
// the row fits: a merged pair keeps the left one's colors and every glyph.
export function runs(cols: number, y: number, at: (x: number, y: number) => Paint, maxRuns = Infinity): Run[] {
  let out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  while (out.length > Math.max(1, maxRuns)) {
    const folded: Run[] = []
    for (let i = 0; i < out.length; i += 2) {
      const [t, c, b] = out[i]
      const next = out[i + 1]
      folded.push(next ? [t + next[0], c, b] : [t, c, b])
    }
    out = folded
  }
  return out
}

// a board as rows of two-character cells (a terminal cell is about twice as tall as wide, so two
// make a square), one styled span per run of the same colors
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint, maxRuns = Infinity) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at, maxRuns).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, statusLine, type Base, type Props } from './common.tsx'
import { move, new2048, SIZE, type G2048 } from '../games/twenty48.ts'

const TILE_COLORS: Record<number, string> = { 2: 'white', 4: 'whiteBright', 8: 'yellow', 16: 'yellowBright', 32: '#ff8800', 64: 'red', 128: 'magenta', 256: 'magentaBright', 512: 'blue', 1024: 'cyan', 2048: 'green' }
const SLIDE_KEYS: Record<string, string> = { left: 'left', right: 'right', up: 'up', down: 'down', a: 'left', d: 'right', w: 'up', s: 'down' }
type State = Base & { game: G2048 }

export default function Twenty48(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), game: new2048() })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key.toLowerCase()
      if (k === 'r') {
        surface.setState({ ...s, banner: false, game: new2048() })
        return
      }
      if (!Object.hasOwn(SLIDE_KEYS, k)) {
        if (s.banner) surface.setState({ ...s, banner: false })
        return
      }
      const game = move(s.game, SLIDE_KEYS[k])
      if (game.over && !s.game.over) surface.post({ game: '2048', score: game.score })
      surface.setState({ ...s, banner: false, game })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const rows = Array.from({ length: SIZE }, (_, y) => (
    <Text>
      {Array.from({ length: SIZE }, (_, x) => {
        const v = g?.cells[y * SIZE + x] ?? 0
        const label = `${v ? String(v) : '·'}`.padStart(5) + ' '
        return v >= 128
          ? <Text color={TILE_COLORS[v] ?? 'greenBright'} bold>{label}</Text>
          : <Text color={v ? TILE_COLORS[v] : 'gray'}>{label}</Text>
      })}
    </Text>
  ))
  const text = !g ? '2048'
    : g.over ? `2048 · no moves left · score ${g.score} · r plays again`
    : `2048 · score ${g.score}${g.won ? ' · 2048 reached, keep going' : ''} · click here, then arrows or wasd · r restarts`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : 'yellow'} width={SIZE * 6 + 3}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

// Which score counts as a new best. Minesweeper's best is its fastest clear, so lower wins there;
// everywhere else higher wins. A score of zero or less never counts: a Minesweeper board whose
// first click clears it takes 0 s and would otherwise lock the best forever, and a Pong match you
// lost posts a negative margin.
export function isBetter(score: number, prev: number | undefined, lowerIsBetter = false): boolean {
  if (!Number.isFinite(score) || score <= 0) return false
  if (prev === undefined || prev <= 0) return true
  return lowerIsBetter ? score < prev : score > prev
}

// 2048: pure game logic, drawn by the Twenty48 module in ../surface.tsx.

export const SIZE = 4
export type G2048 = { cells: number[]; score: number; over: boolean; won: boolean }

// slide one line toward its start: equal neighbours merge once each, first pair first
export function slide(line: number[]): { line: number[]; gained: number } {
  const tiles = line.filter(v => v !== 0)
  const out: number[] = []
  let gained = 0
  for (let i = 0; i < tiles.length; i++) {
    if (tiles[i] === tiles[i + 1]) {
      out.push(tiles[i] * 2)
      gained += tiles[i] * 2
      i++
    } else {
      out.push(tiles[i])
    }
  }
  while (out.length < line.length) out.push(0)
  return { line: out, gained }
}

// the cell indices of every line, each listed from the edge the tiles slide toward
function linesFor(dir: string): number[][] {
  const r = [...Array(SIZE).keys()]
  switch (dir) {
    case 'left': return r.map(y => r.map(x => y * SIZE + x))
    case 'right': return r.map(y => r.map(x => y * SIZE + (SIZE - 1 - x)))
    case 'up': return r.map(x => r.map(y => y * SIZE + x))
    case 'down': return r.map(x => r.map(y => (SIZE - 1 - y) * SIZE + x))
    default: return []
  }
}

// a 2 (nine times in ten) or a 4 on a random empty cell
function addTile(cells: number[], rand: () => number): number[] {
  const empty = cells.flatMap((v, i) => (v ? [] : [i]))
  if (!empty.length) return cells
  const next = [...cells]
  next[empty[Math.floor(rand() * empty.length)]] = rand() < 0.9 ? 2 : 4
  return next
}

const canMove = (cells: number[]) =>
  cells.some((v, i) => v === 0 || (i % SIZE < SIZE - 1 && v === cells[i + 1]) || (i + SIZE < cells.length && v === cells[i + SIZE]))

export function new2048(rand = Math.random): G2048 {
  return { cells: addTile(addTile(Array<number>(SIZE * SIZE).fill(0), rand), rand), score: 0, over: false, won: false }
}

// a move that changes nothing is not a move: no new tile, same game back
export function move(g: G2048, dir: string, rand = Math.random): G2048 {
  const lines = linesFor(dir)
  if (g.over || !lines.length) return g
  const cells = [...g.cells]
  let gained = 0
  for (const idx of lines) {
    const slid = slide(idx.map(i => g.cells[i]))
    idx.forEach((i, k) => { cells[i] = slid.line[k] })
    gained += slid.gained
  }
  if (cells.every((v, i) => v === g.cells[i])) return g
  const next = addTile(cells, rand)
  return { cells: next, score: g.score + gained, won: g.won || next.includes(2048), over: !canMove(next) }
}

