/* @jsx h */
import type { Register } from 'claude-code'
import { isBetter } from './games/best.ts'

// 2048 above the Claude Code prompt, split out of cc-arcade (https://github.com/sezaakgun/cc-arcade,
// MIT, by Seza Akgün) as a single-game mod. `/2048` opens it, `/2048 stop` closes it. The board in
// ./boards is a surface module that runs on the drawing thread; this module mounts it, keeps the best
// score in $.store and pauses the game when Claude finishes a turn. Playing costs no tokens.

const GAME = '2048' // what the board posts its score under
const TITLE = '2048'
const LOWER_IS_BETTER = false
const UNIT = ''

let open = false
// bumped at each finished turn; the open game pauses when it sees a new value
let turnsDone = 0
let best = 0

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    // a store that cannot be read costs the best score, never the game
    const score = Number(await $.store.get('best').catch(() => undefined))
    if (score) best = score
    await $.command.register({
      name: '2048',
      description: `$2048 above the prompt, while Claude works (stop closes)`,
      argumentHint: '[stop]',
      immediate: true,
    }).catch(err => $.ui.log(`2048: /2048 not registered: ${err}`))
    return r
  })

  on('command.run', { command: '2048' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'stop' || arg === 'close') {
      open = false
      $.ui.invalidate('ui.render')
      return { text: `$2048 closed` }
    }
    open = true
    $.ui.invalidate('ui.render')
    const score = best ? ` · best ${best}$` : ''
    return { text: `$2048 · click the board to play · Esc returns to the prompt · /2048 stop closes${score}` }
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    // a subagent's turn is not the one the person is waiting for
    if (e.agentId) return r
    if (open) {
      turnsDone++
      $.ui.invalidate('ui.render')
    }
    return r
  })

  // a finished round, posted by the board: keep the best score and hand it back with the next props
  on('ui.message', async ($, e, next) => {
    const data = e.data as { game?: unknown; score?: unknown } | null
    if (data?.game !== GAME || typeof data.score !== 'number') return next(e)
    if (isBetter(data.score, best || undefined, LOWER_IS_BETTER)) {
      best = data.score
      await $.store.set('best', best).catch(err => $.ui.log(`2048: store write failed: ${err}`))
      $.ui.toast(`$2048: new best ${best}$`)
    }
    return { props: { best, done: turnsDone, safe: false } }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // the board needs a terminal's keys and mouse; the desktop and mobile surfaces draw their own band
    if (!open || e.props.hasSurvey || e.surface !== 'terminal') return next(e)
    const { Box, Button, Client } = $.ui.resolve(e)
    // the band's own width: the transcript column's while a Pane is docked beside it
    const cols = e.props.bodyColumns || (e.viewport?.columns ?? 80)
    const close = () => {
      open = false
      $.ui.invalidate('ui.render')
    }
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={1}>
          <Button key="2048:close" label="close" onPress={close} />
        </Box>
        <Client key="board:2048" module="./boards/twenty48.tsx" width={cols} props={{ best, done: turnsDone, safe: false }} />
        {await next(e)}
      </Box>
    )
  })
}

/* @jsx h */
import type { ClientElements, ClientSurface } from 'claude-code'

// Shared by every board. A board is a surface module: it runs on the drawing thread with its own
// frame clock, keys (after a click gives it focus; Esc gives the prompt back) and mouse.
//
// Never name a local `h` in a board file: every JSX tag compiles to a call of `h`.

export type Props = { best?: number; done?: number; safe?: boolean } | undefined
export type Base = { playing: boolean; banner: boolean; seenDone: number }
export type Paint = readonly [glyph: string, color?: string, bg?: string]
type TextTag = ClientElements['Text']

export const base = (props: Props): Base => ({ playing: false, banner: false, seenDone: props?.done ?? 0 })

// the hooks module bumps props.done when Claude finishes a turn: pause and say so, once per turn
export function claudeDone<S extends Base>(props: Props, surface: ClientSurface<S>) {
  const s = surface.state
  const done = props?.done ?? 0
  if (s && done !== s.seenDone) surface.setState({ ...s, seenDone: done, banner: true, playing: false })
}

export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

export type Run = [text: string, color?: string, bg?: string]

// one run per stretch of cells sharing both colors. A drawing the engine cannot fit in its node
// budget is worse than a coarser one, so maxRuns folds neighbours together, pair by pair, until
// the row fits: a merged pair keeps the left one's colors and every glyph.
export function runs(cols: number, y: number, at: (x: number, y: number) => Paint, maxRuns = Infinity): Run[] {
  let out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  while (out.length > Math.max(1, maxRuns)) {
    const folded: Run[] = []
    for (let i = 0; i < out.length; i += 2) {
      const [t, c, b] = out[i]
      const next = out[i + 1]
      folded.push(next ? [t + next[0], c, b] : [t, c, b])
    }
    out = folded
  }
  return out
}

// a board as rows of two-character cells (a terminal cell is about twice as tall as wide, so two
// make a square), one styled span per run of the same colors
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint, maxRuns = Infinity) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at, maxRuns).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Paint, type Props } from './common.tsx'
import { cast, fire, move, newDoom, select, STEP, SWING, tick, turn, wrap, WEAPON, type DoomGame, type ItemKind, type Kind, type Weapon } from '../games/doom.ts'

// The view is a pixel buffer twice as tall as the band: each cell is drawn as an upper half block,
// so its foreground is the top pixel and its background the bottom one. Columns are cast one ray
// each; monsters, pickups and fireballs are billboards tested against the wall depth of their
// column. Every sprite is an 8 × 8 mask, sampled at whatever size the distance calls for.

type Rgb = readonly [number, number, number]
type State = Base & { game?: DoomGame }
type Sprite = { art: string[]; rgb: Rgb; scale: number; float?: boolean }

const FOV = (70 * Math.PI) / 180
export const WALL: Record<string, Rgb> = {
  '1': [165, 95, 45], '2': [130, 132, 145], '3': [70, 150, 85],
  D: [175, 55, 55], X: [60, 220, 110],
}
// Colour-blind mode. Red and green carry meaning all over this game — a red door against a green
// exit switch is the textbook case — so the mode swaps in colours that stay apart on the axes
// dichromats keep, spreads them by brightness too, and gives the two wall markers a pattern each,
// because no palette is a substitute for a cue that is not colour at all.
// the walls go dark, because they are the background: everything that matters stands in front of
// them, and a dichromat reads a bright thing on a dark wall whatever the two hues do
const SAFE_WALL: Record<string, Rgb> = {
  '1': [78, 78, 78], '2': [96, 102, 108], '3': [52, 66, 82],
  D: [230, 159, 0], X: [86, 180, 233],
}
// spread along brightness as well as hue: hue alone is what a dichromat is short of
const SAFE_TINT: Record<Drawn, Rgb> = {
  imp: [255, 109, 31], demon: [170, 90, 200], zombie: [130, 205, 245],
  health: [255, 255, 255], key: [240, 228, 66], shells: [230, 159, 0],
  bullets: [48, 150, 224], shotgun: [0, 158, 115], chaingun: [154, 160, 166],
  ball: [255, 225, 90],
}
// What a player has to tell apart in a hurry, and what it costs to get wrong. Three kinds of colour
// blindness leave about one hue axis and brightness between them, which is not room for nine
// separate colours, so the promise is made where a mix-up costs something:
//   the door from the exit    — walk into the wrong one and you are lost, and both are flat wall
//   one monster from another  — how fast it closes and how much it takes decides what you do
//   anything from the wall    — seeing that something is there at all
// Pickups are not on the list against each other. You walk over what you step on; there is no
// choice to get wrong, and their shapes differ anyway. Where colour runs out, pattern takes over.
export const CRITICAL: [string, string][] = [
  ['wall:D', 'wall:X'],
  ['imp', 'demon'], ['imp', 'zombie'], ['demon', 'zombie'],
  ['imp', 'wall:2'], ['demon', 'wall:2'], ['zombie', 'wall:2'],
  ['health', 'wall:2'], ['key', 'wall:2'], ['shells', 'wall:2'], ['bullets', 'wall:2'],
]
export const safeRgb = (name: string): Rgb =>
  name.startsWith('wall:') ? SAFE_WALL[name.slice(5)] : SAFE_TINT[name as Drawn]

const CEILING: Rgb = [46, 46, 58]
const GROUND: Rgb = [78, 62, 48]
const METAL: Rgb = [96, 98, 108]
const BARREL: Rgb = [168, 150, 112]

const art = (...rows: string[]) => rows
type Drawn = Kind | ItemKind | 'ball'
export const SPRITE: Record<Drawn, Sprite> = {
  imp: { rgb: [200, 72, 40], scale: 0.8, art: art(
    '..#..#..', '.#.##.#.', '.######.', '.#.##.#.', '..####..', '.##..##.', '.#.##.#.', '##....##') },
  demon: { rgb: [225, 120, 140], scale: 0.95, art: art(
    '#......#', '#.#..#.#', '.######.', '.#.##.#.', '.######.', '.##..##.', '.#....#.', '##....##') },
  zombie: { rgb: [150, 145, 110], scale: 0.75, art: art(
    '...##...', '...##...', '..####..', '.#####..', '..###.##', '..####..', '..#..#..', '..#..#..') },
  health: { rgb: [60, 200, 90], scale: 0.34, art: art(
    '........', '...##...', '...##...', '.######.', '.######.', '...##...', '...##...', '........') },
  shells: { rgb: [215, 180, 40], scale: 0.3, art: art(
    '........', '........', '.######.', '.#.##.#.', '.#.##.#.', '.######.', '........', '........') },
  bullets: { rgb: [190, 140, 60], scale: 0.26, art: art(
    '........', '........', '..####..', '..#..#..', '..#..#..', '..####..', '........', '........') },
  shotgun: { rgb: [175, 140, 95], scale: 0.34, art: art(
    '........', '........', '..#####.', '.######.', '.##.....', '........', '........', '........') },
  chaingun: { rgb: [150, 150, 165], scale: 0.36, art: art(
    '........', '..####..', '.#####..', '.####...', '.###....', '.##.....', '........', '........') },
  key: { rgb: [230, 50, 50], scale: 0.3, art: art(
    '..###...', '..#.#...', '..###...', '...#....', '...#....', '...##...', '...#....', '...##...') },
  ball: { rgb: [255, 190, 60], scale: 0.22, float: true, art: art(
    '..####..', '.######.', '########', '########', '########', '########', '.######.', '..####..') },
}
// the weapon in your hands, bottom centre of the view
const HANDS: Record<Weapon, string[]> = {
  pistol: art('...##...', '...##...', '..####..', '..####..', '.######.', '########'),
  shotgun: art('....##..', '...####.', '..#====#', '.##====#', '######==', '########'),
  chaingun: art('..#..#..', '.##==##.', '.##==##.', '.######.', '########', '########'),
}

// the engine counts the nodes in a frame, and every change of colour along a row is one more span,
// so the shades are quantised: neighbouring columns of the same wall come out equal and merge
export const SHADES = 24
const hex = (rgb: Rgb, k: number) =>
  `#${rgb.map(c => Math.max(0, Math.min(255, Math.round((c * k) / SHADES) * SHADES)).toString(16).padStart(2, '0')).join('')}`
// further is darker, and never quite black
const fog = (d: number) => Math.max(0.16, 1 / (1 + d * 0.14))
// a still frame of a corridor looks exactly like a running one, so a stopped game is dimmed: it is
// the only way to see at a glance that this view is not playing
const dimmed = new Map<string, string>()
const dim = (color: string) => {
  // paused is when the person is reading Claude's answer, and it is the frame that dims every
  // pixel. The palette is quantised, so the colours coming through here are a small fixed set.
  const known = dimmed.get(color)
  if (known !== undefined) return known
  const out = `#${[1, 3, 5].map(i => Math.round(parseInt(color.slice(i, i + 2), 16) * 0.42).toString(16).padStart(2, '0')).join('')}`
  dimmed.set(color, out)
  return out
}

export default function Doom(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const ensure = (s: State): DoomGame => (s.game && !s.game.over ? s.game : newDoom())
  // the view, in pixels: one per column, two per row
  const view = () => ({ w: Math.max(8, surface.columns - 2), ph: Math.max(6, (surface.rows - 3) * 2) })

  const act = (fn: (g: DoomGame) => DoomGame) => {
    const s = surface.state
    if (!s) return
    surface.setState({ ...s, banner: false, playing: true, game: fn(ensure(s)) })
  }

  if (surface.state === undefined) {
    // the floor is there from the first frame; nothing moves until you press or click
    surface.setState({ ...base(props), game: newDoom() })
    // 20 frames a second: the movement is driven by the frame, not by how fast a key repeats
    surface.every(50, () => {
      const s = surface.state
      if (!s?.game || !s.playing || s.game.over) return
      const game = tick(s.game)
      if (game.over) surface.post({ game: 'doom', score: game.kills })
      surface.setState({ ...s, game })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (s.game && !s.game.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        surface.setState({ ...s, banner: false, playing: true, game: newDoom() })
        return
      }
      const weapon: Weapon | undefined = k === '1' ? 'pistol' : k === '2' ? 'shotgun' : k === '3' ? 'chaingun' : undefined
      // one press, one step: what the terminal repeats while you hold a key is what walks you
      const step =
        weapon ? (g: DoomGame) => select(g, weapon)
        : k === 'w' || k === 'up' ? (g: DoomGame) => move(g, STEP)
        : k === 's' || k === 'down' ? (g: DoomGame) => move(g, -STEP)
        : k === 'a' ? (g: DoomGame) => move(g, 0, -STEP)
        : k === 'd' ? (g: DoomGame) => move(g, 0, STEP)
        : k === 'left' || k === 'q' ? (g: DoomGame) => turn(g, -SWING)
        : k === 'right' || k === 'e' ? (g: DoomGame) => turn(g, SWING)
        : k === ' ' || k === 'return' ? fire
        : undefined
      if (step) act(step)
    })
    // the pointer aims: moving over the view turns toward it, a click fires
    surface.onPointer(ev => {
      const s = surface.state
      if (!s) return
      if (ev.type !== 'move' && ev.type !== 'down') return
      if (ev.type === 'move' && (!s.playing || s.game?.over)) return
      const w = view().w
      const dpp = w / 2 / Math.tan(FOV / 2)
      const aim = (g: DoomGame) => turn(g, Math.atan2(ev.x - 1 - w / 2, dpp) * 0.5)
      act(ev.type === 'down' ? g => fire(aim(g)) : aim)
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { w, ph } = view()
  const rows = ph / 2
  const dpp = w / 2 / Math.tan(FOV / 2)
  // one colour per pixel, filled by the wall pass and overdrawn by the sprites and the weapon
  const buf: string[] = Array.from({ length: w * ph })
  const depth = new Float64Array(w)

  const safe = props?.safe ?? false
  const walls = safe ? SAFE_WALL : WALL
  const tint = (name: Drawn, fallback: Rgb) => (safe ? SAFE_TINT[name] : fallback)

  if (g) {
    // one colour per row for the floor and the ceiling: they fade with the row's own distance and
    // nothing else, so building them per pixel rebuilt the same string tens of thousands of times.
    // Every column then shares the identical string, which makes the run merge in grid() a pointer
    // compare rather than a character one.
    const sky = Array.from({ length: ph }, (_, y) =>
      hex(y < ph / 2 ? CEILING : GROUND, fog(ph / 2 / Math.max(0.5, Math.abs(y - ph / 2)))))

    // Wide bars, not every other column: a door filling a wide view would otherwise emit one run
    // per two columns, and the run cap in grid() folds pairs by keeping the left one's colour —
    // which collapses an alternating pattern back to a single flat colour. A dozen bands across
    // the view stays well under the cap at any width, so the cue survives on a big terminal.
    const barW = Math.max(2, Math.round(w / 12))

    for (let x = 0; x < w; x++) {
      const angle = g.dir + Math.atan2(x - w / 2 + 0.5, dpp)
      const ray = cast(g.map, g.px, g.py, angle)
      // the cosine takes the fisheye out: what matters is the distance to the wall's plane
      const d = Math.max(0.05, ray.dist * Math.cos(angle - g.dir))
      depth[x] = d
      const h = dpp / d
      const top = Math.round(ph / 2 - h / 2)
      const bottom = Math.round(ph / 2 + h / 2)
      // the two faces of a corner catch the light differently, which is what makes corners read
      const lit = fog(d) * (ray.side === 1 ? 0.68 : 1)
      const base = walls[ray.kind] ?? walls['2']
      // in colour-blind mode the door is barred the short way and the exit switch the long way, so
      // the two of them read apart with the colour taken away entirely
      const bars = safe && ray.kind === 'D' ? (Math.floor(x / barW) & 1 ? 1.35 : 0.6) : 1
      const wall = hex(base, lit * bars)
      const banded = safe && ray.kind === 'X'
      for (let y = 0; y < ph; y++) {
        buf[y * w + x] = y >= top && y < bottom
          ? (banded ? hex(base, lit * ((y >> 1) & 1 ? 1.35 : 0.6)) : wall)
          : sky[y]
      }
    }

    // billboards, furthest first so a near one covers what stands behind it
    const billboard = (name: Drawn, x: number, y: number, hurt = false) =>
      ({ x, y, art: SPRITE[name].art, scale: SPRITE[name].scale, float: SPRITE[name].float, rgb: tint(name, SPRITE[name].rgb), hurt })
    const board = [
      ...g.enemies.map(e => billboard(e.kind, e.x, e.y, e.hurt > 0)),
      ...g.items.map(i => billboard(i.kind, i.x, i.y)),
      ...g.balls.map(b => billboard('ball', b.x, b.y)),
    ]
      .map(sp => ({ ...sp, d: Math.hypot(sp.x - g.px, sp.y - g.py) }))
      .sort((a, b) => b.d - a.d)
    for (const sp of board) {
      const a = wrap(Math.atan2(sp.y - g.py, sp.x - g.px) - g.dir)
      if (Math.abs(a) > FOV) continue
      // the depth buffer holds perpendicular distances, so the sprite has to be measured the same
      // way or it is culled by a wall it stands in front of, and drawn at a different scale from
      // the walls beside it. Shading still wants the true distance: fog is about how far away it is.
      const perp = Math.max(0.1, sp.d * Math.cos(a))
      const full = dpp / perp
      const size = Math.max(1, Math.round(full * sp.scale))
      const left = w / 2 + Math.tan(a) * dpp - size / 2
      // a monster or a pickup stands on the floor; a fireball flies at eye level
      const top = sp.float ? ph / 2 - size / 2 : ph / 2 + full / 2 - size
      const color = hex(sp.rgb, sp.hurt ? 1.6 : Math.max(0.5, fog(sp.d) * 1.4))
      // walk the part of the screen the sprite covers, not the sprite: something almost in your
      // face is scaled by 1/distance and would otherwise be a loop the size of the square of it
      for (let x = Math.max(0, Math.ceil(left)); x < Math.min(w, left + size); x++) {
        if (depth[x] <= perp) continue
        const col = Math.floor(((x - left) / size) * 8)
        for (let y = Math.max(0, Math.ceil(top)); y < Math.min(ph, top + size); y++) {
          if (sp.art[Math.floor(((y - top) / size) * 8)][col] === '.') continue
          buf[y * w + x] = color
        }
      }
    }

    // the crosshair, then the weapon across the bottom, then the muzzle flash over both
    const cx = Math.floor(w / 2)
    const cy = Math.floor(ph / 2)
    for (const [dx, dy] of [[0, -2], [0, 2], [-2, 0], [2, 0]] as const) {
      const x = cx + dx
      const y = cy + dy
      if (x >= 0 && x < w && y >= 0 && y < ph) buf[y * w + x] = '#d8d8d8'
    }
    const hands = HANDS[g.weapon]
    const gh = Math.max(4, Math.round(ph * 0.3))
    const gw = gh * 2
    for (let iy = 0; iy < gh; iy++) for (let ix = 0; ix < gw; ix++) {
      const mark = hands[Math.floor((iy / gh) * hands.length)][Math.floor((ix / gw) * hands[0].length)]
      if (mark === '.') continue
      const x = Math.round(cx - gw / 2 + ix)
      const y = ph - gh + iy
      if (x < 0 || x >= w || y < 0 || y >= ph) continue
      buf[y * w + x] = hex(mark === '=' ? BARREL : METAL, g.flash > 0 ? 1.5 : 1)
    }
    if (g.flash > 0) {
      const blast = Math.max(2, Math.round(gh * 0.7))
      for (let iy = -blast; iy <= blast; iy++) for (let ix = -blast; ix <= blast; ix++) {
        if (Math.hypot(ix, iy) > blast) continue
        const x = cx + ix
        const y = ph - gh + iy
        if (x < 0 || x >= w || y < 0 || y >= ph) continue
        buf[y * w + x] = Math.hypot(ix, iy) > blast * 0.6 ? '#ffb020' : '#fff0c0'
      }
    }
  }

  const stopped = !s?.playing || !!g?.over
  const shade = (color: string) => (stopped ? dim(color) : color)
  const paint = (x: number, y: number): Paint =>
    ['▀', shade(buf[y * 2 * w + x] ?? '#101014'), shade(buf[(y * 2 + 1) * w + x] ?? '#101014')]
  // what is left of the engine's node budget for this frame, shared out over the rows
  const maxRuns = Math.max(6, Math.floor(1500 / Math.max(1, rows)) - 1)
  const border = g?.over ? 'red' : (g?.pain ?? 0) > 0 ? 'redBright' : g?.flash ? 'yellow' : 'gray'
  // a pickup, a door or a new floor says so for a couple of seconds
  const said = g && g.said && g.ticks - g.saidAt < 50 ? ` · ${g.said}` : ''
  // once a floor is under way the line keeps showing it, paused or not: what you want to read when
  // you come back is your health, not the controls again
  const text = g?.over ? `doom · you died on E1M${g.level} · ${g.kills} killed · r starts again`
    : (g?.ticks ?? 0) === 0 && !s?.playing && !s?.banner ? 'doom · click the view, then WASD moves · ←→ turn · space fires · 1 2 3 weapons'
    : `doom · E1M${g?.level ?? 1} · health ${g?.health ?? 0} · ${g?.weapon ?? 'pistol'} ${g?.[WEAPON[g?.weapon ?? 'pistol'].ammo] ?? 0} · killed ${g?.kills ?? 0}${g?.key ? ' · red key' : ''}${said}`
  // a stopped game says so across the middle of the view, where the click has to land anyway: the
  // keyboard goes to the prompt until a click gives it to the board, and a status line is easy to miss
  const label = !stopped ? undefined
    : g?.over ? 'you died · press r to start again'
    : s?.banner ? '● Claude is done · click here or press a key to carry on'
    : (g?.ticks ?? 0) === 0 ? 'CLICK HERE TO PLAY · then WASD moves, space fires'
    : 'paused · click here or press p'
  const view3d = grid(Text, w, rows, paint, maxRuns)
  if (label) {
    const pad = Math.max(0, Math.floor((w - label.length) / 2))
    const line = (' '.repeat(pad) + label).padEnd(w).slice(0, w)
    view3d[Math.floor(rows / 2)] = <Text backgroundColor="#101014" color={s?.banner ? '#ffd24a' : '#ffffff'} bold>{line}</Text>
  }
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={border} width={w + 2}>
        {view3d}
      </Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { BIRD_X, birdRow, flap, gapSize, newFlappy, tick, type FlappyGame } from '../games/flappy.ts'

type State = Base & { game?: FlappyGame }

export default function Flappy(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => ({
    bw: Math.max(12, Math.min(40, Math.floor((surface.columns - 2) / 2))),
    bh: Math.max(6, Math.min(16, surface.rows - 3)),
  })
  const start = () => {
    const s = surface.state
    if (!s) return
    const { bw, bh } = size()
    surface.setState({ ...s, banner: false, playing: true, game: flap(newFlappy(bw, bh)) })
  }
  // space, up, Enter or a click: flap, or start a new round when there is none
  const press = () => {
    const s = surface.state
    if (!s) return
    if (!s.game || s.game.over) return start()
    surface.setState({ ...s, banner: false, playing: true, game: flap(s.game) })
  }

  if (surface.state === undefined) {
    surface.setState(base(props))
    surface.every(100, () => {
      const s = surface.state
      if (!s?.game || !s.playing || s.game.over) return
      const game = tick(s.game)
      if (game.over) surface.post({ game: 'flappy', score: game.score })
      surface.setState({ ...s, game })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (s.game && !s.game.over) surface.setState({ ...s, banner: false, playing: !s.playing })
      } else if (k === 'r') {
        start()
      } else if (k === ' ' || k === 'up' || k === 'w' || k === 'return') {
        press()
      }
    })
    surface.onPointer(ev => { if (ev.type === 'down') press() })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh } = g ? { bw: g.w, bh: g.h } : size()
  const row = g ? birdRow(g) : Math.floor(bh / 2)
  const opening = gapSize(bh)
  const rows = grid(Text, bw, bh, (x, y) => {
    if (x === BIRD_X && y === row) return ['▓▓', g?.over ? 'red' : 'yellowBright']
    const pipe = g?.pipes.find(p => p.x === x)
    if (pipe && (y < pipe.gap || y >= pipe.gap + opening)) return ['██', 'green']
    return ['  ']
  })
  const text = !g ? 'flappy · click here, then space or click to flap · p pause'
    : g.over ? `flappy · crashed · score ${g.score} · space or click flies again`
    : !s?.playing ? `flappy · paused · score ${g.score} · p resumes`
    : `flappy · score ${g.score} · space or click flaps`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : 'blue'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { fire, newInvaders, shift, tick, type InvadersGame, type Pt } from '../games/invaders.ts'

const ROW_COLORS = ['magentaBright', 'cyan', 'green', 'yellow']
type State = Base & { game?: InvadersGame }

export default function Invaders(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => ({
    bw: Math.max(20, Math.min(30, Math.floor((surface.columns - 2) / 2))),
    bh: Math.max(10, Math.min(16, surface.rows - 3)),
  })
  // the running round, or a new one when there is none or the last one ended
  const ensure = (s: State): InvadersGame => (s.game && !s.game.over ? s.game : newInvaders(size().bw, size().bh))

  if (surface.state === undefined) {
    surface.setState(base(props))
    surface.every(100, () => {
      const s = surface.state
      if (!s?.game || !s.playing || s.game.over) return
      const game = tick(s.game)
      if (game.over) surface.post({ game: 'invaders', score: game.score })
      surface.setState({ ...s, game })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (s.game && !s.game.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        surface.setState({ ...s, banner: false, playing: true, game: newInvaders(size().bw, size().bh) })
        return
      }
      const g = ensure(s)
      const game = k === 'left' || k === 'a' ? shift(g, -1)
        : k === 'right' || k === 'd' ? shift(g, 1)
        : k === ' ' || k === 'up' || k === 'w' ? fire(g)
        : undefined
      if (game) surface.setState({ ...s, banner: false, playing: true, game })
    })
    // the ship follows the pointer over the board and a click fires (the border takes the first column)
    surface.onPointer(ev => {
      const s = surface.state
      if (!s || (ev.type !== 'move' && ev.type !== 'down')) return
      if (ev.type === 'move' && (!s.game || s.game.over || !s.playing)) return
      const g = ensure(s)
      const moved = { ...g, ship: Math.max(0, Math.min(g.w - 1, Math.floor((ev.x - 1) / 2))) }
      surface.setState({ ...s, banner: false, playing: true, game: ev.type === 'down' ? fire(moved) : moved })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh } = g ? { bw: g.w, bh: g.h } : size()
  const top = g ? Math.min(...g.aliens.map(a => a[1])) : 0
  const flap = (g?.ticks ?? 0) % 10 < 5
  const has = (list: Pt[] | undefined, x: number, y: number) => !!list?.some(p => p[0] === x && p[1] === y)
  const rows = grid(Text, bw, bh, (x, y) => {
    if (!g) return ['  ']
    if (y === g.h - 1 && x === g.ship) return ['▟▙', 'greenBright']
    if (has(g.aliens, x, y)) return [flap ? '▚▞' : '▞▚', ROW_COLORS[(y - top) % ROW_COLORS.length]]
    if (has(g.shots, x, y)) return [' |', 'yellowBright']
    if (has(g.bombs, x, y)) return [' :', 'red']
    return ['  ']
  })
  const text = !g ? 'invaders · click here, then ←→ move · space fires · or the mouse'
    : g.over ? `invaders · game over · score ${g.score} · wave ${g.wave} · r plays again`
    : !s?.playing ? `invaders · paused · score ${g.score} · p resumes`
    : `invaders · score ${g.score} · wave ${g.wave} · lives ${'▲'.repeat(g.lives)} · space fires · p pause`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : 'magenta'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { flag, newMines, reveal, type Mines } from '../games/mines.ts'

const NUMBER_COLORS = ['', 'blue', 'green', 'red', 'magenta', 'yellow', 'cyan', 'white', 'gray']
const CURSOR_KEYS: Record<string, readonly [number, number]> = { left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1], a: [-1, 0], d: [1, 0], w: [0, -1], s: [0, 1] }
type State = Base & { game?: Mines; cursor: readonly [number, number]; seconds: number }

export default function Minesweeper(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => {
    const bw = Math.max(4, Math.min(16, Math.floor((surface.columns - 2) / 2)))
    const bh = Math.max(4, Math.min(9, surface.rows - 3))
    return { bw, bh, count: Math.max(1, Math.round(bw * bh * 0.15)) }
  }
  // a click or space reveals, a right-click or f flags; the first action after a finished round
  // only starts a new board, so a stray click cannot open a cell on it
  const act = (x: number, y: number, kind: 'reveal' | 'flag') => {
    const s = surface.state
    if (!s) return
    let g = s.game
    if (!g || g.over || g.won) {
      const { bw, bh, count } = size()
      const fresh = newMines(bw, bh, count)
      if (g) {
        surface.setState({ ...s, banner: false, playing: false, seconds: 0, game: fresh })
        return
      }
      g = fresh
    }
    const game = kind === 'flag' ? flag(g, x, y) : reveal(g, x, y)
    // a board whose first click clears it takes 0 s; count it as 1 s so it cannot lock the best
    if (game.won && !g.won) surface.post({ game: 'minesweeper', score: Math.max(1, s.seconds) })
    const cursor = x >= 0 && y >= 0 && x < game.w && y < game.h ? ([x, y] as const) : s.cursor
    surface.setState({ ...s, banner: false, playing: game.placed && !game.over && !game.won, game, cursor })
  }

  if (surface.state === undefined) {
    surface.setState({ ...base(props), cursor: [0, 0], seconds: 0 })
    surface.every(1000, () => {
      const s = surface.state
      if (s?.game && s.playing && !s.banner) surface.setState({ ...s, seconds: s.seconds + 1 })
    })
    surface.onPointer(ev => {
      if (ev.type !== 'down') return
      // the border takes the first row and column; each cell is two columns wide
      act(Math.floor((ev.x - 1) / 2), ev.y - 1, ev.button === 'right' ? 'flag' : 'reveal')
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      const bw = s.game?.w ?? size().bw
      const bh = s.game?.h ?? size().bh
      if (Object.hasOwn(CURSOR_KEYS, k)) {
        const [dx, dy] = CURSOR_KEYS[k]
        const [cx, cy] = s.cursor
        surface.setState({ ...s, banner: false, cursor: [Math.max(0, Math.min(bw - 1, cx + dx)), Math.max(0, Math.min(bh - 1, cy + dy))] })
      } else if (k === ' ' || k === 'return') {
        act(s.cursor[0], s.cursor[1], 'reveal')
      } else if (k === 'f') {
        act(s.cursor[0], s.cursor[1], 'flag')
      } else if (k === 'r') {
        const { bw: nw, bh: nh, count } = size()
        surface.setState({ ...s, banner: false, playing: false, seconds: 0, game: newMines(nw, nh, count) })
      }
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh, count } = g ? { bw: g.w, bh: g.h, count: g.count } : size()
  const [cx, cy] = s?.cursor ?? [0, 0]
  const rows = grid(Text, bw, bh, (x, y) => {
    const t = g?.tiles[y * bw + x]
    const bg = x === cx && y === cy ? 'blue' : undefined
    if (!t || (!t.open && !t.flag)) return ['░░', 'gray', bg]
    if (t.flag && !t.open) return [' F', 'redBright', bg]
    if (t.mine) return [' *', 'red', bg]
    return t.n ? [` ${t.n}`, NUMBER_COLORS[t.n], bg] : ['  ', undefined, bg]
  })
  const flags = g?.tiles.filter(t => t.flag).length ?? 0
  const seconds = s?.seconds ?? 0
  const text = !g ? 'minesweeper · click a cell, or click here then arrows + space · right-click or f flags'
    : g.over ? 'minesweeper · boom · r or a click plays again'
    : g.won ? `minesweeper · cleared in ${seconds}s · r or a click plays again`
    : `minesweeper · ${count - flags} mines left · ${seconds}s · click reveals · right-click or f flags`
  const best = props?.best ? `${props.best}s` : '—'
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : g?.won ? 'green' : 'gray'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${best}`)}
    </Box>
  )
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { feeling, level, moodAt, stage, type Pet, type PetEvent, type Stage } from '../games/pet.ts'

// The pet's window. The hooks module owns the pet (it feeds it from tool calls and keeps it in
// $.store) and passes it in props; this board only draws it, blinks, and shows hearts on a click.

type PetProps = { pet?: Pet; now?: number } | undefined
type State = { frame: number; petted: number }

const ART: Record<Stage, string[]> = {
  egg: ['   ____   ', '  /    \\  ', ' |  {e}  | ', '  \\____/  '],
  baby: ['  (\\_/)  ', ' ( {e} ) ', ' (")(")  '],
  kid: ['  /\\_/\\  ', ' ( {e} ) ', '  > ^ <  '],
  adult: ['  /\\_____/\\  ', ' (   {e}   ) ', ' (    w    ) ', '  \\_______/  '],
  legend: ['     \\^^^/     ', '  /\\_____/\\  ', ' (   {e}   ) ', ' (    w    ) ', '  \\_______/  '],
}
const EYES = { happy: '^.^', okay: 'o.o', sad: 'T.T' }
const COLORS = { happy: 'greenBright', okay: 'yellow', sad: 'red' }
const FED_BY: Record<PetEvent, string> = { 'test-pass': 'passing tests', 'test-fail': 'failing tests (ouch)', commit: 'a commit', edit: 'an edit' }

const bar = (value: number) => {
  const filled = Math.round(Math.max(0, Math.min(100, value)) / 10)
  return '█'.repeat(filled) + '░'.repeat(10 - filled)
}
const ago = (ms: number) => {
  const min = Math.floor(ms / 60_000)
  return min < 1 ? 'just now' : min < 60 ? `${min} min ago` : min < 1440 ? `${Math.floor(min / 60)} h ago` : `${Math.floor(min / 1440)} days ago`
}

export default function PetBoard(props: PetProps, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ frame: 0, petted: 0 })
    surface.every(200, () => {
      const s = surface.state
      if (s) surface.setState({ frame: s.frame + 1, petted: Math.max(0, s.petted - 1) })
    })
    surface.onPointer(ev => {
      const s = surface.state
      if (s && ev.type === 'down') surface.setState({ ...s, petted: 8 })
    })
  }

  const s = surface.state
  const pet = props?.pet
  if (!pet) return <Text dimColor>pet · waiting for the plugin to load it</Text>

  const now = props?.now ?? pet.at
  const mood = moodAt(pet, now)
  const feel = feeling(mood)
  const lvl = level(pet.xp)
  // a blink for one frame in every five seconds
  const eyes = (s?.frame ?? 1) % 25 === 0 ? '-.-' : EYES[feel]
  const art = ART[stage(pet.xp)].map(line => line.replace('{e}', eyes))
  return (
    <Box flexDirection="row" borderStyle="round" borderColor={COLORS[feel]} paddingX={1}>
      <Box flexDirection="column" marginRight={3}>
        <Text color="magentaBright">{s?.petted ? '   ♥   ♥   ' : ' '}</Text>
        {art.map(line => <Text color={COLORS[feel]}>{line}</Text>)}
      </Box>
      <Box flexDirection="column">
        <Text bold>{`${stage(pet.xp)} · level ${lvl}`}</Text>
        <Text dimColor>{`${pet.xp} xp · next level at ${10 * (lvl + 1) ** 2}`}</Text>
        <Text>{'mood '}<Text color={COLORS[feel]}>{bar(mood)}</Text>{` ${feel}`}</Text>
        <Text dimColor>{`tests passed ${pet.tests} · failed ${pet.fails} · commits ${pet.commits} · edits ${pet.edits}`}</Text>
        <Text dimColor>{pet.last ? `last fed by ${FED_BY[pet.last]}, ${ago(now - pet.at)}` : 'it eats passing tests, commits and edits'}</Text>
        <Text dimColor>{`hatched ${ago(now - pet.born)} · click to pet · /arcade stop closes`}</Text>
      </Box>
    </Box>
  )
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { newPong, nudge, place, tick, WIN, type PongGame } from '../games/pong.ts'

type State = Base & { game?: PongGame }

export default function Pong(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => ({
    bw: Math.max(16, Math.min(40, Math.floor((surface.columns - 2) / 2))),
    bh: Math.max(8, Math.min(15, surface.rows - 3)),
  })
  // the first key or click of a round starts it
  const ensure = (s: State): State => {
    if (s.game && !s.game.over) return s
    const { bw, bh } = size()
    return { ...s, game: newPong(bw, bh) }
  }

  if (surface.state === undefined) {
    surface.setState(base(props))
    surface.every(100, () => {
      const s = surface.state
      if (!s?.game || !s.playing || s.game.over) return
      const game = tick(s.game)
      // best is the winning margin
      if (game.over) surface.post({ game: 'pong', score: game.scoreYou - game.scoreCpu })
      surface.setState({ ...s, game })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p' || k === ' ') {
        if (s.game && !s.game.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        const { bw, bh } = size()
        surface.setState({ ...s, banner: false, playing: true, game: newPong(bw, bh) })
        return
      }
      const rows = k === 'up' || k === 'w' ? -2 : k === 'down' || k === 's' ? 2 : 0
      if (!rows) return
      const next = ensure(s)
      surface.setState({ ...next, banner: false, playing: true, game: nudge(next.game!, rows) })
    })
    // the paddle follows the pointer over the board (the border takes the first row)
    surface.onPointer(ev => {
      const s = surface.state
      if (!s || (ev.type !== 'move' && ev.type !== 'down')) return
      if (ev.type === 'move' && (!s.game || s.game.over || !s.playing)) return
      const next = ensure(s)
      surface.setState({ ...next, banner: false, playing: true, game: place(next.game!, ev.y - 1) })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh } = g ? { bw: g.w, bh: g.h } : size()
  const rows = grid(Text, bw, bh, (x, y) => {
    if (!g) return x === Math.floor(bw / 2) && y % 2 === 0 ? [' ·', 'gray'] : ['  ']
    if (x === 0 && y >= g.you && y < g.you + g.pad) return ['██', 'cyan']
    const cpu = Math.round(g.cpu)
    if (x === bw - 1 && y >= cpu && y < cpu + g.pad) return ['██', 'magenta']
    if (x === g.ball.x && y === Math.round(g.ball.y)) return ['██', 'whiteBright']
    return x === Math.floor(bw / 2) && y % 2 === 0 ? [' ·', 'gray'] : ['  ']
  })
  const text = !g ? `pong · click here, then ↑↓ or move the mouse · first to ${WIN}`
    : g.over ? `pong · ${g.scoreYou > g.scoreCpu ? 'you win' : 'cpu wins'} ${g.scoreYou}:${g.scoreCpu} · r plays again`
    : !s?.playing ? `pong · paused · you ${g.scoreYou} : ${g.scoreCpu} cpu · space resumes`
    : `pong · you ${g.scoreYou} : ${g.scoreCpu} cpu · first to ${WIN} · ↑↓ or the mouse`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? (g.scoreYou > g.scoreCpu ? 'green' : 'red') : 'white'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best margin ${props?.best ?? 0}`)}
    </Box>
  )
}

