import type { ClientSurface } from 'claude-code'
import { base, claudeDone, statusLine, type Base, type Props } from './common.tsx'
import { move, new2048, SIZE, type G2048 } from '../games/twenty48.ts'

const TILE_COLORS: Record<number, string> = { 2: 'white', 4: 'whiteBright', 8: 'yellow', 16: 'yellowBright', 32: '#ff8800', 64: 'red', 128: 'magenta', 256: 'magentaBright', 512: 'blue', 1024: 'cyan', 2048: 'green' }
const SLIDE_KEYS: Record<string, string> = { left: 'left', right: 'right', up: 'up', down: 'down', a: 'left', d: 'right', w: 'up', s: 'down' }
type State = Base & { game: G2048 }

export default function Twenty48(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), game: new2048() })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key.toLowerCase()
      if (k === 'r') {
        surface.setState({ ...s, banner: false, game: new2048() })
        return
      }
      if (!Object.hasOwn(SLIDE_KEYS, k)) {
        if (s.banner) surface.setState({ ...s, banner: false })
        return
      }
      const game = move(s.game, SLIDE_KEYS[k])
      if (game.over && !s.game.over) surface.post({ game: '2048', score: game.score })
      surface.setState({ ...s, banner: false, game })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const rows = Array.from({ length: SIZE }, (_, y) => (
    <Text>
      {Array.from({ length: SIZE }, (_, x) => {
        const v = g?.cells[y * SIZE + x] ?? 0
        const label = `${v ? String(v) : '·'}`.padStart(5) + ' '
        return v >= 128
          ? <Text color={TILE_COLORS[v] ?? 'greenBright'} bold>{label}</Text>
          : <Text color={v ? TILE_COLORS[v] : 'gray'}>{label}</Text>
      })}
    </Text>
  ))
  const text = !g ? '2048'
    : g.over ? `2048 · no moves left · score ${g.score} · r plays again`
    : `2048 · score ${g.score}${g.won ? ' · 2048 reached, keep going' : ''} · click here, then arrows or wasd · r restarts`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : 'yellow'} width={SIZE * 6 + 3}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, statusLine, type Base, type Props } from './common.tsx'
import { accuracy, newTyping, press, wpm, type TypingGame } from '../games/typing.ts'

type State = Base & { game: TypingGame; ms: number; started: boolean }
type Run = [text: string, color: string, bg?: string]

export default function Typing(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const fresh = (s: State): State => ({ ...s, banner: false, playing: false, started: false, ms: 0, game: newTyping(Math.random, Math.max(20, surface.columns - 4)) })

  if (surface.state === undefined) {
    surface.setState({ ...base(props), game: newTyping(), ms: 0, started: false })
    // the clock runs from the first key to the last correct one, and stops while Claude's banner shows
    surface.every(100, () => {
      const s = surface.state
      if (s?.started && s.playing && !s.game.done) surface.setState({ ...s, ms: s.ms + 100 })
    })
    surface.onKey(({ key, ctrl, meta }) => {
      const s = surface.state
      if (!s || ctrl || meta) return
      // Tab skips to another line; Enter after a finished line starts the next
      if (key === 'tab' || (key === 'return' && s.game.done)) return surface.setState(fresh(s))
      // the space bar may arrive as the character or by name
      const game = press(s.game, key === 'space' ? ' ' : key)
      if (game === s.game) return
      if (game.done) surface.post({ game: 'typing', score: wpm(game.text.length, s.ms) })
      surface.setState({ ...s, banner: false, playing: true, started: true, game })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  if (!s || !g) return <Text dimColor>typing</Text>

  // typed characters green when right, the expected character on red when wrong, the cursor
  // inverted, the rest dim; one span per run of the same style
  const runs: Run[] = []
  for (let i = 0; i < g.text.length; i++) {
    const style: Run = i < g.typed.length
      ? g.typed[i] === g.text[i] ? [g.text[i], 'green'] : [g.text[i], 'whiteBright', 'red']
      : i === g.typed.length ? [g.text[i], 'black', 'white'] : [g.text[i], 'gray']
    const last = runs[runs.length - 1]
    if (last && last[1] === style[1] && last[2] === style[2]) last[0] += style[0]
    else runs.push(style)
  }
  const seconds = (s.ms / 1000).toFixed(1)
  const text = g.done ? `typing · ${wpm(g.text.length, s.ms)} wpm · ${accuracy(g)}% accuracy · ${seconds}s · Enter for another line`
    : !s.started ? 'typing · click here and type the line · Tab skips to another'
    : `typing · ${wpm(g.typed.length, s.ms)} wpm · ${accuracy(g)}% · ${seconds}s · Tab skips`
  return (
    <Box flexDirection="column">
      <Box borderStyle="round" borderColor={g.done ? 'green' : 'gray'} paddingX={1}>
        <Text>{runs.map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
      </Box>
      {statusLine(Text, s.banner, `${text} · best ${props?.best ?? 0} wpm`)}
    </Box>
  )
}

// How /arcade random and /arcade auto choose a game. Pure; the hooks module supplies the context.

export type AutoContext = {
  // a model turn is running, and for how long
  working: boolean
  turnMs: number
  // the pet's last event (test-pass, test-fail, commit, edit) and how long ago it was
  lastEvent?: string
  lastEventAgoMs?: number
  lastGame?: string
}

// a random game from the pool, not the one just played when there is another
export function pickRandom(pool: string[], last: string | undefined, rand = Math.random): string {
  const fresh = pool.filter(g => g !== last)
  const from = fresh.length ? fresh : pool
  return from[Math.floor(rand() * from.length)]
}

// a game for the moment: tests that just failed send you to the pet; a long turn gets a game you
// can sink into; a short one a quick round; an idle Claude something you can put down any time
export function pickAuto(ctx: AutoContext, rand = Math.random): { game: string; reason: string } {
  if (ctx.lastEvent === 'test-fail' && (ctx.lastEventAgoMs ?? Infinity) < 5 * 60_000) {
    return { game: 'pet', reason: 'tests just failed, your pet could use a visit' }
  }
  if (ctx.working && ctx.turnMs >= 60_000) {
    const min = Math.floor(ctx.turnMs / 60_000)
    return { game: pickRandom(['tetris', 'invaders', 'doom', 'snake'], ctx.lastGame, rand), reason: `Claude has been working ${min} min, time for a longer game` }
  }
  if (ctx.working) {
    return { game: pickRandom(['flappy', 'pong', 'typing'], ctx.lastGame, rand), reason: 'Claude is working, a quick round' }
  }
  return { game: pickRandom(['2048', 'minesweeper'], ctx.lastGame, rand), reason: 'Claude is idle, a game you can put down any time' }
}

// Which score counts as a new best. Minesweeper's best is its fastest clear, so lower wins there;
// everywhere else higher wins. A score of zero or less never counts: a Minesweeper board whose
// first click clears it takes 0 s and would otherwise lock the best forever, and a Pong match you
// lost posts a negative margin.
export function isBetter(score: number, prev: number | undefined, lowerIsBetter = false): boolean {
  if (!Number.isFinite(score) || score <= 0) return false
  if (prev === undefined || prev <= 0) return true
  return lowerIsBetter ? score < prev : score > prev
}

// Doom: a raycaster corridor shooter, drawn by the Doom board in ../boards/doom.tsx.
// One map cell is one square unit, the player is a point with a radius, angles are radians and
// grow clockwise on screen (+x east, +y south). One tick is one 50 ms frame.
//
// One key press is one step. A terminal sends presses and nothing else — no release, and it repeats
// only the key held last — so anything that keeps moving you after a press has to guess when you
// stopped, and guessing wrong feels worse than a short step. Hold a key and the terminal's own
// repeat walks you; spam the keys and you go exactly as far as you pressed.
//
// A floor is a block of text: walls are 1 (brown), 2 (grey), 3 (green), D a locked door and X the
// exit switch. Everything else stands on the floor and is lifted out when the level is parsed —
// S the spawn, i d z the monsters, + a b g c k the pickups.

export type Kind = 'imp' | 'demon' | 'zombie'
// bite counts down to the next time this one can claw you; hurt is the white flash of being shot
type Enemy = { kind: Kind; x: number; y: number; hp: number; hurt: number; bite?: number }
export type ItemKind = 'health' | 'shells' | 'bullets' | 'shotgun' | 'chaingun' | 'key'
type Item = { kind: ItemKind; x: number; y: number }
export type Weapon = 'pistol' | 'shotgun' | 'chaingun'
type Ball = { x: number; y: number; dx: number; dy: number }
type Ray = { dist: number; side: 0 | 1; kind: string }
type Pt = readonly [number, number]
export type DoomGame = {
  level: number
  map: string[]
  exits: Pt[]
  px: number; py: number; dir: number
  enemies: Enemy[]; balls: Ball[]; items: Item[]
  health: number; bullets: number; shells: number
  weapon: Weapon; owned: Weapon[]; key: boolean
  // frames until the weapon can fire again, frames left on the muzzle flash and on the pain flash
  cool: number; flash: number; pain: number
  kills: number; ticks: number; over: boolean
  // what just happened, and the tick it happened on, for the status line
  said: string; saidAt: number
}

const MONSTER: Record<Kind, { hp: number; speed: number; melee: number; reach: number; shot: number }> = {
  // an imp throws fireballs, a demon only bites but is fast and takes a beating, a zombie shoots
  // Speeds are cells a frame. A key press moves you 0.3 and you can press several times a frame by
  // holding the key, so these sit well under that: a monster that keeps pace with someone spamming
  // keys is a monster you can never get away from. Measured against a bot playing at 7, 10 and 20
  // presses a second; the slowest of those has to be able to finish a floor.
  imp: { hp: 60, speed: 0.038, melee: 7, reach: 0, shot: 0 },
  demon: { hp: 110, speed: 0.07, melee: 12, reach: 0, shot: 0 },
  zombie: { hp: 30, speed: 0.03, melee: 4, reach: 10, shot: 5 },
}
