    '3..2..1..22.222..1..2..3',
    '3..2..1..........1..2..3',
    '3..2..1..z....i..1..2..3',
    '3.....1111111D1111.....3',
    '3..a...................3',
    '3.....2..2..k..2..2....3',
    '3..b..2..2..2..2..2..+.3',
    '3.z.......d.........i..3',
    '333333333333333333333333',
  ],
  [
    '222222222222222222222222',
    '2...b..2S......2....a..2',
    '2......2...d...2.......2',
    '2......2.......2...i...2',
    '2.11.112.22.222D2222.222',
    '2.1....2....a....2.....2',
    '2.1.z..D....k....2..d..2',
    '2.1....2.........2.....2',
    '2.111112.2222222.2.....2',
    '2...+....2.....2.2222.22',
    '2..i..d..2..i..2.......2',
    '2........2.....2...zz..2',
    '22.2222.22..a..2.......2',
    '2...b...2.......2222.222',
    '2...c...2..111111..D...2',
    '2.......2..1XXX.1..1.d.2',
    '2.222.222..1...11..1...2',
    '2.....+....1.i.....1.b.2',
    '2..z.......111111111...2',
    '222222222222222222222222',
  ],
]

export const at = (map: string[], x: number, y: number): string => map[y]?.[x] ?? '2'
export const solid = (cell: string) => cell !== '.' && cell !== 'S'
const put = (map: string[], x: number, y: number, ch: string): string[] =>
  map.map((row, ry) => (ry === y ? row.slice(0, x) + ch + row.slice(x + 1) : row))

// the player's box, not its centre, so you cannot clip a corner
export const blocked = (map: string[], x: number, y: number): boolean => {
  for (const dx of [-RADIUS, RADIUS]) for (const dy of [-RADIUS, RADIUS]) {
    if (solid(at(map, Math.floor(x + dx), Math.floor(y + dy)))) return true
  }
  return false
}

// DDA: step to the next grid line on whichever axis is nearer until a wall. The distance is the
// Euclidean ray length; a view multiplies it by cos(angle - dir) to undo the fisheye.
export function cast(map: string[], x: number, y: number, angle: number, max = 40): Ray {
  const dx = Math.cos(angle)
  const dy = Math.sin(angle)
  const ddx = dx === 0 ? Infinity : Math.abs(1 / dx)
  const ddy = dy === 0 ? Infinity : Math.abs(1 / dy)
  let mx = Math.floor(x)
  let my = Math.floor(y)
  let sdx = dx < 0 ? (x - mx) * ddx : (mx + 1 - x) * ddx
  let sdy = dy < 0 ? (y - my) * ddy : (my + 1 - y) * ddy
  let side: 0 | 1 = 0
  for (let steps = 0; steps < 256; steps++) {
    if (sdx < sdy) { sdx += ddx; mx += dx < 0 ? -1 : 1; side = 0 }
    else { sdy += ddy; my += dy < 0 ? -1 : 1; side = 1 }
    const dist = side === 0 ? sdx - ddx : sdy - ddy
    if (dist > max) break
    const cell = at(map, mx, my)
    if (solid(cell)) return { dist: Math.max(1e-4, dist), side, kind: cell }
  }
  return { dist: max, side: 0, kind: '2' }
}

// is b in plain sight from a, and how far
const sight = (map: string[], ax: number, ay: number, bx: number, by: number) => {
  const d = Math.hypot(bx - ax, by - ay)
  return { d, clear: cast(map, ax, ay, Math.atan2(by - ay, bx - ax), d + 1).dist >= d }
}

// to -PI..PI, so a difference of angles reads as left or right
export const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a))

type Level = { map: string[]; exits: Pt[]; px: number; py: number; enemies: Enemy[]; items: Item[] }

// the text of a floor, with everything that stands on it lifted out and the cell left as floor
export function parseLevel(src: string[]): Level {
  const enemies: Enemy[] = []
  const items: Item[] = []
  const exits: Pt[] = []
  let px = 1.5
  let py = 1.5
  const map = src.map((row, y) =>
    [...row].map((cell, x) => {
      if (cell === 'X') { exits.push([x, y]); return cell }
      if (cell === 'S') { px = x + 0.5; py = y + 0.5; return '.' }
      const monster = SPAWNS[cell]
      if (monster) { enemies.push({ kind: monster, x: x + 0.5, y: y + 0.5, hp: MONSTER[monster].hp, hurt: 0 }); return '.' }
      const item = PICKUP[cell]
      if (item) { items.push({ kind: item, x: x + 0.5, y: y + 0.5 }); return '.' }
      return cell
    }).join(''),
  )
  return { map, exits, px, py, enemies, items }
}

const levelAt = (level: number) => LEVELS[(level - 1) % LEVELS.length]

// Which way to look when a floor starts. Pointing straight at the door is not enough — on most
// floors a wall stands between you and it, so the bearing lands on masonry. Walk the route to the
// door instead and look as far along it as you can actually see: the way out, from the first frame.
function route(map: string[], from: Pt, to: Pt): Pt[] {
  const came = new Map<string, Pt | null>([[`${from[0]},${from[1]}`, null]])
  const queue: Pt[] = [from]
  while (queue.length) {
    const cur = queue.shift()!
    if (cur[0] === to[0] && cur[1] === to[1]) {
      const path: Pt[] = []
      for (let at: Pt | null = cur; at; at = came.get(`${at[0]},${at[1]}`) ?? null) path.unshift(at)
      return path
    }
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) {
      const next: Pt = [cur[0] + dx, cur[1] + dy]
      const cell = at(map, next[0], next[1])
      // a locked door is on the way to itself, so it counts as walkable here
      if (came.has(`${next[0]},${next[1]}`) || (solid(cell) && cell !== 'D')) continue
      came.set(`${next[0]},${next[1]}`, cur)
      queue.push(next)
    }
  }
  return []
}

export function facing(map: string[], exits: Pt[], px: number, py: number): number {
  const doors: Pt[] = []
  for (let y = 0; y < map.length; y++) for (let x = 0; x < map[y].length; x++) {
    if (at(map, x, y) === 'D') doors.push([x, y])
  }
  const marks = doors.length ? doors : exits
  if (!marks.length) return 0
  const near = (m: Pt) => Math.hypot(m[0] + 0.5 - px, m[1] + 0.5 - py)
  const target = marks.reduce((best, m) => (near(m) < near(best) ? m : best))
  const path = route(map, [Math.floor(px), Math.floor(py)], target)
  const bearing = (m: Pt) => Math.atan2(m[1] + 0.5 - py, m[0] + 0.5 - px)
  if (!path.length) return bearing(target)

  // the furthest step of the route still in plain sight: a corridor mouth, a doorway, the door
  let look = bearing(target)
  for (const step of path) {
    const d = Math.hypot(step[0] + 0.5 - px, step[1] + 0.5 - py)
    if (d < 1) continue
    const angle = bearing(step)
    if (cast(map, px, py, angle, d + 1).dist < d) break
    look = angle
  }
  return look
}

export function newDoom(level = 1): DoomGame {
  const l = parseLevel(levelAt(level))
  return {
    level, map: l.map, exits: l.exits, px: l.px, py: l.py, dir: facing(l.map, l.exits, l.px, l.py),
    enemies: l.enemies, balls: [], items: l.items,
    health: 100, bullets: 50, shells: 0,
    weapon: 'pistol', owned: ['pistol'], key: false,
    cool: 0, flash: 0, pain: 0, kills: 0, ticks: 0, over: false,
    said: '', saidAt: 0,
  }
}

// the exit switch keeps what you are carrying and hands you the next floor
function nextLevel(g: DoomGame): DoomGame {
  const l = parseLevel(levelAt(g.level + 1))
  return {
    ...g,
    level: g.level + 1, map: l.map, exits: l.exits, px: l.px, py: l.py, dir: facing(l.map, l.exits, l.px, l.py),
    enemies: l.enemies, balls: [], items: l.items,
    key: false, cool: 0, flash: 0, pain: 0,
    bullets: g.bullets + 10,
    said: `floor ${g.level + 1}`,
    saidAt: g.ticks,
  }
}

// what just happened, stamped with the frame it happened on so the view can fade it. Stamping at
// the source matters: picking up a second health box says 'health' again, and a message compared
// against the last one would take the repeat for no news at all.
const say = (g: DoomGame, said: string): DoomGame => ({ ...g, said, saidAt: g.ticks })

export const turn = (g: DoomGame, radians: number): DoomGame =>
  g.over ? g : { ...g, dir: wrap(g.dir + radians) }

// swapping weapons takes a moment, so it is not a free dodge out of an empty gun
export const select = (g: DoomGame, weapon: Weapon): DoomGame =>
  g.over || !g.owned.includes(weapon) ? g : say({ ...g, weapon, cool: Math.max(g.cool, 4) }, weapon)

// each axis on its own, so a wall you walk into slides you along it instead of stopping you dead
export function move(g: DoomGame, forward: number, strafe = 0): DoomGame {
  if (g.over) return g
  const dx = Math.cos(g.dir) * forward - Math.sin(g.dir) * strafe
  const dy = Math.sin(g.dir) * forward + Math.cos(g.dir) * strafe
  const px = blocked(g.map, g.px + dx, g.py) ? g.px : g.px + dx
  const py = blocked(g.map, g.px, g.py + dy) ? g.py : g.py + dy
  if (px !== g.px || py !== g.py) return { ...g, px, py }

  // Nothing moved: the corner of your shoulder is on the corner of a wall, which is the one place
  // walking forward does nothing at all and feels broken. Step a little to whichever side opens the
  // way — and only if it does, so walking into a flat wall still just stops.
  const len = Math.hypot(dx, dy)
  if (!len) return g
  for (const side of [1, -1]) {
    const ox = (-dy / len) * RADIUS * side
    const oy = (dx / len) * RADIUS * side
    if (blocked(g.map, g.px + ox, g.py + oy)) continue
    if (blocked(g.map, g.px + ox + dx, g.py + oy + dy)) continue
    return { ...g, px: g.px + ox, py: g.py + oy }
  }
  return g
}

// one pellet: the nearest monster inside its cone and in front of the wall takes the damage
function pellet(g: DoomGame, enemies: Enemy[], angle: number, damage: number): { enemies: Enemy[]; killed: number } {
  const wall = cast(g.map, g.px, g.py, angle).dist
  let best: { i: number; d: number } | undefined
  enemies.forEach((e, i) => {
    const d = Math.hypot(e.x - g.px, e.y - g.py)
    if (d > wall) return
    // a monster is about half a cell wide, so it covers less of the view the further away it is
    if (Math.abs(wrap(Math.atan2(e.y - g.py, e.x - g.px) - angle)) > Math.atan2(0.45, d)) return
    if (!best || d < best.d) best = { i, d }
  })
  if (!best) return { enemies, killed: 0 }
  const hit = enemies.map((e, i) => (i === best?.i ? { ...e, hp: e.hp - damage, hurt: 2 } : e))
  const alive = hit.filter(e => e.hp > 0)
  return { enemies: alive, killed: hit.length - alive.length }
}

// what to reach for when the gun in your hands clicks empty: the heaviest thing with ammo in it,
// derived from the table so a weapon added there is never quietly left out of the fallback
const FALLBACK = (Object.keys(WEAPON) as Weapon[])
  .sort((a, b) => WEAPON[b].damage * WEAPON[b].pellets - WEAPON[a].damage * WEAPON[a].pellets)

export function fire(g: DoomGame): DoomGame {
  if (g.over || g.cool > 0) return g
  const spec = WEAPON[g.weapon]
  if (g[spec.ammo] <= 0) {
    // an empty gun switches itself rather than doing nothing while something walks into you
    const next = FALLBACK.find(w => w !== g.weapon && g.owned.includes(w) && g[WEAPON[w].ammo] > 0)
    return next
      ? say(select(g, next), `out of ${spec.ammo} · ${next}`)
      : say({ ...g, cool: 8 }, `out of ${spec.ammo}`)
  }
  let enemies = g.enemies
  let kills = g.kills
  for (let p = 0; p < spec.pellets; p++) {
    // the pellets of a shell spread either side of where you aimed
    const angle = g.dir + (spec.pellets === 1 ? 0 : (p - (spec.pellets - 1) / 2) * (spec.spread ?? 0))
    const shot = pellet(g, enemies, angle, spec.damage)
    enemies = shot.enemies
    kills += shot.killed
  }
  return { ...g, enemies, kills, cool: spec.cool, flash: 4, [spec.ammo]: g[spec.ammo] - 1 }
}

const take = (g: DoomGame, item: Item): DoomGame => {
  switch (item.kind) {
    case 'health': return say({ ...g, health: Math.min(100, g.health + 25) }, 'health')
    case 'shells': return say({ ...g, shells: g.shells + 8 }, 'shells')
    case 'bullets': return say({ ...g, bullets: g.bullets + 20 }, 'bullets')
    case 'key': return say({ ...g, key: true }, 'red key')
    case 'shotgun':
    case 'chaingun': return say({
      ...g,
      owned: g.owned.includes(item.kind) ? g.owned : [...g.owned, item.kind],
      weapon: item.kind,
      shells: item.kind === 'shotgun' ? g.shells + 8 : g.shells,
      bullets: item.kind === 'chaingun' ? g.bullets + 20 : g.bullets,
    }, item.kind)
  }
}

// a locked door in reach opens once, and stays open, when you carry the key
function openDoors(g: DoomGame): DoomGame {
  if (!g.key) return g
  for (let y = Math.floor(g.py) - 1; y <= Math.floor(g.py) + 1; y++) {
    for (let x = Math.floor(g.px) - 1; x <= Math.floor(g.px) + 1; x++) {
      if (at(g.map, x, y) === 'D') return say({ ...g, map: put(g.map, x, y, '.') }, 'the door opens')
    }
  }
  return g
}

export function tick(g: DoomGame, rand = Math.random): DoomGame {
  if (g.over) return g
  const ticks = g.ticks + 1
  let health = g.health
  const balls: Ball[] = []

  const enemies = g.enemies.map(e => {
    const spec = MONSTER[e.kind]
    const { d, clear } = sight(g.map, e.x, e.y, g.px, g.py)
    const hurt = Math.max(0, e.hurt - 1)
    const bite = e.bite ?? BITE_EVERY
    if (!clear || d > 16) return { ...e, hurt, bite: BITE_EVERY }
    // its own cooldown, not a shared frame phase: on a global phase three monsters reaching you
    // together all land on the same frame, and one arriving just before it comes round bites at
    // once while another waits most of a second. The counter only runs while it is on you, so
    // closing in always costs it the same wind-up.
    if (d < REACH) {
      if (bite > 0) return { ...e, hurt, bite: bite - 1 }
      health -= spec.melee
      return { ...e, hurt, bite: BITE_EVERY }
    }
    if (e.kind === 'imp' && d > 2.5 && rand() < THROW_CHANCE) {
      const a = Math.atan2(g.py - e.y, g.px - e.x)
      balls.push({ x: e.x, y: e.y, dx: Math.cos(a) * BALL_SPEED, dy: Math.sin(a) * BALL_SPEED })
    }
    if (spec.reach && d < spec.reach && rand() < SHOOT_CHANCE) health -= spec.shot
    // toward you, each axis on its own so a monster rounds a corner instead of hugging it
    const sx = e.x + Math.sign(g.px - e.x) * spec.speed
    const sy = e.y + Math.sign(g.py - e.y) * spec.speed
    return {
      ...e,
      hurt,
      bite: BITE_EVERY,
      x: solid(at(g.map, Math.floor(sx), Math.floor(e.y))) ? e.x : sx,
      y: solid(at(g.map, Math.floor(e.x), Math.floor(sy))) ? e.y : sy,
    }
  })

  for (const b of g.balls) {
    const x = b.x + b.dx
    const y = b.y + b.dy
    if (solid(at(g.map, Math.floor(x), Math.floor(y)))) continue
    if (Math.hypot(x - g.px, y - g.py) < 0.5) { health -= BALL_HIT; continue }
    balls.push({ ...b, x, y })
  }

  let next: DoomGame = {
    ...g, ticks, enemies, balls, health,
    pain: health < g.health ? 6 : Math.max(0, g.pain - 1),
    flash: Math.max(0, g.flash - 1),
    cool: Math.max(0, g.cool - 1),
    over: health <= 0,
  }
  if (next.over) return say({ ...next, health: 0 }, 'you died')

  // what you walk over you pick up, what you walk into opens, and the exit switch ends the floor
  for (const item of next.items) {
    if (Math.hypot(item.x - next.px, item.y - next.py) > GRAB) continue
    next = { ...take(next, item), items: next.items.filter(i => i !== item) }
  }
  next = openDoors(next)
  if (next.exits.some(([x, y]) => Math.hypot(x + 0.5 - next.px, y + 0.5 - next.py) < 1.2)) next = nextLevel(next)
  return next
}

// Flappy: pure game logic, drawn by the Flappy module in ../surface.tsx.
// Units are board cells; one tick is one 100 ms frame.

export type Pipe = { x: number; gap: number }
export type FlappyGame = { w: number; h: number; y: number; vy: number; pipes: Pipe[]; score: number; over: boolean }

export const BIRD_X = 4
// tuned so a flap every second or so holds height; the first try (0.3 / -1.1 / 1.2) hit the floor
// about a second after the first flap
const GRAVITY = 0.15
const FLAP = -0.9
const MAX_FALL = 0.8
const SPACING = 12

// the opening is a third of the board, at least three rows
export const gapSize = (h: number) => Math.max(3, Math.floor(h / 3))
const randomGap = (h: number, rand: () => number) => 1 + Math.floor(rand() * Math.max(1, h - gapSize(h) - 1))

export function newFlappy(w: number, h: number, rand = Math.random): FlappyGame {
  return { w, h, y: h / 2, vy: 0, pipes: [{ x: w - 1, gap: randomGap(h, rand) }], score: 0, over: false }
}

export const flap = (g: FlappyGame): FlappyGame => (g.over ? g : { ...g, vy: FLAP })

// the bird's row, as drawn and as collisions see it
export const birdRow = (g: FlappyGame) => Math.round(g.y)

// one tick: gravity, the pipes move a column left, a pipe passing the bird scores, and the round
// ends on the floor or a pipe; the ceiling stops the bird instead of ending the round
export function tick(g: FlappyGame, rand = Math.random): FlappyGame {
  if (g.over) return g
  let vy = Math.min(MAX_FALL, g.vy + GRAVITY)
  let y = g.y + vy
  if (y < 0) {
    y = 0
    vy = 0
  }
  let pipes = g.pipes.map(p => ({ ...p, x: p.x - 1 })).filter(p => p.x >= 0)
  const last = pipes[pipes.length - 1]
  if (!last || last.x <= g.w - 1 - SPACING) pipes = [...pipes, { x: g.w - 1, gap: randomGap(g.h, rand) }]
  const score = g.score + pipes.filter(p => p.x === BIRD_X - 1).length
  const row = Math.round(y)
  const hit = row < 0 || row >= g.h || pipes.some(p => p.x === BIRD_X && (row < p.gap || row >= p.gap + gapSize(g.h)))
  return { ...g, y, vy, pipes, score, over: hit }
}

// Space Invaders: pure game logic, drawn by the Invaders board in ../boards/invaders.tsx.
// Units are board cells; one tick is one 100 ms frame. The ship sits on the bottom row.

export type Pt = readonly [number, number]
export type InvadersGame = {
  w: number; h: number
  ship: number
  shots: Pt[]; bombs: Pt[]; aliens: Pt[]
  dir: 1 | -1
  ticks: number; score: number; lives: number; wave: number; over: boolean
}

const COLS = 8
const ROWS = 3
const BOMB_CHANCE = 0.12
const same = (a: Pt, b: Pt) => a[0] === b[0] && a[1] === b[1]

// a formation of COLS × ROWS aliens two cells apart, centred; each wave starts a row lower (at most 3)
export function formation(w: number, wave: number): Pt[] {
  const left = Math.max(0, Math.floor((w - COLS * 2) / 2))
  const top = 1 + Math.min(wave - 1, 3)
  const out: Pt[] = []
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) out.push([left + c * 2, top + r])
  return out
}

export const newInvaders = (w: number, h: number): InvadersGame => ({
  w, h, ship: Math.floor(w / 2), shots: [], bombs: [], aliens: formation(w, 1), dir: 1, ticks: 0, score: 0, lives: 3, wave: 1, over: false,
})

// ticks between formation steps: fewer aliens and later waves step faster
export const stepEvery = (g: InvadersGame) => Math.max(1, Math.round(g.aliens.length / 3) - (g.wave - 1))

export const shift = (g: InvadersGame, dx: number): InvadersGame =>
  g.over ? g : { ...g, ship: Math.max(0, Math.min(g.w - 1, g.ship + dx)) }

// one shot on screen at a time, as in the original
export const fire = (g: InvadersGame): InvadersGame => (g.over || g.shots.length ? g : { ...g, shots: [[g.ship, g.h - 2]] })

// a shot and an alien in the same cell remove each other, ten points each
function hits(g: InvadersGame): InvadersGame {
  const shots = g.shots.filter(s => !g.aliens.some(a => same(a, s)))
  const aliens = g.aliens.filter(a => !g.shots.some(s => same(a, s)))
  return { ...g, shots, aliens, score: g.score + (g.aliens.length - aliens.length) * 10 }
}

export function tick(g: InvadersGame, rand = Math.random): InvadersGame {
  if (g.over) return g
  let next: InvadersGame = { ...g, ticks: g.ticks + 1, shots: g.shots.map(([x, y]): Pt => [x, y - 1]).filter(([, y]) => y >= 0) }
  next = hits(next)

  // the formation steps sideways, or down and back at an edge
  if (next.aliens.length && next.ticks % stepEvery(next) === 0) {
    const dir = next.dir
    const edge = next.aliens.some(([x]) => x + dir < 0 || x + dir >= next.w)
    next = edge
      ? { ...next, dir: dir === 1 ? -1 : 1, aliens: next.aliens.map(([x, y]): Pt => [x, y + 1]) }
      : { ...next, aliens: next.aliens.map(([x, y]): Pt => [x + dir, y]) }
    next = hits(next)
  }

  // bombs fall; now and then the lowest alien of a random column drops a new one
  let bombs = next.bombs.map(([x, y]): Pt => [x, y + 1]).filter(([, y]) => y < next.h)
  if (next.aliens.length && rand() < BOMB_CHANCE) {
    const picked = next.aliens[Math.floor(rand() * next.aliens.length)]
    const lowest = next.aliens.filter(a => a[0] === picked[0]).reduce((m, a) => (a[1] > m[1] ? a : m))
    bombs = [...bombs, [lowest[0], lowest[1] + 1]]
  }
  const hit = bombs.some(([x, y]) => y === next.h - 1 && x === next.ship)
  const lives = next.lives - (hit ? 1 : 0)
  const landed = next.aliens.some(([, y]) => y >= next.h - 1)
  next = { ...next, bombs: hit ? [] : bombs, lives, over: lives <= 0 || landed }

  // a cleared wave brings the next, a row lower and faster
  if (!next.over && !next.aliens.length) {
    next = { ...next, wave: next.wave + 1, aliens: formation(next.w, next.wave + 1), shots: [], bombs: [], dir: 1 }
  }
  return next
}

// Minesweeper: pure game logic, drawn by the Minesweeper module in ../surface.tsx.

export type Tile = { mine: boolean; open: boolean; flag: boolean; n: number }
export type Mines = { w: number; h: number; count: number; tiles: Tile[]; placed: boolean; over: boolean; won: boolean }

export const newMines = (w: number, h: number, count: number): Mines => ({
  w, h, count,
  tiles: Array.from({ length: w * h }, () => ({ mine: false, open: false, flag: false, n: 0 })),
  placed: false, over: false, won: false,
})

const inside = (g: Mines, x: number, y: number) => x >= 0 && y >= 0 && x < g.w && y < g.h

function around(g: Mines, x: number, y: number): number[] {
  const out: number[] = []
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) if ((dx || dy) && inside(g, x + dx, y + dy)) out.push((y + dy) * g.w + x + dx)
  }
  return out
}

// mines go in on the first reveal, never on that cell or next to it, so the first click opens an area
function place(g: Mines, x: number, y: number, rand: () => number): Tile[] {
  const safe = new Set([y * g.w + x, ...around(g, x, y)])
  const spots = g.tiles.map((_, i) => i).filter(i => !safe.has(i))
  const tiles = g.tiles.map(t => ({ ...t }))
  // a partial Fisher-Yates shuffle picks `count` distinct spots
  for (let k = 0; k < Math.min(g.count, spots.length); k++) {
    const j = k + Math.floor(rand() * (spots.length - k))
    ;[spots[k], spots[j]] = [spots[j], spots[k]]
    tiles[spots[k]].mine = true
  }
  tiles.forEach((t, i) => { t.n = around(g, i % g.w, Math.floor(i / g.w)).filter(j => tiles[j].mine).length })
  return tiles
}

// open a cell: a mine ends the round and shows every mine; a zero opens its whole empty area
export function reveal(g: Mines, x: number, y: number, rand = Math.random): Mines {
  if (g.over || g.won || !inside(g, x, y)) return g
  const start = y * g.w + x
  if (g.tiles[start].flag || g.tiles[start].open) return g
  const tiles = g.placed ? g.tiles.map(t => ({ ...t })) : place(g, x, y, rand)
  if (tiles[start].mine) {
    tiles.forEach(t => { if (t.mine) t.open = true })
    return { ...g, tiles, placed: true, over: true }
  }
  const stack = [start]
  while (stack.length) {
    const i = stack.pop()!
    const t = tiles[i]
    if (t.open || t.flag) continue
    t.open = true
    if (t.n === 0) stack.push(...around(g, i % g.w, Math.floor(i / g.w)))
  }
  return { ...g, tiles, placed: true, won: tiles.every(t => t.mine || t.open) }
}

export function flag(g: Mines, x: number, y: number): Mines {
  if (g.over || g.won || !inside(g, x, y) || g.tiles[y * g.w + x].open) return g
  const tiles = g.tiles.map((t, i) => (i === y * g.w + x ? { ...t, flag: !t.flag } : t))
  return { ...g, tiles }
}

// The pet: pure logic. It grows with the work Claude does in any session: tests passing, commits
// and edits give it xp and lift its mood; failing tests hurt its mood; idle time slowly bores it.
// The hooks module feeds it from tool calls and keeps it in $.store; ../boards/pet.tsx draws it.

export type PetEvent = 'test-pass' | 'test-fail' | 'commit' | 'edit'
export type Pet = {
  xp: number
  mood: number
  // when it was last fed, and when it hatched (ms since the epoch)
  at: number
  born: number
  tests: number; fails: number; commits: number; edits: number
  last?: PetEvent
}

const XP: Record<PetEvent, number> = { 'test-pass': 10, 'test-fail': 2, commit: 15, edit: 1 }
const MOOD: Record<PetEvent, number> = { 'test-pass': 8, 'test-fail': -12, commit: 10, edit: 1 }
const BORED = 30

export const newPet = (now: number): Pet => ({ xp: 0, mood: 70, at: now, born: now, tests: 0, fails: 0, commits: 0, edits: 0 })

// test runners across common stacks; a failing run is a tool call that ended in error
const TEST_COMMAND = /\b(bun|npm|pnpm|yarn)\s+(run\s+)?test\b|\bnpx\s+(jest|vitest|mocha)\b|\b(pytest|jest|vitest|rspec|phpunit|mocha)\b|\bgo\s+test\b|\bcargo\s+test\b|\bmake\s+test\b|\b(mvn|gradle|gradlew|sbt)\b.*\btest\b/

// what a finished tool call means for the pet; `ok` is undefined when the call was denied
export function petEvent(tool: string, command: string | undefined, ok: boolean | undefined): PetEvent | undefined {
  if (ok === undefined) return undefined
  if (tool === 'Bash' && command) {
    if (TEST_COMMAND.test(command)) return ok ? 'test-pass' : 'test-fail'
    if (ok && /\bgit\s+commit\b/.test(command) && !/--dry-run\b/.test(command)) return 'commit'
    return undefined
  }
  if (ok && (tool === 'Edit' || tool === 'Write' || tool === 'NotebookEdit')) return 'edit'
  return undefined
}

// idle, mood sinks a point every ten minutes, down to bored; below that only failures take it
export function moodAt(p: Pet, now: number): number {
  if (p.mood <= BORED) return p.mood
  return Math.max(BORED, p.mood - Math.floor(Math.max(0, now - p.at) / 600_000))
}

export function feed(p: Pet, event: PetEvent, now: number): Pet {
  return {
    ...p,
    xp: p.xp + XP[event],
    mood: Math.max(0, Math.min(100, moodAt(p, now) + MOOD[event])),
    at: now,
    last: event,
    tests: p.tests + (event === 'test-pass' ? 1 : 0),
    fails: p.fails + (event === 'test-fail' ? 1 : 0),
    commits: p.commits + (event === 'commit' ? 1 : 0),
    edits: p.edits + (event === 'edit' ? 1 : 0),
  }
}

// level n needs 10·n² xp: level 1 at 10, 2 at 40, 3 at 90, 6 at 360, 10 at 1000
export const level = (xp: number) => Math.floor(Math.sqrt(xp / 10))
export type Stage = 'egg' | 'baby' | 'kid' | 'adult' | 'legend'
export const stage = (xp: number): Stage => {
  const l = level(xp)
  return l >= 10 ? 'legend' : l >= 6 ? 'adult' : l >= 3 ? 'kid' : l >= 1 ? 'baby' : 'egg'
}
export const feeling = (mood: number) => (mood >= 70 ? 'happy' : mood >= 35 ? 'okay' : 'sad')

// Pong against the computer: pure game logic, drawn by the Pong module in ../surface.tsx.
// Your paddle is the left column, the computer's the right; first to WIN points wins.

export type Ball = { x: number; y: number; dx: number; dy: number }
export type PongGame = { w: number; h: number; ball: Ball; you: number; cpu: number; pad: number; scoreYou: number; scoreCpu: number; over: boolean }

export const WIN = 5
// the computer tracks the ball at under a row per tick, so a steep ball gets past it
const CPU_SPEED = 0.6

const serve = (w: number, h: number, towardYou: boolean, rand: () => number): Ball =>
  ({ x: Math.floor(w / 2), y: h / 2, dx: towardYou ? -1 : 1, dy: rand() < 0.5 ? -0.5 : 0.5 })

export function newPong(w: number, h: number, rand = Math.random): PongGame {
  const pad = Math.max(3, Math.floor(h / 4))
  const mid = Math.floor((h - pad) / 2)
  return { w, h, ball: serve(w, h, false, rand), you: mid, cpu: mid, pad, scoreYou: 0, scoreCpu: 0, over: false }
}

const clampPad = (g: PongGame, top: number) => Math.max(0, Math.min(g.h - g.pad, top))

// move your paddle by rows, or to a row (a pointer over the board), keeping it on the board
export const nudge = (g: PongGame, rows: number): PongGame => (g.over ? g : { ...g, you: clampPad(g, g.you + rows) })
export const place = (g: PongGame, row: number): PongGame => (g.over ? g : { ...g, you: clampPad(g, Math.round(row - g.pad / 2)) })

// a paddle at `top` covers the ball's row: send it back, steeper the further from the centre it hits
function returned(g: PongGame, top: number, ball: Ball, dx: number): Ball | undefined {
  const row = Math.round(ball.y)
  if (row < top || row >= top + g.pad) return undefined
  const offset = (row - (top + (g.pad - 1) / 2)) / g.pad
  return { ...ball, dx, dy: Math.max(-1, Math.min(1, ball.dy + offset)) }
}

export function tick(g: PongGame, rand = Math.random): PongGame {
  if (g.over) return g
  let ball: Ball = { ...g.ball, x: g.ball.x + g.ball.dx, y: g.ball.y + g.ball.dy }
  // top and bottom walls
  if (ball.y < 0) ball = { ...ball, y: -ball.y, dy: -ball.dy }
  if (ball.y > g.h - 1) ball = { ...ball, y: 2 * (g.h - 1) - ball.y, dy: -ball.dy }
  // the computer follows the ball while it comes toward it
  const target = ball.y - (g.pad - 1) / 2
  const cpu = ball.dx > 0 ? clampPad(g, g.cpu + Math.max(-CPU_SPEED, Math.min(CPU_SPEED, target - g.cpu))) : g.cpu
  let { scoreYou, scoreCpu } = g
  if (ball.x <= 0) {
    const back = returned(g, g.you, ball, 1)
    if (back) ball = { ...back, x: 1 }
    else { scoreCpu++; ball = serve(g.w, g.h, false, rand) }
  } else if (ball.x >= g.w - 1) {
    const back = returned(g, Math.round(cpu), ball, -1)
    if (back) ball = { ...back, x: g.w - 2 }
    else { scoreYou++; ball = serve(g.w, g.h, true, rand) }
  }
  return { ...g, ball, cpu, scoreYou, scoreCpu, over: scoreYou >= WIN || scoreCpu >= WIN }
}

// Snake: pure game logic, drawn by the Snake module in ../surface.tsx.

export type Pt = readonly [number, number]
export type SnakeGame = { snake: Pt[]; dir: Pt; queued: Pt[]; food: Pt; w: number; h: number; score: number; over: boolean }

const DIRS: Record<string, Pt> = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0], w: [0, -1], s: [0, 1], a: [-1, 0], d: [1, 0] }
const same = (a: Pt, b: Pt) => a[0] === b[0] && a[1] === b[1]

// a random free cell; [-1, -1] once the snake fills the board
export function placeFood(snake: Pt[], w: number, h: number, rand = Math.random): Pt {
  const taken = new Set(snake.map(p => `${p[0]},${p[1]}`))
  const free: Pt[] = []
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (!taken.has(`${x},${y}`)) free.push([x, y])
  return free.length ? free[Math.floor(rand() * free.length)] : [-1, -1]
}

export function newSnake(w: number, h: number, rand = Math.random): SnakeGame {
  const x = Math.floor(w / 4)
  const y = Math.floor(h / 2)
  const snake: Pt[] = [[x, y], [x - 1, y], [x - 2, y]]
  return { snake, dir: [1, 0], queued: [], food: placeFood(snake, w, h, rand), w, h, score: 0, over: false }
}

// a key queues a turn (two at most, so a quick up-then-left lands on consecutive ticks);
// turning back into the neck, or the way it already goes, is ignored
export function turn(g: SnakeGame, key: string): SnakeGame {
  const d = Object.hasOwn(DIRS, key.toLowerCase()) ? DIRS[key.toLowerCase()] : undefined
  const last = g.queued[g.queued.length - 1] ?? g.dir
  if (!d || g.over || same(d, last) || same(d, [-last[0], -last[1]])) return g
  return { ...g, queued: [...g.queued, d].slice(0, 2) }
}

// one tick: move the head, grow on food, end on a wall or the body; the tail cell the snake
// vacates this tick is free to move into
export function step(g: SnakeGame, rand = Math.random): SnakeGame {
  if (g.over) return g
  const [dir = g.dir, ...queued] = g.queued
  const head: Pt = [g.snake[0][0] + dir[0], g.snake[0][1] + dir[1]]
  const eats = same(head, g.food)
  const body = eats ? g.snake : g.snake.slice(0, -1)
  if (head[0] < 0 || head[1] < 0 || head[0] >= g.w || head[1] >= g.h || body.some(p => same(p, head))) return { ...g, dir, queued, over: true }
  const snake = [head, ...body]
  const food = eats ? placeFood(snake, g.w, g.h, rand) : g.food
  return { ...g, snake, dir, queued, food, score: g.score + (eats ? 1 : 0), over: food[0] < 0 }
}

// Tetris: pure game logic, drawn by the Tetris module in ../surface.tsx.

export type Cell = readonly [number, number]
export type Piece = { kind: number; rot: number; x: number; y: number }
export type TetrisGame = { w: number; h: number; board: number[][]; piece: Piece; next: number; score: number; lines: number; over: boolean }

// the seven pieces in spawn rotation, each inside an n×n box it rotates within
const SHAPES: { n: number; cells: Cell[] }[] = [
  { n: 4, cells: [[0, 1], [1, 1], [2, 1], [3, 1]] }, // I
  { n: 2, cells: [[0, 0], [1, 0], [0, 1], [1, 1]] }, // O
  { n: 3, cells: [[1, 0], [0, 1], [1, 1], [2, 1]] }, // T
  { n: 3, cells: [[1, 0], [2, 0], [0, 1], [1, 1]] }, // S
  { n: 3, cells: [[0, 0], [1, 0], [1, 1], [2, 1]] }, // Z
  { n: 3, cells: [[0, 0], [0, 1], [1, 1], [2, 1]] }, // J
  { n: 3, cells: [[2, 0], [0, 1], [1, 1], [2, 1]] }, // L
]
export const NAMES = 'IOTSZJL'
const LINE_SCORES = [0, 100, 300, 500, 800]

// the board cells a piece covers: its shape turned clockwise `rot` times inside its box
export function cells(p: Piece): Cell[] {
  const { n, cells: shape } = SHAPES[p.kind]
  const turns = ((p.rot % 4) + 4) % 4
  return shape.map(([x, y]) => {
    let cx = x
    let cy = y
    for (let i = 0; i < turns; i++) [cx, cy] = [n - 1 - cy, cx]
    return [p.x + cx, p.y + cy] as const
  })
}

export function collides(g: Pick<TetrisGame, 'w' | 'h' | 'board'>, p: Piece): boolean {
  return cells(p).some(([x, y]) => x < 0 || x >= g.w || y >= g.h || (y >= 0 && g.board[y][x] !== 0))
}

const spawn = (w: number, kind: number): Piece => ({ kind, rot: 0, x: Math.floor((w - SHAPES[kind].n) / 2), y: 0 })
const randomKind = (rand: () => number) => Math.floor(rand() * SHAPES.length)

export function newTetris(w: number, h: number, rand = Math.random): TetrisGame {
  const board = Array.from({ length: h }, () => Array<number>(w).fill(0))
  return { w, h, board, piece: spawn(w, randomKind(rand)), next: randomKind(rand), score: 0, lines: 0, over: false }
}

// fix the piece into the board, clear full rows, score them and bring in the next piece;
// the round ends when that piece has no room
function lock(g: TetrisGame, rand: () => number, bonus = 0): TetrisGame {
  const board = g.board.map(row => [...row])
  for (const [x, y] of cells(g.piece)) if (y >= 0) board[y][x] = g.piece.kind + 1
  const kept = board.filter(row => row.some(c => c === 0))
  const cleared = g.h - kept.length
  const next: TetrisGame = {
    ...g,
    board: [...Array.from({ length: cleared }, () => Array<number>(g.w).fill(0)), ...kept],
    piece: spawn(g.w, g.next),
    next: randomKind(rand),
    lines: g.lines + cleared,
    score: g.score + bonus + LINE_SCORES[cleared],
  }
  return collides(next, next.piece) ? { ...next, over: true } : next
}

export function shift(g: TetrisGame, dx: number): TetrisGame {
  const piece = { ...g.piece, x: g.piece.x + dx }
  return g.over || collides(g, piece) ? g : { ...g, piece }
}

// clockwise, nudged sideways off a wall or a block when it would not fit in place
export function rotate(g: TetrisGame): TetrisGame {
  if (g.over) return g
  for (const dx of [0, -1, 1, -2, 2]) {
    const piece = { ...g.piece, rot: (g.piece.rot + 1) % 4, x: g.piece.x + dx }
    if (!collides(g, piece)) return { ...g, piece }
  }
  return g
}

// gravity and soft drop: one row down, or lock when it cannot fall
export function fall(g: TetrisGame, rand = Math.random): TetrisGame {
  if (g.over) return g
  const piece = { ...g.piece, y: g.piece.y + 1 }
  return collides(g, piece) ? lock(g, rand) : { ...g, piece }
}

// hard drop: straight to the bottom, two points per row dropped
export function drop(g: TetrisGame, rand = Math.random): TetrisGame {
  if (g.over) return g
  let piece = g.piece
  let rows = 0
  while (!collides(g, { ...piece, y: piece.y + 1 })) {
    piece = { ...piece, y: piece.y + 1 }
    rows++
  }
  return lock({ ...g, piece }, rand, rows * 2)
}

// frame ticks (100 ms each) between gravity steps: 600 ms, one tick faster every 10 lines
export const dropEvery = (lines: number) => Math.max(1, 6 - Math.floor(lines / 10))

// 2048: pure game logic, drawn by the Twenty48 module in ../surface.tsx.

export const SIZE = 4
export type G2048 = { cells: number[]; score: number; over: boolean; won: boolean }

// slide one line toward its start: equal neighbours merge once each, first pair first
export function slide(line: number[]): { line: number[]; gained: number } {
  const tiles = line.filter(v => v !== 0)
  const out: number[] = []
  let gained = 0
  for (let i = 0; i < tiles.length; i++) {
    if (tiles[i] === tiles[i + 1]) {
      out.push(tiles[i] * 2)
      gained += tiles[i] * 2
      i++
    } else {
      out.push(tiles[i])
    }
  }
  while (out.length < line.length) out.push(0)
  return { line: out, gained }
}

// the cell indices of every line, each listed from the edge the tiles slide toward
function linesFor(dir: string): number[][] {
  const r = [...Array(SIZE).keys()]
  switch (dir) {
    case 'left': return r.map(y => r.map(x => y * SIZE + x))
    case 'right': return r.map(y => r.map(x => y * SIZE + (SIZE - 1 - x)))
    case 'up': return r.map(x => r.map(y => y * SIZE + x))
    case 'down': return r.map(x => r.map(y => (SIZE - 1 - y) * SIZE + x))
    default: return []
  }
}

// a 2 (nine times in ten) or a 4 on a random empty cell
function addTile(cells: number[], rand: () => number): number[] {
  const empty = cells.flatMap((v, i) => (v ? [] : [i]))
  if (!empty.length) return cells
  const next = [...cells]
  next[empty[Math.floor(rand() * empty.length)]] = rand() < 0.9 ? 2 : 4
  return next
}

const canMove = (cells: number[]) =>
  cells.some((v, i) => v === 0 || (i % SIZE < SIZE - 1 && v === cells[i + 1]) || (i + SIZE < cells.length && v === cells[i + SIZE]))

export function new2048(rand = Math.random): G2048 {
  return { cells: addTile(addTile(Array<number>(SIZE * SIZE).fill(0), rand), rand), score: 0, over: false, won: false }
}

// a move that changes nothing is not a move: no new tile, same game back
export function move(g: G2048, dir: string, rand = Math.random): G2048 {
  const lines = linesFor(dir)
  if (g.over || !lines.length) return g
  const cells = [...g.cells]
  let gained = 0
  for (const idx of lines) {
    const slid = slide(idx.map(i => g.cells[i]))
    idx.forEach((i, k) => { cells[i] = slid.line[k] })
    gained += slid.gained
  }
  if (cells.every((v, i) => v === g.cells[i])) return g
  const next = addTile(cells, rand)
  return { cells: next, score: g.score + gained, won: g.won || next.includes(2048), over: !canMove(next) }
}

// Typing test: pure logic, drawn by the Typing module in ../surface.tsx. Lines of code and prose to
// retype; speed is words per minute at five characters a word.

export const LINES = [
  'const total = items.reduce((sum, item) => sum + item.price, 0)',
  'if (!response.ok) throw new Error(`request failed: ${response.status}`)',
  'git commit -m "fix: retry the upload when the connection drops"',
  'for (const [key, value] of Object.entries(config)) console.log(key, value)',
  'The quick brown fox jumps over the lazy dog while the build runs.',
  'export function clamp(n: number, lo: number, hi: number) { return Math.min(hi, Math.max(lo, n)) }',
  'SELECT name, count(*) FROM orders GROUP BY name ORDER BY 2 DESC LIMIT 10;',
  'Small, well-named functions are easier to read than clever ones.',
  'docker run --rm -it -v "$PWD":/app -w /app node:22 npm test',
  'def mean(xs): return sum(xs) / len(xs) if xs else 0.0',
]

export type TypingGame = { text: string; typed: string; errors: number; done: boolean }

export const newTyping = (rand = Math.random, maxLength = Infinity): TypingGame => {
  const fits = LINES.filter(l => l.length <= maxLength)
  const pool = fits.length ? fits : LINES
  return { text: pool[Math.floor(rand() * pool.length)], typed: '', errors: 0, done: false }
}

// one key: a printable character is typed (a wrong one counts as an error and stays until
// backspaced), backspace removes the last character; the line is done when typed exactly
export function press(g: TypingGame, key: string): TypingGame {
  if (g.done) return g
  if (key === 'backspace' || key === 'delete') return { ...g, typed: g.typed.slice(0, -1) }
  if ([...key].length !== 1 || key < ' ') return g
  const typed = g.typed + key
  if (typed.length > g.text.length) return g
  const errors = g.errors + (key === g.text[typed.length - 1] ? 0 : 1)
  return { ...g, typed, errors, done: typed === g.text }
}

export const wpm = (chars: number, ms: number) => (ms > 0 ? Math.round((chars / 5) / (ms / 60_000)) : 0)
export const accuracy = (g: TypingGame) => (g.typed.length ? Math.max(0, Math.round(100 * (1 - g.errors / (g.typed.length + g.errors)))) : 100)

