/* @jsx h */
import type { ClientElements, ClientSurface } from 'claude-code'

// Shared by the aitmpl game boards. A board is a surface module: it runs on the drawing thread
// with its own frame clock (surface.every), keys once a click gives it focus (Esc gives the
// prompt back) and the mouse. Never name a local `h` here: every JSX tag compiles to a call of `h`.

/** What the hooks module hands every board: the best score, and a counter bumped per finished turn. */
export type Props = { best?: number; done?: number } | undefined
export type Base = { playing: boolean; banner: boolean; seenDone: number }
/** A cell as drawn: two characters, a colour, an optional background. */
export type Paint = readonly [glyph: string, color?: string, bg?: string]
type TextTag = ClientElements['Text']

export const base = (props: Props): Base => ({ playing: false, banner: false, seenDone: props?.done ?? 0 })

/** Claude finished a turn (props.done moved): show the banner and pause, once per turn. */
export function claudeDone<S extends Base>(props: Props, surface: ClientSurface<S>, pause = true) {
  const s = surface.state
  const done = props?.done ?? 0
  if (s && done !== s.seenDone) surface.setState({ ...s, seenDone: done, banner: true, playing: pause ? false : s.playing })
}

export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

type Run = [text: string, color?: string, bg?: string]

/** One row of cells as runs of equal colour, so a row costs a handful of nodes rather than one per cell. */
function runs(cols: number, y: number, at: (x: number, y: number) => Paint): Run[] {
  const out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  return out
}

/** A board of two-character cells (a terminal cell is about twice as tall as wide, so two make a square). */
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/** The space bar arrives as the character or by name, depending on the terminal. */
export const isSpace = (key: string) => key === ' ' || key === 'space'

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, isSpace, statusLine, type Base, type Props } from './common.tsx'
import { fire, H, move, newInvaders, step, W, wave, type InvadersGame } from '../games/invaders.ts'

// Waves arrive as props: the hooks module keeps the last few diffs with a running number, and the
// board starts the next one it has not seen once the current wave is cleared.
type Diff = { seq: number; file: string; lines: string[] }
type InvadersProps = (Props & { diffs?: Diff[] }) | undefined
type State = Base & { game: InvadersGame; seenSeq: number; queue: Diff[] }

const TICK_MS = 110
// a wave to shoot while Claude has not written anything yet
const DEMO: Diff = { seq: 0, file: 'demo.ts', lines: ['export function invaders() {', '  const wave = diff.added', '  return shoot(wave)', '}'] }

export default function Invaders(props: InvadersProps, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), playing: true, game: newInvaders(), seenSeq: props?.diffs?.at(-1)?.seq ?? 0, queue: [] })
    surface.every(TICK_MS, () => {
      const s = surface.state
      if (!s || !s.playing || s.game.over) return
      let game = step(s.game)
      let queue = s.queue
      if (game.cleared && queue.length > 0) {
        const [next, ...rest] = queue
        game = wave(game, next!.lines, next!.file)
        queue = rest
      }
      if (game.over) surface.post({ game: 'diff-invaders', score: game.score })
      surface.setState({ ...s, game, queue })
    })
    surface.onPointer(ev => {
      const s = surface.state
      if (!s || ev.type !== 'down') return
      surface.setState({ ...s, game: fire(s.game), banner: false })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key.toLowerCase()
      if (k === 'r') surface.setState({ ...s, game: wave(newInvaders(), DEMO.lines, DEMO.file), queue: [], playing: true, banner: false })
      else if (k === 'left' || k === 'a') surface.setState({ ...s, game: move(s.game, -1), banner: false })
      else if (k === 'right' || k === 'd') surface.setState({ ...s, game: move(s.game, 1), banner: false })
      else if (isSpace(k) || k === 'up' || k === 'w') surface.setState({ ...s, game: fire(s.game), banner: false })
      else if (k === 'p') surface.setState({ ...s, playing: !s.playing, banner: false })
    })
  }
  claudeDone(props, surface, false)

  // queue the diffs that arrived since the last draw
  const s0 = surface.state
  if (s0) {
    const fresh = (props?.diffs ?? []).filter(d => d.seq > s0.seenSeq)
    if (fresh.length > 0) surface.setState({ ...s0, queue: [...s0.queue, ...fresh], seenSeq: fresh[fresh.length - 1]!.seq })
  }

  const s = surface.state
  const g = s?.game ?? newInvaders()
  const aliens = new Map<number, string>()
  for (const a of g.aliens) if (a.alive) aliens.set(a.pos[1] * W + a.pos[0], a.glyph)
  const bombs = new Set(g.bombs.map(([x, y]) => y * W + x))
  const rows = grid(Text, W, H, (x, y) => {
    const k = y * W + x
    const glyph = aliens.get(k)
    if (glyph) return [glyph, y % 2 ? 'greenBright' : 'green']
    if (g.shot && g.shot[0] === x && g.shot[1] === y) return ['│ ', 'yellowBright']
    if (bombs.has(k)) return ['▾ ', 'red']
    if (y === H - 1 && x === g.ship) return [g.over ? '××' : '▟▙', 'cyan']
    return ['  ']
  })
  const pending = s?.queue.length ?? 0
  const text = g.over ? `diff invaders · game over · score ${g.score} · r plays a demo wave`
    : !s?.playing ? 'diff invaders · paused · p resumes'
    : g.cleared ? (pending > 0 ? 'diff invaders · next wave loading' : `diff invaders · score ${g.score} · waiting for Claude to write code · r shoots a demo wave`)
    : `diff invaders · ${g.file} · ← → move, space fires · ♥${g.lives} · score ${g.score}${pending ? ` · +${pending} waves queued` : ''}`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g.over ? 'red' : g.cleared ? 'gray' : 'green'} width={W * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

// Diff Invaders' rules, pure and testable. A wave is the code Claude just added: every added line
// becomes a row of the formation and every two characters of it one alien, so you shoot your own
// diff. The formation steps sideways, drops a row at the edge and rains bombs; you have a ship,
// one shot in the air at a time, and three lives. A cleared wave waits for the next Edit.

export type Pt = readonly [x: number, y: number]
export type Alien = { pos: Pt; glyph: string; alive: boolean }
export type InvadersGame = {
  readonly w: number
  readonly h: number
  aliens: Alien[]
  /** what this wave was made of, for the status line */
  file: string
  dir: 1 | -1
  /** ticks between formation steps: fewer aliens, faster */
  pace: number
  clock: number
  ship: number
  shot?: Pt
  bombs: Pt[]
  lives: number
  score: number
  waves: number
  over: boolean
  cleared: boolean
  tick: number
}

export const W = 30
export const H = 14
const MAX_ROWS = 6
const MAX_COLS = 12

export function newInvaders(score = 0, lives = 3, waves = 0): InvadersGame {
  return { w: W, h: H, aliens: [], file: '', dir: 1, pace: 6, clock: 0, ship: Math.floor(W / 2), bombs: [], lives, score, waves, over: false, cleared: true, tick: 0 }
}

/** Two characters of code per alien; spaces at the edges are trimmed, a run of spaces inside stays a gap. */
export function formation(lines: readonly string[]): Alien[] {
  const rows = lines.map(l => l.replace(/\t/g, '  ').trim()).filter(l => l.length > 0).slice(0, MAX_ROWS)
  const aliens: Alien[] = []
  rows.forEach((line, y) => {
    for (let i = 0, x = 0; i < line.length && x < MAX_COLS; i += 2, x++) {
      const glyph = line.slice(i, i + 2).padEnd(2)
      if (glyph.trim() === '') continue
      aliens.push({ pos: [x + 1, y + 1], glyph, alive: true })
    }
  })
  return aliens
}

/** Start a wave from added lines. Returns the game unchanged when the lines hold no code. */
export function wave(g: InvadersGame, lines: readonly string[], file: string): InvadersGame {
  const aliens = formation(lines)
  if (aliens.length === 0) return g
  return { ...g, aliens, file, dir: 1, pace: Math.max(2, 8 - Math.floor(g.waves / 2)), clock: 0, shot: undefined, bombs: [], cleared: false, waves: g.waves + 1 }
}

export function move(g: InvadersGame, dx: -1 | 1): InvadersGame {
  if (g.over) return g
  return { ...g, ship: Math.max(0, Math.min(W - 1, g.ship + dx)) }
}

export function fire(g: InvadersGame): InvadersGame {
  if (g.over || g.shot) return g
  return { ...g, shot: [g.ship, H - 2] }
}

export function step(g: InvadersGame, rnd: () => number = Math.random): InvadersGame {
  if (g.over) return g
  let out: InvadersGame = { ...g, tick: g.tick + 1 }

  // the shot climbs two rows a tick and takes the first alien it meets
  if (out.shot) {
    const [sx, sy] = out.shot
    let shot: Pt | undefined = [sx, sy - 2]
    let aliens = out.aliens
    let score = out.score
    for (const y of [sy - 1, sy - 2]) {
      const i = aliens.findIndex(a => a.alive && a.pos[0] === sx && a.pos[1] === y)
      if (i !== -1) {
        aliens = aliens.map((a, j) => (j === i ? { ...a, alive: false } : a))
        score += 10
        shot = undefined
        break
      }
    }
    if (shot && shot[1] < 0) shot = undefined
    out = { ...out, shot, aliens, score }
  }

  const alive = out.aliens.filter(a => a.alive)
  if (!out.cleared && alive.length === 0) {
    return { ...out, cleared: true, bombs: [], score: out.score + 50 }
  }

  // the formation steps on its own clock; faster as it thins out
  const pace = Math.max(1, out.pace - Math.floor((out.aliens.length - alive.length) / 8))
  if (alive.length > 0 && out.tick % pace === 0) {
    const xs = alive.map(a => a.pos[0])
    const atEdge = out.dir === 1 ? Math.max(...xs) >= W - 1 : Math.min(...xs) <= 0
    const aliens = out.aliens.map(a => (a.alive ? { ...a, pos: atEdge ? [a.pos[0], a.pos[1] + 1] as Pt : [a.pos[0] + out.dir, a.pos[1]] as Pt } : a))
    out = { ...out, aliens, dir: atEdge ? (out.dir === 1 ? -1 : 1) : out.dir }
    // a landed formation ends the game
    if (aliens.some(a => a.alive && a.pos[1] >= H - 2)) return { ...out, over: true }
    // the lowest alien of a random column drops a bomb, from where the formation now stands
    const moved = aliens.filter(a => a.alive)
    if (rnd() < 0.35 && moved.length > 0) {
      const col = moved[Math.floor(rnd() * moved.length)]!.pos[0]
      const lowest = moved.filter(a => a.pos[0] === col).sort((a, b) => b.pos[1] - a.pos[1])[0]!
      out = { ...out, bombs: [...out.bombs, [lowest.pos[0], lowest.pos[1] + 1]] }
    }
  }

  // bombs fall one row a tick; one on the ship costs a life
  if (out.tick % 2 === 0) {
    const bombs: Pt[] = []
    let lives = out.lives
    for (const [bx, by] of out.bombs) {
      const ny = by + 1
      if (ny >= H - 1 && bx === out.ship) lives--
      else if (ny < H - 1) bombs.push([bx, ny])
    }
    out = { ...out, bombs, lives }
    if (lives <= 0) return { ...out, lives: 0, over: true }
  }
  return out
}

{
  "description": "Diff Invaders above the prompt: /diff-invaders opens it, tool.call on Edit and Write turns the added lines into a wave, turn.complete tells the board, ui.message keeps the best score",
  "modules": [
    "./register.tsx"
  ]
