  let g = wave(newInvaders(), ['abcdef'], 'x.ts')
  expect(g.aliens.length).toBe(3)
  g = fire({ ...g, ship: g.aliens[0]!.pos[0] })
  for (let i = 0; i < 12; i++) g = step(g, () => 0.9)
