import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { BIRD_X, birdRow, flap, gapSize, newFlappy, tick, type FlappyGame } from '../games/flappy.ts'

type State = Base & { game?: FlappyGame }

export default function Flappy(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => ({
    bw: Math.max(12, Math.min(40, Math.floor((surface.columns - 2) / 2))),
    bh: Math.max(6, Math.min(16, surface.rows - 3)),
  })
  const start = () => {
    const s = surface.state
    if (!s) return
    const { bw, bh } = size()
    surface.setState({ ...s, banner: false, playing: true, game: flap(newFlappy(bw, bh)) })
  }
  // space, up, Enter or a click: flap, or start a new round when there is none
  const press = () => {
    const s = surface.state
    if (!s) return
    if (!s.game || s.game.over) return start()
    surface.setState({ ...s, banner: false, playing: true, game: flap(s.game) })
  }

  if (surface.state === undefined) {
    surface.setState(base(props))
    surface.every(100, () => {
      const s = surface.state
      if (!s?.game || !s.playing || s.game.over) return
      const game = tick(s.game)
      if (game.over) surface.post({ game: 'flappy', score: game.score })
      surface.setState({ ...s, game })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (s.game && !s.game.over) surface.setState({ ...s, banner: false, playing: !s.playing })
      } else if (k === 'r') {
        start()
      } else if (k === ' ' || k === 'up' || k === 'w' || k === 'return') {
        press()
      }
    })
    surface.onPointer(ev => { if (ev.type === 'down') press() })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh } = g ? { bw: g.w, bh: g.h } : size()
  const row = g ? birdRow(g) : Math.floor(bh / 2)
  const opening = gapSize(bh)
  const rows = grid(Text, bw, bh, (x, y) => {
    if (x === BIRD_X && y === row) return ['▓▓', g?.over ? 'red' : 'yellowBright']
    const pipe = g?.pipes.find(p => p.x === x)
    if (pipe && (y < pipe.gap || y >= pipe.gap + opening)) return ['██', 'green']
    return ['  ']
  })
  const text = !g ? 'flappy · click here, then space or click to flap · p pause'
    : g.over ? `flappy · crashed · score ${g.score} · space or click flies again`
    : !s?.playing ? `flappy · paused · score ${g.score} · p resumes`
    : `flappy · score ${g.score} · space or click flaps`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : 'blue'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

// Which score counts as a new best. Minesweeper's best is its fastest clear, so lower wins there;
// everywhere else higher wins. A score of zero or less never counts: a Minesweeper board whose
// first click clears it takes 0 s and would otherwise lock the best forever, and a Pong match you
// lost posts a negative margin.
export function isBetter(score: number, prev: number | undefined, lowerIsBetter = false): boolean {
  if (!Number.isFinite(score) || score <= 0) return false
  if (prev === undefined || prev <= 0) return true
  return lowerIsBetter ? score < prev : score > prev
}

// Flappy: pure game logic, drawn by the Flappy module in ../surface.tsx.
// Units are board cells; one tick is one 100 ms frame.

export type Pipe = { x: number; gap: number }
export type FlappyGame = { w: number; h: number; y: number; vy: number; pipes: Pipe[]; score: number; over: boolean }

export const BIRD_X = 4
// tuned so a flap every second or so holds height; the first try (0.3 / -1.1 / 1.2) hit the floor
// about a second after the first flap
const GRAVITY = 0.15
const FLAP = -0.9
const MAX_FALL = 0.8
const SPACING = 12

// the opening is a third of the board, at least three rows
export const gapSize = (h: number) => Math.max(3, Math.floor(h / 3))
const randomGap = (h: number, rand: () => number) => 1 + Math.floor(rand() * Math.max(1, h - gapSize(h) - 1))

export function newFlappy(w: number, h: number, rand = Math.random): FlappyGame {
  return { w, h, y: h / 2, vy: 0, pipes: [{ x: w - 1, gap: randomGap(h, rand) }], score: 0, over: false }
}

export const flap = (g: FlappyGame): FlappyGame => (g.over ? g : { ...g, vy: FLAP })

// the bird's row, as drawn and as collisions see it
export const birdRow = (g: FlappyGame) => Math.round(g.y)

// one tick: gravity, the pipes move a column left, a pipe passing the bird scores, and the round
// ends on the floor or a pipe; the ceiling stops the bird instead of ending the round
export function tick(g: FlappyGame, rand = Math.random): FlappyGame {
  if (g.over) return g
  let vy = Math.min(MAX_FALL, g.vy + GRAVITY)
  let y = g.y + vy
  if (y < 0) {
    y = 0
    vy = 0
  }
  let pipes = g.pipes.map(p => ({ ...p, x: p.x - 1 })).filter(p => p.x >= 0)
  const last = pipes[pipes.length - 1]
  if (!last || last.x <= g.w - 1 - SPACING) pipes = [...pipes, { x: g.w - 1, gap: randomGap(g.h, rand) }]
  const score = g.score + pipes.filter(p => p.x === BIRD_X - 1).length
  const row = Math.round(y)
  const hit = row < 0 || row >= g.h || pipes.some(p => p.x === BIRD_X && (row < p.gap || row >= p.gap + gapSize(g.h)))
  return { ...g, y, vy, pipes, score, over: hit }
}

