export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

export type Run = [text: string, color?: string, bg?: string]

// one run per stretch of cells sharing both colors. A drawing the engine cannot fit in its node
// budget is worse than a coarser one, so maxRuns folds neighbours together, pair by pair, until
// the row fits: a merged pair keeps the left one's colors and every glyph.
export function runs(cols: number, y: number, at: (x: number, y: number) => Paint, maxRuns = Infinity): Run[] {
  let out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  while (out.length > Math.max(1, maxRuns)) {
    const folded: Run[] = []
    for (let i = 0; i < out.length; i += 2) {
      const [t, c, b] = out[i]
      const next = out[i + 1]
      folded.push(next ? [t + next[0], c, b] : [t, c, b])
    }
    out = folded
  }
  return out
}

// a board as rows of two-character cells (a terminal cell is about twice as tall as wide, so two
// make a square), one styled span per run of the same colors
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint, maxRuns = Infinity) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at, maxRuns).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { fire, newInvaders, shift, tick, type InvadersGame, type Pt } from '../games/invaders.ts'

const ROW_COLORS = ['magentaBright', 'cyan', 'green', 'yellow']
type State = Base & { game?: InvadersGame }

export default function Invaders(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => ({
    bw: Math.max(20, Math.min(30, Math.floor((surface.columns - 2) / 2))),
    bh: Math.max(10, Math.min(16, surface.rows - 3)),
  })
  // the running round, or a new one when there is none or the last one ended
  const ensure = (s: State): InvadersGame => (s.game && !s.game.over ? s.game : newInvaders(size().bw, size().bh))

  if (surface.state === undefined) {
    surface.setState(base(props))
    surface.every(100, () => {
      const s = surface.state
      if (!s?.game || !s.playing || s.game.over) return
      const game = tick(s.game)
      if (game.over) surface.post({ game: 'invaders', score: game.score })
      surface.setState({ ...s, game })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (s.game && !s.game.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        surface.setState({ ...s, banner: false, playing: true, game: newInvaders(size().bw, size().bh) })
        return
      }
      const g = ensure(s)
      const game = k === 'left' || k === 'a' ? shift(g, -1)
        : k === 'right' || k === 'd' ? shift(g, 1)
        : k === ' ' || k === 'up' || k === 'w' ? fire(g)
        : undefined
      if (game) surface.setState({ ...s, banner: false, playing: true, game })
    })
    // the ship follows the pointer over the board and a click fires (the border takes the first column)
    surface.onPointer(ev => {
      const s = surface.state
      if (!s || (ev.type !== 'move' && ev.type !== 'down')) return
      if (ev.type === 'move' && (!s.game || s.game.over || !s.playing)) return
      const g = ensure(s)
      const moved = { ...g, ship: Math.max(0, Math.min(g.w - 1, Math.floor((ev.x - 1) / 2))) }
      surface.setState({ ...s, banner: false, playing: true, game: ev.type === 'down' ? fire(moved) : moved })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh } = g ? { bw: g.w, bh: g.h } : size()
  const top = g ? Math.min(...g.aliens.map(a => a[1])) : 0
  const flap = (g?.ticks ?? 0) % 10 < 5
  const has = (list: Pt[] | undefined, x: number, y: number) => !!list?.some(p => p[0] === x && p[1] === y)
  const rows = grid(Text, bw, bh, (x, y) => {
    if (!g) return ['  ']
    if (y === g.h - 1 && x === g.ship) return ['▟▙', 'greenBright']
    if (has(g.aliens, x, y)) return [flap ? '▚▞' : '▞▚', ROW_COLORS[(y - top) % ROW_COLORS.length]]
    if (has(g.shots, x, y)) return [' |', 'yellowBright']
    if (has(g.bombs, x, y)) return [' :', 'red']
    return ['  ']
  })
  const text = !g ? 'invaders · click here, then ←→ move · space fires · or the mouse'
    : g.over ? `invaders · game over · score ${g.score} · wave ${g.wave} · r plays again`
    : !s?.playing ? `invaders · paused · score ${g.score} · p resumes`
    : `invaders · score ${g.score} · wave ${g.wave} · lives ${'▲'.repeat(g.lives)} · space fires · p pause`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : 'magenta'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

// Which score counts as a new best. Minesweeper's best is its fastest clear, so lower wins there;
// everywhere else higher wins. A score of zero or less never counts: a Minesweeper board whose
// first click clears it takes 0 s and would otherwise lock the best forever, and a Pong match you
// lost posts a negative margin.
export function isBetter(score: number, prev: number | undefined, lowerIsBetter = false): boolean {
  if (!Number.isFinite(score) || score <= 0) return false
  if (prev === undefined || prev <= 0) return true
  return lowerIsBetter ? score < prev : score > prev
}

// Space Invaders: pure game logic, drawn by the Invaders board in ../boards/invaders.tsx.
// Units are board cells; one tick is one 100 ms frame. The ship sits on the bottom row.

export type Pt = readonly [number, number]
export type InvadersGame = {
  w: number; h: number
  ship: number
  shots: Pt[]; bombs: Pt[]; aliens: Pt[]
  dir: 1 | -1
  ticks: number; score: number; lives: number; wave: number; over: boolean
}

const COLS = 8
const ROWS = 3
const BOMB_CHANCE = 0.12
const same = (a: Pt, b: Pt) => a[0] === b[0] && a[1] === b[1]

// a formation of COLS × ROWS aliens two cells apart, centred; each wave starts a row lower (at most 3)
export function formation(w: number, wave: number): Pt[] {
  const left = Math.max(0, Math.floor((w - COLS * 2) / 2))
  const top = 1 + Math.min(wave - 1, 3)
  const out: Pt[] = []
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) out.push([left + c * 2, top + r])
  return out
}

export const newInvaders = (w: number, h: number): InvadersGame => ({
  w, h, ship: Math.floor(w / 2), shots: [], bombs: [], aliens: formation(w, 1), dir: 1, ticks: 0, score: 0, lives: 3, wave: 1, over: false,
})

// ticks between formation steps: fewer aliens and later waves step faster
export const stepEvery = (g: InvadersGame) => Math.max(1, Math.round(g.aliens.length / 3) - (g.wave - 1))

export const shift = (g: InvadersGame, dx: number): InvadersGame =>
  g.over ? g : { ...g, ship: Math.max(0, Math.min(g.w - 1, g.ship + dx)) }

// one shot on screen at a time, as in the original
export const fire = (g: InvadersGame): InvadersGame => (g.over || g.shots.length ? g : { ...g, shots: [[g.ship, g.h - 2]] })

// a shot and an alien in the same cell remove each other, ten points each
function hits(g: InvadersGame): InvadersGame {
  const shots = g.shots.filter(s => !g.aliens.some(a => same(a, s)))
  const aliens = g.aliens.filter(a => !g.shots.some(s => same(a, s)))
  return { ...g, shots, aliens, score: g.score + (g.aliens.length - aliens.length) * 10 }
}

export function tick(g: InvadersGame, rand = Math.random): InvadersGame {
  if (g.over) return g
  let next: InvadersGame = { ...g, ticks: g.ticks + 1, shots: g.shots.map(([x, y]): Pt => [x, y - 1]).filter(([, y]) => y >= 0) }
  next = hits(next)

  // the formation steps sideways, or down and back at an edge
  if (next.aliens.length && next.ticks % stepEvery(next) === 0) {
    const dir = next.dir
    const edge = next.aliens.some(([x]) => x + dir < 0 || x + dir >= next.w)
    next = edge
      ? { ...next, dir: dir === 1 ? -1 : 1, aliens: next.aliens.map(([x, y]): Pt => [x, y + 1]) }
      : { ...next, aliens: next.aliens.map(([x, y]): Pt => [x + dir, y]) }
    next = hits(next)
  }

  // bombs fall; now and then the lowest alien of a random column drops a new one
  let bombs = next.bombs.map(([x, y]): Pt => [x, y + 1]).filter(([, y]) => y < next.h)
  if (next.aliens.length && rand() < BOMB_CHANCE) {
    const picked = next.aliens[Math.floor(rand() * next.aliens.length)]
    const lowest = next.aliens.filter(a => a[0] === picked[0]).reduce((m, a) => (a[1] > m[1] ? a : m))
    bombs = [...bombs, [lowest[0], lowest[1] + 1]]
  }
  const hit = bombs.some(([x, y]) => y === next.h - 1 && x === next.ship)
  const lives = next.lives - (hit ? 1 : 0)
  const landed = next.aliens.some(([, y]) => y >= next.h - 1)
  next = { ...next, bombs: hit ? [] : bombs, lives, over: lives <= 0 || landed }

  // a cleared wave brings the next, a row lower and faster
  if (!next.over && !next.aliens.length) {
    next = { ...next, wave: next.wave + 1, aliens: formation(next.w, next.wave + 1), shots: [], bombs: [], dir: 1 }
  }
  return next
}

