import type { ClientElements, ClientSurface } from 'claude-code'

// Shared by every board. A board is a surface module: it runs on the drawing thread with its own
// frame clock, keys (after a click gives it focus; Esc gives the prompt back) and mouse.
//
// Never name a local `h` in a board file: every JSX tag compiles to a call of `h`.

export type Props = { best?: number; done?: number; safe?: boolean } | undefined
export type Base = { playing: boolean; banner: boolean; seenDone: number }
export type Paint = readonly [glyph: string, color?: string, bg?: string]
type TextTag = ClientElements['Text']

export const base = (props: Props): Base => ({ playing: false, banner: false, seenDone: props?.done ?? 0 })

// the hooks module bumps props.done when Claude finishes a turn: pause and say so, once per turn
export function claudeDone<S extends Base>(props: Props, surface: ClientSurface<S>) {
  const s = surface.state
  const done = props?.done ?? 0
  if (s && done !== s.seenDone) surface.setState({ ...s, seenDone: done, banner: true, playing: false })
}

export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

export type Run = [text: string, color?: string, bg?: string]

// one run per stretch of cells sharing both colors. A drawing the engine cannot fit in its node
// budget is worse than a coarser one, so maxRuns folds neighbours together, pair by pair, until
// the row fits: a merged pair keeps the left one's colors and every glyph.
export function runs(cols: number, y: number, at: (x: number, y: number) => Paint, maxRuns = Infinity): Run[] {
  let out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  while (out.length > Math.max(1, maxRuns)) {
    const folded: Run[] = []
    for (let i = 0; i < out.length; i += 2) {
      const [t, c, b] = out[i]
      const next = out[i + 1]
      folded.push(next ? [t + next[0], c, b] : [t, c, b])
    }
    out = folded
  }
  return out
}

// a board as rows of two-character cells (a terminal cell is about twice as tall as wide, so two
// make a square), one styled span per run of the same colors
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint, maxRuns = Infinity) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at, maxRuns).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { flag, newMines, reveal, type Mines } from '../games/mines.ts'

const NUMBER_COLORS = ['', 'blue', 'green', 'red', 'magenta', 'yellow', 'cyan', 'white', 'gray']
const CURSOR_KEYS: Record<string, readonly [number, number]> = { left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1], a: [-1, 0], d: [1, 0], w: [0, -1], s: [0, 1] }
type State = Base & { game?: Mines; cursor: readonly [number, number]; seconds: number }

export default function Minesweeper(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => {
    const bw = Math.max(4, Math.min(16, Math.floor((surface.columns - 2) / 2)))
    const bh = Math.max(4, Math.min(9, surface.rows - 3))
    return { bw, bh, count: Math.max(1, Math.round(bw * bh * 0.15)) }
  }
  // a click or space reveals, a right-click or f flags; the first action after a finished round
  // only starts a new board, so a stray click cannot open a cell on it
  const act = (x: number, y: number, kind: 'reveal' | 'flag') => {
    const s = surface.state
    if (!s) return
    let g = s.game
    if (!g || g.over || g.won) {
      const { bw, bh, count } = size()
      const fresh = newMines(bw, bh, count)
      if (g) {
        surface.setState({ ...s, banner: false, playing: false, seconds: 0, game: fresh })
        return
      }
      g = fresh
    }
    const game = kind === 'flag' ? flag(g, x, y) : reveal(g, x, y)
    // a board whose first click clears it takes 0 s; count it as 1 s so it cannot lock the best
    if (game.won && !g.won) surface.post({ game: 'minesweeper', score: Math.max(1, s.seconds) })
    const cursor = x >= 0 && y >= 0 && x < game.w && y < game.h ? ([x, y] as const) : s.cursor
    surface.setState({ ...s, banner: false, playing: game.placed && !game.over && !game.won, game, cursor })
  }

  if (surface.state === undefined) {
    surface.setState({ ...base(props), cursor: [0, 0], seconds: 0 })
    surface.every(1000, () => {
      const s = surface.state
      if (s?.game && s.playing && !s.banner) surface.setState({ ...s, seconds: s.seconds + 1 })
    })
    surface.onPointer(ev => {
      if (ev.type !== 'down') return
      // the border takes the first row and column; each cell is two columns wide
      act(Math.floor((ev.x - 1) / 2), ev.y - 1, ev.button === 'right' ? 'flag' : 'reveal')
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      const bw = s.game?.w ?? size().bw
      const bh = s.game?.h ?? size().bh
      if (Object.hasOwn(CURSOR_KEYS, k)) {
        const [dx, dy] = CURSOR_KEYS[k]
        const [cx, cy] = s.cursor
        surface.setState({ ...s, banner: false, cursor: [Math.max(0, Math.min(bw - 1, cx + dx)), Math.max(0, Math.min(bh - 1, cy + dy))] })
      } else if (k === ' ' || k === 'return') {
        act(s.cursor[0], s.cursor[1], 'reveal')
      } else if (k === 'f') {
        act(s.cursor[0], s.cursor[1], 'flag')
      } else if (k === 'r') {
        const { bw: nw, bh: nh, count } = size()
        surface.setState({ ...s, banner: false, playing: false, seconds: 0, game: newMines(nw, nh, count) })
      }
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh, count } = g ? { bw: g.w, bh: g.h, count: g.count } : size()
  const [cx, cy] = s?.cursor ?? [0, 0]
  const rows = grid(Text, bw, bh, (x, y) => {
    const t = g?.tiles[y * bw + x]
    const bg = x === cx && y === cy ? 'blue' : undefined
    if (!t || (!t.open && !t.flag)) return ['░░', 'gray', bg]
    if (t.flag && !t.open) return [' F', 'redBright', bg]
    if (t.mine) return [' *', 'red', bg]
    return t.n ? [` ${t.n}`, NUMBER_COLORS[t.n], bg] : ['  ', undefined, bg]
  })
  const flags = g?.tiles.filter(t => t.flag).length ?? 0
  const seconds = s?.seconds ?? 0
  const text = !g ? 'minesweeper · click a cell, or click here then arrows + space · right-click or f flags'
    : g.over ? 'minesweeper · boom · r or a click plays again'
    : g.won ? `minesweeper · cleared in ${seconds}s · r or a click plays again`
    : `minesweeper · ${count - flags} mines left · ${seconds}s · click reveals · right-click or f flags`
  const best = props?.best ? `${props.best}s` : '—'
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? 'red' : g?.won ? 'green' : 'gray'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${best}`)}
    </Box>
  )
}

// Which score counts as a new best. Minesweeper's best is its fastest clear, so lower wins there;
// everywhere else higher wins. A score of zero or less never counts: a Minesweeper board whose
// first click clears it takes 0 s and would otherwise lock the best forever, and a Pong match you
// lost posts a negative margin.
export function isBetter(score: number, prev: number | undefined, lowerIsBetter = false): boolean {
  if (!Number.isFinite(score) || score <= 0) return false
  if (prev === undefined || prev <= 0) return true
  return lowerIsBetter ? score < prev : score > prev
}

// Minesweeper: pure game logic, drawn by the Minesweeper module in ../surface.tsx.

export type Tile = { mine: boolean; open: boolean; flag: boolean; n: number }
export type Mines = { w: number; h: number; count: number; tiles: Tile[]; placed: boolean; over: boolean; won: boolean }

export const newMines = (w: number, h: number, count: number): Mines => ({
  w, h, count,
  tiles: Array.from({ length: w * h }, () => ({ mine: false, open: false, flag: false, n: 0 })),
  placed: false, over: false, won: false,
})

const inside = (g: Mines, x: number, y: number) => x >= 0 && y >= 0 && x < g.w && y < g.h

function around(g: Mines, x: number, y: number): number[] {
  const out: number[] = []
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) if ((dx || dy) && inside(g, x + dx, y + dy)) out.push((y + dy) * g.w + x + dx)
  }
  return out
}

// mines go in on the first reveal, never on that cell or next to it, so the first click opens an area
function place(g: Mines, x: number, y: number, rand: () => number): Tile[] {
  const safe = new Set([y * g.w + x, ...around(g, x, y)])
  const spots = g.tiles.map((_, i) => i).filter(i => !safe.has(i))
  const tiles = g.tiles.map(t => ({ ...t }))
  // a partial Fisher-Yates shuffle picks `count` distinct spots
  for (let k = 0; k < Math.min(g.count, spots.length); k++) {
    const j = k + Math.floor(rand() * (spots.length - k))
    ;[spots[k], spots[j]] = [spots[j], spots[k]]
    tiles[spots[k]].mine = true
  }
  tiles.forEach((t, i) => { t.n = around(g, i % g.w, Math.floor(i / g.w)).filter(j => tiles[j].mine).length })
  return tiles
}

// open a cell: a mine ends the round and shows every mine; a zero opens its whole empty area
export function reveal(g: Mines, x: number, y: number, rand = Math.random): Mines {
  if (g.over || g.won || !inside(g, x, y)) return g
  const start = y * g.w + x
  if (g.tiles[start].flag || g.tiles[start].open) return g
  const tiles = g.placed ? g.tiles.map(t => ({ ...t })) : place(g, x, y, rand)
  if (tiles[start].mine) {
    tiles.forEach(t => { if (t.mine) t.open = true })
    return { ...g, tiles, placed: true, over: true }
  }
  const stack = [start]
  while (stack.length) {
    const i = stack.pop()!
    const t = tiles[i]
    if (t.open || t.flag) continue
    t.open = true
    if (t.n === 0) stack.push(...around(g, i % g.w, Math.floor(i / g.w)))
  }
  return { ...g, tiles, placed: true, won: tiles.every(t => t.mine || t.open) }
}

export function flag(g: Mines, x: number, y: number): Mines {
  if (g.over || g.won || !inside(g, x, y) || g.tiles[y * g.w + x].open) return g
  const tiles = g.tiles.map((t, i) => (i === y * g.w + x ? { ...t, flag: !t.flag } : t))
  return { ...g, tiles }
}

