let open = false
// bumped at each finished turn; the open game pauses when it sees a new value
let turnsDone = 0
let best = 0

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    // a store that cannot be read costs the best score, never the game
    const score = Number(await $.store.get('best').catch(() => undefined))
    if (score) best = score
    await $.command.register({
      name: 'pacman',
      description: 'Pac-Man above the prompt, while Claude works (stop closes)',
      argumentHint: '[stop]',
      immediate: true,
    }).catch(err => $.ui.log(`pacman: /pacman not registered: ${err}`))
    return r
  })

  on('command.run', { command: 'pacman' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'stop' || arg === 'close') {
      open = false
      $.ui.invalidate('ui.render')
      return { text: `${TITLE} closed` }
    }
    open = true
    $.ui.invalidate('ui.render')
    return { text: `${TITLE} · click the maze, then an arrow key · Esc returns to the prompt · /pacman stop closes${best ? ` · best ${best}` : ''}` }
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    // a subagent's turn is not the one the person is waiting for
    if (e.agentId) return r
    if (open) {
      turnsDone++
      $.ui.invalidate('ui.render')
    }
    return r
  })

  // a finished round (or a cleared maze), posted by the board: keep the best score
  on('ui.message', async ($, e, next) => {
    const data = e.data as { game?: unknown; score?: unknown } | null
    if (data?.game !== 'pacman' || typeof data.score !== 'number') return next(e)
    if (Number.isFinite(data.score) && data.score > best) {
      best = data.score
      await $.store.set('best', best).catch(err => $.ui.log(`pacman: store write failed: ${err}`))
      $.ui.toast(`${TITLE}: new best ${best}`)
    }
    return { props: { best, done: turnsDone } }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // the board needs a terminal's keys; the desktop and mobile surfaces draw their own band
    if (!open || e.props.hasSurvey || e.surface !== 'terminal') return next(e)
    const { Box, Button, Client } = $.ui.resolve(e)
    // the band's own width: the transcript column's while a Pane is docked beside it
    const cols = e.props.bodyColumns || (e.viewport?.columns ?? 80)
    // one row for the close button, one for whatever else draws in the band; the maze is 15 rows + border
    const rows = Math.max(8, Math.min(e.props.maxRows - 2, 18))
    const close = () => {
      open = false
      $.ui.invalidate('ui.render')
    }
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={1}>
          <Button key="pacman:close" label="close" onPress={close} />
        </Box>
        <Client key="board:pacman" module="./boards/pacman.tsx" width={cols} height={rows} props={{ best, done: turnsDone }} />
        {await next(e)}
      </Box>
    )
  })
}

import { expect, test } from 'claude-code/testing'
import { MAZE, newPacman, step, turn } from '../hooks/games/pacman.ts'

let seed = 42
const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648

test('the maze is 19 wide, 126 pellets and 4 power pellets', () => {
  expect(MAZE.every(r => r.length === 19)).toBe(true)
  const g = newPacman()
  expect(g.pellets.size).toBe(126)
  expect(g.power.size).toBe(4)
})

test('walking left eats pellets and the ghosts leave the pen', () => {
  let g = turn(newPacman(), 'left')
  for (let i = 0; i < 6; i++) g = step(g, rnd)
  expect(g.score).toBeGreaterThan(0)
  expect(g.ghosts.filter(gh => MAZE[gh.pos[1]]![gh.pos[0]] !== 'G').length).toBeGreaterThanOrEqual(2)
})

test('the tunnel row wraps', () => {
  let g = newPacman()
  g = step({ ...g, pac: [0, 7], dir: 'left', wanted: 'left' }, rnd)
  expect(g.pac).toEqual([18, 7])
})

test('a random walk eventually loses its lives', () => {
  let g = newPacman()
  for (let i = 0; i < 4000 && !g.over; i++) g = step(turn(g, ['up', 'down', 'left', 'right'][Math.floor(rnd() * 4)]!), rnd)
  expect(g.over).toBe(true)
  expect(g.lives).toBe(0)
})

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { feeling, level, moodAt, stage, type Pet, type PetEvent, type Stage } from '../games/pet.ts'

// The pet's window. The hooks module owns the pet (it feeds it from tool calls and keeps it in
// $.store) and passes it in props; this board only draws it, blinks, and shows hearts on a click.

type PetProps = { pet?: Pet; now?: number } | undefined
type State = { frame: number; petted: number }

const ART: Record<Stage, string[]> = {
  egg: ['   ____   ', '  /    \\  ', ' |  {e}  | ', '  \\____/  '],
  baby: ['  (\\_/)  ', ' ( {e} ) ', ' (")(")  '],
  kid: ['  /\\_/\\  ', ' ( {e} ) ', '  > ^ <  '],
  adult: ['  /\\_____/\\  ', ' (   {e}   ) ', ' (    w    ) ', '  \\_______/  '],
  legend: ['     \\^^^/     ', '  /\\_____/\\  ', ' (   {e}   ) ', ' (    w    ) ', '  \\_______/  '],
}
const EYES = { happy: '^.^', okay: 'o.o', sad: 'T.T' }
const COLORS = { happy: 'greenBright', okay: 'yellow', sad: 'red' }
const FED_BY: Record<PetEvent, string> = { 'test-pass': 'passing tests', 'test-fail': 'failing tests (ouch)', commit: 'a commit', edit: 'an edit' }

const bar = (value: number) => {
  const filled = Math.round(Math.max(0, Math.min(100, value)) / 10)
  return '█'.repeat(filled) + '░'.repeat(10 - filled)
}
const ago = (ms: number) => {
  const min = Math.floor(ms / 60_000)
  return min < 1 ? 'just now' : min < 60 ? `${min} min ago` : min < 1440 ? `${Math.floor(min / 60)} h ago` : `${Math.floor(min / 1440)} days ago`
}

export default function PetBoard(props: PetProps, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ frame: 0, petted: 0 })
    surface.every(200, () => {
      const s = surface.state
      if (s) surface.setState({ frame: s.frame + 1, petted: Math.max(0, s.petted - 1) })
    })
    surface.onPointer(ev => {
      const s = surface.state
      if (s && ev.type === 'down') surface.setState({ ...s, petted: 8 })
    })
  }

  const s = surface.state
  const pet = props?.pet
  if (!pet) return <Text dimColor>pet · waiting for the plugin to load it</Text>

  const now = props?.now ?? pet.at
  const mood = moodAt(pet, now)
  const feel = feeling(mood)
  const lvl = level(pet.xp)
  // a blink for one frame in every five seconds
  const eyes = (s?.frame ?? 1) % 25 === 0 ? '-.-' : EYES[feel]
  const art = ART[stage(pet.xp)].map(line => line.replace('{e}', eyes))
  return (
    <Box flexDirection="row" borderStyle="round" borderColor={COLORS[feel]} paddingX={1}>
      <Box flexDirection="column" marginRight={3}>
        <Text color="magentaBright">{s?.petted ? '   ♥   ♥   ' : ' '}</Text>
        {art.map(line => <Text color={COLORS[feel]}>{line}</Text>)}
      </Box>
      <Box flexDirection="column">
        <Text bold>{`${stage(pet.xp)} · level ${lvl}`}</Text>
        <Text dimColor>{`${pet.xp} xp · next level at ${10 * (lvl + 1) ** 2}`}</Text>
        <Text>{'mood '}<Text color={COLORS[feel]}>{bar(mood)}</Text>{` ${feel}`}</Text>
        <Text dimColor>{`tests passed ${pet.tests} · failed ${pet.fails} · commits ${pet.commits} · edits ${pet.edits}`}</Text>
        <Text dimColor>{pet.last ? `last fed by ${FED_BY[pet.last]}, ${ago(now - pet.at)}` : 'it eats passing tests, commits and edits'}</Text>
        <Text dimColor>{`hatched ${ago(now - pet.born)} · click to pet · /arcade stop closes`}</Text>
      </Box>
    </Box>
  )
}

// The pet: pure logic. It grows with the work Claude does in any session: tests passing, commits
// and edits give it xp and lift its mood; failing tests hurt its mood; idle time slowly bores it.
// The hooks module feeds it from tool calls and keeps it in $.store; ../boards/pet.tsx draws it.

export type PetEvent = 'test-pass' | 'test-fail' | 'commit' | 'edit'
export type Pet = {
  xp: number
  mood: number
  // when it was last fed, and when it hatched (ms since the epoch)
  at: number
  born: number
  tests: number; fails: number; commits: number; edits: number
  last?: PetEvent
}

const XP: Record<PetEvent, number> = { 'test-pass': 10, 'test-fail': 2, commit: 15, edit: 1 }
const MOOD: Record<PetEvent, number> = { 'test-pass': 8, 'test-fail': -12, commit: 10, edit: 1 }
const BORED = 30

export const newPet = (now: number): Pet => ({ xp: 0, mood: 70, at: now, born: now, tests: 0, fails: 0, commits: 0, edits: 0 })

// test runners across common stacks; a failing run is a tool call that ended in error
const TEST_COMMAND = /\b(bun|npm|pnpm|yarn)\s+(run\s+)?test\b|\bnpx\s+(jest|vitest|mocha)\b|\b(pytest|jest|vitest|rspec|phpunit|mocha)\b|\bgo\s+test\b|\bcargo\s+test\b|\bmake\s+test\b|\b(mvn|gradle|gradlew|sbt)\b.*\btest\b/

// what a finished tool call means for the pet; `ok` is undefined when the call was denied
export function petEvent(tool: string, command: string | undefined, ok: boolean | undefined): PetEvent | undefined {
  if (ok === undefined) return undefined
  if (tool === 'Bash' && command) {
    if (TEST_COMMAND.test(command)) return ok ? 'test-pass' : 'test-fail'
    if (ok && /\bgit\s+commit\b/.test(command) && !/--dry-run\b/.test(command)) return 'commit'
    return undefined
  }
  if (ok && (tool === 'Edit' || tool === 'Write' || tool === 'NotebookEdit')) return 'edit'
  return undefined
}

// idle, mood sinks a point every ten minutes, down to bored; below that only failures take it
export function moodAt(p: Pet, now: number): number {
  if (p.mood <= BORED) return p.mood
  return Math.max(BORED, p.mood - Math.floor(Math.max(0, now - p.at) / 600_000))
}

export function feed(p: Pet, event: PetEvent, now: number): Pet {
  return {
    ...p,
    xp: p.xp + XP[event],
    mood: Math.max(0, Math.min(100, moodAt(p, now) + MOOD[event])),
    at: now,
    last: event,
    tests: p.tests + (event === 'test-pass' ? 1 : 0),
    fails: p.fails + (event === 'test-fail' ? 1 : 0),
    commits: p.commits + (event === 'commit' ? 1 : 0),
    edits: p.edits + (event === 'edit' ? 1 : 0),
  }
}

// level n needs 10·n² xp: level 1 at 10, 2 at 40, 3 at 90, 6 at 360, 10 at 1000
export const level = (xp: number) => Math.floor(Math.sqrt(xp / 10))
export type Stage = 'egg' | 'baby' | 'kid' | 'adult' | 'legend'
export const stage = (xp: number): Stage => {
  const l = level(xp)
  return l >= 10 ? 'legend' : l >= 6 ? 'adult' : l >= 3 ? 'kid' : l >= 1 ? 'baby' : 'egg'
}
export const feeling = (mood: number) => (mood >= 70 ? 'happy' : mood >= 35 ? 'okay' : 'sad')

