/* @jsx h */
import type { Register } from 'claude-code'
import { feed, level, newPet, petEvent, stage, type Pet } from './games/pet.ts'

// A virtual pet above the Claude Code prompt, split out of cc-arcade (https://github.com/sezaakgun/cc-arcade,
// MIT, by Seza Akgün). It is fed by Claude's actual work: passing tests, commits and edits grant XP and
// mood, failing tests cost mood, idling drains it; it grows egg → baby → kid → adult → legend. `/pet`
// shows it, `/pet stop` hides it. The pet lives in $.store, so sessions side by side feed the same one.

let open = false
let pet: Pet | undefined

const isPet = (value: unknown): value is Pet => typeof value === 'object' && value !== null && typeof (value as Pet).xp === 'number'

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    const saved = await $.store.get('pet').catch(err => { $.ui.log(`pet: store read failed: ${err}`); return undefined })
    pet = isPet(saved) ? saved : newPet(await $.clock.now())
    if (!isPet(saved)) await $.store.set('pet', pet).catch(err => $.ui.log(`pet: store write failed: ${err}`))
    await $.command.register({
      name: 'pet',
      description: 'A pet above the prompt that grows as Claude tests, commits and edits (stop hides it)',
      argumentHint: '[stop]',
      immediate: true,
    }).catch(err => $.ui.log(`pet: /pet not registered: ${err}`))
    return r
  })

  on('command.run', { command: 'pet' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    open = !(arg === 'stop' || arg === 'close')
    $.ui.invalidate('ui.render')
    if (!open) return { text: 'pet hidden' }
    const p = pet
    return { text: p ? `pet: level ${level(p.xp)}, ${stage(p.xp)} · click it to pet it · /pet stop hides it` : 'pet: click it to pet it' }
  })

  // the pet feeds on work: a test run passing or failing, a commit, an edit. It is re-read from the
  // store first, so sessions running side by side feed the same pet instead of overwriting it.
  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    const command = (e as { command?: unknown }).command
    const event = petEvent(e.tool, typeof command === 'string' ? command : undefined, 'deny' in r ? undefined : !r.isError)
    if (!event) return r
    const saved = await $.store.get('pet').catch(() => undefined)
    const now = await $.clock.now()
    const current = isPet(saved) ? saved : pet ?? newPet(now)
    const fed = feed(current, event, now)
    pet = fed
    await $.store.set('pet', fed).catch(err => $.ui.log(`pet: store write failed: ${err}`))
    if (level(fed.xp) > level(current.xp)) {
      const grew = stage(fed.xp) !== stage(current.xp) ? `, and is now ${stage(fed.xp) === 'adult' ? 'an adult' : `a ${stage(fed.xp)}`}` : ''
      $.ui.toast(`pet: reached level ${level(fed.xp)}${grew}`)
    }
    if (open) $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!open || e.props.hasSurvey || e.surface !== 'terminal') return next(e)
    const { Box, Button, Client } = $.ui.resolve(e)
    // the band's own width: the transcript column's while a Pane is docked beside it
    const cols = e.props.bodyColumns || (e.viewport?.columns ?? 80)
    // $.clock.now() is a dispatch (a Promise): resolve it before it becomes a prop
    const now = await $.clock.now()
    const close = () => {
      open = false
      $.ui.invalidate('ui.render')
    }
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={1}>
          <Button key="pet:close" label="close" onPress={close} />
        </Box>
        <Client key="board:pet" module="./boards/pet.tsx" width={cols} props={{ pet, now }} />
        {await next(e)}
      </Box>
    )
  })
}

/* @jsx h */
import type { ClientElements, ClientSurface } from 'claude-code'

// Shared by every board. A board is a surface module: it runs on the drawing thread with its own
// frame clock, keys (after a click gives it focus; Esc gives the prompt back) and mouse.
//
// Never name a local `h` in a board file: every JSX tag compiles to a call of `h`.

export type Props = { best?: number; done?: number; safe?: boolean } | undefined
export type Base = { playing: boolean; banner: boolean; seenDone: number }
export type Paint = readonly [glyph: string, color?: string, bg?: string]
type TextTag = ClientElements['Text']

export const base = (props: Props): Base => ({ playing: false, banner: false, seenDone: props?.done ?? 0 })

// the hooks module bumps props.done when Claude finishes a turn: pause and say so, once per turn
export function claudeDone<S extends Base>(props: Props, surface: ClientSurface<S>) {
  const s = surface.state
  const done = props?.done ?? 0
  if (s && done !== s.seenDone) surface.setState({ ...s, seenDone: done, banner: true, playing: false })
}

export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

export type Run = [text: string, color?: string, bg?: string]

// one run per stretch of cells sharing both colors. A drawing the engine cannot fit in its node
// budget is worse than a coarser one, so maxRuns folds neighbours together, pair by pair, until
// the row fits: a merged pair keeps the left one's colors and every glyph.
export function runs(cols: number, y: number, at: (x: number, y: number) => Paint, maxRuns = Infinity): Run[] {
  let out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  while (out.length > Math.max(1, maxRuns)) {
    const folded: Run[] = []
    for (let i = 0; i < out.length; i += 2) {
      const [t, c, b] = out[i]
      const next = out[i + 1]
      folded.push(next ? [t + next[0], c, b] : [t, c, b])
    }
    out = folded
  }
  return out
}

// a board as rows of two-character cells (a terminal cell is about twice as tall as wide, so two
// make a square), one styled span per run of the same colors
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint, maxRuns = Infinity) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at, maxRuns).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Props } from './common.tsx'
import { newPong, nudge, place, tick, WIN, type PongGame } from '../games/pong.ts'

type State = Base & { game?: PongGame }

export default function Pong(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const size = () => ({
    bw: Math.max(16, Math.min(40, Math.floor((surface.columns - 2) / 2))),
    bh: Math.max(8, Math.min(15, surface.rows - 3)),
  })
  // the first key or click of a round starts it
  const ensure = (s: State): State => {
    if (s.game && !s.game.over) return s
    const { bw, bh } = size()
    return { ...s, game: newPong(bw, bh) }
  }

  if (surface.state === undefined) {
    surface.setState(base(props))
    surface.every(100, () => {
      const s = surface.state
      if (!s?.game || !s.playing || s.game.over) return
      const game = tick(s.game)
      // best is the winning margin
      if (game.over) surface.post({ game: 'pong', score: game.scoreYou - game.scoreCpu })
      surface.setState({ ...s, game })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      // the space bar may arrive as the character or by name
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p' || k === ' ') {
        if (s.game && !s.game.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        const { bw, bh } = size()
        surface.setState({ ...s, banner: false, playing: true, game: newPong(bw, bh) })
        return
      }
      const rows = k === 'up' || k === 'w' ? -2 : k === 'down' || k === 's' ? 2 : 0
      if (!rows) return
      const next = ensure(s)
      surface.setState({ ...next, banner: false, playing: true, game: nudge(next.game!, rows) })
    })
    // the paddle follows the pointer over the board (the border takes the first row)
    surface.onPointer(ev => {
      const s = surface.state
      if (!s || (ev.type !== 'move' && ev.type !== 'down')) return
      if (ev.type === 'move' && (!s.game || s.game.over || !s.playing)) return
      const next = ensure(s)
      surface.setState({ ...next, banner: false, playing: true, game: place(next.game!, ev.y - 1) })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  const { bw, bh } = g ? { bw: g.w, bh: g.h } : size()
  const rows = grid(Text, bw, bh, (x, y) => {
    if (!g) return x === Math.floor(bw / 2) && y % 2 === 0 ? [' ·', 'gray'] : ['  ']
    if (x === 0 && y >= g.you && y < g.you + g.pad) return ['██', 'cyan']
    const cpu = Math.round(g.cpu)
    if (x === bw - 1 && y >= cpu && y < cpu + g.pad) return ['██', 'magenta']
    if (x === g.ball.x && y === Math.round(g.ball.y)) return ['██', 'whiteBright']
    return x === Math.floor(bw / 2) && y % 2 === 0 ? [' ·', 'gray'] : ['  ']
  })
  const text = !g ? `pong · click here, then ↑↓ or move the mouse · first to ${WIN}`
    : g.over ? `pong · ${g.scoreYou > g.scoreCpu ? 'you win' : 'cpu wins'} ${g.scoreYou}:${g.scoreCpu} · r plays again`
    : !s?.playing ? `pong · paused · you ${g.scoreYou} : ${g.scoreCpu} cpu · space resumes`
    : `pong · you ${g.scoreYou} : ${g.scoreCpu} cpu · first to ${WIN} · ↑↓ or the mouse`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g?.over ? (g.scoreYou > g.scoreCpu ? 'green' : 'red') : 'white'} width={bw * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best margin ${props?.best ?? 0}`)}
    </Box>
  )
}

// Which score counts as a new best. Minesweeper's best is its fastest clear, so lower wins there;
// everywhere else higher wins. A score of zero or less never counts: a Minesweeper board whose
// first click clears it takes 0 s and would otherwise lock the best forever, and a Pong match you
// lost posts a negative margin.
export function isBetter(score: number, prev: number | undefined, lowerIsBetter = false): boolean {
  if (!Number.isFinite(score) || score <= 0) return false
  if (prev === undefined || prev <= 0) return true
  return lowerIsBetter ? score < prev : score > prev
}

// Pong against the computer: pure game logic, drawn by the Pong module in ../surface.tsx.
// Your paddle is the left column, the computer's the right; first to WIN points wins.

export type Ball = { x: number; y: number; dx: number; dy: number }
export type PongGame = { w: number; h: number; ball: Ball; you: number; cpu: number; pad: number; scoreYou: number; scoreCpu: number; over: boolean }

export const WIN = 5
// the computer tracks the ball at under a row per tick, so a steep ball gets past it
const CPU_SPEED = 0.6

const serve = (w: number, h: number, towardYou: boolean, rand: () => number): Ball =>
  ({ x: Math.floor(w / 2), y: h / 2, dx: towardYou ? -1 : 1, dy: rand() < 0.5 ? -0.5 : 0.5 })

export function newPong(w: number, h: number, rand = Math.random): PongGame {
  const pad = Math.max(3, Math.floor(h / 4))
  const mid = Math.floor((h - pad) / 2)
  return { w, h, ball: serve(w, h, false, rand), you: mid, cpu: mid, pad, scoreYou: 0, scoreCpu: 0, over: false }
}

const clampPad = (g: PongGame, top: number) => Math.max(0, Math.min(g.h - g.pad, top))

// move your paddle by rows, or to a row (a pointer over the board), keeping it on the board
export const nudge = (g: PongGame, rows: number): PongGame => (g.over ? g : { ...g, you: clampPad(g, g.you + rows) })
export const place = (g: PongGame, row: number): PongGame => (g.over ? g : { ...g, you: clampPad(g, Math.round(row - g.pad / 2)) })

// a paddle at `top` covers the ball's row: send it back, steeper the further from the centre it hits
function returned(g: PongGame, top: number, ball: Ball, dx: number): Ball | undefined {
  const row = Math.round(ball.y)
  if (row < top || row >= top + g.pad) return undefined
  const offset = (row - (top + (g.pad - 1) / 2)) / g.pad
  return { ...ball, dx, dy: Math.max(-1, Math.min(1, ball.dy + offset)) }
}

export function tick(g: PongGame, rand = Math.random): PongGame {
  if (g.over) return g
  let ball: Ball = { ...g.ball, x: g.ball.x + g.ball.dx, y: g.ball.y + g.ball.dy }
  // top and bottom walls
  if (ball.y < 0) ball = { ...ball, y: -ball.y, dy: -ball.dy }
  if (ball.y > g.h - 1) ball = { ...ball, y: 2 * (g.h - 1) - ball.y, dy: -ball.dy }
  // the computer follows the ball while it comes toward it
  const target = ball.y - (g.pad - 1) / 2
  const cpu = ball.dx > 0 ? clampPad(g, g.cpu + Math.max(-CPU_SPEED, Math.min(CPU_SPEED, target - g.cpu))) : g.cpu
  let { scoreYou, scoreCpu } = g
  if (ball.x <= 0) {
    const back = returned(g, g.you, ball, 1)
    if (back) ball = { ...back, x: 1 }
    else { scoreCpu++; ball = serve(g.w, g.h, false, rand) }
  } else if (ball.x >= g.w - 1) {
    const back = returned(g, Math.round(cpu), ball, -1)
    if (back) ball = { ...back, x: g.w - 2 }
    else { scoreYou++; ball = serve(g.w, g.h, true, rand) }
  }
  return { ...g, ball, cpu, scoreYou, scoreCpu, over: scoreYou >= WIN || scoreCpu >= WIN }
}

