/* @jsx h */
import type { Register } from 'claude-code'
import { isBetter } from './games/best.ts'

// Tetris above the Claude Code prompt, split out of cc-arcade (https://github.com/sezaakgun/cc-arcade,
// MIT, by Seza Akgün) as a single-game mod. `/tetris` opens it, `/tetris stop` closes it. The board in
// ./boards is a surface module that runs on the drawing thread; this module mounts it, keeps the best
// score in $.store and pauses the game when Claude finishes a turn. Playing costs no tokens.

const GAME = 'tetris' // what the board posts its score under
const TITLE = 'Tetris'
const LOWER_IS_BETTER = false
const UNIT = ''

let open = false
// bumped at each finished turn; the open game pauses when it sees a new value
let turnsDone = 0
let best = 0

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    // a store that cannot be read costs the best score, never the game
    const score = Number(await $.store.get('best').catch(() => undefined))
    if (score) best = score
    await $.command.register({
      name: 'tetris',
      description: `$Tetris above the prompt, while Claude works (stop closes)`,
      argumentHint: '[stop]',
      immediate: true,
    }).catch(err => $.ui.log(`tetris: /tetris not registered: ${err}`))
    return r
  })

  on('command.run', { command: 'tetris' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'stop' || arg === 'close') {
      open = false
      $.ui.invalidate('ui.render')
      return { text: `$Tetris closed` }
    }
    open = true
    $.ui.invalidate('ui.render')
    const score = best ? ` · best ${best}$` : ''
    return { text: `$Tetris · click the board to play · Esc returns to the prompt · /tetris stop closes${score}` }
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    // a subagent's turn is not the one the person is waiting for
    if (e.agentId) return r
    if (open) {
      turnsDone++
      $.ui.invalidate('ui.render')
    }
    return r
  })

  // a finished round, posted by the board: keep the best score and hand it back with the next props
  on('ui.message', async ($, e, next) => {
    const data = e.data as { game?: unknown; score?: unknown } | null
    if (data?.game !== GAME || typeof data.score !== 'number') return next(e)
    if (isBetter(data.score, best || undefined, LOWER_IS_BETTER)) {
      best = data.score
      await $.store.set('best', best).catch(err => $.ui.log(`tetris: store write failed: ${err}`))
      $.ui.toast(`$Tetris: new best ${best}$`)
    }
    return { props: { best, done: turnsDone, safe: false } }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // the board needs a terminal's keys and mouse; the desktop and mobile surfaces draw their own band
    if (!open || e.props.hasSurvey || e.surface !== 'terminal') return next(e)
    const { Box, Button, Client } = $.ui.resolve(e)
    // the band's own width: the transcript column's while a Pane is docked beside it
    const cols = e.props.bodyColumns || (e.viewport?.columns ?? 80)
    // one row for the close button, one for whatever else draws in the band
    const rows = Math.max(8, e.props.maxRows - 2)
    const tall = (max: number) => Math.min(rows, max)
    const close = () => {
      open = false
      $.ui.invalidate('ui.render')
    }
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={1}>
          <Button key="tetris:close" label="close" onPress={close} />
        </Box>
        <Client key="board:tetris" module="./boards/tetris.tsx" width={cols} height={tall(23)} props={{ best, done: turnsDone, safe: false }} />
        {await next(e)}
      </Box>
    )
  })
}

/* @jsx h */
import type { ClientElements, ClientSurface } from 'claude-code'

// Shared by the aitmpl game boards. A board is a surface module: it runs on the drawing thread
// with its own frame clock (surface.every), keys once a click gives it focus (Esc gives the
// prompt back) and the mouse. Never name a local `h` here: every JSX tag compiles to a call of `h`.

/** What the hooks module hands every board: the best score, and a counter bumped per finished turn. */
export type Props = { best?: number; done?: number } | undefined
export type Base = { playing: boolean; banner: boolean; seenDone: number }
/** A cell as drawn: two characters, a colour, an optional background. */
export type Paint = readonly [glyph: string, color?: string, bg?: string]
type TextTag = ClientElements['Text']

export const base = (props: Props): Base => ({ playing: false, banner: false, seenDone: props?.done ?? 0 })

/** Claude finished a turn (props.done moved): show the banner and pause, once per turn. */
export function claudeDone<S extends Base>(props: Props, surface: ClientSurface<S>, pause = true) {
  const s = surface.state
  const done = props?.done ?? 0
  if (s && done !== s.seenDone) surface.setState({ ...s, seenDone: done, banner: true, playing: pause ? false : s.playing })
}

export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

type Run = [text: string, color?: string, bg?: string]

/** One row of cells as runs of equal colour, so a row costs a handful of nodes rather than one per cell. */
function runs(cols: number, y: number, at: (x: number, y: number) => Paint): Run[] {
  const out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  return out
}

/** A board of two-character cells (a terminal cell is about twice as tall as wide, so two make a square). */
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/** The space bar arrives as the character or by name, depending on the terminal. */
export const isSpace = (key: string) => key === ' ' || key === 'space'

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, isSpace, statusLine, type Base, type Props } from './common.tsx'
import { BASE, build, enemyPos, H, isPath, KINDS, newDefense, spawn, step, TOWER_COST, UPGRADE_COST, W, type DefenseGame, type Pt } from '../games/defense.ts'

// Tool calls arrive as props: the hooks module keeps the last few with a running number, and the
// board spawns every one it has not seen yet, so a redraw never doubles an enemy.
type Call = { seq: number; tool: string }
type DefenseProps = (Props & { calls?: Call[]; working?: boolean }) | undefined
type State = Base & { game: DefenseGame; seenSeq: number; note?: string; noteTtl: number }

const TICK_MS = 125
const LEVEL_GLYPH = ['', '▲▲', '◆◆', '★★'] as const
const LEVEL_COLOR = ['', 'cyan', 'blueBright', 'yellowBright'] as const

export default function Defense(props: DefenseProps, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), playing: true, game: newDefense(), seenSeq: props?.calls?.at(-1)?.seq ?? 0, noteTtl: 0 })
    surface.every(TICK_MS, () => {
      const s = surface.state
      if (!s || !s.playing || s.game.over) return
      const game = step(s.game)
      if (game.over) surface.post({ game: 'tool-defense', score: game.score })
      surface.setState({ ...s, game, noteTtl: Math.max(0, s.noteTtl - 1) })
    })
    surface.onPointer(ev => {
      const s = surface.state
      if (!s || ev.type !== 'down') return
      // the border takes the first row and column; each cell is two columns wide
      const cell: Pt = [Math.floor((ev.x - 1) / 2), ev.y - 1]
      const { game, note } = build(s.game, cell)
      surface.setState({ ...s, game, note, noteTtl: 20, banner: false })
    })
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key.toLowerCase()
      if (k === 'r') surface.setState({ ...s, game: newDefense(), playing: true, banner: false, note: undefined })
      else if (isSpace(k) || k === 'p') surface.setState({ ...s, playing: !s.playing, banner: false })
    })
  }
  // Claude finishing a turn is news here, not a pause: the enemies stop coming on their own
  claudeDone(props, surface, false)

  // spawn the tool calls that arrived since the last draw
  const s0 = surface.state
  if (s0) {
    const fresh = (props?.calls ?? []).filter(c => c.seq > s0.seenSeq)
    if (fresh.length > 0) {
      let game = s0.game
      for (const c of fresh) game = spawn(game, c.tool)
      if (game.over) surface.post({ game: 'tool-defense', score: game.score })
      surface.setState({ ...s0, game, seenSeq: fresh[fresh.length - 1]!.seq })
    }
  }

  const s = surface.state
  const g = s?.game ?? newDefense()
  const towers = new Map<number, 1 | 2 | 3>()
  for (const t of g.towers) towers.set(t.pos[1] * W + t.pos[0], t.level)
  const enemies = new Map<number, { glyph: string; color: string }>()
  for (const e of g.enemies) {
    const p = enemyPos(e)
    const k = KINDS[e.kind]
    enemies.set(p[1] * W + p[0], { glyph: e.hp < e.maxHp / 2 ? k.glyph.slice(0, 1) + ' ' : k.glyph, color: k.color })
  }
  const hits = new Set(g.shots.map(sh => sh.to[1] * W + sh.to[0]))
  const rows = grid(Text, W, H, (x, y) => {
    const k = y * W + x
    const enemy = enemies.get(k)
    if (enemy) return hits.has(k) ? [enemy.glyph, enemy.color, 'white'] : [enemy.glyph, enemy.color]
    if (x === BASE[0] && y === BASE[1]) return ['▐▌', g.lives > 3 ? 'yellow' : 'red']
    const level = towers.get(k)
    if (level) return [LEVEL_GLYPH[level], LEVEL_COLOR[level]]
    if (isPath([x, y])) return ['░░', 'gray']
    return ['  ']
  })
  const note = s && s.noteTtl > 0 && s.note ? ` · ${s.note}` : ''
  const last = g.enemies[g.enemies.length - 1]
  const text = g.over ? `tool defense · the base fell · score ${g.score}, ${g.kills} kills · r plays again`
    : !s?.playing ? `tool defense · paused · space resumes`
    : `tool defense · gold ${g.gold} · ♥${g.lives} · score ${g.score}${note || (last ? ` · incoming: ${last.tool}` : props?.working ? ' · Claude is working: every tool call is an enemy' : ' · quiet: click a cell to build (25), a tower to upgrade')}`
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g.over ? 'red' : g.lives <= 3 ? 'yellow' : 'cyan'} width={W * 2 + 2}>{rows}</Box>
      {statusLine(Text, !!s?.banner, `${text} · best ${props?.best ?? 0}`)}
      <Text dimColor wrap="truncate-end">{`▶▶ Bash  ██ Edit/Write  ◢◣ web & MCP  ▓▓ Agent  ▪▪ other · tower ${TOWER_COST}, upgrades ${UPGRADE_COST[1]}/${UPGRADE_COST[2]}`}</Text>
    </Box>
  )
}

// Tool Defense's rules, pure and testable. Enemies walk a fixed path across a grid toward your base;
// you place and upgrade towers on the cells beside it. Every enemy is one of Claude's real tool calls,
// shaped by the tool: Bash runs fast, an Edit or Write is slow and tough, a web call flies straight
// over the towers, an Agent is a boss. Between Claude's calls a quiet trickle keeps the game alive.

export type Pt = readonly [x: number, y: number]
export type Kind = 'runner' | 'tank' | 'flyer' | 'boss' | 'scout'
export type Enemy = {
  id: number
  kind: Kind
  /** the tool that spawned it, for the status line */
  tool: string
  /** index along PATH (walkers) or x position (flyers), in cells; fractional between cells */
  at: number
  hp: number
  maxHp: number
  speed: number
  reward: number
}
export type Tower = { pos: Pt; level: 1 | 2 | 3; cooldown: number }
export type Shot = { from: Pt; to: Pt; ttl: number }
export type DefenseGame = {
  readonly w: number
  readonly h: number
  towers: Tower[]
  enemies: Enemy[]
  shots: Shot[]
  gold: number
  lives: number
  score: number
  kills: number
  /** id of the next enemy */
  nextId: number
  /** ticks since the last spawn of any kind, for the idle trickle */
  quiet: number
  over: boolean
  tick: number
}

export const W = 26
export const H = 10
export const TOWER_COST = 25
export const UPGRADE_COST = [0, 30, 50, 0] as const
const RANGE = [0, 2.5, 3.2, 4] as const
const DAMAGE = [0, 1, 2, 4] as const
const FIRE_EVERY = [0, 5, 4, 3] as const
const TRICKLE_EVERY = 45

/** The road, cell by cell: a serpentine from the left edge to the base on the right edge. */
export const PATH: readonly Pt[] = (() => {
  const out: Pt[] = []
  const rows = [1, 4, 7]
  for (let x = 0; x < W - 1; x++) out.push([x, rows[0]!])
  for (let y = rows[0]! + 1; y <= rows[1]!; y++) out.push([W - 2, y])
  for (let x = W - 3; x >= 1; x--) out.push([x, rows[1]!])
  for (let y = rows[1]! + 1; y <= rows[2]!; y++) out.push([1, y])
  for (let x = 2; x < W; x++) out.push([x, rows[2]!])
  return out
})()
const PATH_KEYS = new Set(PATH.map(([x, y]) => y * W + x))
export const BASE: Pt = PATH[PATH.length - 1]!
export const FLY_ROW = 7

export const KINDS: Record<Kind, { hp: number; speed: number; reward: number; glyph: string; color: string }> = {
  scout: { hp: 2, speed: 0.35, reward: 3, glyph: '▪▪', color: 'white' },
  runner: { hp: 3, speed: 0.6, reward: 5, glyph: '▶▶', color: 'greenBright' },
  tank: { hp: 9, speed: 0.22, reward: 9, glyph: '██', color: 'magenta' },
  flyer: { hp: 4, speed: 0.5, reward: 7, glyph: '◢◣', color: 'cyan' },
  boss: { hp: 30, speed: 0.18, reward: 40, glyph: '▓▓', color: 'red' },
}

/** Which enemy a tool call becomes. */
export function kindOf(tool: string): Kind {
  if (tool === 'Bash' || tool === 'PowerShell') return 'runner'
  if (tool === 'Edit' || tool === 'Write' || tool === 'NotebookEdit') return 'tank'
  if (tool === 'WebFetch' || tool === 'WebSearch' || tool.startsWith('mcp__')) return 'flyer'
  if (tool === 'Agent' || tool === 'Workflow') return 'boss'
  return 'scout'
}

export function newDefense(): DefenseGame {
  return { w: W, h: H, towers: [], enemies: [], shots: [], gold: 60, lives: 10, score: 0, kills: 0, nextId: 1, quiet: 0, over: false, tick: 0 }
}

export const isPath = (p: Pt) => PATH_KEYS.has(p[1] * W + p[0])
export const towerAt = (g: DefenseGame, p: Pt) => g.towers.find(t => t.pos[0] === p[0] && t.pos[1] === p[1])

/** Where an enemy is drawn. */
export function enemyPos(e: Enemy): Pt {
  if (e.kind === 'flyer') return [Math.min(W - 1, Math.floor(e.at)), FLY_ROW]
  const i = Math.min(PATH.length - 1, Math.floor(e.at))
  return PATH[i]!
}

export function spawn(g: DefenseGame, tool: string, kind = kindOf(tool)): DefenseGame {
  if (g.over) return g
  const k = KINDS[kind]
  // later waves are tougher: +10% hp per 10 kills
  const hp = Math.ceil(k.hp * (1 + g.kills / 100))
  const enemy: Enemy = { id: g.nextId, kind, tool, at: 0, hp, maxHp: hp, speed: k.speed, reward: k.reward }
  return { ...g, enemies: [...g.enemies, enemy], nextId: g.nextId + 1, quiet: 0 }
}

/** Click on a free cell: build (level 1). Click on a tower: upgrade. Returns the game and what happened. */
export function build(g: DefenseGame, p: Pt): { game: DefenseGame; note?: string } {
  if (g.over) return { game: g }
  if (p[0] < 0 || p[1] < 0 || p[0] >= W || p[1] >= H) return { game: g }
  const existing = towerAt(g, p)
  if (existing) {
    if (existing.level >= 3) return { game: g, note: 'that tower is maxed' }
    const cost = UPGRADE_COST[existing.level]!
    if (g.gold < cost) return { game: g, note: `upgrade costs ${cost} gold` }
    const towers = g.towers.map(t => (t === existing ? { ...t, level: (t.level + 1) as 2 | 3 } : t))
    return { game: { ...g, towers, gold: g.gold - cost }, note: `upgraded to level ${existing.level + 1}` }
  }
  if (isPath(p)) return { game: g, note: 'not on the road' }
  if (g.gold < TOWER_COST) return { game: g, note: `a tower costs ${TOWER_COST} gold` }
  return { game: { ...g, towers: [...g.towers, { pos: p, level: 1, cooldown: 0 }], gold: g.gold - TOWER_COST }, note: 'tower built' }
}

const dist = (a: Pt, b: Pt) => Math.hypot(a[0] - b[0], (a[1] - b[1]) * 1.0)

/** One step of the clock (about 8 a second). */
export function step(g: DefenseGame, rnd: () => number = Math.random): DefenseGame {
  if (g.over) return g
  let out: DefenseGame = { ...g, tick: g.tick + 1, quiet: g.quiet + 1 }

  // the idle trickle: a scout now and then, so there is always something to shoot
  if (out.quiet >= TRICKLE_EVERY && rnd() < 0.5) out = spawn(out, 'idle', 'scout')

  // enemies advance; one that reaches the base costs a life
  let lives = out.lives
  const enemies: Enemy[] = []
  for (const e of out.enemies) {
    const at = e.at + e.speed
    const end = e.kind === 'flyer' ? W - 1 : PATH.length - 1
    if (at >= end) lives--
    else enemies.push({ ...e, at })
  }
  out = { ...out, enemies, lives }
  if (lives <= 0) return { ...out, lives: 0, over: true }

  // towers fire at the nearest enemy in range
  const shots: Shot[] = out.shots.map(s => ({ ...s, ttl: s.ttl - 1 })).filter(s => s.ttl > 0)
  let gold = out.gold
  let score = out.score
  let kills = out.kills
  let alive = out.enemies
  const towers = out.towers.map(t => {
    if (t.cooldown > 0) return { ...t, cooldown: t.cooldown - 1 }
    const range = RANGE[t.level]!
    let target: Enemy | undefined
    let bestD = Infinity
    for (const e of alive) {
      const d = dist(t.pos, enemyPos(e))
      if (d <= range && d < bestD) { bestD = d; target = e }
    }
    if (!target) return t
    const hp = target.hp - DAMAGE[t.level]!
    shots.push({ from: t.pos, to: enemyPos(target), ttl: 2 })
    if (hp <= 0) {
      alive = alive.filter(e => e.id !== target!.id)
      gold += target.reward
      score += target.reward * 10
      kills++
    } else {
      alive = alive.map(e => (e.id === target!.id ? { ...e, hp } : e))
    }
    return { ...t, cooldown: FIRE_EVERY[t.level]! }
  })
  return { ...out, towers, enemies: alive, shots, gold, score, kills }
}

