/* @jsx h */
import type { ClientElements, ClientSurface } from 'claude-code'

// Shared by every board. A board is a surface module: it runs on the drawing thread with its own
// frame clock, keys (after a click gives it focus; Esc gives the prompt back) and mouse.
//
// Never name a local `h` in a board file: every JSX tag compiles to a call of `h`.

export type Props = { best?: number; done?: number; safe?: boolean } | undefined
export type Base = { playing: boolean; banner: boolean; seenDone: number }
export type Paint = readonly [glyph: string, color?: string, bg?: string]
type TextTag = ClientElements['Text']

export const base = (props: Props): Base => ({ playing: false, banner: false, seenDone: props?.done ?? 0 })

// the hooks module bumps props.done when Claude finishes a turn: pause and say so, once per turn
export function claudeDone<S extends Base>(props: Props, surface: ClientSurface<S>) {
  const s = surface.state
  const done = props?.done ?? 0
  if (s && done !== s.seenDone) surface.setState({ ...s, seenDone: done, banner: true, playing: false })
}

export function statusLine(Text: TextTag, banner: boolean, text: string) {
  return banner
    ? <Text color="yellow" bold wrap="truncate-end">{`● Claude is done · ${text}`}</Text>
    : <Text dimColor wrap="truncate-end">{text}</Text>
}

export type Run = [text: string, color?: string, bg?: string]

// one run per stretch of cells sharing both colors. A drawing the engine cannot fit in its node
// budget is worse than a coarser one, so maxRuns folds neighbours together, pair by pair, until
// the row fits: a merged pair keeps the left one's colors and every glyph.
export function runs(cols: number, y: number, at: (x: number, y: number) => Paint, maxRuns = Infinity): Run[] {
  let out: Run[] = []
  for (let x = 0; x < cols; x++) {
    const [glyph, color, bg] = at(x, y)
    const last = out[out.length - 1]
    if (last && last[1] === color && last[2] === bg) last[0] += glyph
    else out.push([glyph, color, bg])
  }
  while (out.length > Math.max(1, maxRuns)) {
    const folded: Run[] = []
    for (let i = 0; i < out.length; i += 2) {
      const [t, c, b] = out[i]
      const next = out[i + 1]
      folded.push(next ? [t + next[0], c, b] : [t, c, b])
    }
    out = folded
  }
  return out
}

// a board as rows of two-character cells (a terminal cell is about twice as tall as wide, so two
// make a square), one styled span per run of the same colors
export function grid(Text: TextTag, cols: number, rowCount: number, at: (x: number, y: number) => Paint, maxRuns = Infinity) {
  return Array.from({ length: Math.max(0, rowCount) }, (_, y) => (
    <Text>{runs(cols, y, at, maxRuns).map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
  ))
}

/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, statusLine, type Base, type Props } from './common.tsx'
import { accuracy, newTyping, press, wpm, type TypingGame } from '../games/typing.ts'

type State = Base & { game: TypingGame; ms: number; started: boolean }
type Run = [text: string, color: string, bg?: string]

export default function Typing(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const fresh = (s: State): State => ({ ...s, banner: false, playing: false, started: false, ms: 0, game: newTyping(Math.random, Math.max(20, surface.columns - 4)) })

  if (surface.state === undefined) {
    surface.setState({ ...base(props), game: newTyping(), ms: 0, started: false })
    // the clock runs from the first key to the last correct one, and stops while Claude's banner shows
    surface.every(100, () => {
      const s = surface.state
      if (s?.started && s.playing && !s.game.done) surface.setState({ ...s, ms: s.ms + 100 })
    })
    surface.onKey(({ key, ctrl, meta }) => {
      const s = surface.state
      if (!s || ctrl || meta) return
      // Tab skips to another line; Enter after a finished line starts the next
      if (key === 'tab' || (key === 'return' && s.game.done)) return surface.setState(fresh(s))
      // the space bar may arrive as the character or by name
      const game = press(s.game, key === 'space' ? ' ' : key)
      if (game === s.game) return
      if (game.done) surface.post({ game: 'typing', score: wpm(game.text.length, s.ms) })
      surface.setState({ ...s, banner: false, playing: true, started: true, game })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  const g = s?.game
  if (!s || !g) return <Text dimColor>typing</Text>

  // typed characters green when right, the expected character on red when wrong, the cursor
  // inverted, the rest dim; one span per run of the same style
  const runs: Run[] = []
  for (let i = 0; i < g.text.length; i++) {
    const style: Run = i < g.typed.length
      ? g.typed[i] === g.text[i] ? [g.text[i], 'green'] : [g.text[i], 'whiteBright', 'red']
      : i === g.typed.length ? [g.text[i], 'black', 'white'] : [g.text[i], 'gray']
    const last = runs[runs.length - 1]
    if (last && last[1] === style[1] && last[2] === style[2]) last[0] += style[0]
    else runs.push(style)
  }
  const seconds = (s.ms / 1000).toFixed(1)
  const text = g.done ? `typing · ${wpm(g.text.length, s.ms)} wpm · ${accuracy(g)}% accuracy · ${seconds}s · Enter for another line`
    : !s.started ? 'typing · click here and type the line · Tab skips to another'
    : `typing · ${wpm(g.typed.length, s.ms)} wpm · ${accuracy(g)}% · ${seconds}s · Tab skips`
  return (
    <Box flexDirection="column">
      <Box borderStyle="round" borderColor={g.done ? 'green' : 'gray'} paddingX={1}>
        <Text>{runs.map(([t, c, b]) => (b ? <Text color={c} backgroundColor={b}>{t}</Text> : <Text color={c}>{t}</Text>))}</Text>
      </Box>
      {statusLine(Text, s.banner, `${text} · best ${props?.best ?? 0} wpm`)}
    </Box>
  )
}

// Which score counts as a new best. Minesweeper's best is its fastest clear, so lower wins there;
// everywhere else higher wins. A score of zero or less never counts: a Minesweeper board whose
// first click clears it takes 0 s and would otherwise lock the best forever, and a Pong match you
// lost posts a negative margin.
export function isBetter(score: number, prev: number | undefined, lowerIsBetter = false): boolean {
  if (!Number.isFinite(score) || score <= 0) return false
  if (prev === undefined || prev <= 0) return true
  return lowerIsBetter ? score < prev : score > prev
}

// Typing test: pure logic, drawn by the Typing module in ../surface.tsx. Lines of code and prose to
// retype; speed is words per minute at five characters a word.

export const LINES = [
  'const total = items.reduce((sum, item) => sum + item.price, 0)',
  'if (!response.ok) throw new Error(`request failed: ${response.status}`)',
  'git commit -m "fix: retry the upload when the connection drops"',
  'for (const [key, value] of Object.entries(config)) console.log(key, value)',
  'The quick brown fox jumps over the lazy dog while the build runs.',
  'export function clamp(n: number, lo: number, hi: number) { return Math.min(hi, Math.max(lo, n)) }',
  'SELECT name, count(*) FROM orders GROUP BY name ORDER BY 2 DESC LIMIT 10;',
  'Small, well-named functions are easier to read than clever ones.',
  'docker run --rm -it -v "$PWD":/app -w /app node:22 npm test',
  'def mean(xs): return sum(xs) / len(xs) if xs else 0.0',
]

export type TypingGame = { text: string; typed: string; errors: number; done: boolean }

export const newTyping = (rand = Math.random, maxLength = Infinity): TypingGame => {
  const fits = LINES.filter(l => l.length <= maxLength)
  const pool = fits.length ? fits : LINES
  return { text: pool[Math.floor(rand() * pool.length)], typed: '', errors: 0, done: false }
}

// one key: a printable character is typed (a wrong one counts as an error and stays until
// backspaced), backspace removes the last character; the line is done when typed exactly
export function press(g: TypingGame, key: string): TypingGame {
  if (g.done) return g
  if (key === 'backspace' || key === 'delete') return { ...g, typed: g.typed.slice(0, -1) }
  if ([...key].length !== 1 || key < ' ') return g
  const typed = g.typed + key
  if (typed.length > g.text.length) return g
  const errors = g.errors + (key === g.text[typed.length - 1] ? 0 : 1)
  return { ...g, typed, errors, done: typed === g.text }
}

export const wpm = (chars: number, ms: number) => (ms > 0 ? Math.round((chars / 5) / (ms / 60_000)) : 0)
export const accuracy = (g: TypingGame) => (g.typed.length ? Math.max(0, Math.round(100 * (1 - g.errors / (g.typed.length + g.errors)))) : 100)

