/**
 * bluesky-feed — Claude Mod
 *
 * Your Bluesky "Following" timeline in a side pane:
 *
 *   - the posts of the accounts you follow, newest first, with reposts and
 *     replies marked, images, videos, link cards and quotes described in a line
 *   - a field to write and send a post (links and #hashtags become clickable)
 *   - a like button on every post (press again to unlike) and a link that
 *     opens the post on bsky.app
 *
 * `/bsky` opens it, `/bsky stop` closes it. `$.clock.every(5000)` decides when
 * to read again, every `pollSeconds`, only while the pane is open.
 *
 * It logs in with an app password (Bluesky, Settings, Privacy and security,
 * App passwords), never your account password. The app password and the
 * session tokens stay in memory, are sent only to `service`, and are never
 * logged, drawn or stored. Never hardcode them in this file.
 *
 * Needs Claude Code >= 2.1.287.
 *
 * Options (pluginConfigs["bluesky-feed@skills-dir"].options):
 *   handle: string        your handle, e.g. dan.bsky.social (required)
 *   appPassword: string   an app password (required)
 *   service: string       your PDS (default https://bsky.social)
 *   limit: number         posts per page, 10-50 (default 30)
 *   pollSeconds: number   refresh interval, 30-3600 (default 120)
 *   openOnStart: boolean  open the pane at session start (default false)
 */
import type { Register } from 'claude-code'
import { BskyError, Client, MAX_GRAPHEMES, ago, clampInt, compact, graphemes, handleOf, postUrl, serviceUrl } from './bsky-api.ts'
import type { Post } from './bsky-api.ts'

const PANE = 'bsky'
const COMMAND = 'bsky'
const TICK_MS = 5000
const MAX_POSTS = 120

const SKY = '#1185fe'
const PINK = '#ec4899'
const INK = '#0b1220'
const GREY = '#8a8a8a'
const RULE = '#3a3a3a'
const GREEN = '#22c55e'

let posts: Post[] = []
let cursor: string | undefined
let error: string | undefined
let notice: { text: string; tone: 'success' | 'error' } | undefined
let isOpen = false
let isBusy = false
let isPosting = false
let lastReadAt = 0
let draftLength = 0
let composeGeneration = 0
let timer: { cancel: () => void } | undefined

const text = (v: unknown) => (typeof v === 'string' ? v.trim() : '')
const message = (err: unknown) => (err instanceof Error ? err.message : String(err))
// Desktop draws text as HTML and collapses runs of spaces; keep short gaps
const nb = (s: string) => s.replace(/ /g, ' ')

export const register: Register = (on, options) => {
  const handle = handleOf(options.handle)
  const password = text(options.appPassword)
  const service = serviceUrl(options.service)
  const limit = clampInt(options.limit, 30, 10, 50)
  const pollMs = clampInt(options.pollSeconds, 120, 30, 3600) * 1000
  const openOnStart = options.openOnStart === true
  const isConfigured = handle !== '' && password !== ''

  let client: Client | undefined
  const api = (f: ConstructorParameters<typeof Client>[0]) => (client ??= new Client(f, service, handle, password))

  async function read(c: Client, more = false): Promise<void> {
    isBusy = true
    try {
      const page = await c.timeline(limit, more ? cursor : undefined)
      if (more) {
        const seen = new Set(posts.map(p => p.uri))
        posts = [...posts, ...page.posts.filter(p => !seen.has(p.uri))].slice(0, MAX_POSTS)
      } else {
        posts = page.posts
      }
      cursor = page.cursor
      error = undefined
    } catch (err) {
      error = message(err)
    } finally {
      lastReadAt = Date.now()
      isBusy = false
    }
  }

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await $.command
      .register({
        name: COMMAND,
        description: 'Your Bluesky timeline: read, post and like (stop closes)',
        argumentHint: '[stop]',
        immediate: true,
      })
      .catch(err => $.ui.log(`bluesky-feed: /${COMMAND} not registered: ${err}`))
    if (!isConfigured) {
      $.ui.log('bluesky-feed: set handle and appPassword in the plugin options', { to: 'debug' })
      return r
    }

    timer?.cancel()
    timer = $.clock.every(TICK_MS, () => {
      if (isBusy || !isOpen) return
      if (Date.now() - lastReadAt < pollMs - TICK_MS / 2) return
      void read(api((url, init) => $.http.fetch(url, init))).then(() => $.ui.invalidate('ui.render'))
    })

    if (openOnStart) {
      // open first and read in the background: a slow PDS never holds up the session
      isOpen = true
      await $.ui.open({ id: PANE, title: 'bluesky' }).catch(() => {
        isOpen = false
      })
      if (isOpen) void read(api((url, init) => $.http.fetch(url, init))).then(() => $.ui.invalidate('ui.render'))
    }
    return r
  })

  on('session.end', async ($, e, next) => {
    timer?.cancel()
    timer = undefined
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    if (!isConfigured) return { text: 'bsky: set handle and appPassword in the plugin options' }
    if (['stop', 'close'].includes(e.args.trim().toLowerCase())) {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      isOpen = false
      return { text: 'bluesky closed' }
    }
    await read(api((url, init) => $.http.fetch(url, init)))
    isOpen = true
    const opened = await $.ui.open({ id: PANE, title: 'bluesky', focus: true }).then(
      () => true,
      () => false,
    )
    if (!opened) {
      isOpen = false
      return { text: 'bsky: the pane could not open here' }
    }
    $.ui.invalidate('ui.render')
    if (error) return { text: `bsky: ${error}` }
    return { text: `bluesky: ${posts.length} posts from the accounts you follow · /${COMMAND} stop closes` }
  })

  on('ui.close', async ($, e, next) => {
    if (e.id !== PANE) return next(e)
    isOpen = false
    return next(e)
  })

  on('ui.input', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE || !e.element.startsWith('compose')) return next(e)
    const r = await next(e)
    if (e.kind === 'change') {
      const n = graphemes(e.value)
      // redraw only when the counter's look changes, not on every key
      const band = (x: number) => (x === 0 ? 0 : x > MAX_GRAPHEMES ? 3 : x > MAX_GRAPHEMES - 20 ? 2 : 1)
      const changed = band(n) !== band(draftLength) || band(n) >= 2
      draftLength = n
      if (changed) $.ui.invalidate('ui.render')
      return r
    }
    const body = e.value.trim()
    if (!body || isPosting) return r
    if (graphemes(body) > MAX_GRAPHEMES) {
      notice = { text: `Too long: ${graphemes(body)}/${MAX_GRAPHEMES} characters`, tone: 'error' }
      $.ui.invalidate('ui.render')
      return r
    }
    isPosting = true
    $.ui.invalidate('ui.render')
    try {
      const c = api((url, init) => $.http.fetch(url, init))
      await c.post(body)
      notice = { text: 'Posted', tone: 'success' }
      composeGeneration++
      draftLength = 0
      $.ui.toast('🦋 posted to Bluesky')
      await read(c)
    } catch (err) {
      notice = { text: `Not posted: ${message(err)}`, tone: 'error' }
    } finally {
      isPosting = false
    }
    $.ui.invalidate('ui.render')
    return r
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    const r = await next(e)
    const target = e.element
    const c = api((url, init) => $.http.fetch(url, init))
    if (target === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return r
    }
    if (target === 'refresh') {
      notice = undefined
      if (!isBusy) await read(c)
    } else if (target === 'more') {
      if (!isBusy && cursor) await read(c, true)
    } else if (target.startsWith('like:')) {
      const p = posts.find(x => x.cid === target.slice(5))
      if (p && p.likeUri !== 'pending') {
        // optimistic: draw the heart now, put it back if Bluesky refuses
        const before = { likeUri: p.likeUri, likeCount: p.likeCount }
        const wasLiked = Boolean(p.likeUri)
        p.likeUri = wasLiked ? undefined : 'pending'
        p.likeCount = Math.max(0, p.likeCount + (wasLiked ? -1 : 1))
        $.ui.invalidate('ui.render')
        try {
          if (wasLiked) await c.unlike(before.likeUri!)
          else p.likeUri = await c.like(p)
        } catch (err) {
          Object.assign(p, before)
          notice = { text: `${wasLiked ? 'Unlike' : 'Like'} failed: ${message(err)}`, tone: 'error' }
          if (err instanceof BskyError && err.status === 401) error = err.message
        }
      }
    }
    $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    // a pane the engine kept open across a reload or a resume: read once, poll again
    if (isConfigured && !isOpen) {
      isOpen = true
      if (lastReadAt === 0 && !isBusy) void read(api((url, init) => $.http.fetch(url, init))).then(() => $.ui.invalidate('ui.render'))
    }
    const els = $.ui.resolve(e)
    const { Box, Text, Button } = els
    // mobile draws no field and no link: there the timeline is read-only
    const Input = 'Input' in els ? els.Input : undefined
    const Link = 'Link' in els ? els.Link : undefined
    const W = Math.max(30, e.props.bodyColumns - 1)
    const now = Date.now()
    const noop = () => {}
    const me = client?.session?.handle ?? handle
    const counter = MAX_GRAPHEMES - draftLength
    const counterColor = counter < 0 ? 'error' : counter < 20 ? 'warning' : GREY

    const rows = posts.map(p => {
      const isLiked = Boolean(p.likeUri)
      const lines = p.text.split('\n').filter((l, i, all) => l.trim() !== '' || (i > 0 && i < all.length - 1))
      return (
        <Box key={`p:${p.uri}`} flexDirection="column" width={W}>
          {p.repostBy ? <Text color={GREEN} wrap="truncate-end">{nb(`↻ reposted by ${p.repostBy}`)}</Text> : null}
          <Text wrap="truncate-end">
            <Text color={SKY} bold>{p.name || p.handle}</Text>
            <Text color={GREY}>{nb(` @${p.handle} · ${ago(p.createdAt, now)}`)}</Text>
          </Text>
          {p.replyTo ? <Text color={SKY} dimColor wrap="truncate-end">{nb(`↳ replying to @${p.replyTo}`)}</Text> : null}
          {lines.map((l, i) => (
            <Text key={`l:${i}`}>{l || ' '}</Text>
          ))}
          {p.embed ? <Text color={GREY} wrap="truncate-end">{p.embed}</Text> : null}
          <Box flexDirection="row" columnGap={2}>
            <Box flexDirection="row">
              <Text color={isLiked ? PINK : GREY}>{nb(isLiked ? '♥ ' : '♡ ')}</Text>
              {/* a label string, not rich children: Claude Code 2.1.287 (and the Desktop build) skips the whole render on those */}
              <Button key={`like:${p.cid}`} plain dimColor={!isLiked} label={compact(p.likeCount)} onPress={noop} />
            </Box>
            <Text color={GREY}>{nb(`↩ ${compact(p.replyCount)}`)}</Text>
            <Text color={GREY}>{nb(`↻ ${compact(p.repostCount)}`)}</Text>
            {Link ? <Link href={postUrl(p)} label="open ↗" /> : null}
          </Box>
          <Text color={RULE}>{'─'.repeat(W)}</Text>
        </Box>
      )
    })

    return (
      <Box flexDirection="column" width={W}>
        <Box key="head" flexDirection="column" width={W}>
          <Box flexDirection="row" justifyContent="space-between" width={W}>
            <Text>
              <Text backgroundColor={SKY} color={INK} bold>{nb(' 🦋 BLUESKY ')}</Text>
              <Text backgroundColor="#1b2a41" color="#e6f0ff" bold>{nb(' FOLLOWING ')}</Text>
            </Text>
            <Text color={GREY}>{nb([`@${me}`, isBusy ? 'updating…' : lastReadAt ? `updated ${ago(new Date(lastReadAt).toISOString(), now)}` : ''].filter(Boolean).join(' · '))}</Text>
          </Box>
          <Text color={RULE}>{'─'.repeat(W)}</Text>
          {error ? <Text color="error">{`! ${error}`}</Text> : null}
          {notice ? <Text color={notice.tone}>{`${notice.tone === 'success' ? '✓' : '!'} ${notice.text}`}</Text> : null}
        </Box>

        {Input ? (
          <Box key="compose-box" flexDirection="column" width={W} marginBottom={1}>
            <Input
              key={`compose:${composeGeneration}`}
              label="✎ post"
              placeholder="What's up?"
              submitLabel={isPosting ? 'posting…' : 'post'}
              onSubmit={noop}
            />
            <Text color={counterColor}>{nb(`${counter} left · Enter posts · links and #tags are clickable`)}</Text>
          </Box>
        ) : null}

        {posts.length === 0 && !error ? <Text color={GREY}>{isBusy ? 'Loading your timeline…' : 'Nothing here yet: follow a few accounts on bsky.app'}</Text> : null}
        {rows}

        <Box key="foot" flexDirection="column" width={W}>
          <Box flexDirection="row" columnGap={1}>
            {cursor && posts.length < MAX_POSTS ? <Button key="more" label="more" hotkey="m" onPress={noop} /> : null}
            <Button key="refresh" label="refresh" hotkey="r" onPress={noop} />
            <Button key="close" label="close" onPress={noop} />
          </Box>
          <Text color={GREY}>{nb(`${posts.length} posts · refreshes every ${Math.round(pollMs / 1000)}s while open`)}</Text>
        </Box>
      </Box>
    )
  })
}

/**
 * Bluesky's XRPC API, the parts bluesky-feed uses. Pure functions and one
 * small client over an injected fetch, so the tests drive it without a
 * network and the hooks module passes `$.http.fetch`.
 *
 * Shapes checked against the lexicons shipped in @atproto/api 0.28:
 * com.atproto.server.createSession / refreshSession, app.bsky.feed.getTimeline
 * (FeedViewPost, PostView, ViewerState, ReasonRepost), app.bsky.feed.post,
 * app.bsky.feed.like, app.bsky.richtext.facet, com.atproto.repo.createRecord /
 * deleteRecord.
 */

export type Fetch = (
  url: string,
  init?: { method?: string; headers?: Record<string, string>; body?: string },
) => Promise<{ status: number; ok: boolean; text: string }>

export type Session = { did: string; handle: string; accessJwt: string; refreshJwt: string }

export type Post = {
  uri: string
  cid: string
  handle: string
  name: string
  text: string
  createdAt: string
  likeCount: number
  repostCount: number
  replyCount: number
  /** The viewer's like record, when they liked it: what an unlike deletes. */
  likeUri?: string
  /** Who reposted it into the timeline. */
  repostBy?: string
  /** The handle of the post this one answers. */
  replyTo?: string
  /** One line describing images, a video, a link card or a quoted post. */
  embed?: string
}

export const MAX_GRAPHEMES = 300

export class BskyError extends Error {
  readonly status: number
  readonly code: string | undefined

  constructor(message: string, status: number, code?: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

type Json = Record<string, unknown>
const obj = (v: unknown): Json => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Json) : {})
const str = (v: unknown): string => (typeof v === 'string' ? v : '')
const num = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0)

export const clampInt = (v: unknown, fallback: number, min: number, max: number): number => {
  const n = typeof v === 'number' && Number.isFinite(v) ? Math.round(v) : fallback
  return Math.min(max, Math.max(min, n))
}

/**
 * `https://bsky.social` from whatever the option holds; never a trailing slash.
 * https only, so the app password never travels in cleartext; plain http is
 * kept for a PDS on this machine (localhost, 127.0.0.1), as in development.
 */
export const serviceUrl = (v: unknown): string => {
  const s = str(v).trim().replace(/\/+$/, '')
  if (!s) return 'https://bsky.social'
  if (/^https:\/\//.test(s)) return s
  if (/^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(s)) return s
  if (/^[a-z]+:\/\//i.test(s)) return 'https://bsky.social'
  return `https://${s}`
}

/** `@dan.bsky.social` and `dan.bsky.social` are the same identifier. */
export const handleOf = (v: unknown): string => str(v).trim().replace(/^@/, '')

export const rkeyOf = (uri: string): string => uri.split('/').pop() ?? ''

export const postUrl = (p: Pick<Post, 'uri' | 'handle'>): string =>
  `https://bsky.app/profile/${p.handle}/post/${rkeyOf(p.uri)}`

export function graphemes(text: string): number {
  const Seg = (Intl as { Segmenter?: new (l?: string, o?: { granularity: string }) => { segment: (s: string) => Iterable<unknown> } }).Segmenter
  if (Seg) {
    let n = 0
    for (const _ of new Seg(undefined, { granularity: 'grapheme' }).segment(text)) n++
    return n
  }
  return [...text].length
}

type Facet = { index: { byteStart: number; byteEnd: number }; features: Json[] }

/**
 * Links and hashtags as richtext facets, so they are clickable on bsky.app.
 * Offsets are UTF-8 byte offsets. Mentions are left plain: they need the
 * handle resolved to a DID, one more request per name.
 */
export function facetsOf(text: string): Facet[] {
  const enc = new TextEncoder()
  const bytes = (s: string) => enc.encode(s).length
  const out: Facet[] = []
  for (const m of text.matchAll(/https?:\/\/[^\s<>"]+/g)) {
    const uri = m[0].replace(/[.,;:!?)\]}'"]+$/, '')
    const start = bytes(text.slice(0, m.index))
    out.push({ index: { byteStart: start, byteEnd: start + bytes(uri) }, features: [{ $type: 'app.bsky.richtext.facet#link', uri }] })
  }
  for (const m of text.matchAll(/(^|\s)#([^\s#.,;:!?)\]}'"]+)/g)) {
    // Bluesky does not treat a tag of digits alone (#1) as a hashtag
    if (/^\d+$/.test(m[2]!)) continue
    const at = (m.index ?? 0) + m[1]!.length
    const start = bytes(text.slice(0, at))
    out.push({ index: { byteStart: start, byteEnd: start + bytes(`#${m[2]}`) }, features: [{ $type: 'app.bsky.richtext.facet#tag', tag: m[2] }] })
  }
  return out.sort((a, b) => a.index.byteStart - b.index.byteStart)
}

function describeEmbed(v: unknown): string | undefined {
  const e = obj(v)
  const type = str(e.$type)
  if (type.startsWith('app.bsky.embed.images')) {
    const n = Array.isArray(e.images) ? e.images.length : 1
    return n === 1 ? '▣ image' : `▣ ${n} images`
  }
  if (type.startsWith('app.bsky.embed.video')) return '▶ video'
  if (type.startsWith('app.bsky.embed.external')) {
    const x = obj(e.external)
    return `🔗 ${str(x.title) || str(x.uri)}`
  }
  if (type.startsWith('app.bsky.embed.recordWithMedia')) {
    return [describeEmbed(e.media), describeEmbed(e.record)].filter(Boolean).join(' · ')
  }
  if (type.startsWith('app.bsky.embed.record')) {
    const r = obj(obj(e.record).record ?? e.record)
    const author = str(obj(r.author).handle)
    return author ? `❝ quoting @${author}` : '❝ quote'
  }
  return undefined
}

/** The timeline's FeedViewPosts as Posts; anything malformed is dropped. */
export function parseTimeline(text: string): { posts: Post[]; cursor?: string } {
  const body = obj(JSON.parse(text))
  const feed = Array.isArray(body.feed) ? body.feed : []
  const posts: Post[] = []
  for (const item of feed) {
    const it = obj(item)
    const p = obj(it.post)
    const author = obj(p.author)
    const record = obj(p.record)
    if (!str(p.uri) || !str(p.cid) || !str(author.handle)) continue
    const reason = obj(it.reason)
    const parent = obj(obj(it.reply).parent)
    posts.push({
      uri: str(p.uri),
      cid: str(p.cid),
      handle: str(author.handle),
      name: str(author.displayName).trim(),
      text: str(record.text),
      createdAt: str(record.createdAt) || str(p.indexedAt),
      likeCount: num(p.likeCount),
      repostCount: num(p.repostCount),
      replyCount: num(p.replyCount),
      likeUri: str(obj(p.viewer).like) || undefined,
      repostBy: str(reason.$type).endsWith('#reasonRepost') ? str(obj(reason.by).displayName).trim() || str(obj(reason.by).handle) : undefined,
      replyTo: str(obj(parent.author).handle) || undefined,
      embed: describeEmbed(p.embed),
    })
  }
  const cursor = str(body.cursor) || undefined
  return { posts, cursor }
}

/** `now`, `5m`, `3h`, `2d`, then the date. */
export function ago(iso: string, now: number): string {
  const t = Date.parse(iso)
  if (!Number.isFinite(t)) return ''
  const s = Math.max(0, Math.round((now - t) / 1000))
  if (s < 60) return 'now'
  if (s < 3600) return `${Math.floor(s / 60)}m`
  if (s < 86_400) return `${Math.floor(s / 3600)}h`
  if (s < 7 * 86_400) return `${Math.floor(s / 86_400)}d`
  return new Date(t).toISOString().slice(0, 10)
}

/** 1234 -> 1.2K; the pane is narrow. */
export const compact = (n: number): string =>
  n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1).replace(/\.0$/, '')}M` : n >= 1000 ? `${(n / 1000).toFixed(1).replace(/\.0$/, '')}K` : String(n)

/**
 * One account's session over XRPC. Logs in on first use with the app
 * password, refreshes an expired access token with the refresh token, and
 * logs in again when the refresh is refused. The password and the tokens stay
 * in memory, are sent only to `service`, and never appear in an error.
 */
export class Client {
  session: Session | undefined
  private pendingLogin: Promise<Session> | undefined
  private readonly fetch: Fetch
  private readonly service: string
  private readonly identifier: string
  private readonly password: string

  constructor(fetch: Fetch, service: string, identifier: string, password: string) {
    this.fetch = fetch
    this.service = service
    this.identifier = identifier
    this.password = password
  }

  private async xrpc(nsid: string, opts: { method?: 'GET' | 'POST'; token?: string; body?: unknown; params?: Record<string, string> }): Promise<Json> {
    const qs = opts.params ? `?${new URLSearchParams(opts.params).toString()}` : ''
    const headers: Record<string, string> = {}
    if (opts.token) headers.authorization = `Bearer ${opts.token}`
    if (opts.body !== undefined) headers['content-type'] = 'application/json'
    const res = await this.fetch(`${this.service}/xrpc/${nsid}${qs}`, {
      method: opts.method ?? 'GET',
      headers,
      body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
    })
    let data: Json = {}
    try {
      data = obj(res.text ? JSON.parse(res.text) : {})
    } catch {
      data = {}
    }
    if (!res.ok) throw new BskyError(str(data.message) || str(data.error) || `HTTP ${res.status}`, res.status, str(data.error) || undefined)
    return data
  }

  private take(d: Json): Session {
    const s = { did: str(d.did), handle: str(d.handle), accessJwt: str(d.accessJwt), refreshJwt: str(d.refreshJwt) }
    if (!s.did || !s.accessJwt) throw new BskyError('Bluesky answered the login without a session', 500)
    this.session = s
    return s
  }

  /** One login at a time: a poll, a press and a post racing share it. */
  login(): Promise<Session> {
    this.pendingLogin ??= this.createSession().finally(() => {
      this.pendingLogin = undefined
    })
    return this.pendingLogin
  }

  private async createSession(): Promise<Session> {
    try {
      return this.take(await this.xrpc('com.atproto.server.createSession', { method: 'POST', body: { identifier: this.identifier, password: this.password } }))
    } catch (err) {
      if (err instanceof BskyError && (err.status === 401 || err.code === 'AuthenticationRequired'))
        throw new BskyError('Bluesky refused the handle or app password', 401, err.code)
      throw err
    }
  }

  private async refresh(): Promise<Session> {
    const s = this.session
    if (!s) return this.login()
    try {
      return this.take(await this.xrpc('com.atproto.server.refreshSession', { method: 'POST', token: s.refreshJwt }))
    } catch (err) {
      // a refused refresh token means log in again; an outage is reported as is
      if (err instanceof BskyError && (err.status === 400 || err.status === 401)) return this.login()
      throw err
    }
  }

  /** A call with the access token, refreshed once if Bluesky says it expired. */
  async call(nsid: string, opts: { method?: 'GET' | 'POST'; body?: unknown; params?: Record<string, string> } = {}): Promise<Json> {
    const s = this.session ?? (await this.login())
    try {
      return await this.xrpc(nsid, { ...opts, token: s.accessJwt })
    } catch (err) {
      const expired = err instanceof BskyError && (err.code === 'ExpiredToken' || err.code === 'InvalidToken' || err.status === 401)
      if (!expired) throw err
      const fresh = await this.refresh()
      return this.xrpc(nsid, { ...opts, token: fresh.accessJwt })
    }
  }

  async timeline(limit: number, cursor?: string): Promise<{ posts: Post[]; cursor?: string }> {
    const params: Record<string, string> = { limit: String(limit) }
    if (cursor) params.cursor = cursor
    return parseTimeline(JSON.stringify(await this.call('app.bsky.feed.getTimeline', { params })))
  }

  async post(text: string, now = new Date()): Promise<{ uri: string; cid: string }> {
    const s = this.session ?? (await this.login())
    const facets = facetsOf(text)
    const record: Json = { $type: 'app.bsky.feed.post', text, createdAt: now.toISOString() }
    if (facets.length > 0) record.facets = facets
    const d = await this.call('com.atproto.repo.createRecord', { method: 'POST', body: { repo: s.did, collection: 'app.bsky.feed.post', record } })
    return { uri: str(d.uri), cid: str(d.cid) }
  }

  async like(p: Pick<Post, 'uri' | 'cid'>, now = new Date()): Promise<string> {
    const s = this.session ?? (await this.login())
    const d = await this.call('com.atproto.repo.createRecord', {
      method: 'POST',
      body: { repo: s.did, collection: 'app.bsky.feed.like', record: { $type: 'app.bsky.feed.like', subject: { uri: p.uri, cid: p.cid }, createdAt: now.toISOString() } },
    })
    return str(d.uri)
  }

  async unlike(likeUri: string): Promise<void> {
    const s = this.session ?? (await this.login())
    await this.call('com.atproto.repo.deleteRecord', { method: 'POST', body: { repo: s.did, collection: 'app.bsky.feed.like', rkey: rkeyOf(likeUri) } })
  }
}

