/**
 * linear-api.ts — the Linear GraphQL reads the mod makes, and the arithmetic
 * behind its charts. No `$` in here.
 *
 * Reference: https://linear.app/developers (POST https://api.linear.app/graphql).
 * A personal API key goes in `Authorization` as it is; an OAuth token
 * (`lin_oauth_...`) goes as `Bearer <token>`. Fields used, checked against
 * linear/linear's schema.graphql:
 *   issues(filter, first, orderBy)   Issue { identifier title url priority priorityLabel estimate
 *                                    updatedAt startedAt completedAt dueDate
 *                                    state { name type color } cycle { id number name startsAt endsAt }
 *                                    project { name } assignee { name } }
 *   cycle(id)                        Cycle { number name progress startsAt endsAt
 *                                    scopeHistory completedScopeHistory issueCountHistory completedIssueCountHistory }
 * Workflow state `type` is one of triage, backlog, unstarted, started, completed, canceled.
 * The key is only sent to api.linear.app and never logged.
 */

export const ENDPOINT = 'https://api.linear.app/graphql'

export type Fetch = (
  url: string,
  init?: { method?: string; headers?: Record<string, string>; body?: string },
) => Promise<{ status: number; ok: boolean; text: string }>

export type Bucket = 'started' | 'todo' | 'backlog' | 'done'

export type Ticket = {
  id: string
  identifier: string
  title: string
  url: string
  stateName: string
  stateType: string
  bucket: Bucket | 'canceled'
  priority: number
  priorityLabel?: string
  estimate?: number
  updatedAt?: number
  startedAt?: number
  completedAt?: number
  dueDate?: string
  project?: string
  cycle?: { id: string; number: number; name?: string; startsAt: number; endsAt: number }
}

export type Cycle = {
  number: number
  name?: string
  progress: number
  startsAt: number
  endsAt: number
  scope: number[]
  completed: number[]
}

const obj = (v: unknown): Record<string, unknown> | undefined =>
  v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : undefined
const str = (v: unknown): string | undefined => (typeof v === 'string' && v ? v : undefined)
const num = (v: unknown): number | undefined => (typeof v === 'number' && Number.isFinite(v) ? v : undefined)
const time = (v: unknown): number | undefined => {
  const s = str(v)
  const t = s ? Date.parse(s) : NaN
  return Number.isNaN(t) ? undefined : t
}
const numbers = (v: unknown): number[] => (Array.isArray(v) ? v.filter((n): n is number => typeof n === 'number') : [])

export function bucketOf(type: string): Ticket['bucket'] {
  switch (type) {
    case 'started':
      return 'started'
    case 'unstarted':
      return 'todo'
    case 'completed':
      return 'done'
    case 'canceled':
      return 'canceled'
    default:
      return 'backlog'
  }
}

export const ISSUES_QUERY = `query Tickets($filter: IssueFilter, $first: Int) {
  issues(filter: $filter, first: $first, orderBy: updatedAt) {
    nodes {
      id identifier title url priority priorityLabel estimate
      updatedAt startedAt completedAt dueDate
      state { name type }
      project { name }
      cycle { id number name startsAt endsAt }
    }
  }
}`

export const CYCLE_QUERY = `query Cycle($id: String!) {
  cycle(id: $id) {
    number name progress startsAt endsAt
    scopeHistory completedScopeHistory
  }
}`

export type Scope = { assignee: 'me' | 'anyone'; teamKey: string; project: string }

/** Open tickets plus those closed since `sinceIso`, narrowed by the scope. */
export function buildFilter(scope: Scope, sinceIso: string): Record<string, unknown> {
  const and: Record<string, unknown>[] = []
  if (scope.assignee === 'me') and.push({ assignee: { isMe: { eq: true } } })
  if (scope.teamKey) and.push({ team: { key: { eq: scope.teamKey } } })
  if (scope.project) and.push({ project: { name: { containsIgnoreCase: scope.project } } })
  and.push({
    or: [{ state: { type: { nin: ['completed', 'canceled'] } } }, { completedAt: { gte: sinceIso } }],
  })
  return { and }
}

export function parseTicket(raw: unknown): Ticket | undefined {
  const n = obj(raw)
  const id = str(n?.id)
  const identifier = str(n?.identifier)
  if (!n || !id || !identifier) return undefined
  const state = obj(n.state)
  const stateType = str(state?.type) ?? 'backlog'
  const cycle = obj(n.cycle)
  const cycleId = str(cycle?.id)
  const startsAt = time(cycle?.startsAt)
  const endsAt = time(cycle?.endsAt)
  return {
    id,
    identifier,
    title: str(n.title) ?? '(no title)',
    url: str(n.url) ?? '',
    stateName: str(state?.name) ?? stateType,
    stateType,
    bucket: bucketOf(stateType),
    priority: num(n.priority) ?? 0,
    priorityLabel: str(n.priorityLabel),
    estimate: num(n.estimate),
    updatedAt: time(n.updatedAt),
    startedAt: time(n.startedAt),
    completedAt: time(n.completedAt),
    dueDate: str(n.dueDate),
    project: str(obj(n.project)?.name),
    cycle:
      cycleId && startsAt !== undefined && endsAt !== undefined
        ? { id: cycleId, number: num(cycle?.number) ?? 0, name: str(cycle?.name), startsAt, endsAt }
        : undefined,
  }
}

/** GraphQL answers 200 with `errors` for a bad query or key; surface the first message. */
export function graphqlData(text: string): Record<string, unknown> {
  const body = obj(JSON.parse(text))
  const errors = body?.errors
  if (Array.isArray(errors) && errors.length > 0) {
    throw new Error(`Linear: ${str(obj(errors[0])?.message) ?? 'the query was refused'}`)
  }
  const data = obj(body?.data)
  if (!data) throw new Error('Linear answered without data')
  return data
}

export function parseTickets(text: string): Ticket[] {
  const nodes = obj(graphqlData(text).issues)?.nodes
  return (Array.isArray(nodes) ? nodes : []).map(parseTicket).filter((t): t is Ticket => t !== undefined && t.bucket !== 'canceled')
}

export function parseCycle(text: string): Cycle | undefined {
  const c = obj(graphqlData(text).cycle)
  const startsAt = time(c?.startsAt)
  const endsAt = time(c?.endsAt)
  if (!c || startsAt === undefined || endsAt === undefined) return undefined
  return {
    number: num(c.number) ?? 0,
    name: str(c.name),
    progress: num(c.progress) ?? 0,
    startsAt,
    endsAt,
    scope: numbers(c.scopeHistory),
    completed: numbers(c.completedScopeHistory),
  }
}

async function post(f: Fetch, key: string, query: string, variables: Record<string, unknown>): Promise<string> {
  const res = await f(ENDPOINT, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: key.startsWith('lin_oauth_') ? `Bearer ${key}` : key,
    },
    body: JSON.stringify({ query, variables }),
  })
  if (res.status === 401 || res.status === 403) throw new Error(`Linear refused the key (${res.status}); check linearApiKey`)
  if (!res.ok && res.status >= 500) throw new Error(`Linear answered ${res.status}`)
  return res.text
}

export async function listTickets(f: Fetch, key: string, scope: Scope, sinceIso: string): Promise<Ticket[]> {
  return parseTickets(await post(f, key, ISSUES_QUERY, { filter: buildFilter(scope, sinceIso), first: 100 }))
}

export async function getCycle(f: Fetch, key: string, id: string): Promise<Cycle | undefined> {
  return parseCycle(await post(f, key, CYCLE_QUERY, { id }))
}

/** The cycle running at `now` among the tickets', the one most of them sit in. */
export function currentCycleId(tickets: readonly Ticket[], now: number): string | undefined {
  const counts = new Map<string, number>()
  for (const t of tickets) {
    if (t.cycle && t.cycle.startsAt <= now && now <= t.cycle.endsAt) counts.set(t.cycle.id, (counts.get(t.cycle.id) ?? 0) + 1)
  }
  let best: string | undefined
  let n = 0
  for (const [id, c] of counts) if (c > n) [best, n] = [id, c]
  return best
}

const DAY = 86_400_000

/**
 * Local day number of a time: whole days since the epoch in the viewer's timezone.
 * `tz` is an offset in minutes (as `Date.getTimezoneOffset` returns) or a function
 * of the time. Left out, each time uses the offset in force at that moment, so a
 * daylight-saving change inside the window does not shift older days.
 */
export type TzOffset = number | ((ms: number) => number)
const localOffset = (ms: number) => new Date(ms).getTimezoneOffset()
export const dayOf = (ms: number, tz: TzOffset = localOffset) =>
  Math.floor((ms - (typeof tz === 'function' ? tz(ms) : tz) * 60_000) / DAY)

/** Tickets closed on each of the last `days` days, oldest first, today last. */
export function doneByDay(tickets: readonly Ticket[], now: number, days: number, tz?: TzOffset): number[] {
  const today = dayOf(now, tz)
  const out = new Array<number>(days).fill(0)
  for (const t of tickets) {
    if (t.bucket !== 'done' || t.completedAt === undefined) continue
    const ago = today - dayOf(t.completedAt, tz)
    if (ago >= 0 && ago < days) out[days - 1 - ago] += 1
  }
  return out
}

export type Counts = Record<Bucket, number>

export function count(tickets: readonly Ticket[]): Counts {
  const c: Counts = { started: 0, todo: 0, backlog: 0, done: 0 }
  for (const t of tickets) if (t.bucket !== 'canceled') c[t.bucket] += 1
  return c
}

export const summaryText = (c: Counts, days: number) =>
  `linear: ${c.started} in progress · ${c.todo} todo · ${c.done} done (${days}d)`

const BLOCKS = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█']

/** One row of block characters, scaled to the largest value (a zero stays blank). */
export function spark(values: readonly number[]): string {
  const max = Math.max(0, ...values)
  return values.map(v => (v <= 0 || max === 0 ? ' ' : BLOCKS[Math.min(7, Math.ceil((v / max) * 8) - 1)])).join('')
}

/**
 * A vertical bar chart `height` rows tall, one column per value, top row first;
 * each column is as tall as its value is large next to the biggest one.
 */
export function barChart(values: readonly number[], height: number): string[] {
  const max = Math.max(0, ...values)
  const rows: string[] = []
  for (let r = height - 1; r >= 0; r--) {
    rows.push(
      values
        .map(v => {
          if (max === 0 || v <= 0) return r === 0 ? '▁' : ' '
          const eighths = Math.round((v / max) * height * 8)
          const below = r * 8
          if (eighths >= below + 8) return '█'
          if (eighths <= below) return ' '
          return BLOCKS[eighths - below - 1]
        })
        .join(''),
    )
  }
  return rows
}

/** A horizontal bar of `width` cells split in proportion to `parts`, each as its own run of one glyph. */
export function stacked(parts: readonly { n: number; glyph: string }[], width: number): { glyph: string; cells: number }[] {
  const total = parts.reduce((s, p) => s + p.n, 0)
  if (total === 0) return []
  const out = parts.map(p => ({ glyph: p.glyph, cells: Math.floor((p.n / total) * width), n: p.n }))
  let used = out.reduce((s, p) => s + p.cells, 0)
  // a state with tickets is never invisible; leftover cells go to the largest
  for (const p of out) if (p.n > 0 && p.cells === 0 && used < width) (p.cells = 1), (used += 1)
  const largest = out.reduce((a, b) => (b.n > a.n ? b : a), out[0]!)
  largest.cells += width - used
  return out.filter(p => p.cells > 0).map(({ glyph, cells }) => ({ glyph, cells }))
}

/** Fraction of the cycle that has elapsed at `now`, 0 to 1. */
export function cycleElapsed(c: Pick<Cycle, 'startsAt' | 'endsAt'>, now: number): number {
  const span = c.endsAt - c.startsAt
  return span <= 0 ? 1 : Math.min(1, Math.max(0, (now - c.startsAt) / span))
}

export function fit(text: string, width: number): string {
  return text.length <= width ? text : `${text.slice(0, Math.max(0, width - 1))}…`
}

export function clampInt(v: unknown, fallback: number, min: number, max: number): number {
  const n = typeof v === 'number' && Number.isFinite(v) ? Math.round(v) : fallback
  return Math.min(max, Math.max(min, n))
}

export const BUCKET_LABEL: Record<Bucket, string> = {
  started: 'In progress',
  todo: 'Todo',
  backlog: 'Backlog',
  done: 'Done',
}

export const BUCKET_GLYPH: Record<Bucket, string> = { started: '◐', todo: '○', backlog: '·', done: '●' }
export const BUCKET_COLOR: Record<Bucket, string | undefined> = {
  started: 'yellow',
  todo: 'blue',
  backlog: undefined,
  done: 'green',
}

/** Urgent first, then high, medium, low; no priority last (Linear's 0 means none). */
export const priorityRank = (p: number) => (p === 0 ? 5 : p)

export function sortTickets(tickets: readonly Ticket[]): Ticket[] {
  return [...tickets].sort((a, b) => {
    if (a.bucket === 'done' && b.bucket === 'done') return (b.completedAt ?? 0) - (a.completedAt ?? 0)
    const r = priorityRank(a.priority) - priorityRank(b.priority)
    return r !== 0 ? r : (b.updatedAt ?? 0) - (a.updatedAt ?? 0)
  })
}

/**
 * linear-tickets — Claude Mod
 *
 * Your Linear tickets in a pane, with their status and how you are progressing:
 *
 *   - a status bar of the tickets you hold (in progress, todo, backlog, done)
 *   - a bar chart of tickets closed per day over the last `days` days
 *   - the burn-up of the cycle your tickets sit in (scope against completed)
 *   - the tickets themselves, grouped by state; a row opens its detail, with
 *     the ticket's URL one button away from your clipboard
 *
 * Read-only: it reads issues and one cycle through Linear's GraphQL API and
 * never writes. `$.clock.every(5000)` decides when to read, every
 * `pollSeconds`, and only while the pane is open or the status line is on.
 * The key is sent only to api.linear.app, in the Authorization header, and is
 * never logged or drawn. Never hardcode it in this file.
 *
 * Needs Claude Code >= 2.1.287 and a
 * Linear API key in the plugin's options.
 *
 * Options (pluginConfigs["linear-tickets@skills-dir"].options):
 *   linearApiKey: string        required; without it the mod does nothing
 *   assignee: "me" | "anyone"   whose tickets (default me)
 *   teamKey: string             only this team (the CLA of CLA-143)
 *   project: string             only projects whose name contains this
 *   days: number                history shown, 7-60 (default 14)
 *   pollSeconds: number         refresh interval, 30-3600 (default 120)
 *   status: boolean             status line summary, keeps polling with the pane closed (default false)
 *   openOnStart: boolean        open the pane at session start (default false)
 */
import type { Register } from 'claude-code'
import {
  BUCKET_COLOR,
  BUCKET_GLYPH,
  BUCKET_LABEL,
  barChart,
  clampInt,
  count,
  currentCycleId,
  cycleElapsed,
  doneByDay,
  fit,
  getCycle,
  listTickets,
  sortTickets,
  spark,
  stacked,
  summaryText,
} from './linear-api.ts'
import type { Bucket, Counts, Cycle, Fetch, Ticket } from './linear-api.ts'

const PANE = 'linear'
const COMMAND = 'linear'
const TICK_MS = 5000
const DAY = 86_400_000
const CAPS: Record<Bucket, number> = { started: 10, todo: 8, backlog: 0, done: 5 }

let tickets: Ticket[] = []
let cycle: Cycle | undefined
let error: string | undefined
let isOpen = false
let isBusy = false
let lastReadAt = 0
let selected: string | undefined
let showBacklog = false
let timer: { cancel: () => void } | undefined

const text = (v: unknown) => (typeof v === 'string' ? v.trim() : '')

export const register: Register = (on, options) => {
  const key = text(options.linearApiKey)
  const assignee = options.assignee === 'anyone' ? 'anyone' : 'me'
  const teamKey = text(options.teamKey)
  const project = text(options.project)
  const days = clampInt(options.days, 14, 7, 60)
  const pollMs = clampInt(options.pollSeconds, 120, 30, 3600) * 1000
  const showStatus = options.status === true
  const openOnStart = options.openOnStart === true
  const scope = { assignee, teamKey, project } as const

  const statusText = () => (key && tickets.length > 0 ? summaryText(count(tickets), days) : undefined)

  async function read(f: Fetch): Promise<void> {
    isBusy = true
    try {
      const since = new Date(Date.now() - days * DAY).toISOString()
      tickets = sortTickets(await listTickets(f, key, scope, since))
      const id = currentCycleId(tickets, Date.now())
      cycle = id ? await getCycle(f, key, id).catch(() => undefined) : undefined
      error = undefined
    } catch (err) {
      error = err instanceof Error ? err.message : String(err)
    } finally {
      lastReadAt = Date.now()
      isBusy = false
    }
  }

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await $.command
      .register({
        name: COMMAND,
        description: 'Your Linear tickets by status, with a progress chart (stop closes)',
        argumentHint: '[stop]',
        immediate: true,
      })
      .catch(err => $.ui.log(`linear-tickets: /${COMMAND} not registered: ${err}`))
    if (!key) {
      $.ui.log('linear-tickets: set linearApiKey in the plugin options to list your tickets', { to: 'debug' })
      return r
    }

    timer?.cancel()
    timer = $.clock.every(TICK_MS, () => {
      if (isBusy || (!isOpen && !showStatus)) return
      if (Date.now() - lastReadAt < pollMs - TICK_MS / 2) return
      void read((url, init) => $.http.fetch(url, init)).then(() => {
        $.ui.status(showStatus ? statusText() : undefined)
        $.ui.invalidate('ui.render')
      })
    })

    if (openOnStart) {
      await read((url, init) => $.http.fetch(url, init))
      isOpen = true
      await $.ui.open({ id: PANE, title: 'linear' }).catch(() => {
        isOpen = false
      })
      $.ui.status(showStatus ? statusText() : undefined)
    }
    return r
  })

  on('session.end', async ($, e, next) => {
    timer?.cancel()
    timer = undefined
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    if (!key) return { text: 'linear: set linearApiKey in the plugin options' }
    if (['stop', 'close'].includes(e.args.trim().toLowerCase())) {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      isOpen = false
      return { text: 'linear closed' }
    }
    await read((url, init) => $.http.fetch(url, init))
    isOpen = true
    await $.ui.open({ id: PANE, title: 'linear', focus: true })
    $.ui.status(showStatus ? statusText() : undefined)
    $.ui.invalidate('ui.render')
    if (error) return { text: `linear: ${error}` }
    return { text: `${summaryText(count(tickets), days)} · /${COMMAND} stop closes` }
  })

  on('ui.close', async ($, e, next) => {
    if (e.id !== PANE) return next(e)
    isOpen = false
    return next(e)
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    const r = await next(e)
    const target = e.element
    if (target === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return r
    }
    if (target === 'refresh') {
      if (!isBusy) await read((url, init) => $.http.fetch(url, init))
    } else if (target === 'backlog') {
      showBacklog = !showBacklog
    } else if (target.startsWith('t:')) {
      const id = tickets[Number(target.slice(2))]?.id
      selected = id === selected ? undefined : id
    } else if (target === 'copy') {
      const url = tickets.find(t => t.id === selected)?.url
      if (url) {
        await $.ui.copy({ text: url, surface: e.surface }).catch(() => undefined)
        $.ui.toast(`linear: copied ${url}`)
      }
    }
    $.ui.status(showStatus ? statusText() : undefined)
    $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(30, e.props.bodyColumns - 1)
    const now = Date.now()
    const noop = () => {}
    const counts: Counts = count(tickets)
    const perDay = doneByDay(tickets, now, days)
    const chart = barChart(perDay.slice(-Math.min(days, width - 2)), 4)
    const bar = stacked(
      [
        { n: counts.started, glyph: 'started' },
        { n: counts.todo, glyph: 'todo' },
        { n: counts.backlog, glyph: 'backlog' },
        { n: counts.done, glyph: 'done' },
      ],
      width,
    )
    const chosen = selected ? tickets.find(t => t.id === selected) : undefined
    const indexOf = new Map(tickets.map((t, i) => [t.id, i] as const))
    const groups: Bucket[] = ['started', 'todo', 'done']

    return (
      <Box flexDirection="column">
        <Text bold>{fit(summaryText(counts, days), width)}</Text>
        {error ? <Text color="red">{fit(error, width)}</Text> : null}

        <Box key="bar" flexDirection="row">
          {bar.map((part, i) => (
            <Text key={`bar:${i}`} color={BUCKET_COLOR[part.glyph as Bucket]} dimColor={part.glyph === 'backlog'}>
              {(part.glyph === 'backlog' ? '░' : '█').repeat(part.cells)}
            </Text>
          ))}
        </Box>

        <Box key="chart" flexDirection="column" marginTop={1}>
          <Text dimColor>{fit(`closed per day · ${perDay.reduce((a, b) => a + b, 0)} in ${days}d · max ${Math.max(0, ...perDay)}/day`, width)}</Text>
          {chart.map((row, i) => (
            <Text key={`c:${i}`} color="green">{row}</Text>
          ))}
          <Text dimColor>{fit(`${days}d ago${' '.repeat(Math.max(1, Math.min(days, width - 2) - `${days}d ago`.length - 5))}today`, width)}</Text>
        </Box>

        {cycle ? (
          <Box key="cycle" flexDirection="column" marginTop={1}>
            <Text>
              <Text bold>{`cycle ${cycle.number}${cycle.name ? ` ${cycle.name}` : ''} `}</Text>
              <Text color="green">{`${Math.round(cycle.progress * 100)}% done`}</Text>
              <Text dimColor>{` · ${Math.round(cycleElapsed(cycle, now) * 100)}% of time`}</Text>
            </Text>
            {cycle.scope.length > 1 ? <Text dimColor>{fit(`scope ${spark(cycle.scope)}`, width)}</Text> : null}
            {cycle.completed.length > 1 ? <Text color="green">{fit(`done  ${spark(cycle.completed)}`, width)}</Text> : null}
          </Box>
        ) : null}

        {groups.map(bucket => {
          const rows = tickets.filter(t => t.bucket === bucket)
          if (rows.length === 0) return null
          return (
            <Box key={`g:${bucket}`} flexDirection="column" marginTop={1}>
              <Text bold color="cyan">{`${BUCKET_LABEL[bucket]} (${rows.length})`}</Text>
              {rows.slice(0, CAPS[bucket]).map(t => (
                <Box key={`row:${t.id}`} flexDirection="row">
                  <Text color={BUCKET_COLOR[bucket]}>{`${BUCKET_GLYPH[bucket]} `}</Text>
                  <Button
                    key={`t:${indexOf.get(t.id)}`}
                    plain
                    dimColor={selected !== t.id && bucket === 'done'}
                    label={fit(`${t.identifier}${t.priority > 0 && t.priority < 3 ? ` ${t.priorityLabel ?? ''}` : ''}  ${t.title}`, width - 2)}
                    onPress={noop}
                  />
                </Box>
              ))}
              {rows.length > CAPS[bucket] ? <Text dimColor>{`  +${rows.length - CAPS[bucket]} more`}</Text> : null}
            </Box>
          )
        })}

        {counts.backlog > 0 ? (
          <Box key="backlog-box" flexDirection="column" marginTop={1}>
            <Button key="backlog" plain label={`${showBacklog ? '▾' : '▸'} Backlog (${counts.backlog})`} onPress={noop} />
            {showBacklog
              ? tickets
                  .filter(t => t.bucket === 'backlog')
                  .slice(0, 12)
                  .map(t => (
                    <Box key={`bl:${t.id}`} flexDirection="row">
                      <Text dimColor>{'· '}</Text>
                      <Button key={`t:${indexOf.get(t.id)}`} plain dimColor label={fit(`${t.identifier}  ${t.title}`, width - 2)} onPress={noop} />
                    </Box>
                  ))
              : null}
          </Box>
        ) : null}

        {chosen ? (
          <Box key="detail" flexDirection="column" marginTop={1} borderStyle="round" borderDimColor paddingX={1}>
            <Text bold>{fit(`${chosen.identifier} ${chosen.title}`, width - 4)}</Text>
            <Text dimColor>
              {fit(
                [chosen.stateName, chosen.priorityLabel, chosen.estimate !== undefined ? `${chosen.estimate} pts` : '', chosen.project, chosen.dueDate ? `due ${chosen.dueDate}` : '']
                  .filter(Boolean)
                  .join(' · '),
                width - 4,
              )}
            </Text>
            {chosen.url ? <Button key="copy" label="copy url" hotkey="c" onPress={noop} /> : null}
          </Box>
        ) : null}

        <Box key="foot" marginTop={1} flexDirection="column">
          <Box flexDirection="row" columnGap={1}>
            <Button key="refresh" label="refresh" hotkey="r" onPress={noop} />
            <Button key="close" label="close" onPress={noop} />
          </Box>
          <Text dimColor>{fit('read-only · status, charts and cycle from Linear', width)}</Text>
        </Box>
      </Box>
    )
  })
}

// Run with: claude plugin test integrations/linear-tickets
