    const w = world()
    fakeEngine(on, w)
    await start($)
    expect((w.calls.find(c => c.method === 'POST')!.body!.branch as Record<string, unknown>).parent_id).toBe('br-main-9')
    expect(w.calls.find(c => c.url.includes('/connection_uri'))!.url).toContain('pooled=false')
