  test('a stored branch that is gone is made again', { options: OPTIONS }, async ($, on) => {
    const w = world()
    w.store[`neon-branch-per-session:session:${SESSION}`] = 'br-new-1'
    w.exists = false
    fakeEngine(on, w)
    await start($)
    expect(w.calls.some(c => c.method === 'POST')).toBe(true)
  })
})

