/**
 * rex-tty: the parts with no engine in them. Which commands need a terminal,
 * what Rex's CLI answered, and how the pane's text becomes a tool result.
 */

/** A list option: a string[] or a comma-separated string; empty means none. */
export function strings(value: unknown): string[] {
  if (Array.isArray(value)) return value.filter((v): v is string => typeof v === 'string' && v.trim() !== '')
  if (typeof value === 'string') return value.split(',').map(s => s.trim()).filter(Boolean)
  return []
}

/** Compiles regex sources; one that does not compile is returned in `bad`, never thrown. */
export function compile(sources: readonly string[]): { ok: RegExp[]; bad: string[] } {
  const ok: RegExp[] = []
  const bad: string[] = []
  for (const s of sources) {
    try {
      ok.push(new RegExp(s))
    } catch {
      bad.push(s)
    }
  }
  return { ok, bad }
}

export const SIDES = ['below', 'right', 'above', 'left'] as const
export type Side = (typeof SIDES)[number]

export function side(value: unknown): Side {
  return SIDES.find(s => s === value) ?? 'below'
}

export function clamp(value: unknown, min: number, max: number, fallback: number): number {
  const n = typeof value === 'number' ? value : typeof value === 'string' && value.trim() ? Number(value) : NaN
  return Number.isFinite(n) ? Math.min(max, Math.max(min, Math.round(n))) : fallback
}

/**
 * The simple commands of a shell line, split at `;`, `&&`, `||`, `|`, `&`, a
 * newline and `(`, quotes respected, heredoc bodies left out. Good enough to
 * find each command word.
 */
export function segments(source: string): string[] {
  const command = source
    // a heredoc's body is data, not commands; its delimiter is any shell word, quoted or not
    .replace(/<<-?[ \t]*(?:'([^'\n]+)'|"([^"\n]+)"|\\?([^\s'"<>|;&()]+))[^\n]*\n([\s\S]*?\n)?[ \t]*(?:\1|\2|\3)[ \t]*(?=\n|$)/g, '<<HEREDOC')
    // a backslash before a line break joins the two lines
    .replace(/\\\r?\n/g, ' ')
  const out: string[] = []
  let current = ''
  let quote: '"' | "'" | null = null
  for (let i = 0; i < command.length; i++) {
    const c = command[i]!
    if (quote) {
      current += c
      if (c === '\\' && quote === '"' && i + 1 < command.length) current += command[++i]
      else if (c === quote) quote = null
      continue
    }
    if (c === '"' || c === "'") {
      quote = c
      current += c
    } else if (c === '\\' && i + 1 < command.length) {
      current += c + command[++i]
    } else if (c === ';' || c === '\n' || c === '|' || c === '&' || c === '(' || c === ')') {
      out.push(current)
      current = ''
    } else current += c
  }
  out.push(current)
  return out.map(s => s.trim()).filter(Boolean)
}

/** The words of one simple command, without leading `VAR=value` assignments; quotes are dropped. */
export function words(segment: string): { assignments: string[]; argv: string[] } {
  const all = segment.match(/(?:[^\s"']+|"(?:\\.|[^"\\])*"|'[^']*')+/g) ?? []
  const clean = all.map(w => w.replace(/^(["'])(.*)\1$/s, '$2'))
  let i = 0
  while (i < clean.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(clean[i]!)) i++
  return { assignments: clean.slice(0, i), argv: clean.slice(i) }
}

/** True when a short flag (in a cluster like `-am`) or one of the long ones is among the arguments. */
function has(args: readonly string[], short: string, ...long: string[]): boolean {
  return args.some(a =>
    a.startsWith('--')
      ? long.some(l => a === l || a.startsWith(l + '='))
      : short !== '' && /^-[A-Za-z]+$/.test(a) && [...short].some(s => a.includes(s)),
  )
}

/**
 * Words that run the command after them, looked through to the real command:
 * for each, the options that take a separate value, and how many operands of
 * its own come before the command (`timeout 5 cmd`).
 */
const WRAPPERS: Record<string, { valued: readonly string[]; operands: number }> = {
  env: { valued: ['-u', '--unset', '-C', '--chdir', '-S', '--split-string', '-P'], operands: 0 },
  command: { valued: [], operands: 0 },
  builtin: { valued: [], operands: 0 },
  nohup: { valued: [], operands: 0 },
  time: { valued: ['-o', '--output', '-f', '--format'], operands: 0 },
  exec: { valued: ['-a'], operands: 0 },
  nice: { valued: ['-n', '--adjustment'], operands: 0 },
  caffeinate: { valued: ['-t', '-w'], operands: 0 },
  timeout: { valued: ['-k', '--kill-after', '-s', '--signal'], operands: 1 },
}

/** `argv` without leading wrappers (`env -u A B=1`, `command`, `timeout -k 5 10`), their options and operands. */
export function unwrap(argv: readonly string[]): string[] {
  let rest = [...argv]
  for (;;) {
    // own keys only: a command named `constructor` or `toString` is no wrapper
    const name = (rest[0] ?? '').replace(/^.*\//, '')
    const wrapper = Object.hasOwn(WRAPPERS, name) ? WRAPPERS[name] : undefined
    if (!wrapper) return rest
    let i = 1
    while (i < rest.length) {
      const word = rest[i]!
      if (word === '--') {
        i++
        break
      }
      if (wrapper.valued.includes(word)) i += 2
      else if (word.startsWith('-') || /^[A-Za-z_][A-Za-z0-9_]*=/.test(word)) i++
      else break
    }
    rest = rest.slice(i + wrapper.operands)
  }
}

/** `args` without the options named in `valued` and the value each takes. */
function dropValued(args: readonly string[], valued: readonly string[]): string[] {
  const out: string[] = []
  for (let i = 0; i < args.length; i++) {
    if (valued.includes(args[i]!)) i++
    else out.push(args[i]!)
  }
  return out
}

const GIT_GLOBAL = ['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--exec-path', '--super-prefix', '--config-env']

/** A git command line from its subcommand on: the global options before it (`-C dir`, `-c k=v`, `--no-pager`) dropped, the subcommand's own kept. */
export function gitFromSubcommand(args: readonly string[]): string[] {
  let i = 0
  while (i < args.length && args[i]!.startsWith('-')) i += GIT_GLOBAL.includes(args[i]!) ? 2 : 1
  return args.slice(i)
}

/** Flags that make a login take its credential from an argument, a file or the environment. */
const UNATTENDED = ['--with-token', '--token', '--api-key', '--service-principal', '--identity', '--cred-file', '--browserless', '--password-stdin', '--access-token', '--ci', '--no-browser', '--help']

const LOGINS: Record<string, readonly (readonly string[])[]> = {
  npm: [['login'], ['adduser']],
  pnpm: [['login'], ['adduser']],
  yarn: [['login'], ['npm', 'login']],
  vercel: [['login']],
  wrangler: [['login']],
  gcloud: [['auth', 'login'], ['auth', 'application-default', 'login'], ['init']],
  aws: [['sso', 'login']],
  az: [['login']],
  firebase: [['login']],
  heroku: [['login']],
  supabase: [['login']],
  fly: [['auth', 'login']],
  flyctl: [['auth', 'login']],
  op: [['signin']],
  netlify: [['login']],
  stripe: [['login']],
  doctl: [['auth', 'init']],
  railway: [['login']],
}

/** Why one simple command needs a terminal, or null. */
function reasonFor(segment: string): string | null {
  const parsed = words(segment)
  const assignments = parsed.assignments
  const argv = unwrap(parsed.argv)
  const name = (argv[0] ?? '').replace(/^.*\//, '')
  const args = argv.slice(1)
  const plain = args.filter(a => !a.startsWith('-'))
  switch (name) {
    case 'sudo': {
      // the options before the command sudo runs
      const flags = dropValued(args, ['-u', '-g', '-h', '-p', '-C', '-D', '-R', '-T', '-r', '-t', '-U', '--user', '--group', '--host', '--prompt', '--chdir'])
      const end = flags.findIndex(a => !a.startsWith('-'))
      const own = end === -1 ? flags : flags.slice(0, end)
      if (has(own, 'nSAKVh', '--non-interactive', '--stdin', '--askpass', '--version', '--help', '--remove-timestamp')) return null
      return 'sudo asks for a password'
    }
    case 'su':
      return 'su asks for a password'
    case 'passwd':
      return 'passwd asks for a password'
    case 'gh':
      if (plain[0] === 'auth' && (plain[1] === 'login' || plain[1] === 'refresh') && !has(args, '', '--with-token')) return 'gh auth asks questions and waits for the browser'
      return null
    case 'git': {
      if (assignments.some(a => /^GIT_(SEQUENCE_)?EDITOR=/.test(a))) return null
      const [sub, ...rest] = gitFromSubcommand(args)
      if (sub === 'rebase' && has(rest, 'i', '--interactive') && !has(rest, '', '--continue', '--abort', '--skip')) return 'git rebase -i opens an editor'
      if ((sub === 'add' || sub === 'checkout' || sub === 'restore' || sub === 'reset' || sub === 'stash') && has(rest, 'p', '--patch')) return `git ${sub} -p asks hunk by hunk`
      if (sub === 'add' && has(rest, 'i', '--interactive')) return 'git add -i is interactive'
      if (sub === 'commit' && !has(rest, 'mFC', '--message', '--file', '--no-edit', '--reuse-message', '--fixup', '--dry-run', '--help')) return 'git commit without a message opens an editor'
      return null
    }
    case 'docker':
    case 'podman':
      if (plain[0] === 'login' && !has(args, 'p', '--password', '--password-stdin')) return `${name} login asks for a password`
      return null
    case 'ssh-add':
      if (has(args, 'lLdDqT', '--help') && !plain.length) return null
      return 'ssh-add asks for the key passphrase'
    case 'ssh-keygen':
      if (has(args, 'NlyFRH')) return null
      return 'ssh-keygen asks questions'
    case 'ssh-copy-id':
      return 'ssh-copy-id asks for a password'
    case 'gpg':
      if (has(args, '', '--gen-key', '--full-generate-key', '--full-gen-key', '--edit-key')) return 'gpg asks questions'
      return null
    default: {
      const form = Object.hasOwn(LOGINS, name) ? LOGINS[name]!.find(f => f.every((w, i) => plain[i] === w)) : undefined
      if (!form || has(args, '', ...UNATTENDED)) return null
      return `${name} ${form.join(' ')} is interactive`
    }
  }
}

/**
 * Why a Bash command needs a terminal the person can type in, or null when it
 * does not look like one. `skip` wins over everything, `extra` adds matches.
 */
export function needsTerminal(command: string, extra: readonly RegExp[] = [], skip: readonly RegExp[] = []): string | null {
  if (!command.trim() || skip.some(r => r.test(command))) return null
  for (const s of segments(command)) {
    const why = reasonFor(s)
    if (why) return why
  }
  return extra.some(r => r.test(command)) ? 'matches your rex-tty commands option' : null
}

const NO_TTY = [
  /a terminal is required/i,
  /no tty present/i,
  /not a tty/i,
  /not a terminal/i,
  /inappropriate ioctl for device/i,
  /can(?:no|')t open \/dev\/tty/i,
  /could not open a (?:new )?tty/i,
  /stdin is not a tty/i,
  /terminal is dumb/i,
  /cannot prompt/i,
  /could not read (?:password|username|passphrase)/i,
  /unable to read askpass response/i,
  /no askpass program/i,
  /pseudo-terminal will not be allocated/i,
]

/** True when a command's output says it failed for lack of a terminal. */
export function saysNoTerminal(text: string): boolean {
  return NO_TTY.some(r => r.test(text))
}

/** Text without control characters (escape sequences included), so it cannot redraw what shows it. */
export function printable(text: string): string {
  return text.replace(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g, '')
}

/** A command on one line, cut to `max` characters. */
export function shortCommand(command: string, max = 60): string {
  const one = printable(command).replace(/\s+/g, ' ').trim()
  return one.length > max ? one.slice(0, max - 1) + '…' : one
}

/**
 * The command as the permission question shows it: whole, line breaks kept,
 * up to `max` characters, and how much was left out when it is longer.
 */
export function quoted(command: string, max = 1500): string {
  const text = printable(command).trim()
  if (text.length <= max) return text
  const cut = text.slice(0, max)
  return `${cut}\n… (${text.length - max} more characters, ${text.split('\n').length} lines in all, not shown)`
}

/** The line the pane prints first, so the person sees what Claude asked to run. */
export function banner(command: string): string {
  return `rex-tty ▸ ${shortCommand(command, 200)}`
}

/**
 * The script the pane's shell runs: prints the banner dimmed, then replaces
 * itself with the same shell running the command. `$0` the shell, `$1` the
 * banner, `$2` the command: nothing of the command is interpolated here.
 */
export const PANE_SCRIPT = `printf '\\033[2m%s\\033[0m\\n\\n' "$1"; exec "$0" -c "$2"`

/** The shell that runs the command: the person's, when it takes `-c` as bash does. */
export function shellFor(shell: string | undefined): string {
  return shell && /\/(?:bash|zsh|sh|dash|ksh)$/.test(shell) ? shell : '/bin/bash'
}

/** The new block's id from `rex split --json`, or null. */
export function blockOf(stdout: string): string | null {
  try {
    const parsed = JSON.parse(stdout) as { block_ids?: unknown }
    const first = Array.isArray(parsed.block_ids) ? parsed.block_ids[0] : undefined
    return typeof first === 'string' && first ? first : null
  } catch {
    return null
  }
}

export type Waited = { kind: 'exit'; code: number } | { kind: 'timeout' } | { kind: 'gone'; detail: string }

/** What `rex wait --for … --json BLOCK` said: the child's exit, the limit, or a pane that went away. */
export function waited(stdout: string, stderr: string): Waited {
  for (const line of stdout.split('\n')) {
    const t = line.trim()
    if (!t.startsWith('{')) continue
    try {
      const code = (JSON.parse(t) as { exit_code?: unknown }).exit_code
      if (typeof code === 'number') return { kind: 'exit', code }
    } catch {
      // not the payload
    }
  }
  if (/timed out/i.test(stderr)) return { kind: 'timeout' }
  return { kind: 'gone', detail: stderr.trim().split('\n')[0] ?? '' }
}

/** The pane's text without the banner, its last `max` characters. */
export function paneOutput(captured: string, bannerLine: string, max = 30_000): string {
  const lines = captured.replace(/\r/g, '').split('\n')
  // the banner may wrap in a narrow pane: --unwrap joins it back, so one line
  const at = lines.findIndex(l => l.trim() !== '')
  if (at !== -1 && lines[at]!.trim() === bannerLine.trim()) lines.splice(0, at + 1)
  const text = lines.join('\n').replace(/^\n+/, '').replace(/\s+$/, '')
  return text.length > max ? `[… ${text.length - max} earlier characters left out]\n${text.slice(-max)}` : text
}

{
  "description": "rex-tty: tool.call on Bash sends a command that needs a terminal to a Rex pane (after tool.check and, on an ask, a question to the person), waits for it and answers with its output and exit code; tool.call serves the tty_run tool; session.start registers it when the session runs inside Rex",
  "modules": [
    "./rex-tty.ts"
  ]
}

/**
 * rex-tty — Claude Mod
 *
 * Claude's Bash tool has no terminal: `sudo`, `gh auth login`, a key
 * passphrase or `git rebase -i` fail or hang there. Inside the Rex terminal
 * (https://www.superlogical.com/rex) this mod runs those commands in a Rex
 * pane beside the session instead. The person types in the pane; Claude gets
 * the exit code and what the pane showed, as the Bash tool's own result. What
 * the person types at a hidden prompt is never on screen, so it never reaches
 * the model.
 *
 *   session.start  inside Rex: registers the tty_run tool
 *   tool.call      Bash: a command that needs a terminal goes to a pane;
 *                  any other Bash result that says "no terminal" gets a note
 *                  pointing Claude at tty_run
 *   tool.call      mcp__rex-tty__tty_run: Claude's own request for a pane
 *
 * A hook that answers a tool call runs before core's permission dialog, so
 * the mod asks first: `$.tool.check` on the Bash command, and on anything but
 * an allow, a question to the person. A denied command is denied.
 *
 * Outside Rex (no REX_BLOCK) the mod does nothing. Needs Claude Code >=
 * 2.1.316 and the `rex` CLI Rex puts on the PATH of its terminals.
 *
 * Options: commands, skip (comma-separated regex sources), side, ratio,
 * closeOnExit, returnOutput, timeoutMinutes.
 */
import type { ProcessRunInit, ProcessRunResult, Register } from 'claude-code'
import {
  PANE_SCRIPT,
  banner,
  blockOf,
  clamp,
  compile,
  needsTerminal,
  paneOutput,
  quoted,
  saysNoTerminal,
  shellFor,
  shortCommand,
  side,
  strings,
  waited,
} from './detect.ts'

const TAG = '[rex-tty]'
const TOOL = 'tty_run'
const ASK = { pane: 'Run in a Rex pane', here: 'Run without a terminal', no: 'Do not run' } as const

/** What a run needs from the engine, spelled where `$` is. */
type Host = {
  run: (argv: readonly string[], init?: ProcessRunInit) => Promise<ProcessRunResult>
  /** Runs `rex wait` as a stream, so an interrupted turn kills it; resolves its whole output. */
  wait: (argv: readonly string[]) => Promise<{ stdout: string; stderr: string }>
  cwd: () => Promise<string>
  check: (command: string) => Promise<{ decision: 'allow' | 'ask' | 'deny'; reason?: string; rule?: string }>
  ask: (question: string, labels: readonly string[]) => Promise<string>
  log: (line: string) => void
  status: (line: string | undefined) => void
}

type Rex = { bin: string; anchor: string; shell: string }
type Outcome = { ok: true; stdout: string; context: string } | { ok: false; deny: string }

export const register: Register = (on, options) => {
  const extra = compile(strings(options.commands))
  const skip = compile(strings(options.skip))
  const where = side(options.side)
  const ratio = clamp(options.ratio, 10, 90, 35)
  const closeOnExit = options.closeOnExit !== false
  const returnOutput = options.returnOutput !== false
  const timeoutMinutes = clamp(options.timeoutMinutes, 1, 720, 30)

  let rex: Rex | undefined
  let toolName = ''
  let count = 0
  let isBadReported = false
  /** Calls the person sent to a pane: these never fall through to core, whatever fails. */
  const chosen = new Set<string>()

  /** Decides whether the command may go to a pane: the session's rules first, the person on anything but an allow. */
  async function permit(host: Host, command: string, why: string): Promise<'pane' | 'here' | { deny: string }> {
    const verdict = await host.check(command)
    if (verdict.decision === 'deny') return { deny: verdict.reason ?? 'This command is denied by the session\'s permission rules.' }
    // only a rule the person wrote stands in for their answer: an allow from the
    // mode (bypass, a sandbox's auto-allow) was given for a call core would run
    // its own way, not for a pane outside it
    if (verdict.decision === 'allow' && verdict.rule) return 'pane'
    let answer: string
    try {
      answer = await host.ask(`rex-tty: this command needs a terminal (${why}). Run it in a Rex pane where you can type?\n\n${quoted(command)}`, [ASK.pane, ASK.here, ASK.no])
    } catch {
      // dismissed, or a -p run with no one to ask: as if the mod were not here
      return 'here'
    }
    if (answer === ASK.pane) return 'pane'
    if (answer === ASK.here) return 'here'
    return { deny: answer === ASK.no ? 'The user chose not to run this command.' : `The user did not run this command and said: ${answer}` }
  }

  /** Closes the pane of an interrupted turn and says, truthfully, whether that worked. */
  async function interrupted(host: Host, r: Rex, block: string | undefined): Promise<Outcome> {
    if (!block) return { ok: false, deny: 'The turn was interrupted before this command was sent to a Rex pane; it was not run.' }
    const closed = await host.run([r.bin, 'block', 'close', block]).catch(() => undefined)
    return closed && closed.exitCode === 0
      ? { ok: false, deny: 'The turn was interrupted while this command waited in a Rex pane; the pane was closed.' }
      : { ok: false, deny: `The turn was interrupted while this command waited in a Rex pane, and the pane (${block}) could not be closed: the command may still be running there. Tell the user; do not run it again.` }
  }

  /**
   * `pane` with every failure turned into a refusal: once the person's answer
   * was "a pane", a hook that threw would be skipped and core would run the
   * command in its own shell, a second time if the pane had started it.
   */
  async function inPane(host: Host, r: Rex, command: string, signal: AbortSignal): Promise<Outcome> {
    const opened: { block?: string } = {}
    try {
      return await pane(host, r, command, opened, signal)
    } catch (err) {
      host.status(undefined)
      // the turn was interrupted: the pane goes with it, whatever was running in it
      if (signal.aborted) return interrupted(host, r, opened.block)
      const what = err instanceof Error ? err.message : String(err)
      return {
        ok: false,
        deny: opened.block
          ? `rex-tty lost track of this command (${what}). It was started in a Rex pane that is still open and may still be running there: do not run it again; ask the user to look at the pane.`
          : `rex-tty could not open a Rex pane (${what}). The command was not run.`,
      }
    }
  }

  /** Opens the pane, waits for the command and reads what the pane showed. */
  async function pane(host: Host, r: Rex, command: string, opened: { block?: string }, signal: AbortSignal): Promise<Outcome> {
    count += 1
    const label = `tty-${count}`
    const head = banner(command)
    const cwd = await host.cwd().catch(() => '')
    const split = await host.run([
      r.bin, 'split', '-b', r.anchor, '--split', where, '--ratio', String(ratio), '--keep-open', '--focus', '--label', label, '--json',
      ...(cwd ? ['-c', cwd] : []),
      '--', r.shell, '-c', PANE_SCRIPT, r.shell, head, command,
    ])
    const block = split.exitCode === 0 ? blockOf(split.stdout) : null
    if (block) opened.block = block
    if (!block) return { ok: false, deny: `rex-tty could not open a Rex pane (${(split.stderr || split.stdout).trim().split('\n')[0] || `rex split exited ${split.exitCode}`}). The command was not run.` }

    host.status(`${TAG} waiting for you in pane ${label}: ${shortCommand(command, 40)}`)
    const out = await host.wait([r.bin, 'wait', '--for', `${timeoutMinutes}m`, '--json', block])
    const end = waited(out.stdout, out.stderr)
    host.status(undefined)
    // an interrupted turn kills `rex wait`, and its stream may just end rather than throw:
    // the pane goes with the turn whatever closeOnExit says, so nothing runs on unattended
    if (signal.aborted && end.kind !== 'exit') return interrupted(host, r, block)

    const shown = await host.run([r.bin, 'capture', '-b', block, '--trim', '--unwrap']).catch(() => undefined)
    // unread, or cut at the engine's 4 MiB (its end, the part that matters, is what was dropped)
    // (a pane that is gone has nothing to read and nothing to keep: that case says so itself)
    const isLost = returnOutput && end.kind !== 'gone' && (!shown || shown.exitCode !== 0 || shown.isStdoutTruncated)
    const text = shown && shown.exitCode === 0 ? paneOutput(shown.stdout, head) : ''
    const lost = !isLost
      ? ''
      : shown && shown.exitCode === 0
        ? `${TAG} the pane's output is larger than 4 MiB: only its beginning could be read, the end is missing. The pane (${label}) was left open.`
        : `${TAG} the pane's output could not be read (${(shown && (shown.stderr || shown.stdout).trim().split('\n')[0]) || 'rex capture failed'}). The pane (${label}) was left open.`
    const body = !returnOutput ? '(rex-tty withheld the pane\'s output: the returnOutput option is off)' : lost ? `${text}\n\n${lost}`.trim() : text
    const lostNote = lost ? ' Its output is incomplete or missing as the result says; the pane was left open so the user can read it. Say so rather than assuming what it printed.' : ''

    if (end.kind === 'timeout') {
      return {
        ok: true,
        stdout: `${body}\n\n${TAG} still running after ${timeoutMinutes} min in Rex pane ${label}; the pane was left open.`.trim(),
        context: `This command runs in a Rex terminal pane (${label}, ${block}) and had not ended after ${timeoutMinutes} minutes, probably waiting for the user. It was not stopped. Tell the user it is waiting in that pane; do not run it again.`,
      }
    }
    if (closeOnExit && !isLost) await host.run([r.bin, 'block', 'close', block]).catch(() => undefined)
    await host.run([r.bin, 'block', 'focus', r.anchor]).catch(() => undefined)
    if (end.kind === 'gone') {
      return {
        ok: true,
        stdout: `${body}\n\n${TAG} the pane closed before the command reported an exit code.`.trim(),
        context: `This command ran in a Rex terminal pane (${label}) that the user closed, or that went away, before the command ended${end.detail ? ` (${end.detail})` : ''}. Its exit code is unknown; check the effect before relying on it, and ask the user rather than running it again blindly.`,
      }
    }
    host.log(`${TAG} ${label} exited ${end.code}: ${shortCommand(command)}`)
    return {
      ok: true,
      stdout: end.code === 0 ? body : `${body}\n\nExit code ${end.code}`.trim(),
      context: `This command ran in a Rex terminal pane (${label}) where the user could type, not in your shell: exit code ${end.code}. ${returnOutput ? 'The output is what the pane showed; anything the user typed at a hidden prompt (a password, a passphrase) is not in it.' : 'Its output was withheld by the user\'s configuration; only the exit code is known.'} The pane had its own shell with the user's login environment, so variables you exported earlier were not set there.${lostNote}`,
    }
  }

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    const anchor = await $.env.get('REX_BLOCK').catch(() => undefined)
    if (!anchor) {
      rex = undefined
      $.ui.log(`${TAG} not inside Rex (REX_BLOCK is unset): nothing to do`, { to: 'debug' })
      return started
    }
    const dir = await $.env.get('REX_BIN_DIR').catch(() => undefined)
    rex = { bin: dir ? `${dir.replace(/\/$/, '')}/rex` : 'rex', anchor, shell: shellFor(await $.env.get('SHELL').catch(() => undefined)) }
    await $.tool
      .register({
        name: TOOL,
        description:
          'Run a shell command in a Rex terminal pane beside this session, where the user can type: a password or passphrase, a yes/no confirmation, an editor, an interactive login. Use it when a Bash command failed because it had no terminal (for example "a terminal is required", "not a tty", "cannot prompt") or plainly needs the user at the keyboard. It waits for the command to end and returns what the pane showed and the exit code; what the user types at a hidden prompt is never returned. Do not use it for commands that need no input.',
        inputSchema: {
          type: 'object',
          properties: {
            command: { type: 'string', description: 'The shell command, as you would give it to Bash' },
            reason: { type: 'string', description: 'One short sentence for the user: what they will be asked to type' },
          },
          required: ['command'],
        },
      })
      .then(({ tool }) => void (toolName = tool))
      .catch(err => $.ui.log(`${TAG} could not register ${TOOL}: ${err}`, { to: 'debug' }))
    return started
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const r = rex
    const command = typeof e.command === 'string' ? e.command : ''
    if (!r || !command.trim() || e.run_in_background === true) return next(e)
    if (!isBadReported && (extra.bad.length || skip.bad.length)) {
      isBadReported = true
      $.ui.log(`${TAG} ignored option patterns that are not valid regular expressions: ${[...extra.bad, ...skip.bad].join(', ')}`)
    }

    const why = needsTerminal(command, extra.ok, skip.ok)
    if (!why) {
      // after: a command that failed for lack of a terminal gets a pointer to the tool
      const outcome = await next(e)
      const text = outcome.deny === undefined ? (outcome.text ?? '') : ''
      const isFailure = outcome.deny === undefined && (outcome.isError === true || /\bExit code [1-9]/.test(text))
      if (!toolName || !isFailure || !saysNoTerminal(text)) return outcome
      return {
        ...outcome,
        context: [
          ...(outcome.context ?? []),
          `This command seems to have failed because Bash has no terminal. The ${toolName} tool runs a command in a Rex pane where the user can type; use it for this command if it needs the user's input.`,
        ],
      }
    }

    const host: Host = {
      run: (argv, init) => $.process.run(argv, init),
      wait: async argv => {
        let stdout = ''
        let stderr = ''
        for await (const chunk of $.process.spawn({ argv })) {
          if (chunk.stream === 'stdout') stdout += chunk.text
          else stderr += chunk.text
        }
        return { stdout, stderr }
      },
      cwd: () => $.session.cwd(),
      check: c => $.tool.check({ tool: 'Bash', input: { command: c } }),
      ask: (question, labels) => $.ui.ask(question, { header: 'Terminal', options: labels }),
      log: line => void $.ui.log(line),
      status: line => void $.ui.status(line),
    }
    const go = await permit(host, command, why)
    if (go === 'here') return next(e)
    if (go !== 'pane') return go
    const key = e.tool_use_id ?? command
    chosen.add(key)
    const done = await inPane(host, r, command, next.signal)
    // settled: only a call still in flight needs the .catch below
    chosen.delete(key)
    if (!done.ok) return { deny: done.deny }
    return { result: { stdout: done.stdout, stderr: '', interrupted: false }, context: [done.context] }
  }).catch(async ($, e, next) => {
    // before the person chose a pane nothing ran: core decides as if the mod were absent
    const key = typeof e.command === 'string' ? (e.tool_use_id ?? e.command) : ''
    if (!chosen.delete(key)) return next(e)
    return { deny: `rex-tty failed (${next.error.kind}) after this command was sent to a Rex pane. It may have run there: do not run it again; ask the user to look at the pane.` }
  })

  on('tool.call', async ($, e, next) => {
    if (!toolName || e.tool !== toolName) return next(e)
    const r = rex
    const input = e as unknown as Record<string, unknown>
    const command = typeof input.command === 'string' ? input.command : ''
    if (!command.trim()) return { deny: `${TOOL} needs a command` }
    if (!r) return { deny: `${TOOL} only works when Claude Code runs inside the Rex terminal.` }
    const why = typeof input.reason === 'string' && input.reason.trim() ? `Claude says: ${shortCommand(input.reason, 120)}` : 'Claude asked for a terminal'

    const host: Host = {
      run: (argv, init) => $.process.run(argv, init),
      wait: async argv => {
        let stdout = ''
        let stderr = ''
        for await (const chunk of $.process.spawn({ argv })) {
          if (chunk.stream === 'stdout') stdout += chunk.text
          else stderr += chunk.text
        }
        return { stdout, stderr }
      },
      cwd: () => $.session.cwd(),
      check: c => $.tool.check({ tool: 'Bash', input: { command: c } }),
      ask: (question, labels) => $.ui.ask(question, { header: 'Terminal', options: labels }),
      log: line => void $.ui.log(line),
      status: line => void $.ui.status(line),
    }
    const go = await permit(host, command, why)
    if (go === 'here') return { deny: `The user chose to run this without a terminal: use Bash for it instead of ${TOOL}.` }
    if (go !== 'pane') return go
    const done = await inPane(host, r, command, next.signal)
    if (!done.ok) return { deny: done.deny }
    return { result: done.stdout || '(no output)', context: [done.context] }
  }).catch(async ($, e, next) => {
    if (!toolName || e.tool !== toolName) return next(e)
    return { deny: `rex-tty failed (${next.error.kind}). If a Rex pane opened, the command may have run there: do not run it again; ask the user to look at the pane.` }
  })
}

// Run with: claude plugin test integrations/rex-tty
import { describe, expect, test } from 'claude-code/testing'
import type { Engine } from 'claude-code/testing'
import type { On } from 'claude-code'

type Verdict = { decision: 'allow' | 'ask' | 'deny'; reason?: string; rule?: string }
type World = {
  env: Record<string, string | undefined>
  verdict: Verdict
  /** What the person picks in the question; null dismisses it. */
  answer: string | null
  asked: string[]
  checked: string[]
  /** Commands that reached core's own Bash. */
  ranLocally: string[]
  /** What core's Bash answers. */
  local: { text: string; isError?: true }
  /** Every `rex …` call, without the binary. */
  rex: string[][]
  splitFails: boolean
  /** What `rex wait` writes, or 'throw' for a wait that cannot start. */
  wait: { stdout: string; stderr: string } | 'throw'
  capture: { exitCode: number; stdout: string; stderr: string; isStdoutTruncated?: boolean }
  registered: string[]
}

const BIN = '/rex/bin/rex'
const BLOCK = 'block:new'
const exited = (code: number) => ({ stdout: `{"exit_code":${code}}\n`, stderr: '' })

const world = (extra: Partial<World> = {}): World => ({
  env: { REX_BLOCK: 'block:anchor', REX_BIN_DIR: '/rex/bin', SHELL: '/bin/zsh' },
  verdict: { decision: 'ask' },
  answer: 'Run in a Rex pane',
  asked: [],
  checked: [],
  ranLocally: [],
  local: { text: 'local' },
  rex: [],
  splitFails: false,
  wait: exited(0),
  capture: { exitCode: 0, stdout: 'rex-tty ▸ sudo ls\n\nPassword:\nfile.txt\n', stderr: '' },
  registered: [],
  ...extra,
})

function fakeEngine(on: On, w: World) {
  on('env.get', ($, e) => ({ value: w.env[e.name] }))
  on('session.cwd', () => ({ value: '/repo' }))
  on('session.start', async ($, e) => ({ cwd: e.cwd }) as never)
  on('ui.log', () => ({ value: undefined }))
  on('ui.status', () => ({ value: undefined }))
  on('tool.register', ($, e) => {
    w.registered.push((e as { name: string }).name)
    return { value: { tool: `mcp__rex-tty__${(e as { name: string }).name}` } } as never
  })
  on('tool.check', ($, e) => {
    // the engine's own check of a real call, not the mod's query
    if (e.tool_use_id !== undefined) return { decision: 'allow' } as never
    w.checked.push(String((e.input as { command?: unknown }).command))
    return w.verdict as never
  })
  on('tool.call', async ($, e) => {
    if (e.tool === 'AskUserQuestion') {
      const q = (e as unknown as { questions: { question: string }[] }).questions[0]!.question
      w.asked.push(q)
      if (w.answer === null) return { deny: 'dismissed' }
      return { result: { questions: [], answers: { [q]: w.answer } } } as never
    }
    w.ranLocally.push(String((e as { command?: unknown }).command))
    return { result: { stdout: w.local.text, stderr: '', interrupted: false }, text: w.local.text, ...(w.local.isError ? { isError: true } : {}) } as never
  })
  on('process.run', ($, e) => {
    const [bin, ...args] = e.argv
    if (bin !== BIN) throw new Error(`unexpected process ${bin}`)
    w.rex.push(args)
    const out = (stdout: string, exitCode = 0, stderr = '') => ({ value: { exitCode, stdout, stderr, isStdoutTruncated: false, isStderrTruncated: false } })
    if (args[0] === 'split') return w.splitFails ? out('', 3, 'Error: block target "block:anchor" not found\n') : out(JSON.stringify({ block_ids: [BLOCK] }))
    if (args[0] === 'capture') return { value: { isStdoutTruncated: false, isStderrTruncated: false, ...w.capture } }
    return out('')
  })
  on('process.spawn', async function* ($, e) {
    const [, ...args] = e.argv
    w.rex.push(args)
    if (w.wait === 'throw') throw new Error('spawn rex ENOENT')
    if (w.wait.stdout) yield { stream: 'stdout' as const, text: w.wait.stdout }
    if (w.wait.stderr) yield { stream: 'stderr' as const, text: w.wait.stderr }
    return { value: { code: 0, signal: null } } as never
  })
}

let ids = 0
type BashAnswer = { deny?: string; result?: { stdout: string; stderr: string; interrupted: boolean }; context?: readonly string[] }
const start = ($: Engine) => $.session.start({ cwd: '/repo' } as never)
const bash = async ($: Engine, command: string, extra: Record<string, unknown> = {}) =>
  (await $.tool.call({ tool: 'Bash', tool_use_id: `toolu_${++ids}`, command, ...extra } as never)) as BashAnswer
const ttyRun = async ($: Engine, input: Record<string, unknown>) =>
  (await $.tool.call({ tool: 'mcp__rex-tty__tty_run', tool_use_id: `toolu_${++ids}`, ...input } as never)) as { deny?: string; result?: string; context?: readonly string[] }
const did = (w: World, verb: string) => w.rex.filter(a => a[0] === verb || (a[0] === 'block' && a[1] === verb))

describe('rex-tty: where a command runs', () => {
  test('outside Rex nothing is registered and every command runs as usual', async ($, on) => {
    const w = world({ env: {} })
    fakeEngine(on, w)
    await start($)
    await bash($, 'sudo ls')
    expect(w.registered).toEqual([])
    expect(w.ranLocally).toEqual(['sudo ls'])
    expect(w.checked).toEqual([])
    expect(w.rex).toEqual([])
  })

  test('a command that needs no terminal is not checked, asked about or moved', async ($, on) => {
    const w = world()
    fakeEngine(on, w)
    await start($)
    await bash($, 'ls -la')
    expect(w.registered).toEqual(['tty_run'])
    expect(w.ranLocally).toEqual(['ls -la'])
    expect(w.checked).toEqual([])
    expect(w.asked).toEqual([])
  })

  test('a background command stays in Bash', async ($, on) => {
    const w = world()
    fakeEngine(on, w)
    await start($)
    await bash($, 'sudo ls', { run_in_background: true })
    expect(w.ranLocally).toEqual(['sudo ls'])
    expect(w.rex).toEqual([])
  })
})

describe('rex-tty: permission', () => {
