/**
 * vercel-api.ts — the Vercel REST reads the mod makes, and what it takes out of them.
 *
 * Reference: https://vercel.com/docs/rest-api (base https://api.vercel.com,
 * `Authorization: Bearer <token>`, `teamId` for a team's resources):
 *   GET /v10/projects?limit=N    projects[] (a bare array on older shapes) with
 *                                `latestDeployments[]` { id, readyState, url, createdAt,
 *                                target, meta } and `targets.production` { alias[], url }
 *   GET /v7/deployments?projectId&limit   deployments[] { uid, url, readyState, target, created, meta, errorMessage }
 *
 * `readyState` is one of BLOCKED, BUILDING, CANCELED, DELETED, ERROR,
 * INITIALIZING, QUEUED, READY. Nothing here trusts a field to be there: the
 * parsers read what they find and leave the rest out. No `$` in this file, and
 * the token only ever leaves in an Authorization header.
 */

export const API = 'https://api.vercel.com'

export type Fetch = (
  url: string,
  init?: { method?: string; headers?: Record<string, string>; body?: string },
) => Promise<{ status: number; ok: boolean; text: string }>

export type DeployState = 'ready' | 'building' | 'failed' | 'canceled' | 'blocked' | 'unknown'

export type Deploy = {
  id: string
  /** the raw readyState Vercel reported */
  readyState: string
  state: DeployState
  /** hostname, no scheme */
  url?: string
  target?: string
  createdAt?: number
  readyAt?: number
  commit?: string
  branch?: string
  error?: string
}

export type Project = {
  id: string
  name: string
  framework?: string
  repo?: string
  /** the domain the production site is reached at, no scheme */
  domain?: string
  latest?: Deploy
  /** state of the production deployment, when Vercel names one */
  production?: DeployState
  updatedAt?: number
}

const obj = (v: unknown): Record<string, unknown> | undefined =>
  v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : undefined
const str = (v: unknown): string | undefined => (typeof v === 'string' && v ? v : undefined)
const num = (v: unknown): number | undefined => (typeof v === 'number' && Number.isFinite(v) ? v : undefined)

export function toState(readyState: string | undefined): DeployState {
  switch (readyState) {
    case 'READY':
      return 'ready'
    case 'BUILDING':
    case 'INITIALIZING':
    case 'QUEUED':
      return 'building'
    case 'ERROR':
      return 'failed'
    case 'CANCELED':
    case 'DELETED':
      return 'canceled'
    case 'BLOCKED':
      return 'blocked'
    default:
      return 'unknown'
  }
}

/** Hostname of a url or domain: no scheme, no path. */
export function hostOf(value: string | undefined): string | undefined {
  if (!value) return undefined
  return value.replace(/^https?:\/\//, '').replace(/\/.*$/, '') || undefined
}

export function parseDeploy(raw: unknown): Deploy | undefined {
  const d = obj(raw)
  if (!d) return undefined
  const id = str(d.uid) ?? str(d.id)
  if (!id) return undefined
  const readyState = str(d.readyState) ?? str(d.state) ?? 'UNKNOWN'
  const meta = obj(d.meta)
  const commit =
    str(meta?.githubCommitMessage) ?? str(meta?.gitlabCommitMessage) ?? str(meta?.bitbucketCommitMessage)
  return {
    id,
    readyState,
    state: toState(readyState),
    url: hostOf(str(d.url)),
    target: str(d.target),
    createdAt: num(d.createdAt) ?? num(d.created),
    readyAt: num(d.readyAt) ?? num(d.ready),
    commit: commit?.split('\n')[0],
    branch: str(meta?.githubCommitRef) ?? str(meta?.gitlabCommitRef) ?? str(meta?.bitbucketCommitRef),
    error: str(d.errorMessage),
  }
}

/** The production domain: a custom one beats the *.vercel.app alias. */
export function productionDomain(p: Record<string, unknown>): string | undefined {
  const production = obj(obj(p.targets)?.production)
  const aliases: string[] = []
  if (Array.isArray(production?.alias)) {
    for (const a of production.alias) if (typeof a === 'string') aliases.push(a)
  }
  if (Array.isArray(p.alias)) {
    for (const a of p.alias) {
      const domain = str(obj(a)?.domain)
      if (domain) aliases.push(domain)
    }
  }
  const hosts = aliases.map(a => hostOf(a)).filter((h): h is string => h !== undefined)
  return hosts.find(h => !h.endsWith('.vercel.app')) ?? hosts[0] ?? hostOf(str(production?.url))
}

export function parseProject(raw: unknown): Project | undefined {
  const p = obj(raw)
  if (!p) return undefined
  const id = str(p.id)
  const name = str(p.name)
  if (!id || !name) return undefined
  const deploys = (Array.isArray(p.latestDeployments) ? p.latestDeployments : [])
    .map(parseDeploy)
    .filter((d): d is Deploy => d !== undefined)
    .sort((a, b) => (b.createdAt ?? 0) - (a.createdAt ?? 0))
  const link = obj(p.link)
  const org = str(link?.org)
  const repo = str(link?.repo)
  const production = obj(obj(p.targets)?.production)
  return {
    id,
    name,
    framework: str(p.framework),
    repo: org && repo ? `${org}/${repo}` : repo,
    domain: productionDomain(p),
    latest: deploys[0],
    production: production ? toState(str(production.readyState)) : undefined,
    updatedAt: num(p.updatedAt),
  }
}

/** The list endpoint answers a bare array or `{ projects, pagination }`. */
export function parseProjects(text: string): Project[] {
  const body: unknown = JSON.parse(text)
  const list = Array.isArray(body) ? body : obj(body)?.projects
  return (Array.isArray(list) ? list : []).map(parseProject).filter((p): p is Project => p !== undefined)
}

export function parseDeploys(text: string): Deploy[] {
  const list = obj(JSON.parse(text))?.deployments
  return (Array.isArray(list) ? list : []).map(parseDeploy).filter((d): d is Deploy => d !== undefined)
}

const RANK: Record<DeployState, number> = { building: 0, failed: 1, blocked: 2, unknown: 3, ready: 4, canceled: 5 }

/** Building first, then failed, then the rest by recent activity. */
export function sortProjects(projects: readonly Project[]): Project[] {
  const state = (p: Project) => p.latest?.state ?? 'unknown'
  return [...projects].sort((a, b) => {
    const r = RANK[state(a)] - RANK[state(b)]
    if (r !== 0) return r
    return (b.latest?.createdAt ?? b.updatedAt ?? 0) - (a.latest?.createdAt ?? a.updatedAt ?? 0)
  })
}

export type Summary = { total: number; live: number; building: number; failed: number }

export function summarize(projects: readonly Project[]): Summary {
  const s: Summary = { total: projects.length, live: 0, building: 0, failed: 0 }
  for (const p of projects) {
    const state = p.latest?.state
    if (state === 'building') s.building += 1
    else if (state === 'failed') s.failed += 1
    else if (state === 'ready') s.live += 1
  }
  return s
}

export const summaryText = (s: Summary) =>
  `vercel: ${s.live} ready · ${s.building} building · ${s.failed} failed`

export type Change = { project: string; to: 'ready' | 'failed'; target?: string; error?: string }

/**
 * What finished between two reads: a project whose latest deployment was
 * building and is now ready or failed, or whose latest deployment is a new one
 * that already is. The first read (nothing before) announces nothing.
 */
export function changes(before: ReadonlyMap<string, Deploy>, projects: readonly Project[]): Change[] {
  const out: Change[] = []
  if (before.size === 0) return out
  for (const p of projects) {
    const now = p.latest
    if (!now || (now.state !== 'ready' && now.state !== 'failed')) continue
    const was = before.get(p.id)
    const settled = was === undefined ? false : was.id === now.id ? was.state === 'building' : true
    if (settled) out.push({ project: p.name, to: now.state, target: now.target, error: now.error })
  }
  return out
}

/** Hours, minutes or seconds since `at`, in the shortest form. */
export function ago(at: number | undefined, now: number): string {
  if (at === undefined) return ''
  const s = Math.max(0, Math.round((now - at) / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.round(s / 60)}m`
  if (s < 86_400) return `${Math.round(s / 3600)}h`
  return `${Math.round(s / 86_400)}d`
}

export const GLYPH: Record<DeployState, string> = {
  ready: '●',
  building: '◐',
  failed: '✕',
  canceled: '○',
  blocked: '◌',
  unknown: '·',
}

export const COLOR: Record<DeployState, string | undefined> = {
  ready: 'green',
  building: 'yellow',
  failed: 'red',
  canceled: undefined,
  blocked: 'yellow',
  unknown: undefined,
}

export function fit(text: string, width: number): string {
  return text.length <= width ? text : `${text.slice(0, Math.max(0, width - 1))}…`
}

export function clampInt(v: unknown, fallback: number, min: number, max: number): number {
  const n = typeof v === 'number' && Number.isFinite(v) ? Math.round(v) : fallback
  return Math.min(max, Math.max(min, n))
}

function headers(token: string): Record<string, string> {
  return { authorization: `Bearer ${token}`, accept: 'application/json' }
}

const withTeam = (q: URLSearchParams, team: string) => {
  if (team) q.set(team.startsWith('team_') ? 'teamId' : 'slug', team)
  return q
}

export async function listProjects(f: Fetch, token: string, team: string, limit: number): Promise<Project[]> {
  const q = withTeam(new URLSearchParams({ limit: String(limit) }), team)
  const res = await f(`${API}/v10/projects?${q}`, { headers: headers(token) })
  if (!res.ok) throw new Error(describeFailure(res.status, res.text))
  return parseProjects(res.text)
}

export async function listDeploys(f: Fetch, token: string, team: string, projectId: string, limit: number): Promise<Deploy[]> {
  const q = withTeam(new URLSearchParams({ projectId, limit: String(limit) }), team)
  const res = await f(`${API}/v7/deployments?${q}`, { headers: headers(token) })
  if (!res.ok) throw new Error(describeFailure(res.status, res.text))
  return parseDeploys(res.text)
}

export function describeFailure(status: number, text: string): string {
  if (status === 401 || status === 403) return `Vercel refused the token (${status}); check vercelToken and teamId`
  let detail = ''
  try {
    detail = str(obj(obj(JSON.parse(text))?.error)?.message) ?? ''
  } catch {
    detail = ''
  }
  return `Vercel answered ${status}${detail ? `: ${detail}` : ''}`
}

/** A site "answers" when the request completes with a status below 500 that is not a gateway failure. */
export const answers = (status: number) => status > 0 && status < 500

/**
 * vercel-deploys — Claude Mod
 *
 * Your Vercel projects in a pane: one row per connected site with the state of
 * its latest deployment, the production domain, the commit behind it and
 * whether the site answers. It keeps itself current:
 *
 *   - `$.clock.every(5000)` decides when to read: every `pollSeconds` while
 *     nothing builds, every 10 s while something does; nothing while the pane
 *     is closed and the status line is off
 *   - a deployment that turns ready or fails raises a toast
 *   - `$.ui.status` keeps "N ready · N building · N failed" under the prompt
 *
 * Read-only: it lists projects and deployments through Vercel's REST API and,
 * if `healthCheck` is on, sends one GET to each production domain at most once
 * a minute. The token is only ever sent to api.vercel.com in an Authorization
 * header and is never logged or drawn. Never hardcode it in this file.
 *
 * Needs Claude Code >= 2.1.287 and a
 * Vercel access token in the plugin's options.
 *
 * Options (pluginConfigs["vercel-deploys@skills-dir"].options):
 *   vercelToken: string   required; without it the mod does nothing
 *   teamId: string        team_... id or a team slug (default: the token's own account)
 *   maxProjects: number   projects listed, 1-50 (default 20)
 *   pollSeconds: number   idle refresh interval, 10-3600 (default 60)
 *   healthCheck: boolean  GET each production domain, at most once a minute (default true)
 *   status: boolean       status line summary, keeps polling with the pane closed (default true)
 *   toast: boolean        toast when a deployment finishes (default true)
 *   openOnStart: boolean  open the pane at session start (default false)
 */
import type { Register } from 'claude-code'
import {
  COLOR,
  GLYPH,
  ago,
  answers,
  changes,
  clampInt,
  fit,
  listDeploys,
  listProjects,
  sortProjects,
  summarize,
  summaryText,
} from './vercel-api.ts'
import type { Change, Deploy, Fetch, Project } from './vercel-api.ts'

const PANE = 'vercel'
const COMMAND = 'vercel'
const TICK_MS = 5000
const BUILDING_POLL_MS = 10_000
const HEALTH_EVERY_MS = 60_000
const HEALTH_TIMEOUT_MS = 5000

type Health = { status: number; ok: boolean; at: number }

let projects: Project[] = []
let before = new Map<string, Deploy>()
let health = new Map<string, Health>()
let error: string | undefined
let isOpen = false
let isBusy = false
let lastReadAt = 0
let selected: string | undefined
let history: Deploy[] = []
let timer: { cancel: () => void } | undefined

const str = (v: unknown) => (typeof v === 'string' ? v.trim() : '')

export const register: Register = (on, options) => {
  const token = str(options.vercelToken)
  const team = str(options.teamId)
  const maxProjects = clampInt(options.maxProjects, 20, 1, 50)
  const idleMs = clampInt(options.pollSeconds, 60, 10, 3600) * 1000
  const healthCheck = options.healthCheck !== false
  const showStatus = options.status !== false
  const wantToast = options.toast !== false
  const openOnStart = options.openOnStart === true

  const isBuilding = () => projects.some(p => p.latest?.state === 'building')
  const statusText = () => (token && projects.length > 0 ? summaryText(summarize(projects)) : undefined)

  /** One read of the projects, then the sites that are due a health check; the toasts it earned. */
  async function read(f: Fetch, sleep: (ms: number) => Promise<void>): Promise<Change[]> {
    isBusy = true
    try {
      const list = sortProjects(await listProjects(f, token, team, maxProjects))
      const finished = changes(before, list)
      before = new Map(list.flatMap(p => (p.latest ? [[p.id, p.latest] as const] : [])))
      projects = list
      error = undefined
      lastReadAt = Date.now()

      if (healthCheck) {
        const due = list.filter(p => p.domain && Date.now() - (health.get(p.id)?.at ?? 0) >= HEALTH_EVERY_MS)
        await Promise.all(
          due.map(async p => {
            const at = Date.now()
            const hit = await Promise.race([
              f(`https://${p.domain}`, { method: 'GET' }).then(r => ({ status: r.status })),
              sleep(HEALTH_TIMEOUT_MS).then(() => ({ status: 0 })),
            ]).catch(() => ({ status: 0 }))
            health.set(p.id, { status: hit.status, ok: answers(hit.status), at })
          }),
        )
      }
      return finished
    } catch (err) {
      error = err instanceof Error ? err.message : String(err)
      lastReadAt = Date.now()
      return []
    } finally {
      isBusy = false
    }
  }

  const toastFor = (c: Change) =>
    c.to === 'ready'
      ? `vercel: ${c.project} is ready${c.target === 'production' ? ' in production' : ''}`
      : `vercel: ${c.project} failed${c.error ? `: ${fit(c.error, 80)}` : ''}`

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await $.command
      .register({
        name: COMMAND,
        description: 'Your Vercel projects and the state of their deployments (stop closes)',
        argumentHint: '[stop]',
        immediate: true,
      })
      .catch(err => $.ui.log(`vercel-deploys: /${COMMAND} not registered: ${err}`))
    if (!token) {
      $.ui.log('vercel-deploys: set vercelToken in the plugin options to list your projects', { to: 'debug' })
      return r
    }

    timer?.cancel()
    timer = $.clock.every(TICK_MS, () => {
      if (isBusy || (!isOpen && !showStatus)) return
      if (Date.now() - lastReadAt < (isBuilding() ? BUILDING_POLL_MS : idleMs) - TICK_MS / 2) return
      void read(
        (url, init) => $.http.fetch(url, init),
        ms => $.clock.sleep(ms),
      ).then(finished => {
        if (wantToast) for (const c of finished) $.ui.toast(toastFor(c))
        $.ui.status(showStatus ? statusText() : undefined)
        $.ui.invalidate('ui.render')
      })
    })

    if (openOnStart) {
      await read(
        (url, init) => $.http.fetch(url, init),
        ms => $.clock.sleep(ms),
      )
      isOpen = true
      await $.ui.open({ id: PANE, title: 'vercel' }).catch(() => {
        isOpen = false
      })
      $.ui.status(showStatus ? statusText() : undefined)
    }
    return r
  })

  on('session.end', async ($, e, next) => {
    timer?.cancel()
    timer = undefined
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    if (!token) return { text: 'vercel: set vercelToken in the plugin options' }
    const arg = e.args.trim().toLowerCase()
    if (arg === 'stop' || arg === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      isOpen = false
      return { text: 'vercel closed' }
    }
    await read(
      (url, init) => $.http.fetch(url, init),
      ms => $.clock.sleep(ms),
    )
    isOpen = true
    await $.ui.open({ id: PANE, title: 'vercel', focus: true })
    $.ui.status(showStatus ? statusText() : undefined)
    $.ui.invalidate('ui.render')
    if (error) return { text: `vercel: ${error}` }
    return { text: `${summaryText(summarize(projects))} · /${COMMAND} stop closes` }
  })

  on('ui.close', async ($, e, next) => {
    if (e.id !== PANE) return next(e)
    isOpen = false
    return next(e)
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    const r = await next(e)
    const key = e.element
    if (key === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return r
    }
    if (key === 'refresh') {
      if (!isBusy) {
        health = new Map()
        const finished = await read(
          (url, init) => $.http.fetch(url, init),
          ms => $.clock.sleep(ms),
        )
        if (wantToast) for (const c of finished) $.ui.toast(toastFor(c))
        if (selected) {
          history = await listDeploys((url, init) => $.http.fetch(url, init), token, team, selected, 5).catch(() => history)
        }
      }
    } else if (key.startsWith('p:')) {
      const project = projects[Number(key.slice(2))]
      if (project && selected === project.id) {
        selected = undefined
        history = []
      } else if (project) {
        selected = project.id
        history = await listDeploys((url, init) => $.http.fetch(url, init), token, team, project.id, 5).catch(() => [])
      }
    } else if (key === 'copy') {
      const domain = projects.find(p => p.id === selected)?.domain
      if (domain) {
        await $.ui.copy({ text: `https://${domain}`, surface: e.surface }).catch(() => undefined)
        $.ui.toast(`vercel: copied https://${domain}`)
      }
    }
    $.ui.status(showStatus ? statusText() : undefined)
    $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(30, e.props.bodyColumns - 1)
    const now = Date.now()
    const noop = () => {}
    const chosen = selected ? projects.find(p => p.id === selected) : undefined

    return (
      <Box flexDirection="column">
        <Text bold>{fit(summaryText(summarize(projects)), width)}</Text>
        {error ? <Text color="red">{fit(error, width)}</Text> : null}
        {projects.length === 0 && !error ? <Text dimColor>no projects</Text> : null}

        {projects.map((p, i) => {
          const state = p.latest?.state ?? 'unknown'
          const probe = health.get(p.id)
          const site = !healthCheck || !p.domain || !probe ? '' : probe.ok ? ` ✓${probe.status}` : probe.status === 0 ? ' ✕down' : ` ✕${probe.status}`
          const age = ago(p.latest?.createdAt, now)
          const label = `${p.name}${age ? `  ${age}` : ''}`
          const room = width - 2 - site.length
          return (
            <Box key={`row:${i}`} flexDirection="row">
              <Text color={COLOR[state]}>{`${GLYPH[state]} `}</Text>
              <Button key={`p:${i}`} plain dimColor={selected !== p.id && state === 'canceled'} label={fit(label, room)} onPress={noop} />
              {site ? <Text color={probe?.ok ? 'green' : 'red'}>{site}</Text> : null}
            </Box>
          )
        })}

        {chosen ? (
          <Box key="detail" flexDirection="column" marginTop={1} borderStyle="round" borderDimColor paddingX={1}>
            <Text bold>{fit(chosen.domain ?? chosen.name, width - 4)}</Text>
            <Text dimColor>
              {fit([chosen.framework, chosen.repo].filter(Boolean).join(' · ') || 'no Git repository linked', width - 4)}
            </Text>
            {history.map((d, i) => (
              <Text key={`d:${i}`} wrap="truncate-end">
                <Text color={COLOR[d.state]}>{`${GLYPH[d.state]} `}</Text>
                {`${d.target === 'production' ? 'prod' : 'prev'} ${ago(d.createdAt, now)} ${d.commit ?? d.readyState.toLowerCase()}`}
              </Text>
            ))}
            {chosen.latest?.error ? <Text color="red">{fit(chosen.latest.error, width - 4)}</Text> : null}
            {chosen.domain ? <Button key="copy" label="copy url" hotkey="c" onPress={noop} /> : null}
          </Box>
        ) : null}

        <Box key="foot" marginTop={1} flexDirection="column">
          <Box flexDirection="row" columnGap={1}>
            <Button key="refresh" label="refresh" hotkey="r" onPress={noop} />
            <Button key="close" label="close" onPress={noop} />
          </Box>
          <Text dimColor>{fit('● ready  ◐ building  ✕ failed · ✓ site answers', width)}</Text>
        </Box>
      </Box>
    )
  })
}

