/**
 * cache.ts — the pure half of prompt-cache-control: no `$`, no engine.
 *
 * What it models, from Anthropic's prompt-caching documentation:
 *   - the cache lives 5 minutes by default, 1 hour when asked for; a read
 *     refreshes the entry at no extra cost, and the lifetime is measured from
 *     the START of the request that wrote or read it
 *   - a request's prompt is `input_tokens` (uncached remainder) +
 *     `cache_read_input_tokens` + `cache_creation_input_tokens`
 *   - writes cost 1.25x base input for 5m and 2x for 1h; reads about 0.1x
 *     (less on some models), so an expired cache on a large context is the
 *     expensive moment
 *   - a prefix change (model, effort/thinking settings, tool set, system
 *     prompt) makes the next request write instead of read
 *
 * Claude Code's own switches (read from the environment):
 *   ENABLE_PROMPT_CACHING_1H=1   ask for the 1-hour TTL
 *   FORCE_PROMPT_CACHING_5M=1    force the 5-minute TTL, beating the above
 *   DISABLE_PROMPT_CACHING=1     no caching; DISABLE_PROMPT_CACHING_{HAIKU,SONNET,OPUS}
 *                                 turn it off for that model family only
 */

export type Ttl = '5m' | '1h'

export type CacheEnv = {
  enable1h?: string
  force5m?: string
  /** CLAUDE_CODE_PROMPT_CACHE_TTL: "5m" or "1h" for the main conversation */
  ttlVar?: string
  disableAll?: string
  disableHaiku?: string
  disableSonnet?: string
  disableOpus?: string
}

/** One main-loop request, as the API reported it. */
export type Sample = {
  turnId: string
  index: number
  model: string
  /** ms since the epoch when the request started: the cache's lifetime is counted from here */
  startedAt: number
  read: number
  write: number
  fresh: number
  output: number
}

export type AdviceKind = 'off' | 'cold' | 'uncached' | 'warm' | 'soon' | 'expired' | 'miss'

export type Advice = {
  kind: AdviceKind
  /** one sentence for the band */
  text: string
}

export type Policy = {
  ttl: Ttl
  warnMs: number
  compactAtTokens: number
}

export const isOn = (v: string | undefined) => v === '1' || v?.toLowerCase() === 'true'

/** What the account is billed as, as far as the mod can tell. */
export type Account = 'subscription' | 'credits' | 'other'

export type TtlChoice = { ttl: Ttl; source: string }

const asTtl = (v: unknown): Ttl | undefined => (v === '5m' || v === '1h' ? v : undefined)

/**
 * Which lifetime Claude Code asks for on the main conversation, in the order
 * its documentation gives (https://code.claude.com/docs/en/prompt-caching,
 * "Choose the TTL yourself"), after the mod's own `ttl` option:
 *
 *   FORCE_PROMPT_CACHING_5M, CLAUDE_CODE_PROMPT_CACHE_TTL, the promptCacheTtl
 *   setting, ENABLE_PROMPT_CACHING_1H, then the default of the account: one
 *   hour on a Claude subscription within its plan usage, five minutes on usage
 *   credits, an API key or a cloud provider.
 */
export function decideTtl(option: unknown, env: CacheEnv, setting?: unknown, account?: Account): TtlChoice {
  const pinned = asTtl(option)
  if (pinned) return { ttl: pinned, source: 'the ttl option' }
  if (isOn(env.force5m)) return { ttl: '5m', source: 'FORCE_PROMPT_CACHING_5M' }
  const fromVar = asTtl(env.ttlVar)
  if (fromVar) return { ttl: fromVar, source: 'CLAUDE_CODE_PROMPT_CACHE_TTL' }
  const fromSetting = asTtl(setting)
  if (fromSetting) return { ttl: fromSetting, source: 'the promptCacheTtl setting' }
  if (isOn(env.enable1h)) return { ttl: '1h', source: 'ENABLE_PROMPT_CACHING_1H' }
  if (account === 'subscription') return { ttl: '1h', source: 'Claude subscription default' }
  if (account === 'credits') return { ttl: '5m', source: 'usage credits default' }
  return { ttl: '5m', source: 'default' }
}

export const resolveTtl = (option: unknown, env: CacheEnv, setting?: unknown, account?: Account): Ttl =>
  decideTtl(option, env, setting, account).ttl

/**
 * The account, from the rate-limit windows the last response reported: a
 * five-hour or seven-day window means a Claude subscription, and one that is
 * full means the next requests draw on usage credits. No window (an API key,
 * a cloud provider, or no response yet) says nothing.
 */
export function accountOf(windows: readonly { kind: string; percentUsed: number }[]): Account {
  const plan = windows.filter(w => w.kind === 'five_hour' || w.kind === 'seven_day')
  if (plan.length === 0) return 'other'
  return plan.some(w => w.percentUsed >= 100) ? 'credits' : 'subscription'
}

export function ttlMs(ttl: Ttl): number {
  return ttl === '1h' ? 3_600_000 : 300_000
}

/** Caching switched off for this model by the environment. */
export function isCachingDisabled(model: string, env: CacheEnv): boolean {
  if (isOn(env.disableAll)) return true
  const name = model.toLowerCase()
  if (name.includes('haiku')) return isOn(env.disableHaiku)
  if (name.includes('sonnet')) return isOn(env.disableSonnet)
  if (name.includes('opus')) return isOn(env.disableOpus)
  return false
}

export const promptTokens = (s: Sample) => s.read + s.write + s.fresh

/** Share of the prompt the cache served, 0 to 1; 0 for an empty prompt. */
export function hitRatio(s: Sample): number {
  const total = promptTokens(s)
  return total === 0 ? 0 : s.read / total
}

/** When the cache entry the sample touched lapses, ms since the epoch. */
export const expiresAt = (s: Sample, ttl: Ttl) => s.startedAt + ttlMs(ttl)

/** Zero for a request that read and wrote nothing: it created or refreshed no entry, so there is nothing to count down. */
export function remainingMs(s: Sample, ttl: Ttl, now: number): number {
  if (s.read + s.write === 0) return 0
  return Math.max(0, expiresAt(s, ttl) - now)
}

/**
 * Why a request that should have read the cache wrote it instead; undefined
 * when it did not miss. A prompt that shrank is a /compact or /clear, not a
 * miss, and the first request of a session has nothing to read.
 */
export function missReason(prev: Sample | undefined, cur: Sample, ttl: Ttl): string | undefined {
  if (!prev) return undefined
  const before = promptTokens(prev)
  if (before === 0 || promptTokens(cur) < before * 0.7) return undefined
  if (cur.read >= before * 0.5 || cur.write === 0) return undefined
  if (cur.model !== prev.model) return `model changed (${prev.model} to ${cur.model})`
  if (cur.startedAt - prev.startedAt > ttlMs(ttl)) return `the ${ttl} cache had lapsed`
  return 'the prompt prefix changed (effort, tools, system prompt or CLAUDE.md)'
}

export function advise(last: Sample | undefined, prev: Sample | undefined, policy: Policy, now: number, disabled: boolean): Advice {
  if (disabled) return { kind: 'off', text: 'prompt caching is off for this model (DISABLE_PROMPT_CACHING*)' }
  if (!last) return { kind: 'cold', text: 'no request yet: the first one writes the cache' }
  if (last.read + last.write === 0) {
    return { kind: 'uncached', text: 'this request was not cached (prompt under the model minimum, or caching off)' }
  }
  const miss = missReason(prev, last, policy.ttl)
  const left = remainingMs(last, policy.ttl, now)
  const size = promptTokens(last)
  if (left <= 0) {
    const big = size >= policy.compactAtTokens
    return {
      kind: 'expired',
      text: big
        ? `expired: the next message rewrites ${fmtTokens(size)} tokens. /compact first, or /clear if the task is done`
        : `expired: only ${fmtTokens(size)} tokens to rebuild, just keep going`,
    }
  }
  if (left <= policy.warnMs) {
    return { kind: 'soon', text: 'expires soon: any message refreshes it for free' }
  }
  if (miss) return { kind: 'miss', text: `cache missed: ${miss}` }
  return { kind: 'warm', text: 'warm: keep going' }
}

export function fmtTokens(n: number): string {
  if (n < 1000) return String(n)
  if (n < 100_000) return `${(n / 1000).toFixed(1).replace(/\.0$/, '')}k`
  if (n < 1_000_000) return `${Math.round(n / 1000)}k`
  return `${(n / 1_000_000).toFixed(1).replace(/\.0$/, '')}M`
}

/** m:ss, or h:mm:ss from an hour up. */
export function fmtClock(ms: number): string {
  const total = Math.max(0, Math.ceil(ms / 1000))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  const pad = (n: number) => String(n).padStart(2, '0')
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`
}

export function bar(ratio: number, width: number): string {
  const filled = Math.round(Math.min(1, Math.max(0, ratio)) * width)
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

export type TurnRow = {
  turnId: string
  steps: number
  read: number
  write: number
  fresh: number
  output: number
}

/** Samples grouped by turn, oldest first, each turn's requests summed. */
export function byTurn(samples: readonly Sample[]): TurnRow[] {
  const rows: TurnRow[] = []
  for (const s of samples) {
    let row = rows[rows.length - 1]
    if (!row || row.turnId !== s.turnId) {
      row = { turnId: s.turnId, steps: 0, read: 0, write: 0, fresh: 0, output: 0 }
      rows.push(row)
    }
    row.steps += 1
    row.read += s.read
    row.write += s.write
    row.fresh += s.fresh
    row.output += s.output
  }
  return rows
}

export const rowRatio = (r: TurnRow) => {
  const total = r.read + r.write + r.fresh
  return total === 0 ? 0 : r.read / total
}

export function fit(text: string, width: number): string {
  return text.length <= width ? text : `${text.slice(0, Math.max(0, width - 1))}…`
}

export function positive(v: unknown, fallback: number): number {
  return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : fallback
}

/** Share of the cache lifetime left, 0 to 1. */
export function lifeRatio(leftMs: number, ttl: Ttl): number {
  return Math.min(1, Math.max(0, leftMs / ttlMs(ttl)))
}

/**
 * Widths of the three stacked-bar segments (read, wrote, new) over `width`
 * cells: proportional, each non-empty part at least one cell, summing to width.
 */
export function segments(read: number, write: number, fresh: number, width: number): [number, number, number] {
  const total = read + write + fresh
  if (total === 0 || width <= 0) return [0, 0, 0]
  const parts = [read, write, fresh]
  const cells = parts.map(p => (p > 0 ? Math.max(1, Math.round((p / total) * width)) : 0))
  let over = cells.reduce((a, b) => a + b, 0) - width
  while (over !== 0) {
    const i = over > 0 ? cells.indexOf(Math.max(...cells)) : parts.indexOf(Math.max(...parts))
    cells[i] += over > 0 ? -1 : 1
    over += over > 0 ? -1 : 1
  }
  return [cells[0], cells[1], cells[2]]
}

/** Seconds left at which a toast counts down after the one at the warning threshold. */
export const COUNTDOWN_MARKS = [10, 3, 2, 1]

/**
 * The toast mark to fire now, or undefined. `level` is the mark last fired for
 * this cache entry (Infinity before any); a late tick skips straight to the
 * newest mark crossed, so a stalled clock never replays old ones.
 */
export function nextToastMark(secsLeft: number, warnSecs: number, level: number): number | undefined {
  const marks = [warnSecs, ...COUNTDOWN_MARKS].filter(m => m <= warnSecs)
  const due = marks.filter(m => secsLeft <= m && m < level)
  return due.length ? Math.min(...due) : undefined
}

export type LifeColor = 'green' | 'yellow' | 'red'

/** Countdown colour: green while there is plenty, yellow below 40% of the lifetime, red from the warning threshold down. */
export function lifeColor(leftMs: number, ttl: Ttl, warnMs: number): LifeColor {
  if (leftMs <= warnMs) return 'red'
  return leftMs / ttlMs(ttl) <= 0.4 ? 'yellow' : 'green'
}

// requests are timed from their start, so a little slack keeps a hit that
// landed just inside the lifetime from reading as proof of the longer one
const SLACK_MS = 10_000

/**
 * What the traffic says about the cache lifetime, given the request before and
 * `known`, what earlier requests already showed.
 *
 *   - a hit (the cache served at least half of the previous prompt) more than
 *     5 minutes after the previous request began proves the 1-hour lifetime,
 *     and nothing later undoes it: a miss afterwards is more likely a changed
 *     prefix than a lapse
 *   - a miss with the same model and a prompt that did not shrink, 5 minutes to
 *     an hour after the previous request, says the entry lapsed: 5 minutes
 *     (weaker: a changed prefix looks the same, so a later hit overrules it)
 *
 * Needed because the API names the TTL of a write (`cache_creation.ephemeral_*`)
 * but Claude Code's mod API passes on only the four token counts.
 */
export function observeTtl(prev: Sample | undefined, cur: Sample, known: Ttl | undefined): Ttl | undefined {
  if (!prev || prev.read + prev.write === 0 || cur.model !== prev.model) return known
  const gap = cur.startedAt - prev.startedAt
  const before = promptTokens(prev)
  if (gap <= ttlMs('5m') + SLACK_MS) return known
  if (cur.read >= before * 0.5) return '1h'
  if (known === '1h') return known
  const lapsed = cur.write > 0 && promptTokens(cur) >= before * 0.7 && gap < ttlMs('1h') + SLACK_MS
  return lapsed ? '5m' : known
}

/**
 * Idle compaction (Claude Code 2.1.290+): a terminal conversation left idle is
 * compacted shortly before its one-hour cache lapses, so the next message reads
 * a summary instead of rewriting the whole prefix. Claude Code fires it at
 * `fraction` of the cache lifetime (0.9 of an hour: about 54 minutes) when all
 * of these hold, read from the 2.1.299 build:
 *
 *   - the rollout flag is on for the account (a server-side flag Claude Code
 *     caches in ~/.claude.json; `mode: "off"` there means it never runs, and
 *     `idleCompaction: true` does not turn it on)
 *   - auto-compact is on (no DISABLE_COMPACT / DISABLE_AUTO_COMPACT,
 *     autoCompactEnabled not false) and the idleCompaction setting is not false
 *   - the main conversation's cache lives one hour and is still warm
 *   - the prompt is at least minTokens: CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS,
 *     never below 100K, 200K when unset
 */
export const IDLE_MIN_FLOOR = 100_000
export const IDLE_MIN_DEFAULT = 200_000
export const IDLE_FRACTION = 0.9

export type IdleInputs = {
  /** CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS */
  minTokensVar?: string
  /** the idleCompaction setting */
  setting?: unknown
  /** the autoCompactEnabled setting */
  autoCompact?: unknown
  /** DISABLE_AUTO_COMPACT */
  disableAuto?: string
  /** DISABLE_COMPACT */
  disableAll?: string
  /** the cached rollout flag, `{ mode, minTokens?, fireAtFraction? }`; undefined when not found */
  flag?: unknown
}

export type IdleCompact = {
  /** whether Claude Code will compact this session while idle */
  on: boolean
  /** false when the rollout flag could not be read (then `on` is false) */
  known: boolean
  minTokens: number
  fraction: number
  /** one phrase: why it is off, or where the threshold came from */
  why: string
}

const finite = (v: unknown): number | undefined => {
  const n = typeof v === 'string' && v.trim() !== '' ? Number(v) : v
  return typeof n === 'number' && Number.isFinite(n) ? n : undefined
}

export function idlePolicy(i: IdleInputs): IdleCompact {
  const flag = i.flag && typeof i.flag === 'object' ? (i.flag as Record<string, unknown>) : undefined
  const fromVar = finite(i.minTokensVar)
  const raw = fromVar ?? finite(flag?.minTokens)
  const minTokens = raw === undefined ? IDLE_MIN_DEFAULT : Math.max(IDLE_MIN_FLOOR, raw)
  const f = finite(flag?.fireAtFraction)
  const fraction = f === undefined ? IDLE_FRACTION : Math.min(0.95, Math.max(0.5, f))
  const base = { minTokens, fraction, known: flag !== undefined }
  if (isOn(i.disableAll) || isOn(i.disableAuto)) return { ...base, on: false, why: 'auto-compact is off (DISABLE_*COMPACT)' }
  if (i.autoCompact === false) return { ...base, on: false, why: 'auto-compact is off (autoCompactEnabled)' }
  if (i.setting === false) return { ...base, on: false, why: 'turned off (idleCompaction: false)' }
  // without the cached flag there is no telling: a countdown to something that may never happen is worse than none
  if (!flag) return { ...base, on: false, why: 'rollout flag not found in ~/.claude.json' }
  const mode = flag.mode
  if (mode !== 'compact' && mode !== 'compact_on_return') {
    return { ...base, on: false, why: `not rolled out to this account (mode ${String(mode ?? 'off')})` }
  }
  const source = fromVar !== undefined ? 'CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS' : 'default'
  return { ...base, on: true, why: `from ${fmtTokens(minTokens)} tokens (${source})` }
}

/**
 * When Claude Code will compact this conversation if nobody types, ms since
 * the epoch; undefined when it will not (off, a 5-minute cache, a prompt under
 * the threshold, or a cache already lapsed).
 */
export function idleCompactAt(last: Sample | undefined, ttl: Ttl, idle: IdleCompact, now: number): number | undefined {
  if (!last || !idle.on || ttl !== '1h') return undefined
  if (promptTokens(last) < idle.minTokens || remainingMs(last, ttl, now) <= 0) return undefined
  return last.startedAt + ttlMs(ttl) * idle.fraction
}

{
  "description": "prompt-cache-control: turn.step reads each request's cache usage; a one-second clock.every drives the countdown; ui.render draws the AbovePrompt band and the /cache pane",
  "modules": [
    "./prompt-cache-control.tsx"
  ]
}

/**
 * prompt-cache-control — Claude Mod
 *
 * A prompt-cache meter for Claude Code. Every main-loop request reports how
 * many prompt tokens the cache served (`cache_read_input_tokens`), wrote
 * (`cache_creation_input_tokens`) and sent uncached (`input_tokens`); this mod
 * keeps those per request and per turn, counts down to the moment the cache
 * lapses, and says what to do about it: keep going, /compact or /clear.
 *
 *   - `turn.step` reads each main-loop request's usage (subagents have their
 *     own prefixes and are left out)
 *   - `$.clock.every(1000)` redraws the countdown, and only while its text
 *     changes: an idle, expired session costs nothing
 *   - a row above the prompt (the AbovePrompt component), an optional status
 *     line entry, and `/cache`, a pane with one row per turn
 *   - idle compaction (Claude Code 2.1.290+): when Claude Code will compact
 *     the conversation by itself before the 1-hour cache lapses, the band
 *     counts down to that moment as well as to the expiry, and
 *     `session.compact` (trigger "idle") says when it happened (see idlePolicy
 *     in ./cache.ts for the conditions)
 *
 * The lifetime is counted from the start of the request that last wrote or read
 * the cache, as Anthropic documents it. Which lifetime Claude Code asked for
 * follows its documented rules (see decideTtl in ./cache.ts): FORCE_PROMPT_CACHING_5M,
 * CLAUDE_CODE_PROMPT_CACHE_TTL, the promptCacheTtl setting, ENABLE_PROMPT_CACHING_1H,
 * then the account (1 hour on a Claude subscription, 5 minutes otherwise). The
 * API names the TTL of a write but the mod API passes on only the token counts,
 * so the mod also watches the gaps between requests (a hit after more than 5
 * minutes proves 1 hour; see observeTtl). `ttl: "5m" | "1h"` pins it.
 *
 * Needs Claude Code >= 2.1.287.
 *
 * Options (pluginConfigs["prompt-cache-control@skills-dir"].options):
 *   ttl: "auto" | "5m" | "1h"   cache lifetime (default auto)
 *   warnSeconds: number         countdown threshold for the warning (default 60)
 *   compactAtTokens: number     prompt size that makes an expired cache suggest /compact (default 100000)
 *   band: boolean               row above the prompt (default true)
 *   status: boolean             entry under the prompt (default false)
 *   toast: boolean              toasts near expiry: at warnSeconds, then 10, 3, 2 and 1 s (default true)
 *   idleCompact: boolean        idle compaction countdown and notice (default true)
 */
import type { EngineInterface, Register } from 'claude-code'
import {
  advise,
  COUNTDOWN_MARKS,
  bar,
  byTurn,
  fit,
  fmtClock,
  fmtTokens,
  hitRatio,
  idleCompactAt,
  idlePolicy,
  isCachingDisabled,
  accountOf,
  decideTtl,
  observeTtl,
  lifeColor,
  lifeRatio,
  nextToastMark,
  positive,
  promptTokens,
  remainingMs,
  rowRatio,
  segments,
} from './cache.ts'
import type { Account, Advice, CacheEnv, IdleCompact, Sample, Ttl } from './cache.ts'

const PANE = 'cache'
const COMMAND = 'cache'
const KEEP = 200
// below this a lapsed cache costs too little to interrupt anyone about
const TOAST_MIN_TOKENS = 20_000

let samples: Sample[] = []
let ttl: Ttl = '5m'
let baseTtl: Ttl = '5m'
let pinned = false
let observed: Ttl | undefined
let setting: unknown
let account: Account = 'other'
let ttlSource = 'default'
let envSource = 'default'
let env: CacheEnv = {}
let timer: { cancel: () => void } | undefined
let lastKey = ''
let toastedFor = 0
let toastLevel = Infinity
let isPaneOpen = false
let idle: IdleCompact = idlePolicy({})
// the last compaction of the main conversation: a cache entry older than it is gone
let compacted: { at: number; trigger: string; before?: number; after?: number } | undefined

type Policy = { warnMs: number; compactAtTokens: number }

function current(policy: Policy, now: number) {
  const last = samples[samples.length - 1]
  const prev = samples[samples.length - 2]
  const disabled = last ? isCachingDisabled(last.model, env) : isCachingDisabled('', env)
  if (last && compacted && compacted.at > last.startedAt) {
    // the conversation the last request cached is gone: the next one starts from the summary
    const sizes = compacted.before && compacted.after ? ` (${fmtTokens(compacted.before)} → ${fmtTokens(compacted.after)})` : ''
    const how = compacted.trigger === 'idle' ? 'compacted while idle' : 'compacted'
    const advice: Advice = { kind: 'cold', text: `${how}${sizes}: the next message starts from the summary` }
    return { last, advice, left: 0, idleAt: undefined }
  }
  const advice: Advice = advise(last, prev, { ttl, ...policy }, now, disabled)
  const left = last ? remainingMs(last, ttl, now) : 0
  const idleAt = disabled ? undefined : idleCompactAt(last, ttl, idle, now)
  return { last, advice, left, idleAt }
}

// "⇣ 41:12" until Claude Code compacts on its own, "⇣ now" once that moment has come
const idleClock = (idleAt: number, now: number) => (idleAt > now ? `⇣ ${fmtClock(idleAt - now)}` : '⇣ now')

const COLOR: Record<Advice['kind'], string | undefined> = {
  warm: 'green',
  soon: 'yellow',
  expired: 'red',
  miss: 'red',
  off: undefined,
  cold: undefined,
  uncached: undefined,
}

function shortLine(policy: Policy, now: number): string {
  const { last, advice, left } = current(policy, now)
  if (!last || advice.kind === 'off') return `cache: ${advice.text}`
  const clock = left > 0 ? ` · ${fmtClock(left)}` : ''
  return `cache ${Math.round(hitRatio(last) * 100)}%${clock}`
}

type Settings = { promptCacheTtl?: unknown; idleCompaction?: unknown; autoCompactEnabled?: unknown }

// the settings the mod follows, each from the first settings file that sets it (local over project over user)
async function readSettings($: EngineInterface): Promise<Settings> {
  const home = await $.env.get('HOME').catch(() => undefined)
  const cwd = await $.session.cwd().catch(() => undefined)
  const files = [cwd && `${cwd}/.claude/settings.local.json`, cwd && `${cwd}/.claude/settings.json`, home && `${home}/.claude/settings.json`]
  const out: Settings = {}
  for (const file of files) {
    if (!file) continue
    try {
      const json = JSON.parse(await $.fs.read(file))
      if (out.promptCacheTtl === undefined && (json.promptCacheTtl === '5m' || json.promptCacheTtl === '1h')) out.promptCacheTtl = json.promptCacheTtl
      if (out.idleCompaction === undefined && typeof json.idleCompaction === 'boolean') out.idleCompaction = json.idleCompaction
      if (out.autoCompactEnabled === undefined && typeof json.autoCompactEnabled === 'boolean') out.autoCompactEnabled = json.autoCompactEnabled
    } catch {
      // missing or unreadable: the next file
    }
  }
  return out
}

// Claude Code's global config: the cached idle-compaction rollout flag, and autoCompactEnabled as /config saves it.
// Only those two keys are kept; nothing else in the file is held by the mod.
async function readGlobalConfig($: EngineInterface): Promise<{ flag?: unknown; autoCompact?: unknown }> {
  const dir = await $.env.get('CLAUDE_CONFIG_DIR').catch(() => undefined)
  const home = await $.env.get('HOME').catch(() => undefined)
  const file = dir ? `${dir}/.claude.json` : home ? `${home}/.claude.json` : undefined
  if (!file) return {}
  try {
    const json = JSON.parse(await $.fs.read(file))
    const flag = json?.cachedGrowthBookFeatures?.tengu_sunny_locket
    return { flag: flag && typeof flag === 'object' ? flag : undefined, autoCompact: json?.autoCompactEnabled }
  } catch {
    return {}
  }
}

export const register: Register = (on, options) => {
  const policy: Policy = {
    warnMs: positive(options.warnSeconds, 60) * 1000,
    compactAtTokens: positive(options.compactAtTokens, 100_000),
  }
  const showBand = options.band !== false
  const showStatus = options.status === true
  const wantToast = options.toast !== false
  const showIdle = options.idleCompact !== false

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    samples = []
    lastKey = ''
    toastedFor = 0
    compacted = undefined
    const none = () => undefined
    env = {
      enable1h: await $.env.get('ENABLE_PROMPT_CACHING_1H').catch(none),
      force5m: await $.env.get('FORCE_PROMPT_CACHING_5M').catch(none),
      ttlVar: await $.env.get('CLAUDE_CODE_PROMPT_CACHE_TTL').catch(none),
      disableAll: await $.env.get('DISABLE_PROMPT_CACHING').catch(none),
      disableHaiku: await $.env.get('DISABLE_PROMPT_CACHING_HAIKU').catch(none),
      disableSonnet: await $.env.get('DISABLE_PROMPT_CACHING_SONNET').catch(none),
      disableOpus: await $.env.get('DISABLE_PROMPT_CACHING_OPUS').catch(none),
    }
    pinned = options.ttl === '5m' || options.ttl === '1h'
    observed = undefined
    const settings = await readSettings($)
    setting = settings.promptCacheTtl
    const global = await readGlobalConfig($)
    idle = idlePolicy({
      minTokensVar: await $.env.get('CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS').catch(none),
      disableAuto: await $.env.get('DISABLE_AUTO_COMPACT').catch(none),
      disableAll: await $.env.get('DISABLE_COMPACT').catch(none),
      setting: settings.idleCompaction,
      autoCompact: settings.autoCompactEnabled ?? global.autoCompact,
      flag: global.flag,
    })
    account = accountOf((await $.session.usage().catch(() => undefined))?.rateLimits ?? [])
    const choice = decideTtl(options.ttl, env, setting, account)
    baseTtl = choice.ttl
    ttl = baseTtl
    envSource = choice.source
    ttlSource = envSource

    await $.command
      .register({
        name: COMMAND,
        description: 'Prompt-cache usage per turn and the time left before it lapses (stop closes)',
        argumentHint: '[stop]',
        immediate: true,
      })
      .catch(err => $.ui.log(`prompt-cache-control: /${COMMAND} not registered: ${err}`))
    $.ui.log(`prompt-cache-control loaded: ${ttl} cache (${ttlSource}), /${COMMAND} opens the table`, { to: 'debug' })
    $.ui.log(`prompt-cache-control: idle compaction ${idle.on ? 'on' : 'off'}, ${idle.why}${idle.known ? '' : ' (rollout flag not found)'}`, { to: 'debug' })

    timer?.cancel()
    timer = $.clock.every(1000, () => {
      const now = Date.now()
      const { last, advice, left, idleAt } = current(policy, now)
      const key = `${advice.kind}|${advice.text}|${left > 0 ? fmtClock(left) : ''}|${showIdle && idleAt ? idleClock(idleAt, now) : ''}`
      if (key !== lastKey) {
        lastKey = key
        if (showStatus) $.ui.status(shortLine(policy, now))
        $.ui.invalidate('ui.render')
      }
      if (wantToast && last && left > 0 && promptTokens(last) >= TOAST_MIN_TOKENS) {
        if (toastedFor !== last.startedAt) {
          toastedFor = last.startedAt
          toastLevel = Infinity
        }
        // the first toast comes at warnSeconds, then 10, 3, 2 and 1 seconds; a late tick skips to the newest one
        const secs = Math.ceil(left / 1000)
        const mark = nextToastMark(secs, policy.warnMs / 1000, toastLevel)
        if (mark !== undefined) {
          toastLevel = mark
          const tail = secs <= COUNTDOWN_MARKS[0] ? 'send a message now' : `send a message to keep ${fmtTokens(promptTokens(last))} tokens warm`
          $.ui.toast(`cache expires in ${secs >= 60 ? fmtClock(left) : `${secs}s`}: ${tail}`)
        }
      }
    })
    return r
  })

  on('session.end', async ($, e, next) => {
    // /clear starts a new conversation in the same process: its cache is a new one
    if (e.reason === 'clear') {
      samples = []
      lastKey = ''
      toastedFor = 0
      compacted = undefined
      observed = undefined
      ttl = baseTtl
      ttlSource = envSource
      $.ui.invalidate('ui.render')
      return next(e)
    }
    timer?.cancel()
    timer = undefined
    return next(e)
  })

  // a compaction of the main conversation replaces what the cache held; "idle" is Claude Code compacting on its own (2.1.290+)
  on('session.compact', async ($, e, next) => {
    const r = await next(e)
    // a precompute only prepares a summary; the conversation is unchanged until it is used.
    // "idle" is newer than the d.ts (2.1.283), hence the string: re-check when it is regenerated
    const trigger = String(e.trigger)
    if (e.agentId || trigger === 'precompute' || 'skip' in r) return r
    compacted = { at: Date.now(), trigger, before: r.tokensBefore, after: r.tokensAfter }
    lastKey = ''
    if (trigger === 'idle') {
      const sizes = r.tokensBefore && r.tokensAfter ? ` ${fmtTokens(r.tokensBefore)} → ${fmtTokens(r.tokensAfter)} tokens` : ''
      $.ui.log(`prompt-cache-control: compacted while idle${sizes}, before the ${ttl} cache lapsed`)
      if (showIdle && wantToast) $.ui.toast(`compacted while idle${sizes}: your next message starts from the summary`)
    }
    if (showStatus) $.ui.status(shortLine(policy, Date.now()))
    $.ui.invalidate('ui.render')
    return r
  })

  // each main-loop request: what the cache did with it
  on('turn.step', async function* ($, e, next) {
    if (e.agentId) return yield* next(e)
    const startedAt = Date.now()
    const r = yield* next(e)
    if (r.usage) {
      samples.push({
        turnId: e.turnId,
        index: e.index,
        model: r.usage.model || e.model,
        startedAt,
        read: r.usage.cache_read_input_tokens,
        write: r.usage.cache_creation_input_tokens,
        fresh: r.usage.input_tokens,
        output: r.usage.output_tokens,
      })
      if (samples.length > KEEP) samples = samples.slice(-KEEP)
      if (!pinned) {
        // the account can change under a session: a subscription running out of plan usage moves to usage credits
        account = accountOf((await $.session.usage().catch(() => undefined))?.rateLimits ?? [])
        const choice = decideTtl(options.ttl, env, setting, account)
        baseTtl = choice.ttl
        envSource = choice.source
        if (observed === undefined) {
          ttl = baseTtl
          ttlSource = envSource
        }
        const seen = observeTtl(samples[samples.length - 2], samples[samples.length - 1], observed)
        if (seen !== observed) {
          observed = seen
          ttl = seen ?? baseTtl
          ttlSource = `observed from request timing; ${envSource} said ${baseTtl}`
          $.ui.log(`prompt-cache-control: cache lifetime is ${ttl} (${ttlSource})`, { to: 'debug' })
        }
      }
      lastKey = ''
      if (showStatus) $.ui.status(shortLine(policy, Date.now()))
      $.ui.invalidate('ui.render')
    }
    return r
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    if (e.args.trim().toLowerCase() === 'stop') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      isPaneOpen = false
      return { text: 'cache table closed' }
    }
    isPaneOpen = true
    await $.ui.open({ id: PANE, title: 'cache', focus: true })
    $.ui.invalidate('ui.render')
    const { advice } = current(policy, Date.now())
    return { text: `${ttl} cache (${ttlSource}) · ${advice.text} · /${COMMAND} stop closes` }
  })

  on('ui.close', async ($, e, next) => {
    if (e.id !== PANE) return next(e)
    isPaneOpen = false
    return next(e)
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    if (e.element === 'close') await $.ui.close({ id: PANE }).catch(() => undefined)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!showBand || e.props.hasSurvey || isPaneOpen) return next(e)
    const now = Date.now()
    const { last, advice, left, idleAt } = current(policy, now)
    if (!last && advice.kind !== 'off') return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const columns = e.viewport?.columns ?? 100
    const color = COLOR[advice.kind]
    // The band is one instance: whatever the plugins beneath draw (another mod's band) stays, under this line.
    const below = await next(e)
    const stack = (own: ReturnType<typeof Text>) => (
      <Box flexDirection="column">
        {own}
        {below}
      </Box>
    )

    if (!last) return stack(<Text dimColor>{fit(`cache: ${advice.text}`, columns)}</Text>)

    const ratio = hitRatio(last)
    const wide = columns >= 90
    return stack(
      <Box flexDirection="row" columnGap={1}>
        <Text bold color={color}>{advice.kind === 'warm' ? '●' : advice.kind === 'soon' ? '▲' : advice.kind === 'off' || advice.kind === 'cold' || advice.kind === 'uncached' ? '○' : '✖'}</Text>
        <Text bold color="cyan">cache</Text>
        <Text color={color}>{bar(ratio, wide ? 10 : 6)}</Text>
        <Text bold>{`${Math.round(ratio * 100)}%`}</Text>
        {wide ? (
          <>
            <Text color="green">{`read ${fmtTokens(last.read)}`}</Text>
            <Text color="yellow">{`wrote ${fmtTokens(last.write)}`}</Text>
            <Text color="cyan">{`new ${fmtTokens(last.fresh)}`}</Text>
          </>
        ) : (
          <Text dimColor>{`${fmtTokens(promptTokens(last))} tok`}</Text>
        )}
        {advice.kind !== 'uncached' && advice.kind !== 'off' && advice.kind !== 'cold' && (
          <Text bold color={left > 0 ? lifeColor(left, ttl, policy.warnMs) : 'red'}>{left > 0 ? `⏱ ${fmtClock(left)}` : '⏱ 0:00'}</Text>
        )}
        {showIdle && idleAt !== undefined && <Text bold color="magenta">{idleClock(idleAt, now)}</Text>}
        <Text dimColor wrap="truncate-end">{`${ttl} · ${showIdle && idleAt !== undefined ? (idleAt > now ? 'left idle, Claude Code compacts it before the cache lapses' : 'compacting while idle') : advice.text}`}</Text>
      </Box>,
    )
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(30, e.props.bodyColumns - 1)
    // HTML collapses runs of spaces and trims a text's ends; a no-break space keeps them
    const sp = (t: string) => (e.surface === 'terminal' ? t : t.replace(/ /g, ' '))
    const now = Date.now()
    const { last, advice, left, idleAt } = current(policy, now)
    const all = byTurn(samples)
    const counting = !!last && advice.kind !== 'uncached' && advice.kind !== 'off' && advice.kind !== 'cold'
    // the countdown goes green, then yellow, then red as the cache runs out
    const clockColor = counting ? lifeColor(left, ttl, policy.warnMs) : undefined
    const stateColor = advice.kind === 'expired' || advice.kind === 'miss' ? 'red' : (clockColor ?? COLOR[advice.kind])
    const hitColor = (pct: number) => (pct >= 80 ? 'green' : pct >= 40 ? 'yellow' : 'red')
    // solid bars are filled Boxes, not block characters, so HTML draws no seams between cells
    const solid = (key: string, parts: [number, string | undefined][]) => (
      <Box key={key} flexDirection="row" height={1} flexShrink={0}>
        {parts.map(([w, c], i) => (w > 0 ? <Box key={`${key}:${i}`} width={w} height={1} flexShrink={0} backgroundColor={c} /> : null))}
      </Box>
    )
    const cell = (key: string, w: number, text: string, c?: string, bold = false) => (
      <Box key={key} width={w} flexShrink={0} justifyContent="flex-end">
        <Text color={c} bold={bold} dimColor={!c}>{sp(text)}</Text>
      </Box>
    )

    const barW = Math.min(width, 40)
    const life = lifeRatio(left, ttl)
    const lifeFilled = Math.round(life * barW)
    const [sr, sw, sn] = last ? segments(last.read, last.write, last.fresh, barW) : [0, 0, 0]
    const rows = all.slice(-Math.max(3, (e.viewport?.rows ?? 24) - 16))
    // why the idle-compaction line says what it says
    const idleDetail = (at: number | undefined) => {
      if (!idle.on) return `${idle.why}`
      if (at !== undefined) return `if nobody types, Claude Code compacts at ${Math.round(idle.fraction * 100)}% of the 1h cache, ${idle.why}`
      if (ttl !== '1h') return `needs the 1h cache; this session's is ${ttl}`
      if (last && promptTokens(last) < idle.minTokens) return `waits for ${fmtTokens(idle.minTokens)} tokens; the prompt is ${fmtTokens(promptTokens(last))}`
      return `armed while the cache is warm, ${idle.why}`
    }
    const icon = advice.kind === 'warm' ? '●' : advice.kind === 'soon' ? '▲' : advice.kind === 'expired' || advice.kind === 'miss' ? '✖' : '○'

    return (
      <Box flexDirection="column">
        <Box key="title" flexDirection="row" columnGap={1}>
          <Text bold color="cyan">{sp('⚡ PROMPT CACHE')}</Text>
          <Text dimColor>{sp(`· ${ttl} lifetime (${ttlSource})`)}</Text>
        </Box>

        <Box key="clock" flexDirection="column" marginTop={1}>
          <Text bold color={clockColor}>{sp(counting ? `⏱ ${left > 0 ? fmtClock(left) : '0:00'}` : '⏱ --:--')}</Text>
          {counting ? (
            <Box flexDirection="row" columnGap={1}>
              {solid('life', [[lifeFilled, clockColor], [barW - lifeFilled, 'gray']])}
              <Text dimColor>{sp(`${Math.round(life * 100)}%`)}</Text>
            </Box>
          ) : null}
        </Box>

        <Box key="advice" marginTop={1} flexDirection="column">
          <Text bold color={stateColor}>{sp(`${icon} ${advice.text}`)}</Text>
          {last ? <Text dimColor>{sp(fit(`${last.model} · prompt ${fmtTokens(promptTokens(last))} tokens`, width))}</Text> : null}
        </Box>

        {showIdle ? (
          <Box key="idle" marginTop={1} flexDirection="column">
            <Text bold color={idleAt !== undefined ? 'magenta' : undefined} dimColor={idleAt === undefined}>
              {sp(idleAt !== undefined ? `${idleClock(idleAt, now)} idle compaction` : `⇣ idle compaction ${idle.on ? 'on' : 'off'}`)}
            </Text>
            <Text dimColor>{sp(fit(idleDetail(idleAt), width))}</Text>
          </Box>
        ) : null}

        {last ? (
          <Box key="stack" flexDirection="column" marginTop={1}>
            <Box flexDirection="row" columnGap={1}>
              {solid('stack', [[sr, 'green'], [sw, 'yellow'], [sn, 'cyan']])}
              <Text bold color={hitColor(Math.round(hitRatio(last) * 100))}>{sp(`${Math.round(hitRatio(last) * 100)}% hit`)}</Text>
            </Box>
            <Box flexDirection="row" columnGap={2}>
              <Text color="green">{sp(`■ read ${fmtTokens(last.read)}`)}</Text>
              <Text color="yellow">{sp(`■ wrote ${fmtTokens(last.write)}`)}</Text>
              <Text color="cyan">{sp(`■ new ${fmtTokens(last.fresh)}`)}</Text>
            </Box>
          </Box>
        ) : null}

        <Box key="table" flexDirection="column" marginTop={1}>
          <Box key="head" flexDirection="row" columnGap={1}>
            {cell('h:turn', 4, 'turn', 'cyan', true)}
            {cell('h:steps', 5, 'steps', 'cyan', true)}
            {cell('h:read', 6, 'read', 'green', true)}
            {cell('h:wrote', 6, 'wrote', 'yellow', true)}
            {cell('h:new', 5, 'new', 'cyan', true)}
            {cell('h:hit', 4, 'hit', 'magenta', true)}
          </Box>
          {rows.length === 0 ? <Text dimColor>{sp('no requests yet')}</Text> : null}
          {rows.map((row, i) => {
            const n = all.length - rows.length + i + 1
            const pct = Math.round(rowRatio(row) * 100)
            return (
              <Box key={`t:${row.turnId}`} flexDirection="row" columnGap={1}>
                {cell(`c:turn:${row.turnId}`, 4, String(n))}
                {cell(`c:steps:${row.turnId}`, 5, String(row.steps))}
                {cell(`c:read:${row.turnId}`, 6, fmtTokens(row.read), 'green')}
                {cell(`c:wrote:${row.turnId}`, 6, fmtTokens(row.write), 'yellow')}
                {cell(`c:new:${row.turnId}`, 5, fmtTokens(row.fresh), 'cyan')}
                {cell(`c:hit:${row.turnId}`, 4, `${pct}%`, hitColor(pct), true)}
              </Box>
            )
          })}
        </Box>

        <Box key="foot" marginTop={1} flexDirection="column">
          <Button key="close" label="close" onPress={() => {}} />
          <Box key="legend" marginTop={1} flexDirection="column">
            <Text color="green">{sp('■ read: served by the cache')}</Text>
            <Text color="yellow">{sp('■ wrote: new cache entry')}</Text>
            <Text color="cyan">{sp('■ new: sent uncached')}</Text>
          </Box>
        </Box>
      </Box>
    )
  })
}

// Run with: claude plugin test observability/prompt-cache-control
import { describe, expect, test } from 'claude-code/testing'
import {
  advise,
  lifeColor,
  segments,
  observeTtl,
  decideTtl,
  accountOf,
  nextToastMark,
  bar,
  byTurn,
  fmtClock,
  fmtTokens,
  hitRatio,
  idleCompactAt,
  idlePolicy,
  isCachingDisabled,
  missReason,
  remainingMs,
  resolveTtl,
} from '../hooks/cache.ts'
import type { Policy, Sample } from '../hooks/cache.ts'
import type { Engine } from 'claude-code/testing'
import type { On } from 'claude-code'

const T0 = 1_000_000_000_000
const policy: Policy = { ttl: '5m', warnMs: 60_000, compactAtTokens: 100_000 }

const sample = (over: Partial<Sample> = {}): Sample => ({
  turnId: 't1',
  index: 0,
  model: 'claude-sonnet-5-5',
  startedAt: T0,
  read: 80_000,
  write: 1_000,
  fresh: 500,
  output: 300,
  ...over,
})

describe('ttl and switches', () => {
  test('auto follows the environment; the option wins; FORCE_5M beats ENABLE_1H', () => {
    expect(resolveTtl('auto', {})).toBe('5m')
    expect(resolveTtl('auto', { enable1h: '1' })).toBe('1h')
    expect(resolveTtl('auto', { enable1h: '1', force5m: '1' })).toBe('5m')
    expect(resolveTtl('1h', { force5m: '1' })).toBe('1h')
    expect(resolveTtl(undefined, { enable1h: 'true' })).toBe('1h')
  })

  test('DISABLE_PROMPT_CACHING variants are per model family', () => {
    expect(isCachingDisabled('claude-opus-5-5', { disableAll: '1' })).toBe(true)
    expect(isCachingDisabled('claude-opus-5-5', { disableSonnet: '1' })).toBe(false)
    expect(isCachingDisabled('claude-sonnet-5-5', { disableSonnet: '1' })).toBe(true)
    expect(isCachingDisabled('claude-haiku-4-5', { disableHaiku: '1' })).toBe(true)
  })
})

describe('the countdown counts from the start of the request', () => {
  test('remaining time and expiry', () => {
    const s = sample()
    expect(remainingMs(s, '5m', T0 + 100_000)).toBe(200_000)
    expect(remainingMs(s, '1h', T0 + 100_000)).toBe(3_500_000)
    expect(remainingMs(s, '5m', T0 + 400_000)).toBe(0)
  })

  test('a request that touched no cache has no countdown', () => {
    expect(remainingMs(sample({ read: 0, write: 0 }), '5m', T0 + 1000)).toBe(0)
  })

  test('formatting', () => {
    expect(fmtClock(200_000)).toBe('3:20')
    expect(fmtClock(3_500_000)).toBe('58:20')
    expect(fmtClock(3_600_000)).toBe('1:00:00')
    expect(fmtClock(1)).toBe('0:01')
    expect(fmtTokens(950)).toBe('950')
    expect(fmtTokens(84_200)).toBe('84.2k')
    expect(fmtTokens(182_000)).toBe('182k')
    expect(fmtTokens(1_200_000)).toBe('1.2M')
    expect(bar(0.5, 10)).toBe('█████░░░░░')
    expect(Math.round(hitRatio(sample()) * 1000)).toBe(982)
  })
})

describe('advice', () => {
  test('warm, then soon, then expired', () => {
    const s = sample()
    expect(advise(s, undefined, policy, T0 + 10_000, false).kind).toBe('warm')
    expect(advise(s, undefined, policy, T0 + 250_000, false).kind).toBe('soon')
    expect(advise(s, undefined, policy, T0 + 300_000, false).kind).toBe('expired')
  })

  test('an expired large context suggests /compact, a small one says keep going', () => {
    const big = advise(sample({ read: 150_000 }), undefined, policy, T0 + 400_000, false)
    expect(big.text).toContain('/compact')
    const small = advise(sample({ read: 5_000, write: 100, fresh: 50 }), undefined, policy, T0 + 400_000, false)
    expect(small.text).toContain('keep going')
    expect(small.text).not.toContain('/compact')
  })

  test('the 1h cache stays warm where the 5m one has lapsed', () => {
    const s = sample()
    expect(advise(s, undefined, { ...policy, ttl: '1h' }, T0 + 1_000_000, false).kind).toBe('warm')
  })

  test('off, cold and uncached', () => {
    expect(advise(sample(), undefined, policy, T0, true).kind).toBe('off')
    expect(advise(undefined, undefined, policy, T0, false).kind).toBe('cold')
    expect(advise(sample({ read: 0, write: 0, fresh: 900 }), undefined, policy, T0, false).kind).toBe('uncached')
  })
})

describe('misses', () => {
  const prev = sample({ read: 50_000, write: 1_000, fresh: 200 })

  test('names the cause', () => {
    const wrote = { read: 0, write: 52_000, fresh: 300 }
    expect(missReason(prev, sample({ ...wrote, model: 'claude-opus-5-5', startedAt: T0 + 20_000 }), '5m')).toContain('model changed')
    expect(missReason(prev, sample({ ...wrote, startedAt: T0 + 400_000 }), '5m')).toContain('had lapsed')
    expect(missReason(prev, sample({ ...wrote, startedAt: T0 + 20_000 }), '5m')).toContain('prefix changed')
  })

  test('a hit, a first request and a /compact are not misses', () => {
    expect(missReason(prev, sample({ read: 51_000, write: 400, fresh: 100 }), '5m')).toBeUndefined()
    expect(missReason(undefined, sample(), '5m')).toBeUndefined()
    expect(missReason(prev, sample({ read: 0, write: 8_000, fresh: 100 }), '5m')).toBeUndefined()
  })

  test('advise reports a miss while the entry is still live', () => {
    const cur = sample({ read: 0, write: 52_000, fresh: 300, startedAt: T0 + 20_000 })
    const a = advise(cur, prev, policy, T0 + 30_000, false)
    expect(a.kind).toBe('miss')
    expect(a.text).toContain('prefix changed')
  })
})

describe('per-turn rows', () => {
  test('requests of one turn are summed', () => {
    const rows = byTurn([
      sample({ turnId: 'a', index: 0, read: 10, write: 5, fresh: 1 }),
      sample({ turnId: 'a', index: 1, read: 15, write: 0, fresh: 2 }),
      sample({ turnId: 'b', index: 0, read: 20, write: 0, fresh: 3 }),
    ])
    expect(rows.length).toBe(2)
    expect(rows[0]).toEqual(expect.objectContaining({ turnId: 'a', steps: 2, read: 25, write: 5, fresh: 3 }))
    expect(rows[1].steps).toBe(1)
  })
})

// The module end to end: a main-loop request feeds the band, a subagent's does not.
type Calls = { status: (string | undefined)[]; logs: string[]; toasts?: string[] }

function fakeEngine(
  on: On,
  env: Record<string, string>,
  calls: Calls,
  cache = { read: 80_000, write: 1_000 },
  limits: { kind: string; percentUsed: number }[] = [],
  files: Record<string, string> = {},
) {
  on('fs.read', ($, e) => {
    const text = files[e.path]
    if (text === undefined) throw new Error(`ENOENT ${e.path}`)
    return { value: text }
  })
  on('session.compact', async ($, e) => ({ messages: [{ role: 'user', text: 'summary', toolUses: [], toolResults: [] }], tokensBefore: 240_000, tokensAfter: 30_000 }) as never)
  on('session.usage', () => ({ value: { startedAt: 0, context: {}, rateLimits: limits } }) as never)
  on('session.start', async ($, e) => ({ cwd: e.cwd }) as never)
  on('session.end', async () => ({ sessionId: 's1' }) as never)
  on('env.get', ($, e) => ({ value: env[e.name] }))
  on('command.register', () => ({ value: undefined }) as never)
  on('clock.every', () => ({ value: undefined }) as never)
  on('ui.open', () => ({ value: undefined }) as never)
  on('ui.close', () => ({ value: undefined }) as never)
  on('ui.invalidate', () => ({ value: undefined }) as never)
  on('ui.toast', ($, e) => {
    calls.toasts?.push(String((e as { text: unknown }).text))
    return { value: undefined }
  })
  // what the plugins beneath draw above the prompt (another mod's band)
  on('ui.render', ($, e) => {
    const { Text } = $.ui.resolve(e)
    return <Text>beneath</Text>
  })
  on('ui.log', ($, e) => {
    calls.logs.push(String((e as { text: unknown }).text))
    return { value: undefined }
  })
  on('ui.status', ($, e) => {
    calls.status.push((e as { text?: string }).text)
    return { value: undefined }
  })
  on('turn.step', async function* ($, e) {
    return {
      turnId: e.turnId,
      index: e.index,
      answer: '',
      toolUses: [],
      stopReason: 'end_turn',
      usage: { model: 'claude-sonnet-5-5', input_tokens: 300, output_tokens: 50, cache_read_input_tokens: cache.read, cache_creation_input_tokens: cache.write },
    } as never
  })
}

async function step($: Engine, over: { turnId?: string; index?: number; agentId?: string } = {}) {
  const stream = $.turn.step({ turnId: 't1', index: 0, model: 'claude-sonnet-5-5', messageCount: 3, ...over } as never)
  for (;;) {
    const n = await stream.next()
    if (n.done) return n.value
  }
}

const BAND = { hasSurvey: false } as never
const band = ($: Engine) => $.ui.mount({ plugin: 'prompt-cache-control', surface: 'terminal', component: 'AbovePrompt', props: BAND })

describe('the band', () => {
  test('shows nothing before the first request, then the hit rate and the countdown', { options: { status: true } }, async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, {}, calls)
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)

    expect(calls.status).toEqual([])
    await step($)
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /98%/ })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: /read 80k/ })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: /wrote 1k/ })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: /new 300/ })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: /5m · warm/ })).toBeDefined()
    // ours first, what the plugins beneath drew under it
    const texts = (await ui.findAll({ type: 'Text', text: /98%|beneath/ })).map(t => t.text)
    expect(texts.at(-1)).toBe('beneath')
    expect(texts.slice(0, -1).some(t => /98%/.test(t))).toBe(true)
    await ui.unmount()
    expect(calls.status.at(-1)).toMatch(/^cache 98% · [45]:\d\d$/)
  })

  test('a subagent request is not the main loop and leaves the meter alone', { options: { status: true } }, async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, {}, calls)
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    await step($, { agentId: 'agent-1' })
    expect(calls.status.filter(t => t?.includes('%'))).toEqual([])
    await step($)
    expect(calls.status.filter(t => t?.includes('%')).length).toBe(1)
  })

  test('ENABLE_PROMPT_CACHING_1H makes the lifetime an hour; the option beats the environment', async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, { ENABLE_PROMPT_CACHING_1H: '1' }, calls)
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    expect(calls.logs.join('\n')).toContain('1h cache (ENABLE_PROMPT_CACHING_1H)')
    await step($)
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /1h · warm/ })).toBeDefined()
    await ui.unmount()
  })

  test('a Claude subscription defaults to an hour, usage credits to five minutes', async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, {}, calls, undefined, [{ kind: 'five_hour', percentUsed: 12 }])
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    expect(calls.logs.join('\n')).toContain('1h cache (Claude subscription default)')
  })

  test('CLAUDE_CODE_PROMPT_CACHE_TTL beats the subscription default', async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, { CLAUDE_CODE_PROMPT_CACHE_TTL: '5m' }, calls, undefined, [{ kind: 'five_hour', percentUsed: 12 }])
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    expect(calls.logs.join('\n')).toContain('5m cache (CLAUDE_CODE_PROMPT_CACHE_TTL)')
  })

  test('the ttl option beats the environment', { options: { ttl: '5m' } }, async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, { ENABLE_PROMPT_CACHING_1H: '1' }, calls)
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    expect(calls.logs.join('\n')).toContain('5m cache (the ttl option)')
  })

  test('a request that touched no cache shows no countdown', async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, {}, calls, { read: 0, write: 0 })
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    await step($)
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /not cached/ })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: /⏱/ })).toBeUndefined()
    await ui.unmount()
  })

  test('DISABLE_PROMPT_CACHING says so instead of a countdown', async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, { DISABLE_PROMPT_CACHING: '1' }, calls)
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /prompt caching is off/ })).toBeDefined()
    await ui.unmount()

    // after a request the band still shows no countdown
    await step($)
    const after = await band($)
    expect(await after.find({ type: 'Text', text: /⏱/ })).toBeUndefined()
    await after.unmount()
  })
})

describe('pane helpers', () => {
  test('the countdown is green, then yellow below 40%, then red from the warning threshold', () => {
    expect(lifeColor(250_000, '5m', 60_000)).toBe('green')
    expect(lifeColor(110_000, '5m', 60_000)).toBe('yellow')
    expect(lifeColor(60_000, '5m', 60_000)).toBe('red')
    expect(lifeColor(5_000, '1h', 60_000)).toBe('red')
    expect(lifeColor(1_800_000, '1h', 60_000)).toBe('green')
  })
  test('segments sum to the width and keep small parts visible', () => {
    const s = segments(113_000, 4_000, 2, 48)
    expect(s[0] + s[1] + s[2]).toBe(48)
    expect(s[2]).toBeGreaterThanOrEqual(1)
    expect(segments(0, 0, 0, 48)).toEqual([0, 0, 0])
  })
})

describe('countdown toasts', () => {
  test('fires at the threshold, then 10, 3, 2 and 1 seconds, once each', () => {
    let level = Infinity
    const fired: number[] = []
    for (let secs = 70; secs >= 1; secs--) {
      const m = nextToastMark(secs, 60, level)
      if (m !== undefined) {
        fired.push(secs)
        level = m
      }
    }
    expect(fired).toEqual([60, 10, 3, 2, 1])
  })
  test('a stalled clock skips to the newest mark; a short warning drops the early ones', () => {
    expect(nextToastMark(2, 60, Infinity)).toBe(2)
    expect(nextToastMark(2, 60, 2)).toBeUndefined()
    expect(nextToastMark(5, 5, Infinity)).toBe(5)
    expect(nextToastMark(30, 5, Infinity)).toBeUndefined()
  })
})

describe('observed lifetime', () => {
  const prev = sample({ startedAt: T0 })
  const MIN = 60_000
  test('a hit more than 5 minutes later proves the 1-hour lifetime and sticks', () => {
    const hit = sample({ startedAt: T0 + 20 * MIN, read: 80_000, write: 500 })
    expect(observeTtl(prev, hit, undefined)).toBe('1h')
    const miss = sample({ startedAt: T0 + 40 * MIN, read: 0, write: 81_000 })
    expect(observeTtl(hit, miss, '1h')).toBe('1h')
  })
  test('a miss 5 minutes to an hour later says 5 minutes; a later hit overrules it', () => {
    const miss = sample({ startedAt: T0 + 7 * MIN, read: 0, write: 81_000 })
    expect(observeTtl(prev, miss, undefined)).toBe('5m')
    const hit = sample({ startedAt: T0 + 20 * MIN, read: 80_000, write: 500 })
    expect(observeTtl(miss, hit, '5m')).toBe('1h')
  })
  test('says nothing inside 5 minutes, across a model change, after /compact, or when nothing was cached', () => {
    expect(observeTtl(prev, sample({ startedAt: T0 + 2 * MIN, read: 0, write: 81_000 }), undefined)).toBeUndefined()
    expect(observeTtl(prev, sample({ startedAt: T0 + 20 * MIN, model: 'claude-opus-5-5', read: 0, write: 81_000 }), undefined)).toBeUndefined()
    expect(observeTtl(prev, sample({ startedAt: T0 + 20 * MIN, read: 0, write: 5_000, fresh: 100 }), undefined)).toBeUndefined()
    expect(observeTtl(sample({ read: 0, write: 0 }), sample({ startedAt: T0 + 20 * MIN }), undefined)).toBeUndefined()
    expect(observeTtl(prev, sample({ startedAt: T0 + 2 * MIN, read: 80_000 }), undefined)).toBeUndefined()
  })
})

describe('which lifetime Claude Code asks for', () => {
  test('follows the documented order: force 5m, CLAUDE_CODE_PROMPT_CACHE_TTL, setting, ENABLE_1H, account', () => {
    expect(decideTtl('auto', { force5m: '1', ttlVar: '1h' }, '1h', 'subscription').ttl).toBe('5m')
    expect(decideTtl('auto', { ttlVar: '5m', enable1h: '1' }, '1h', 'subscription')).toEqual({ ttl: '5m', source: 'CLAUDE_CODE_PROMPT_CACHE_TTL' })
    expect(decideTtl('auto', { enable1h: '1' }, '5m', 'other')).toEqual({ ttl: '5m', source: 'the promptCacheTtl setting' })
    expect(decideTtl('auto', { enable1h: '1' }, undefined, 'other').ttl).toBe('1h')
    expect(decideTtl('auto', {}, 'junk', 'subscription')).toEqual({ ttl: '1h', source: 'Claude subscription default' })
    expect(decideTtl('auto', {}, undefined, 'credits').ttl).toBe('5m')
    expect(decideTtl('auto', {}, undefined, 'other').ttl).toBe('5m')
    expect(decideTtl('1h', { force5m: '1' }, '5m', 'other').ttl).toBe('1h')
  })
  test('the account comes from the plan windows the last response reported', () => {
    expect(accountOf([])).toBe('other')
    expect(accountOf([{ kind: 'spend_limit', percentUsed: 10 }])).toBe('other')
    expect(accountOf([{ kind: 'five_hour', percentUsed: 20 }, { kind: 'seven_day', percentUsed: 5 }])).toBe('subscription')
    expect(accountOf([{ kind: 'five_hour', percentUsed: 100 }])).toBe('credits')
  })
})

describe('idle compaction', () => {
  const ON = { mode: 'compact' }
  test('200k by default, never under 100k, the variable beats the flag', () => {
    expect(idlePolicy({ flag: ON })).toEqual(expect.objectContaining({ on: true, known: true, minTokens: 200_000, fraction: 0.9 }))
    expect(idlePolicy({ flag: ON, minTokensVar: '50000' }).minTokens).toBe(100_000)
    expect(idlePolicy({ flag: { ...ON, minTokens: 150_000 }, minTokensVar: '120000' }).minTokens).toBe(120_000)
    expect(idlePolicy({ flag: { ...ON, minTokens: 150_000 } }).minTokens).toBe(150_000)
    expect(idlePolicy({ flag: { ...ON, fireAtFraction: 0.99 } }).fraction).toBe(0.95)
  })
  test('off: rollout flag off or log-only, the setting, auto-compact off', () => {
    expect(idlePolicy({ flag: { mode: 'off' } })).toEqual(expect.objectContaining({ on: false, why: expect.stringMatching(/not rolled out/) }))
    expect(idlePolicy({ flag: { mode: 'log' } }).on).toBe(false)
    expect(idlePolicy({ flag: ON, setting: false }).why).toMatch(/idleCompaction: false/)
    expect(idlePolicy({ flag: ON, autoCompact: false }).on).toBe(false)
    expect(idlePolicy({ flag: ON, disableAuto: '1' }).on).toBe(false)
    expect(idlePolicy({ flag: ON, setting: true }).on).toBe(true)
  })
  test('no cached flag means no countdown', () => {
    expect(idlePolicy({})).toEqual(expect.objectContaining({ on: false, known: false, why: expect.stringMatching(/flag not found/) }))
  })
  test('fires at 90% of a warm 1h cache, only from the threshold up', () => {
    const big = sample({ read: 230_000 })
    const pol = idlePolicy({ flag: ON })
    expect(idleCompactAt(big, '1h', pol, T0 + 1000)).toBe(T0 + 3_240_000)
    expect(idleCompactAt(big, '5m', pol, T0 + 1000)).toBeUndefined()
    expect(idleCompactAt(sample(), '1h', pol, T0 + 1000)).toBeUndefined()
    expect(idleCompactAt(big, '1h', pol, T0 + 3_700_000)).toBeUndefined()
    expect(idleCompactAt(big, '1h', idlePolicy({ flag: { mode: 'off' } }), T0)).toBeUndefined()
  })

  const config = (flag: unknown) => ({ '/home/me/.claude.json': JSON.stringify({ cachedGrowthBookFeatures: { tengu_sunny_locket: flag } }) })
  const ENV = { HOME: '/home/me', ENABLE_PROMPT_CACHING_1H: '1' }

  test('the band counts down to the idle compaction of a large 1h conversation', async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, ENV, calls, { read: 230_000, write: 1_000 }, [], config(ON))
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    expect(calls.logs.join('\n')).toContain('idle compaction on')
    await step($)
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /^⇣ 5[34]:\d\d$/ })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: /beneath/ })).toBeDefined()
    await ui.unmount()
  })

  test('no idle countdown when the account has not got it', async ($, on) => {
    const calls: Calls = { status: [], logs: [] }
    fakeEngine(on, ENV, calls, { read: 230_000, write: 1_000 }, [], config({ mode: 'off' }))
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    expect(calls.logs.join('\n')).toContain('not rolled out')
    await step($)
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /⇣/ })).toBeUndefined()
    await ui.unmount()
  })

  test('an idle compaction is announced and the band stops counting down the old cache', async ($, on) => {
    const calls: Calls = { status: [], logs: [], toasts: [] }
    fakeEngine(on, ENV, calls, { read: 230_000, write: 1_000 }, [], config(ON))
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    await step($)
    await new Promise(r => setTimeout(r, 5))
    await $.session.compact({ trigger: 'idle', messages: [{ role: 'user', text: 'old', toolUses: [], toolResults: [] }] } as never)
    expect(calls.toasts?.join('\n')).toMatch(/compacted while idle 240k → 30k tokens/)
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /compacted while idle/ })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: /⏱ \d/ })).toBeUndefined()
    await ui.unmount()
  })

  test('a precompute or a subagent compaction changes nothing', async ($, on) => {
    const calls: Calls = { status: [], logs: [], toasts: [] }
    fakeEngine(on, ENV, calls, { read: 230_000, write: 1_000 }, [], config(ON))
    await $.session.start({ cwd: '/repo', surface: 'terminal', isInteractive: true } as never)
    await step($)
    await $.session.compact({ trigger: 'precompute', messages: [{ role: 'user', text: 'old', toolUses: [], toolResults: [] }] } as never)
    await $.session.compact({ trigger: 'auto', agentId: 'a1', messages: [{ role: 'user', text: 'old', toolUses: [], toolResults: [] }] } as never)
    expect(calls.toasts).toEqual([])
    const ui = await band($)
    expect(await ui.find({ type: 'Text', text: /^⇣ / })).toBeDefined()
    await ui.unmount()
  })
})

