{
  "description": "Picks the model and the reasoning effort for each task with TypeSafe's Jev, through TypeSafe's own API or the Vercel AI Gateway, in both directions: agent.spawn for subagent models, prompt.submit + turn.step for the main loop's effort and model.",
  "modules": [
    "./jev-model-router.ts"
  ]
}

/**
 * jev-model-router — Claude Mod
 *
 * Picks the model each task runs on with TypeSafe's Jev, a System One
 * decision model: unstructured state in, a typed choice with a probability
 * distribution out.
 *
 * Jev is reached one of two ways, whichever key is configured: TypeSafe's
 * own API (`typesafeApiKey`), which reports a calibrated confidence per
 * answer, or the Vercel AI Gateway (`gatewayApiKey`), which does not. With
 * neither, the engine's own `$.model.classify` stands in, so the mod is
 * useful without any account.
 *
 * Three things it can set, each on its own switch:
 *   agent.spawn  — the model of each subagent (on by default)
 *   turn.step    — the reasoning effort of the main loop (on by default)
 *   turn.step    — the model of the main loop (off by default: switching
 *                  models mid-session invalidates the prompt cache, which can
 *                  cost more than the cheaper tier saves)
 *
 * Every one of them moves in both directions: a task the decision model reads
 * as mechanical is routed down, one it reads as hard is routed up. The two
 * mistakes do not cost the same, so they do not clear the same confidence bar
 * (see `minUpgradeConfidence` / `minDowngradeConfidence` in policy.ts).
 *
 * The Agent tool has no effort parameter, so a subagent's effort is not ours
 * to set; only its model is.
 *
 * The prompt is classified at `prompt.submit`, which runs before the turn
 * starts, and the decision is applied at the turn's first request.
 *
 * Every failure path is fail-open: a classification that errors or runs past
 * the latency budget leaves the request exactly as the engine built it.
 *
 * The API key comes from the plugin's options (userConfig "typesafeApiKey"
 * or "gatewayApiKey"). Never hardcode it in this file.
 *
 * Needs Claude Code >= 2.1.287. Typed
 * against Anthropic's declarations: https://github.com/anthropics/claude-code/tree/main/mods
 *
 * Privacy: with a key set, the prompt text is sent to whichever backend the
 * key belongs to.
 */
import type { Register } from 'claude-code'
import {
  DEFAULT_BASE_URL,
  DEFAULT_MODEL,
  describeDecision,
  describeSetup,
  describeStatus,
  endpoint,
  pendingDecisions,
  readDecision,
  selectProvider,
  requestBody,
  requestHeaders,
  requestModelId,
  route,
  TIER_ORDER,
  bareCommand,
} from './policy.ts'
import type { Decision, Effort, PolicyConfig, Provider, Tier } from './policy.ts'

export const register: Register = (on, options) => {
  const text = (key: string, fallback: string) =>
    typeof options[key] === 'string' && options[key] ? (options[key] as string) : fallback
  const number = (key: string, fallback: number) =>
    typeof options[key] === 'number' ? (options[key] as number) : fallback
  const flag = (key: string, fallback: boolean) =>
    typeof options[key] === 'boolean' ? (options[key] as boolean) : fallback

  // TypeSafe's own API is preferred when both keys are set: it is the only
  // one that reports a calibrated confidence, which the policy's threshold
  // reads. `provider` forces one, including "builtin" to use neither.
  const typesafeKey = text('typesafeApiKey', '')
  const gatewayKey = text('gatewayApiKey', '')
  const forced = text('provider', 'auto')
  const active: Provider | null = selectProvider(forced, typesafeKey, gatewayKey)

  // Each backend keeps its own URL and model, so an override written for one
  // can never be sent to the other when `auto` picks differently than expected.
  const apiKey = active === 'typesafe' ? typesafeKey : active === 'gateway' ? gatewayKey : ''
  const modelId = !active
    ? ''
    : active === 'typesafe'
      ? text('typesafeModel', DEFAULT_MODEL.typesafe)
      : text('gatewayModel', DEFAULT_MODEL.gateway)
  const url = !active
    ? ''
    : active === 'typesafe'
      ? endpoint('typesafe', text('typesafeBaseUrl', DEFAULT_BASE_URL.typesafe))
      : endpoint('gateway', text('gatewayBaseUrl', DEFAULT_BASE_URL.gateway))

  // A backend named in the options but missing its key degrades to the
  // built-in classifier, which is silent; say so once, when a hook first runs.
  let unusableReported = forced === 'auto' || forced === 'builtin' || active !== null

  const timeoutMs = number('timeoutMs', 800)
  const routeSubagentModel = flag('routeSubagentModel', true)
  const routeMainEffort = flag('routeMainEffort', true)
  const routeMainModel = flag('routeMainModel', false)
  const routeMainLoop = routeMainEffort || routeMainModel
  const logDecisions = flag('logDecisions', true)

  const policy: PolicyConfig = {
    tiers: {
      fast: text('fastModel', 'haiku'),
      balanced: text('balancedModel', 'sonnet'),
      deep: text('deepModel', 'opus'),
    },
    minUpgradeConfidence: number('minUpgradeConfidence', 0.3),
    minDowngradeConfidence: number('minDowngradeConfidence', 0.6),
  }

  // The classification waiting for the turn that reads its prompt, and what
  // the current turn settled on. Both are single slots: main-loop turns run
  // one at a time, so nothing accumulates over a long session. `pending`
  // reports no decision when two prompts are waiting at once, rather than
  // routing a turn on a decision made for a different prompt.
  const pending = pendingDecisions()
  // Said once, the first time a hook runs. A router that loaded and one that
  // never loaded are otherwise told apart only by the absence of later lines,
  // and absence is not evidence: the policy leaves most turns alone anyway.
  let announced = false
  let appliedTurnId: string | undefined
  let applied: { model?: string; effort?: Effort } | null = null

  on('prompt.submit', async ($, e, next) => {
    // Before the routing guards: a module whose switches are all off has still
    // loaded, and that is exactly when its silence is most misleading.
    if (!announced) {
      announced = true
      if (logDecisions) {
        $.ui.log(
          `[jev-model-router] ${describeSetup(
            active,
            url,
            {
              subagentModel: routeSubagentModel,
              mainEffort: routeMainEffort,
              mainModel: routeMainModel,
            },
            forced === 'builtin',
          )}`,
        )
      }
    }
    if (!routeMainLoop) return next(e)

    if (!unusableReported) {
      unusableReported = true
      $.ui.log(`[jev-model-router] provider "${forced}" has no key set; using the built-in classifier`)
    }

    // A slash command alone gives the decision model only the command's name.
    // Its turn keeps the session's model and effort; the null put keeps a
    // previous prompt's decision from reaching it.
    if (bareCommand(e.text)) {
      if (logDecisions) $.ui.log('[jev-model-router] a command with nothing after it; leaving the turn alone')
      pending.put(null)
      return next(e)
    }

    const startedAt = await $.clock.now()
    let decision: Decision | null = null
    if (active) {
      try {
        const response = await Promise.race([
          $.http.fetch(url, {
            method: 'POST',
            headers: requestHeaders(active, apiKey, modelId),
            body: requestBody(active, { prompt: e.text }, modelId),
          }),
          $.clock.sleep(timeoutMs),
        ])
        if (response && response.ok) decision = readDecision(response.text)
        else if (response) $.ui.log(`[jev-model-router] ${active} responded ${response.status}`)
        else $.ui.log(`[jev-model-router] classification passed ${timeoutMs}ms; leaving the turn alone`)
      } catch (error) {
        $.ui.log(`[jev-model-router] classification failed: ${String(error)}`)
      }
    } else {
      // No backend: the engine's own small-model classifier answers the same
      // question, without the confidence the policy's threshold reads.
      try {
        const label = await $.model.classify(e.text, TIER_ORDER)
        if (label) {
          decision = {
            tier: label as Tier,
            confidence: null,
            risky: null,
            effort: null,
            effortConfidence: null,
          }
        }
      } catch (error) {
        $.ui.log(`[jev-model-router] built-in classifier failed: ${String(error)}`)
      }
    }

    // What the decision model actually answered, whatever the policy then
    // does with it. This is the line that proves the classification ran.
    if (logDecisions) {
      const ms = (await $.clock.now()) - startedAt
      $.ui.log(`[jev-model-router] jev: ${describeDecision(decision, ms)}`)
    }

    pending.put(decision)
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (!routeMainLoop || e.agentId) return yield* next(e)

    // Every request after the first reuses what the turn settled on, so
    // neither the model nor the effort changes under its own tool loop.
    if (e.index > 0 && e.turnId === appliedTurnId) {
      return yield* next(applied ? { ...e, ...applied } : e)
    }

    const decision = pending.take()
    const routing = route(decision, { model: e.model, effort: e.effort }, policy)
    const change: { model?: string; effort?: Effort } = {}
    // The main loop's `model` is sent to the API as written, so an alias
    // becomes its id here; a subagent's (agent.spawn) may stay an alias.
    if (routeMainModel && routing.model) change.model = requestModelId(routing.model)
    if (routeMainEffort && routing.effort) change.effort = routing.effort

    appliedTurnId = e.turnId
    applied = Object.keys(change).length > 0 ? change : null
    // A row in the transcript scrolls away; this line stays on screen.
    if (logDecisions) $.ui.status(describeStatus(decision, applied))

    if (!applied) {
      // A turn left alone is the common case, and it used to be silent, which
      // made a working mod look like one that never loaded. Say what happened.
      if (logDecisions) {
        const suppressed = routing.model && !routeMainModel ? ' (main-loop model routing off)' : ''
        $.ui.log(`[jev-model-router] main loop: ${routing.reason}${suppressed}`)
      }
      return yield* next(e)
    }
    if (logDecisions) {
      const what = [change.model, change.effort && `effort ${change.effort}`]
        .filter(Boolean)
        .join(', ')
      $.ui.log(`[jev-model-router] main loop → ${what}: ${routing.reason}`)
    }
    return yield* next({ ...e, ...change })
  })

  on('agent.spawn', async ($, e, next) => {
    // Before the routing guards: a module whose switches are all off has still
    // loaded, and that is exactly when its silence is most misleading.
    if (!announced) {
      announced = true
      if (logDecisions) {
        $.ui.log(
          `[jev-model-router] ${describeSetup(
            active,
            url,
            {
              subagentModel: routeSubagentModel,
              mainEffort: routeMainEffort,
              mainModel: routeMainModel,
            },
            forced === 'builtin',
          )}`,
        )
      }
    }

    // A fork inherits its parent's model; `model` is ignored for it. A resumed
    // agent keeps the model it started on (2.1.299: a hook can only refuse a
    // resume), and its `prompt` is the resuming message, not the task. A
    // workflow agent is routed like any other: its `model` rewrite applies
    // since 2.1.300.
    if (!routeSubagentModel || e.fork || e.resume) return next(e)

    if (!unusableReported) {
      unusableReported = true
      $.ui.log(`[jev-model-router] provider "${forced}" has no key set; using the built-in classifier`)
    }

    const startedAt = await $.clock.now()
    let decision: Decision | null = null
    if (active) {
      try {
        const response = await Promise.race([
          $.http.fetch(url, {
            method: 'POST',
            headers: requestHeaders(active, apiKey, modelId),
            body: requestBody(
              active,
              { prompt: e.prompt, description: e.description, agentType: e.subagentType },
              modelId,
            ),
          }),
          $.clock.sleep(timeoutMs),
        ])
        if (response && response.ok) decision = readDecision(response.text)
        else if (response) $.ui.log(`[jev-model-router] ${active} responded ${response.status}`)
        else $.ui.log(`[jev-model-router] classification passed ${timeoutMs}ms; leaving the subagent alone`)
      } catch (error) {
        $.ui.log(`[jev-model-router] classification failed: ${String(error)}`)
      }
    } else {
      try {
        const label = await $.model.classify(e.prompt, TIER_ORDER)
        if (label) {
          decision = {
            tier: label as Tier,
            confidence: null,
            risky: null,
            effort: null,
            effortConfidence: null,
          }
        }
      } catch (error) {
        $.ui.log(`[jev-model-router] built-in classifier failed: ${String(error)}`)
      }
    }

    if (logDecisions) {
      const ms = (await $.clock.now()) - startedAt
      $.ui.log(`[jev-model-router] jev (${e.subagentType}): ${describeDecision(decision, ms)}`)
    }

    // The subagent's own model wins when the caller named one; otherwise it
    // would inherit the parent's, so that is what a change is measured from.
    // The Agent tool takes no effort, so only the model is ours to set here.
    const current = e.model ?? e.parentModel
    const { model, reason } = route(decision, { model: current }, policy)
    if (!model) {
      if (logDecisions) $.ui.log(`[jev-model-router] ${e.subagentType}: ${reason}`)
      return next(e)
    }
    if (logDecisions) $.ui.log(`[jev-model-router] ${e.subagentType} → ${model}: ${reason}`)
    return next({ ...e, model })
  })
}

/**
 * jev-model-router — pure decision logic.
 *
 * No `$` and no I/O here: this module only builds the request the decision
 * API takes, reads its answer, and turns that answer into a model id. The
 * hooks module does every call on `$` at its own call site.
 *
 * Two backends speak to the same model with different wire shapes:
 *
 *   typesafe  POST https://api.typesafe.ai/v1/systemone
 *             `{ model, state, questions }`; a yes/no question is a `noul`
 *             and every answer carries its own `confidence`.
 *   gateway   POST https://ai-gateway.vercel.sh/v4/ai/evaluation-model
 *             `{ state, questions }` with the model in a header; a yes/no
 *             question is a `boolean`, and there is no `confidence` field —
 *             it has to be derived from an optional distribution.
 *
 * The Gateway shape is not documented publicly; it was read from
 * @ai-sdk/gateway and @ai-sdk/provider.
 */

export type Provider = 'typesafe' | 'gateway'

export type Tier = 'fast' | 'balanced' | 'deep'

export interface Tiers {
  fast: string
  balanced: string
  deep: string
}

export interface Decision {
  tier: Tier
  /** Confidence in the tier, or null when the backend reported none. */
  confidence: number | null
  /** P(true) that carrying the task out would itself be costly or final. */
  risky: number | null
  /** 0..3 along the effort rubric, or null when absent. */
  effort: number | null
  /** Confidence in the effort, or null when the backend reported none. */
  effortConfidence: number | null
}

/** The reasoning levels a turn can ask for, cheapest first. */
export const EFFORT_ORDER = ['low', 'medium', 'high', 'xhigh'] as const

export type Effort = (typeof EFFORT_ORDER)[number]

export const TIER_ORDER: readonly Tier[] = ['fast', 'balanced', 'deep']

/**
 * How each tier is described to the decision model. Deliberately about the
 * shape of the work, not about model names: the model never sees an id.
 */
const TIER_CRITERIA: Record<Tier, string> = {
  fast: 'Mechanical and local: read or summarise a file, run one command, rename a symbol, answer something already in context.',
  balanced:
    'Ordinary engineering: implement a well-specified change across a few files, write tests, fix a clearly described bug, review a small diff.',
  deep: 'Hard or high-stakes: architecture and design, debugging a failure whose cause is unknown, security, data migrations, concurrency, anything touching production or money.',
}

const EFFORT_RUBRIC = ['almost none', 'some', 'a lot', 'as much as possible'] as const

export const DEFAULT_BASE_URL: Record<Provider, string> = {
  typesafe: 'https://api.typesafe.ai',
  gateway: 'https://ai-gateway.vercel.sh/v4/ai',
}

/**
 * The Gateway's own protocol version, sent as `ai-gateway-protocol-version`.
 * Tracks the `AI_GATEWAY_PROTOCOL_VERSION` of `@ai-sdk/gateway` (4.0.87).
 */
const AI_GATEWAY_PROTOCOL_VERSION = '0.0.1'

export const DEFAULT_MODEL: Record<Provider, string> = {
  typesafe: 'jev-latest',
  gateway: 'typesafe-ai/jev',
}

/**
 * Which backend a configuration asks for, or null for the built-in
 * classifier. `auto` prefers TypeSafe, since it is the only one that reports
 * a calibrated confidence; a forced backend whose key is missing resolves to
 * null rather than falling through to the other one's key.
 */
export function selectProvider(
  forced: string,
  typesafeKey: string,
  gatewayKey: string,
): Provider | null {
  if (forced === 'builtin') return null
  if (forced === 'typesafe') return typesafeKey ? 'typesafe' : null
  if (forced === 'gateway') return gatewayKey ? 'gateway' : null
  if (typesafeKey) return 'typesafe'
  if (gatewayKey) return 'gateway'
  return null
}

/** The full endpoint a backend posts to. */
export function endpoint(provider: Provider, baseUrl: string): string {
  const root = baseUrl.replace(/\/+$/, '')
  return provider === 'typesafe' ? `${root}/v1/systemone` : `${root}/evaluation-model`
}

/** The `questions` map, in the shape the backend's schema names. */
export function questions(provider: Provider): Record<string, unknown> {
  return {
    tier: {
      type: 'choice',
      instructions: 'Which is the cheapest tier that can complete this coding task well?',
      criteria: TIER_CRITERIA,
    },
    effort: {
      type: 'score',
      instructions: 'How much step-by-step reasoning does this task need?',
      criteria: EFFORT_RUBRIC,
    },
    risky: {
      // The same question under two names: `noul` on TypeSafe's own API,
      // `boolean` in the AI SDK's evaluation schema.
      type: provider === 'typesafe' ? 'noul' : 'boolean',
      // Asked about the act, not the subject. The first wording ("the task
      // touches production, money, credentials") scored 0.96 on "add a
      // refund endpoint that calls Stripe" — ordinary code that happens to be
      // about money — and would have escalated it past a 0.98-confidence
      // answer of the balanced tier.
      instructions:
        'Carrying out this task would itself change production, move real money, or alter data that cannot be restored. Writing or testing code that deals with such things, without running it against the real system, does not count.',
    },
  }
}

/** The request body. The Gateway carries the model in a header instead. */
export function requestBody(
  provider: Provider,
  state: Record<string, unknown>,
  model: string,
): string {
  const body =
    provider === 'typesafe'
      ? { model, state, questions: questions(provider) }
      : { state, questions: questions(provider) }
  return JSON.stringify(body)
}

/** The request headers. */
export function requestHeaders(
  provider: Provider,
  apiKey: string,
  model: string,
): Record<string, string> {
  const common = { 'content-type': 'application/json', authorization: `Bearer ${apiKey}` }
  if (provider === 'typesafe') return common
  return {
    ...common,
    'ai-gateway-auth-method': 'api-key',
    'ai-model-id': model,
    // The Gateway rejects any request that does not name the protocol it
    // speaks: 400 "Unsupported gateway protocol version". Every other header
    // here is accepted without it, so the omission fails the whole backend.
    'ai-gateway-protocol-version': AI_GATEWAY_PROTOCOL_VERSION,
    'ai-evaluation-model-specification-version': '4',
  }
}

function isTier(value: unknown): value is Tier {
  return value === 'fast' || value === 'balanced' || value === 'deep'
}

/**
 * Reads a response from either backend.
 *
 * TypeSafe's own API reports a `confidence` per answer and a `noul` number
 * for a yes/no question. The Gateway reports neither: confidence has to come
 * from the highest probability of a distribution that is itself optional, and
 * a yes/no answer arrives as `probability`. Both are handled, and a missing
 * confidence reads as null rather than as a number the policy would trust.
 */
export function readDecision(responseText: string): Decision | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(responseText)
  } catch {
    return null
  }
  const answers = (parsed as { answers?: Record<string, Record<string, unknown>> }).answers
  if (!answers) return null

  const tierAnswer = answers.tier
  if (!tierAnswer || !isTier(tierAnswer.choice)) return null

  const effortAnswer = answers.effort
  const riskyAnswer = answers.risky
  const risky =
    typeof riskyAnswer?.noul === 'number'
      ? riskyAnswer.noul
      : typeof riskyAnswer?.probability === 'number'
        ? riskyAnswer.probability
        : null

  return {
    tier: tierAnswer.choice,
    confidence: confidenceOf(tierAnswer),
    effort: typeof effortAnswer?.score === 'number' ? effortAnswer.score : null,
    effortConfidence: effortAnswer ? confidenceOf(effortAnswer) : null,
    risky,
  }
}

/**
 * How sure an answer is. TypeSafe reports it; the Gateway does not, so there
 * it is the highest probability of a distribution that is itself optional.
 */
function confidenceOf(answer: Record<string, unknown>): number | null {
  if (typeof answer.confidence === 'number') return answer.confidence
  const probabilities = answer.probabilities as Record<string, number> | undefined
  const values = probabilities ? Object.values(probabilities) : []
  return values.length > 0 ? Math.max(...values) : null
}

/** The rubric score (0..3) as a reasoning level. */
export function effortLevel(score: number): Effort {
  const index = Math.min(EFFORT_ORDER.length - 1, Math.max(0, Math.round(score)))
  return EFFORT_ORDER[index] as Effort
}

/**
 * Where a reasoning level sits on the ladder, or null when its place cannot
 * be known. `max` is above every rung the rubric can produce, so it ranks
 * above them without joining EFFORT_ORDER, which is also the set of values
 * this router is allowed to ask for.
 */
export function effortRank(effort: string | number | undefined): number | null {
  if (typeof effort !== 'string') return null
  if (effort === 'max') return EFFORT_ORDER.length
  const index = EFFORT_ORDER.indexOf(effort as Effort)
  return index === -1 ? null : index
}

/**
 * Where a model id sits on the tier ladder, by matching it against the
 * configured tier names first and then the family words. Null when it matches
 * none, in which case the change is treated as an upgrade rather than guessed
 * at: an unrecognised id gets the gentler threshold, never the strict one.
 */
export function rankOf(model: string, tiers: Tiers): number | null {
  const lowered = model.toLowerCase()
  for (let index = 0; index < TIER_ORDER.length; index++) {
    const tier = TIER_ORDER[index] as Tier
    const configured = tiers[tier].toLowerCase()
    if (configured && lowered.includes(configured)) return index
  }
  if (lowered.includes('haiku')) return 0
  if (lowered.includes('sonnet')) return 1
  if (lowered.includes('opus')) return 2
  return null
}

/**
 * The full id a family alias names on the main loop.
 *
 * `agent.spawn` takes an alias (`haiku`) the way the Agent tool does, but
 * `turn.step`'s `model` is the id the engine already resolved for the request
 * and goes to the API as written: an alias there is refused ("There's an
 * issue with the selected model (haiku)"). So the tiers stay aliases in the
 * options, and only a main-loop rewrite resolves them, here.
 */
const ALIAS_IDS: Record<string, string> = {
  haiku: 'claude-haiku-4-5-20251001',
  sonnet: 'claude-sonnet-5',
  opus: 'claude-opus-5',
}

/**
 * What to write into `turn.step`'s `model`: a full id as given, or the id
 * behind a family alias. Anything else is returned unchanged for the engine
 * to judge.
 */
export function requestModelId(model: string): string {
  return ALIAS_IDS[model.trim().toLowerCase()] ?? model
}

export interface PolicyConfig {
  tiers: Tiers
  /**
   * How sure the decision must be to spend more (a bigger model, more
   * reasoning). Being wrong here costs money, so the bar is low.
   */
  minUpgradeConfidence: number
  /**
   * How sure it must be to spend less. Being wrong here means a task handled
   * by too small a model or too little thought, so the bar is high.
   */
  minDowngradeConfidence: number
}

export interface Routing {
  /** The model to run on, or null to leave the request as it is. */
  model: string | null
  /** The reasoning level to ask for, or null to leave it as it is. */
  effort: Effort | null
  /** Why, for the log line. */
  reason: string
}

const NOTHING: Routing = { model: null, effort: null, reason: 'no decision' }

/**
 * Whether a change of rank passes its threshold. Both directions are allowed;
 * they just do not have to clear the same bar, because the two mistakes do not
 * cost the same. A move whose direction cannot be told (an unrecognised
 * current value) is treated as an upgrade.
 */
function allowed(
  wanted: number,
  current: number | null,
  confidence: number | null,
  config: PolicyConfig,
): boolean {
  if (current !== null && wanted === current) return false
  const isDowngrade = current !== null && wanted < current
  const bar = isDowngrade ? config.minDowngradeConfidence : config.minUpgradeConfidence
  // A backend that reports no confidence (the Gateway without a distribution,
  // or the built-in classifier) clears the upgrade bar but never the
  // downgrade one: spending less on an unmeasured hunch is the bad trade.
  if (confidence === null) return !isDowngrade
  return confidence >= bar
}

/**
 * Turns a decision into a model and a reasoning level, either of which may be
 * null to leave the request as it is. Both can move in either direction.
 */
export function route(
  decision: Decision | null,
  current: { model: string; effort?: string | number },
  config: PolicyConfig,
): Routing {
  if (!decision) return NOTHING

  let tier = decision.tier
  let effortScore = decision.effort
  let forced = false

  // Carrying out something final is never worth the saving: take the deep
  // tier and real reasoning, whatever the cheaper answer said, and skip the
  // thresholds — this is the one case that is not a confidence question.
  if (decision.risky !== null && decision.risky > 0.7) {
    tier = 'deep'
    effortScore = Math.max(effortScore ?? 0, 2)
    forced = true
  }

  const wantedTier = TIER_ORDER.indexOf(tier)
  const currentTier = rankOf(current.model, config.tiers)
  const wantedModel = config.tiers[tier]

  const model =
    wantedModel &&
    wantedModel !== current.model &&
    (forced || allowed(wantedTier, currentTier, decision.confidence, config))
      ? wantedModel
      : null

  let effort: Effort | null = null
  if (effortScore !== null) {
    const currentRank = effortRank(current.effort)
    let wantedRank = EFFORT_ORDER.indexOf(effortLevel(effortScore))

    // Risk raises the floor; it must never lower one. Forcing only skips the
    // thresholds, so without this clamp a task already at `xhigh` or `max`
    // and rated mechanically simple would be pulled down to `high` with no
    // confidence check at all — the opposite of what the rule is for.
    if (forced && currentRank !== null) wantedRank = Math.max(wantedRank, currentRank)

    // A numeric effort is the caller's own scale, not this ladder; leave it.
    const comparable = typeof current.effort !== 'number'
    const wanted = EFFORT_ORDER[Math.min(EFFORT_ORDER.length - 1, wantedRank)] as Effort
    if (
      comparable &&
      wantedRank !== currentRank &&
      (forced || allowed(wantedRank, currentRank, decision.effortConfidence, config))
    ) {
      effort = wanted
    }
  }

  const said = decision.confidence === null ? 'confidence n/d' : `confidence ${decision.confidence.toFixed(2)}`

  if (!model && !effort) {
    // Naming what it wanted and what it kept is the whole point of this line.
    // Without it, a mod that classified and decided to leave the request alone
    // is indistinguishable from one that never loaded.
    const wantedEffort = effortScore === null ? null : effortLevel(effortScore)
    const kept = `${current.model}${current.effort === undefined ? '' : `/${current.effort}`}`
    const wanted = `${wantedModel}${wantedEffort ? `/${wantedEffort}` : ''}`
    return { model: null, effort: null, reason: `kept ${kept}, wanted ${wanted} (${said})` }
  }

  return { model, effort, reason: forced ? `${tier}, forced by risk` : `${tier} (${said})` }
}

/**
 * Whether a prompt is a slash command and nothing else (`/simplify`). The
 * decision model sees only the name, never the skill or command it runs:
 * measured on TypeSafe (three calls each), `/simplify`, `/run` and `/github`
 * came back fast with effort 0.1 to 0.5, low effort for a multi-step skill,
 * while `/code-review` and `/security-review` came back balanced and deep.
 * With text after the name there is a task to read, and it is classified.
 * A one-segment path alone (`/etc`) matches too; nobody sends one as a task.
 */
export function bareCommand(text: string): boolean {
  return /^\/[^\s/]+$/.test(text.trim())
}

/**
 * Holds a prompt's classification until the turn that reads that prompt
 * starts.
 *
 * Nothing ties a decision to the turn it belongs to. Prompts can be queued
 * while the model is busy, a peer session's message can be delivered inside a
 * running turn, and `prompt.submit` carries no turn id at all while the
 * session is idle. So when more than one prompt is waiting, `take` reports
 * none: running a turn on another prompt's decision is a worse outcome than
 * not routing it, and not routing is what every other failure path here does.
 */
export function pendingDecisions(): {
  put(decision: Decision | null): void
  take(): Decision | null
} {
  let held: Decision | null = null
  let waiting = 0

  return {
    put(decision) {
      waiting += 1
      // Past the first, which prompt a turn will read is unknowable, so the
      // slot is emptied instead of holding a decision that may not fit.
      held = waiting === 1 ? decision : null
    },
    take() {
      const decision = waiting === 1 ? held : null
      held = null
      waiting = 0
      return decision
    },
  }
}

/** A number for the log, or `n/d` when the backend reported none. */
function reported(value: number | null): string {
  return value === null ? 'n/d' : value.toFixed(2)
}

/**
 * The one-time line that says the router is alive, which backend answers it,
 * and which of the three switches are on.
 *
 * Without this, a router that loaded and a router that never loaded are told
 * apart only by the absence of later lines, which is not evidence of anything.
 */
export function describeSetup(
  provider: Provider | null,
  url: string,
  switches: { subagentModel: boolean; mainEffort: boolean; mainModel: boolean },
  // `provider: "builtin"` is a choice, not a missing key. Reporting it as a
  // credential problem sends someone hunting for a key they meant to omit.
  builtinByChoice = false,
): string {
  const backend = provider
    ? `${provider} (${url})`
    : builtinByChoice
      ? 'the built-in classifier, by choice'
      : 'the built-in classifier, no key set'
  const on = [
    switches.subagentModel && 'subagent model',
    switches.mainEffort && 'main effort',
    switches.mainModel && 'main model',
  ].filter(Boolean)
  return `ready on ${backend}; routing ${on.length > 0 ? on.join(', ') : 'nothing, every switch is off'}`
}

/**
 * What the decision model answered, before any policy touches it: the raw
 * tier, effort and risk with their confidences, and how long it took.
 *
 * This is the line that shows the classification happened at all, separately
 * from whether the policy then decided to act on it.
 */
export function describeDecision(decision: Decision | null, ms: number | null): string {
  const took = ms === null ? '' : ` · ${Math.round(ms)}ms`
  if (!decision) return `no answer${took}`

  const parts = [`tier ${decision.tier} (${reported(decision.confidence)})`]
  if (decision.effort !== null) {
    parts.push(
      `effort ${decision.effort.toFixed(1)} → ${effortLevel(decision.effort)} (${reported(decision.effortConfidence)})`,
    )
  }
  if (decision.risky !== null) parts.push(`risky ${reported(decision.risky)}`)
  return parts.join(' · ') + took
}

/**
 * The persistent status line: the last thing the router did, short enough to
 * sit on screen beside the engine's own notices.
 */
export function describeStatus(
  decision: Decision | null,
  change: { model?: string; effort?: Effort } | null,
): string {
  if (!decision) return 'jev · no answer'
  const asked = `${decision.tier} ${reported(decision.confidence)}`
  if (!change) return `jev · ${asked} · unchanged`
  const to = [change.model, change.effort].filter(Boolean).join('/')
  return `jev · ${asked} → ${to}`
}

import { expect, test } from 'claude-code/testing'
import {
  effortLevel,
  effortRank,
  endpoint,
  questions,
  describeDecision,
  describeSetup,
  describeStatus,
  pendingDecisions,
  rankOf,
  readDecision,
  requestBody,
  requestHeaders,
  requestModelId,
  route,
  selectProvider,
  bareCommand,
} from '../hooks/policy.ts'
import type { Decision, PolicyConfig } from '../hooks/policy.ts'

const config: PolicyConfig = {
  tiers: { fast: 'haiku', balanced: 'sonnet', deep: 'opus' },
  minUpgradeConfidence: 0.3,
  minDowngradeConfidence: 0.6,
}

const gatewayAnswer = (
  tier: string,
  probabilities?: Record<string, number>,
  risky = 0.01,
  effort = 1.4,
) =>
  JSON.stringify({
    answers: {
      tier: { type: 'choice', choice: tier, ...(probabilities ? { probabilities } : {}) },
      effort: { type: 'score', score: effort, probabilities: { '1': 0.9 } },
      risky: { type: 'boolean', probability: risky },
    },
    usage: { inputTokens: 120, outputTokens: 0 },
  })

/** The current state of a request, as turn.step hands it over. */
const on = (model: string, effort?: string) => ({ model, effort })

test('confidence is the highest probability, since the Gateway sends no confidence field', () => {
  const decision = readDecision(gatewayAnswer('balanced', { fast: 0.1, balanced: 0.85, deep: 0.05 }))
  expect(decision?.tier).toBe('balanced')
  expect(Math.abs((decision?.confidence) - (0.85)) < 0.005).toBe(true)
  expect(Math.abs((decision?.effort) - (1.4)) < 0.005).toBe(true)
})

test('a distribution is optional in the response schema, so confidence may be absent', () => {
  const decision = readDecision(gatewayAnswer('deep'))
  expect(decision?.tier).toBe('deep')
  expect(decision?.confidence).toBeNull()
})

test('malformed or unexpected payloads read as no decision rather than throwing', () => {
  expect(readDecision('not json')).toBeNull()
  expect(readDecision('{}')).toBeNull()
  expect(readDecision(JSON.stringify({ answers: { tier: { type: 'choice', choice: 'cheap' } } }))).toBeNull()
})

test('spending less needs the high bar; the same confidence is enough to spend more', () => {
  // 0.51 sits between the two bars: too low to downgrade, high enough to upgrade.
  const down = readDecision(gatewayAnswer('fast', { fast: 0.51, balanced: 0.4, deep: 0.09 }))
  expect(route(down, on('claude-sonnet-5'), config).model).toBeNull()

  const up = readDecision(gatewayAnswer('deep', { deep: 0.51, balanced: 0.4, fast: 0.09 }))
  expect(route(up, on('claude-sonnet-5'), config).model).toBe('opus')
})

test('both directions are available once the bar is cleared', () => {
  const down = readDecision(gatewayAnswer('fast', { fast: 0.95, balanced: 0.04, deep: 0.01 }))
  expect(route(down, on('claude-opus-5'), config).model).toBe('haiku')

  const up = readDecision(gatewayAnswer('deep', { deep: 0.9, balanced: 0.08, fast: 0.02 }))
  expect(route(up, on('claude-haiku-4-5-20251001'), config).model).toBe('opus')
})

test('effort moves in both directions too, on its own confidence', () => {
  const low = readDecision(gatewayAnswer('fast', { fast: 0.95 }, 0.01, 0.1))
  expect(route(low, on('claude-haiku-4-5-20251001', 'high'), config).effort).toBe('low')

  const high = readDecision(gatewayAnswer('deep', { deep: 0.95 }, 0.01, 2.8))
  expect(route(high, on('claude-opus-5', 'low'), config).effort).toBe('xhigh')
})

test('a numeric effort is the caller\'s own scale and is left alone', () => {
  const decision = readDecision(gatewayAnswer('deep', { deep: 0.95 }, 0.01, 2.8))
  expect(route(decision, { model: 'claude-opus-5', effort: 4000 }, config).effort).toBeNull()
})

test('the rubric score maps onto the reasoning ladder', () => {
  expect(effortLevel(0)).toBe('low')
  expect(effortLevel(0.4)).toBe('low')
  expect(effortLevel(1.4)).toBe('medium')
  expect(effortLevel(2.04)).toBe('high')
  expect(effortLevel(3)).toBe('xhigh')
  expect(effortLevel(99)).toBe('xhigh')
})

test('a risky task takes the deep tier and real reasoning, past both thresholds', () => {
  const decision = readDecision(gatewayAnswer('fast', { fast: 0.97, balanced: 0.02, deep: 0.01 }, 0.93))
  const routing = route(decision, on('claude-sonnet-5', 'low'), config)
  expect(routing.model).toBe('opus')
  expect(routing.effort).toBe('high')
  expect(routing.reason).toContain('risk')
})

test('no decision, and a decision that changes nothing, both leave the request as it is', () => {
  expect(route(null, on('claude-sonnet-5'), config).model).toBeNull()
  const same = readDecision(gatewayAnswer('balanced', { balanced: 0.9 }, 0.01, 1.4))
  const routing = route(same, on('sonnet', 'medium'), config)
  expect(routing.model).toBeNull()
  expect(routing.effort).toBeNull()
})

test('without a confidence a change may only go up, never down', () => {
  // The Gateway may omit the distribution, and the built-in classifier has none.
  const noDistribution = readDecision(
    JSON.stringify({ answers: { tier: { type: 'choice', choice: 'fast' } } }),
  )
  expect(route(noDistribution, on('claude-opus-5'), config).model).toBeNull()

  const up = readDecision(JSON.stringify({ answers: { tier: { type: 'choice', choice: 'deep' } } }))
  expect(route(up, on('claude-haiku-4-5-20251001'), config).model).toBe('opus')
})

test('an unrecognised model id is treated as an upgrade, not guessed at', () => {
  expect(rankOf('some-other-vendor-model', config.tiers)).toBeNull()
  const decision = readDecision(gatewayAnswer('fast', { fast: 0.35, balanced: 0.4, deep: 0.25 }))
  // 0.35 clears the upgrade bar only; an undecidable direction gets that one.
  expect(route(decision, on('some-other-vendor-model'), config).model).toBe('haiku')
})

test('the Gateway request carries the model id and spec version it matches on', () => {
  const headers = requestHeaders('gateway', 'key-under-test', 'typesafe-ai/jev')
  expect(headers['ai-model-id']).toBe('typesafe-ai/jev')
  expect(headers['ai-evaluation-model-specification-version']).toBe('4')
  expect(headers.authorization).toBe('Bearer key-under-test')
})

// Omitting this one is not a degraded request, it is a rejected one: the
// Gateway answers 400 "Unsupported gateway protocol version" before it looks
// at anything else, so the whole backend silently falls back to routing
// nothing.
test('the Gateway request names the protocol version, without which it is refused', () => {
  const headers = requestHeaders('gateway', 'k', 'typesafe-ai/jev')
  expect(headers['ai-gateway-protocol-version']).toBe('0.0.1')
})

test('the protocol version is a Gateway header and is never sent to TypeSafe', () => {
  const headers = requestHeaders('typesafe', 'k', 'jev-latest')
  expect(headers['ai-gateway-protocol-version']).toBeUndefined()
})

// --- TypeSafe's own API ------------------------------------------------------
//
// Same model, different wire shape: a yes/no question is a `noul` rather than a
// `boolean`, every answer reports its own `confidence`, and the model rides in
// the body instead of a header.

const typesafeAnswer = (tier: string, confidence: number, noul = 0.01) =>
  JSON.stringify({
    model: 'jev-1.13',
    answers: {
      tier: { type: 'choice', choice: tier, confidence, probabilities: { [tier]: confidence } },
      effort: { type: 'score', score: 2.1, confidence: 0.8 },
      risky: { type: 'noul', noul },
    },
    usage: { input_tokens: 120, output_tokens: 0 },
  })

test('a TypeSafe answer is read from its own confidence and noul fields', () => {
  const decision = readDecision(typesafeAnswer('deep', 0.91, 0.04))
  expect(decision?.tier).toBe('deep')
  expect(Math.abs((decision?.confidence) - (0.91)) < 0.005).toBe(true)
  expect(Math.abs((decision?.effort) - (2.1)) < 0.005).toBe(true)
  expect(Math.abs((decision?.risky) - (0.04)) < 0.005).toBe(true)
})

test('a low-confidence TypeSafe downgrade is refused, like the Gateway path', () => {
  expect(route(readDecision(typesafeAnswer('fast', 0.42)), on('claude-sonnet-5'), config).model).toBeNull()
})

test('a risky TypeSafe answer forces the deep tier through the noul field', () => {
  const decision = readDecision(typesafeAnswer('fast', 0.98, 0.88))
  expect(route(decision, on('claude-sonnet-5'), config).model).toBe('opus')
})

test('each backend gets its own endpoint, question type and model placement', () => {
  expect(endpoint('typesafe', 'https://api.typesafe.ai/')).toBe('https://api.typesafe.ai/v1/systemone')
  expect(endpoint('gateway', 'https://ai-gateway.vercel.sh/v4/ai')).toBe(
    'https://ai-gateway.vercel.sh/v4/ai/evaluation-model',
  )

  expect((questions('typesafe').risky as { type: string }).type).toBe('noul')
  expect((questions('gateway').risky as { type: string }).type).toBe('boolean')

  const typesafeBody = JSON.parse(requestBody('typesafe', { prompt: 'x' }, 'jev-latest'))
  expect(typesafeBody.model).toBe('jev-latest')
  expect(JSON.parse(requestBody('gateway', { prompt: 'x' }, 'typesafe-ai/jev')).model).toBeUndefined()

  expect(requestHeaders('typesafe', 'k', 'jev-latest')['ai-model-id']).toBeUndefined()
})

// --- backend selection -------------------------------------------------------

test('auto prefers TypeSafe, since it is the only backend that reports a confidence', () => {
  expect(selectProvider('auto', 'ts-key', 'gw-key')).toBe('typesafe')
  expect(selectProvider('auto', '', 'gw-key')).toBe('gateway')
  expect(selectProvider('auto', '', '')).toBeNull()
})

test('a forced backend without its own key falls back to the built-in classifier, never to the other key', () => {
  expect(selectProvider('typesafe', '', 'gw-key')).toBeNull()
  expect(selectProvider('gateway', 'ts-key', '')).toBeNull()
})

test('builtin ignores both keys', () => {
  expect(selectProvider('builtin', 'ts-key', 'gw-key')).toBeNull()
})

// --- the two ways a downgrade could have slipped the bar ---------------------

test('risk raises the effort floor but never lowers one', () => {
  // A prod deletion: risky, but mechanically simple, so its own effort is low.
  const decision = readDecision(gatewayAnswer('fast', { fast: 0.99 }, 0.95, 0))
  // Forcing skips the thresholds, so without a clamp this would pull xhigh
  // down to high with no confidence check at all.
  expect(route(decision, on('claude-opus-5', 'xhigh'), config).effort).toBeNull()
  expect(route(decision, on('claude-opus-5', 'max'), config).effort).toBeNull()
  // It still raises a session that is below the floor.
  expect(route(decision, on('claude-opus-5', 'low'), config).effort).toBe('high')
})

test('max ranks above every rung the rubric can produce', () => {
  expect(effortRank('max')).toBeGreaterThan(effortRank('xhigh') as number)
  // Leaving max is a downgrade, so it needs the high bar, not the lenient one.
  const decision = readDecision(gatewayAnswer('fast', { fast: 0.9 }, 0.01, 0))
  const barelyConfident = { ...(decision as NonNullable<typeof decision>), effortConfidence: 0.35 }
  expect(route(barelyConfident, on('claude-sonnet-5', 'max'), config).effort).toBeNull()

  const sure = { ...(decision as NonNullable<typeof decision>), effortConfidence: 0.8 }
  expect(route(sure, on('claude-sonnet-5', 'max'), config).effort).toBe('low')
})

// A prompt classified while another one is still waiting: the turn that
// starts next cannot be tied to either, so neither decision is applied.
const deepDecision: Decision = {
  tier: 'deep',
  confidence: 0.99,
  risky: null,
  effort: null,
  effortConfidence: null,
}
const fastDecision: Decision = { ...deepDecision, tier: 'fast' }

test('a decision is handed to the turn that follows its prompt', () => {
  const pending = pendingDecisions()
  pending.put(deepDecision)
  expect(pending.take()).toEqual(deepDecision)
})

test('two prompts waiting at once yield no decision instead of the wrong one', () => {
  const pending = pendingDecisions()
  pending.put(fastDecision)
  pending.put(deepDecision)
  expect(pending.take()).toBeNull()
})

test('a prompt that failed to classify still shields the next prompt', () => {
  const pending = pendingDecisions()
  pending.put(null)
  pending.put(deepDecision)
  expect(pending.take()).toBeNull()
})

test('the slot empties on take, so a later turn never reuses a decision', () => {
  const pending = pendingDecisions()
  pending.put(deepDecision)
  pending.take()
  expect(pending.take()).toBeNull()
})

test('the slot recovers after an ambiguous round', () => {
  const pending = pendingDecisions()
  pending.put(fastDecision)
  pending.put(deepDecision)
  expect(pending.take()).toBeNull()
  pending.put(deepDecision)
  expect(pending.take()).toEqual(deepDecision)
})

// A turn the router leaves alone still has to say so: a silent no-op and a mod
// that never loaded look identical in the transcript otherwise.
test('a no-change decision reports what it wanted and what it kept', () => {
  const decision: Decision = {
    tier: 'fast',
    confidence: 0.41,
    risky: null,
    effort: 0,
    effortConfidence: 0.41,
  }
  const routing = route(decision, { model: 'sonnet', effort: 'medium' }, config)
  expect(routing.model).toBeNull()
  expect(routing.effort).toBeNull()
  expect(routing.reason).toBe('kept sonnet/medium, wanted haiku/low (confidence 0.41)')
})

test('a no-change decision without a confidence says so rather than going quiet', () => {
  const decision: Decision = {
    tier: 'fast',
    confidence: null,
    risky: null,
    effort: 0,
    effortConfidence: null,
  }
  const routing = route(decision, { model: 'sonnet', effort: 'medium' }, config)
  expect(routing.reason).toBe('kept sonnet/medium, wanted haiku/low (confidence n/d)')
})

test('no classification at all is its own reason, not a no-change', () => {
  expect(route(null, { model: 'sonnet', effort: 'medium' }, config).reason).toBe('no decision')
})

// The transcript is the only place a mod's work is visible, so the lines it
// writes are a contract, not decoration.
test('the setup line names the backend and which switches are on', () => {
  expect(
    describeSetup('typesafe', 'https://api.typesafe.ai/v1/systemone', {
      subagentModel: true,
      mainEffort: true,
      mainModel: false,
    }),
  ).toBe(
    'ready on typesafe (https://api.typesafe.ai/v1/systemone); routing subagent model, main effort',
  )
})

test('the setup line says so when there is no backend and when nothing routes', () => {
  expect(
    describeSetup(null, '', { subagentModel: false, mainEffort: false, mainModel: false }),
  ).toBe('ready on the built-in classifier, no key set; routing nothing, every switch is off')
})

// `provider: "builtin"` is a deliberate choice; reporting it as a missing key
// sends someone looking for a credential they meant to leave out.
test('choosing the built-in classifier is not reported as a missing key', () => {
  expect(
    describeSetup(null, '', { subagentModel: true, mainEffort: true, mainModel: false }, true),
  ).toBe('ready on the built-in classifier, by choice; routing subagent model, main effort')
})

test('the decision line carries every answer and the latency', () => {
  const decision = readDecision(gatewayAnswer('deep', { deep: 0.95 }, 0.01, 2.8))
  expect(describeDecision(decision, 249.4)).toBe(
    'tier deep (0.95) · effort 2.8 → xhigh (0.90) · risky 0.01 · 249ms',
  )
})

test('a classification that never answered says that, not nothing', () => {
  expect(describeDecision(null, 800)).toBe('no answer · 800ms')
})

test('the status line distinguishes a change from a deliberate no-change', () => {
  const decision = readDecision(gatewayAnswer('fast', { fast: 0.87 }))
  expect(describeStatus(decision, { model: 'haiku', effort: 'low' })).toBe(
    'jev · fast 0.87 → haiku/low',
  )
  expect(describeStatus(decision, null)).toBe('jev · fast 0.87 · unchanged')
  expect(describeStatus(null, null)).toBe('jev · no answer')
})

// `turn.step`'s `model` goes to the API as written, so a family alias has to
// become an id there; the engine refuses "haiku" on a request.
test('a family alias resolves to a full id for the main loop', () => {
  expect(requestModelId('haiku')).toBe('claude-haiku-4-5-20251001')
  expect(requestModelId('Sonnet')).toBe('claude-sonnet-5')
  expect(requestModelId('opus')).toBe('claude-opus-5')
})

test('a full id or an unknown name is passed through unchanged', () => {
  expect(requestModelId('claude-haiku-4-5-20251001')).toBe('claude-haiku-4-5-20251001')
  expect(requestModelId('claude-opus-5[1m]')).toBe('claude-opus-5[1m]')
  expect(requestModelId('my-org/custom')).toBe('my-org/custom')
})

// Staying in the same tier is not a change, so a session on `claude-opus-5[1m]`
// keeps its 1M-context id when the decision is `deep`.
test('a decision for the tier the session already runs keeps its exact id', () => {
  const decision = readDecision(gatewayAnswer('deep', { deep: 0.95 }))
  const routing = route(decision, { model: 'claude-opus-5[1m]', effort: 'medium' }, config)
  expect(routing.model).toBeNull()
})

test('a slash command alone is not a task; with text after it, it is', () => {
  for (const text of ['/simplify', ' /run ', '/code-review\n']) expect(bareCommand(text)).toBe(true)
  for (const text of ['/code-review high', '/simplify the retry loop', '/tmp/log.txt', '/', 'fix /api', 'rename foo'])
    expect(bareCommand(text)).toBe(false)
})

