/**
 * npm-to-pnpm-rewriter — Claude Mod
 *
 * Rewrites npm / npx invocations to the package manager your project uses
 * (pnpm by default, yarn or bun via options). The "modifying" placement: the
 * hook forwards a copy of the event with a changed `command` to `next`, and
 * tells the model what ran through `context` (the model's own tool_use block
 * keeps the command it wrote, for prompt-cache stability).
 *
 * Needs Claude Code >= 2.1.287. Typed
 * against Anthropic's declarations: https://github.com/anthropics/claude-code/tree/main/mods
 *
 * Options:
 *   manager: "pnpm" | "yarn" | "bun"  (default "pnpm")
 */
import type { Register } from 'claude-code'

type Manager = 'pnpm' | 'yarn' | 'bun'

// [regex on the npm form, replacement per manager]. $1 keeps the command separator.
const REWRITES: Array<[RegExp, Record<Manager, string>]> = [
  [/(^|&&\s*|;\s*|\|\s*)npm\s+ci\b/g, { pnpm: '$1pnpm install --frozen-lockfile', yarn: '$1yarn install --immutable', bun: '$1bun install --frozen-lockfile' }],
  [/(^|&&\s*|;\s*|\|\s*)npm\s+(install|i|add)\b/g, { pnpm: '$1pnpm add', yarn: '$1yarn add', bun: '$1bun add' }],
  [/(^|&&\s*|;\s*|\|\s*)npm\s+(uninstall|remove|rm)\b/g, { pnpm: '$1pnpm remove', yarn: '$1yarn remove', bun: '$1bun remove' }],
  [/(^|&&\s*|;\s*|\|\s*)npm\s+run\b/g, { pnpm: '$1pnpm run', yarn: '$1yarn run', bun: '$1bun run' }],
  [/(^|&&\s*|;\s*|\|\s*)npm\s+(test|start|build)\b/g, { pnpm: '$1pnpm $2', yarn: '$1yarn $2', bun: '$1bun run $2' }],
  [/(^|&&\s*|;\s*|\|\s*)npx\s+/g, { pnpm: '$1pnpm dlx ', yarn: '$1yarn dlx ', bun: '$1bunx ' }],
]

// "<manager> add" with no package means "install everything": keep the bare install form.
function fixBareAdd(command: string, manager: Manager): string {
  return command.replace(new RegExp(`${manager} add(\\s*(&&|;|\\||$))`, 'g'), `${manager} install$1`)
}

export const register: Register = (on, options) => {
  const manager: Manager =
    options.manager === 'yarn' || options.manager === 'bun' ? options.manager : 'pnpm'

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const original = e.command
    if (!/\bnp[mx]\b/.test(original)) return next(e)

    // rewrite only outside single- and double-quoted strings: `echo '&& npm test'` is text, not a call
    const rewritten = original
      .split(/("[^"]*"|'[^']*')/)
      .map((part, i) => {
        if (i % 2 === 1) return part
        let out = part
        for (const [re, byManager] of REWRITES) out = out.replace(re, byManager[manager])
        return fixBareAdd(out, manager)
      })
      .join('')

    if (rewritten === original) return next(e)

    $.ui.log(`[npm-to-pnpm-rewriter] ${original}  ->  ${rewritten}`)
    // Events are frozen: forward a modified copy instead of mutating e.
    const outcome = await next({ ...e, command: rewritten })
    if (outcome.deny !== undefined) return outcome
    return {
      ...outcome,
      context: [
        ...(outcome.context ?? []),
        `npm-to-pnpm-rewriter ran \`${rewritten}\` instead of \`${original}\` (this project uses ${manager}).`,
      ],
    }
  })
}

/**
 * session-chats: the record of messages between Claude Code sessions, and how
 * to read it back. No `$` here: the hooks module hands in what it read.
 *
 * Each session that runs the mod keeps its own log under `log:<sessionId>` in
 * the mod's store (so two sessions never write the same key), and the pane
 * merges every log into conversations: one per pair of sessions, whichever
 * side wrote it. A side is known by its session id once the live-session
 * registry (`~/.claude/sessions/<pid>.json`) names it; before that, by the
 * name or address SendMessage used.
 */

/** One end of a conversation. */
export type Side = {
  /** The session id `claude --resume` takes. */
  id?: string
  /** The name ListAgents shows and SendMessage addresses (`demob-74`). */
  name?: string
  /** The address a reply goes to (`uds:/tmp/cc-socks/1421.sock`, `session_…`). */
  address?: string
  /** The session's working directory, where `claude --resume` must run. */
  cwd?: string
}

export type Msg = { at: number; from: 'self' | 'peer'; text: string }

export type Chat = { peer: Side; firstAt: number; lastAt: number; messages: Msg[] }

/** What one session keeps: who it is and whom it talked to. */
export type Log = { v: 1; self: Side; updatedAt: number; chats: Chat[] }

/** A row of the engine's live-session registry. */
export type Live = {
  pid: number
  sessionId: string
  cwd: string
  name?: string
  socket?: string
  status?: string
  kind?: string
  tmux?: string
}

export type Limits = { messages: number; chars: number; chats: number }
export const LIMITS: Limits = { messages: 40, chars: 600, chats: 200 }

/** A message as the pane shows it: who wrote it, by the conversation's own sides. */
export type Line = { at: number; by: 'a' | 'b'; text: string }

/** One conversation, merged from every log that holds it; `a` is this session when it is one of the two. */
export type Conversation = { key: string; a: Side; b: Side; firstAt: number; lastAt: number; lines: Line[] }

// ---------------------------------------------------------------------------
// reading what the engine hands over

const ENVELOPE = /^\s*<cross-session-message\b([^>]*)>\n?([\s\S]*?)\n?<\/cross-session-message>\s*$/

/** The sender and body of a delivered cross-session message; undefined for anything else. */
export function parseEnvelope(text: string): { from: string; name?: string; body: string } | undefined {
  const m = ENVELOPE.exec(text)
  if (!m) return undefined
  const attrs = attributes(m[1]!)
  if (!attrs.from) return undefined
  return { from: attrs.from, name: attrs['from-name'] || undefined, body: m[2]! }
}

function attributes(src: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const m of src.matchAll(/([\w-]+)="([^"]*)"/g)) out[m[1]!] = unescape(m[2]!)
  return out
}

function unescape(s: string): string {
  return s.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&apos;/g, "'").replace(/&amp;/g, '&')
}

/** The registry's rows, from the text of each `sessions/<pid>.json`; a file that does not parse is skipped. */
export function parseRegistry(files: readonly string[]): Live[] {
  const out: Live[] = []
  for (const text of files) {
    try {
      const j = JSON.parse(text) as Record<string, unknown>
      if (typeof j.sessionId !== 'string' || typeof j.cwd !== 'string' || typeof j.pid !== 'number') continue
      out.push({
        pid: j.pid,
        sessionId: j.sessionId,
        cwd: j.cwd,
        name: str(j.name),
        socket: str(j.messagingSocketPath),
        status: str(j.status),
        kind: str(j.kind),
        tmux: str(j.tmux),
      })
    } catch {
      // a file mid-write, or not ours
    }
  }
  return out
}

const str = (v: unknown): string | undefined => (typeof v === 'string' && v ? v : undefined)

/** SendMessage's `to` without the ` [ref]` a listing may add. */
export function bareAddress(to: string): string {
  return to.replace(/\s*\[[^\]]*\]\s*$/, '').trim()
}

/** The registry row a name or an address belongs to. */
export function findLive(live: readonly Live[], to: string): Live | undefined {
  const t = bareAddress(to)
  const socket = t.startsWith('uds:') ? t.slice(4) : undefined
  return live.find(l => (socket ? l.socket === socket : l.name === t || l.sessionId === t))
}

/** The registry row of this session (several share an id only when one inherited it). */
export function findSelf(live: readonly Live[], id: string, cwd: string): Live | undefined {
  const mine = live.filter(l => l.sessionId === id)
  return mine.find(l => l.cwd === cwd) ?? mine[0]
}

/** A side from a registry row. */
export function sideOf(l: Live): Side {
  return { id: l.sessionId, name: l.name, address: l.socket ? `uds:${l.socket}` : undefined, cwd: l.cwd }
}

/** Whether `to` reads as another session, not a subagent or teammate of this one. */
export function looksLikeSession(to: string, live: readonly Live[]): boolean {
  const t = bareAddress(to)
  if (/^(uds:|session_|cse_|bridge:)/.test(t)) return true
  return findLive(live, t) !== undefined
}

// ---------------------------------------------------------------------------
// writing the log

export function emptyLog(self: Side, now: number): Log {
  return { v: 1, self, updatedAt: now, chats: [] }
}

/** A stored value read back as a log, or undefined when it is not one. */
export function asLog(v: unknown): Log | undefined {
  if (!v || typeof v !== 'object') return undefined
  const l = v as Partial<Log>
  if (l.v !== 1 || !l.self || !Array.isArray(l.chats)) return undefined
  return l as Log
}

function sameSide(x: Side, y: Side): boolean {
  if (x.id && y.id) return x.id === y.id
  if (x.address || y.address) return !!x.address && x.address === y.address
  return !!x.name && x.name === y.name
}

function mergeSide(old: Side, add: Side): Side {
  return { id: add.id ?? old.id, name: add.name ?? old.name, address: add.address ?? old.address, cwd: add.cwd ?? old.cwd }
}

/** Text a peer wrote, without terminal control sequences (newlines and tabs kept). */
export function clean(text: string): string {
  return text
    .replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '')
    .replace(/\x1b\][^\x07\x1b]*(\x07|\x1b\\)?/g, '')
    .replace(/[\x00-\x08\x0b-\x1f\x7f-\x9f]/g, '')
}

/** The log with one more message to or from `peer`; the newest conversations and messages are kept. */
export function record(log: Log, self: Side, peer: Side, msg: Msg, now: number, limits: Limits = LIMITS): Log {
  const raw = clean(msg.text)
  const text = Array.from(raw).length > limits.chars ? Array.from(raw).slice(0, limits.chars - 1).join('') + '…' : raw
  const chats = log.chats.slice()
  const i = chats.findIndex(c => sameSide(c.peer, peer))
  const m: Msg = { ...msg, text }
  if (i >= 0) {
    const c = chats[i]!
    chats[i] = { peer: mergeSide(c.peer, peer), firstAt: c.firstAt, lastAt: Math.max(c.lastAt, msg.at), messages: [...c.messages, m].slice(-limits.messages) }
  } else {
    chats.push({ peer, firstAt: msg.at, lastAt: msg.at, messages: [m] })
  }
  chats.sort((x, y) => y.lastAt - x.lastAt)
  return { v: 1, self: mergeSide(log.self, self), updatedAt: now, chats: chats.slice(0, limits.chats) }
}

// ---------------------------------------------------------------------------
// reading it back

export function sideKey(s: Side): string {
  return s.id ? `id:${s.id}` : s.address ? `a:${s.address}` : `n:${s.name ?? '?'}`
}

/**
 * Every log merged into conversations, newest first. A message both sides
 * logged (the sender's `self` line, the receiver's `peer` line) is kept once.
 * With `selfId`, a conversation this session is part of has it as `a`.
 */
export function conversations(logs: readonly Log[], selfId?: string): Conversation[] {
  // a side known by its socket in one log and by id in another is the same session
  const byName = new Map<string, Side>()
  const note = (s: Side) => {
    if (s.id && s.address) byName.set(`a:${s.address}`, { ...byName.get(`a:${s.address}`), ...s })
  }
  for (const l of logs) {
    note(l.self)
    for (const c of l.chats) note(c.peer)
  }
  const full = (s: Side): Side => (s.id ? s : byName.get(sideKey(s)) ? mergeSide(s, byName.get(sideKey(s))!) : s)

  const out = new Map<string, Conversation>()
  for (const l of logs) {
    const self = full(l.self)
    for (const c of l.chats) {
      const peer = full(c.peer)
      const ks = sideKey(self)
      const kp = sideKey(peer)
      if (ks === kp) continue
      const [first, second] = ks < kp ? [self, peer] : [peer, self]
      const key = `${sideKey(first)}|${sideKey(second)}`
      let conv = out.get(key)
      if (!conv) {
        conv = { key, a: first, b: second, firstAt: c.firstAt, lastAt: c.lastAt, lines: [] }
        out.set(key, conv)
      } else {
        conv.a = mergeSide(conv.a, first)
        conv.b = mergeSide(conv.b, second)
        conv.firstAt = Math.min(conv.firstAt, c.firstAt)
        conv.lastAt = Math.max(conv.lastAt, c.lastAt)
      }
      const selfIsA = sideKey(conv.a) === ks
      for (const m of c.messages) {
        const by: 'a' | 'b' = (m.from === 'self') === selfIsA ? 'a' : 'b'
        const dupe = conv.lines.some(x => x.by === by && x.text === m.text && Math.abs(x.at - m.at) < 120_000)
        if (!dupe) conv.lines.push({ at: m.at, by, text: m.text })
      }
    }
  }
  const list = [...out.values()]
  for (const c of list) {
    c.lines.sort((x, y) => x.at - y.at)
    if (selfId && c.b.id === selfId) {
      ;[c.a, c.b] = [c.b, c.a]
      c.lines = c.lines.map(x => ({ ...x, by: x.by === 'a' ? 'b' : 'a' }))
    }
  }
  return list.sort((x, y) => y.lastAt - x.lastAt)
}

/** Logs not written for `days` dropped, the store's own key names returned. */
export function stale(entries: readonly [string, Log][], now: number, days: number): string[] {
  return entries.filter(([, l]) => now - l.updatedAt > days * 86_400_000).map(([k]) => k)
}

// ---------------------------------------------------------------------------
// opening a session again

const ID = /^[A-Za-z0-9][A-Za-z0-9_-]{7,79}$/

/** Whether `claude --resume` can take this side from this machine. */
export function canResume(s: Side): s is Side & { id: string; cwd: string } {
  // no backslash in a POSIX path: fish reads it as an escape inside single quotes
  return !!s.id && ID.test(s.id) && !!s.cwd && s.cwd.startsWith('/') && !/[\\\x00-\x1f\x7f]/.test(s.cwd)
}

/** A single-quoted shell word. */
export function shq(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`
}

/** The line that resumes a side in a shell. */
export function resumeCommand(s: Side & { id: string; cwd: string }): string {
  return `cd ${shq(s.cwd)} && claude --resume ${s.id}`
}

/** A value tmux will not expand: `#(...)` and `#{...}` run or read formats. */
export function tmuxLiteral(s: string): string {
  return s.replace(/#/g, '##')
}

/** A tmux window name: letters, digits, `.`, `_`, `-`. */
export function windowName(s: string): string {
  return s.replace(/[^A-Za-z0-9._-]/g, '').slice(0, 24) || 'session'
}

/** An AppleScript string literal. */
export function appleQuote(text: string): string {
  return `"${text.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`
}

// ---------------------------------------------------------------------------
// drawing helpers

/** `text` cut to `width` cells with an ellipsis. */
export function fit(text: string, width: number): string {
  const w = Math.max(1, Math.floor(width))
  const chars = Array.from(text)
  return chars.length <= w ? text : chars.slice(0, Math.max(0, w - 1)).join('') + '…'
}


/** `3m`, `2h`, `5d`: how long ago. */
export function ago(at: number, now: number): string {
  const s = Math.max(0, Math.round((now - at) / 1000))
  if (s < 60) return 'now'
  if (s < 3600) return `${Math.floor(s / 60)}m`
  if (s < 86_400) return `${Math.floor(s / 3600)}h`
  return `${Math.floor(s / 86_400)}d`
}

/** The end of a path, home shortened to `~` and cut at the front. */
export function shortPath(path: string | undefined, home: string, width: number): string {
  if (!path) return ''
  const p = home && (path === home || path.startsWith(home + '/')) ? `~${path.slice(home.length)}` : path
  const chars = Array.from(p)
  return chars.length <= width ? p : '…' + chars.slice(chars.length - width + 1).join('')
}

/** What a side is called in the pane. */
export function label(s: Side): string {
  const raw = s.name ?? (s.id ? s.id.slice(0, 8) : s.address?.replace(/^uds:.*\//, '') ?? 'unknown')
  // a peer names itself: no control bytes, and short
  return Array.from(clean(raw)).slice(0, 60).join('') || 'unknown'
}

/** The message on one line. */
export function oneLine(text: string): string {
  return text.replace(/\s+/g, ' ').trim()
}

/** A short stable id for an element key. */
export function hash(s: string): string {
  let h1 = 5381
  for (let i = 0; i < s.length; i++) h1 = ((h1 << 5) + h1 + s.charCodeAt(i)) | 0
  return (h1 >>> 0).toString(36)
}

/**
 * session-chats: the conversations as a graph, drawn as a file tree. Each
 * session is a node; each conversation is one link, its arrow from the session
 * that wrote first. No `$` here.
 *
 * Every group of sessions that talked is one tree, this session's first. A
 * link to a session already in the tree is a one-line reference, not a second
 * copy of its branch, so the tree stays as long as the number of links.
 */
import { clean, sideKey } from './chats.ts'
import type { Conversation, Side } from './chats.ts'

export type Node = {
  key: string
  side: Side
  isSelf: boolean
  isRunning: boolean
  /** The folder's last part, shown after the name. */
  sub: string
}

export type Edge = {
  from: string
  to: string
  /** The other side answered at least once. */
  isAnswered: boolean
  count: number
  lastAt: number
  conv: Conversation
}

export type Graph = { nodes: Node[]; edges: Edge[] }

/** The graph of every conversation; `isActive` keeps the running sessions and the links between them. */
export function buildGraph(convs: readonly Conversation[], running: ReadonlySet<string>, selfId: string | undefined, isActive: boolean): Graph {
  const nodes = new Map<string, Node>()
  const edges: Edge[] = []
  const add = (s: Side) => {
    const key = sideKey(s)
    const old = nodes.get(key)
    // conversations come newest first: the first seen name is the current one
    const side = old ? { ...defined(s), ...defined(old.side) } : s
    const isSelf = !!selfId && side.id === selfId
    nodes.set(key, {
      key,
      side,
      isSelf,
      isRunning: isSelf || (!!side.id && running.has(side.id)),
      sub: isSelf ? 'this session' : clean(folder(side.cwd)),
    })
    return key
  }
  for (const c of convs) {
    if (c.lines.length === 0) continue
    const ka = add(c.a)
    const kb = add(c.b)
    const firstByA = c.lines[0]!.by === 'a'
    edges.push({
      from: firstByA ? ka : kb,
      to: firstByA ? kb : ka,
      isAnswered: c.lines.some(l => l.by !== c.lines[0]!.by),
      count: c.lines.length,
      lastAt: c.lastAt,
      conv: c,
    })
  }
  if (!isActive) return { nodes: [...nodes.values()], edges }
  const keep = new Set([...nodes.values()].filter(n => n.isRunning).map(n => n.key))
  return { nodes: [...nodes.values()].filter(n => keep.has(n.key)), edges: edges.filter(e => keep.has(e.from) && keep.has(e.to)) }
}

const defined = (s: Side): Side => Object.fromEntries(Object.entries(s).filter(([, v]) => v !== undefined)) as Side

function folder(path: string | undefined): string {
  return path ? path.replace(/[\\/]+$/, '').split(/[\\/]/).pop() || path : ''
}

export type Row = {
  node: Node
  /** `│   ` and `    ` of the ancestors, then `├─` or `└─`; empty for a root. */
  prefix: string
  /** The link to the parent row; none for a root. */
  edge?: Edge
  /** `→` the parent wrote first, `←` this one did; `⇢` `⇠` while unanswered; `↺` a session shown elsewhere. */
  arrow: string
  /** A link to a session that already has its own row. */
  isRef: boolean
}

/** The graph as tree rows: this session's tree first, then each other group from its first sender. */
export function tree(g: Graph): Row[] {
  const touching = new Map<string, Edge[]>()
  for (const n of g.nodes) touching.set(n.key, [])
  for (const e of g.edges) {
    touching.get(e.from)?.push(e)
    touching.get(e.to)?.push(e)
  }
  const firstAt = (k: string) => Math.min(Infinity, ...touching.get(k)!.map(e => e.conv.firstAt))
  const reached = new Set(g.edges.map(e => e.to))
  const isSource = (k: string) => !reached.has(k)
  const roots = [...g.nodes].sort(
    (x, y) => Number(y.isSelf) - Number(x.isSelf) || Number(isSource(y.key)) - Number(isSource(x.key)) || (firstAt(x.key) === firstAt(y.key) ? 0 : firstAt(x.key) < firstAt(y.key) ? -1 : 1),
  )
  const byKey = new Map(g.nodes.map(n => [n.key, n]))
  const seen = new Set<string>()
  const used = new Set<Edge>()
  const rows: Row[] = []
  const visit = (k: string, indent: string) => {
    const mine = touching.get(k)!.filter(e => !used.has(e)).sort((x, y) => y.lastAt - x.lastAt)
    for (const e of mine) used.add(e)
    mine.forEach((e, i) => {
      const other = e.from === k ? e.to : e.from
      const node = byKey.get(other)
      if (!node) return
      const isLast = i === mine.length - 1
      const isRef = seen.has(other)
      const arrow = isRef ? '↺' : e.from === k ? (e.isAnswered ? '→' : '⇢') : e.isAnswered ? '←' : '⇠'
      rows.push({ node, prefix: indent + (isLast ? '└─' : '├─'), edge: e, arrow, isRef })
      if (isRef) return
      seen.add(other)
      visit(other, indent + (isLast ? '    ' : '│   '))
    })
  }
  for (const r of roots) {
    if (seen.has(r.key)) continue
    seen.add(r.key)
    rows.push({ node: r, prefix: '', arrow: '', isRef: false })
    visit(r.key, '')
  }
  return rows
}

{
  "description": "session-chats: session.send and session.receive record each cross-session message (observe only); /chats opens a Pane with every conversation and a button to resume each session in a new terminal",
  "modules": [
    "./session-chats.tsx"
  ]
}

/**
 * session-chats — Claude Mod
 *
 * Keeps a record of every conversation between Claude Code sessions (one
 * session's SendMessage to another, and the replies) and draws it in a side
 * pane as a tree: a row per session, an arrow per conversation. Who was
 * talking to whom survives after those sessions close, and the selected
 * session opens again in a new terminal (`claude --resume <id>` in its folder).
 *
 *   `/chats` opens the pane · `/chats close` closes it
 *
 * What it hooks: `session.send` (a message leaving this session for another)
 * and `session.receive` (a `<cross-session-message>` arriving). Both only
 * observe and pass the message on unchanged. Which session a name or address
 * belongs to, and its folder, come from Claude Code's live-session registry
 * (`~/.claude/sessions/<pid>.json`) at the moment of the message. The record
 * is the mod's own store (`~/.claude/plugins/store/`), one key per session.
 *
 * Needs Claude Code >= 2.1.287 (recorded live on 2.1.312, tree drawn live on 2.1.314).
 *
 * Options (pluginConfigs["session-chats@skills-dir"].options):
 *   terminal: auto|Terminal|iTerm|tmux|copy  how Open starts the session (default auto)
 *   keepDays: number   forget logs not written for this many days (default 90)
 *   columns:  number   width asked for the docked pane (default 72)
 */
import type { ElementTable, EngineInterface, Register, RenderChildren, RenderSurface } from 'claude-code'
import {
  ago,
  appleQuote,
  asLog,
  bareAddress,
  canResume,
  conversations,
  emptyLog,
  findLive,
  findSelf,
  fit,
  hash,
  label,
  looksLikeSession,
  oneLine,
  parseEnvelope,
  parseRegistry,
  record,
  resumeCommand,
  shortPath,
  sideKey,
  sideOf,
  stale,
  tmuxLiteral,
  windowName,
} from './chats.ts'
import type { Conversation, Live, Log, Side } from './chats.ts'
import { buildGraph, tree } from './graph.ts'
import type { Graph, Node as GraphNode, Row } from './graph.ts'

const PANE = 'session-chats'
const COMMAND = 'chats'
const PREFIX = 'log:'
const TERMINALS = ['auto', 'Terminal', 'iTerm', 'tmux', 'copy'] as const
type How = (typeof TERMINALS)[number]

// Anthropic's palette: ivory text, warm grays, one orange accent
const ORANGE = '#d97757'
const IVORY = '#faf9f5'
const GRAY = '#b0aea5'
const DIM = '#87867f'
const LINE = '#5e5d59'
const ROW_BG = '#3d3d3a'

let convs: Conversation[] = []
let live: Live[] = []
/** Session ids whose process answered `kill -0`. */
let running = new Set<string>()
let me: Side = {}
let home = ''
let isOpen = false
let note: string | undefined
/** The selected node's key; undefined selects this session. */
let selected: string | undefined
/** Only running sessions and the links between them. */
let isActive = false
let timer: { cancel: () => void } | undefined
let keepDays = 90
let writing: Promise<void> = Promise.resolve()

export const register: Register = (on, options) => {
  const how: How = (TERMINALS as readonly string[]).includes(String(options.terminal)) ? (options.terminal as How) : 'auto'
  keepDays = typeof options.keepDays === 'number' && options.keepDays > 0 ? options.keepDays : 90
  const columns = Math.min(140, Math.max(40, typeof options.columns === 'number' ? Math.round(options.columns) : 72))

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await $.command
      .register({
        name: COMMAND,
        description: 'Tree of the sessions that messaged each other, with a button to reopen each one (close)',
        argumentHint: '[close]',
        immediate: true,
      })
      .catch(err => $.ui.log(`session-chats: /${COMMAND} not registered: ${err}`))
    return r
  })

  // a message this session sends to another one
  on('session.send', async ($, e, next) => {
    const r = await next(e)
    if (!r.isDelivered) return r
    try {
      await reread($)
      const to = bareAddress(e.to)
      if (!looksLikeSession(to, live)) return r
      const hit = findLive(live, to)
      await write($, hit ? sideOf(hit) : { address: to }, 'self', e.text)
    } catch (err) {
      $.ui.log(`session-chats: send not recorded: ${err}`)
    }
    return r
  }).catch(($, e, next) => next(e))

  // a message another session sent here
  on('session.receive', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId || r.consumed !== undefined) return r
    if (e.origin.kind !== 'peer' && e.origin.kind !== 'peer-send-message') return r
    const env = parseEnvelope(e.text)
    if (!env) return r
    try {
      await reread($)
      // the address is the engine's; the name is only what the sender says it is
      const hit = findLive(live, env.from)
      const peer: Side = hit ? sideOf(hit) : { address: env.from, name: env.name }
      await write($, peer, 'peer', env.body)
    } catch (err) {
      $.ui.log(`session-chats: message not recorded: ${err}`)
    }
    return r
  }).catch(($, e, next) => next(e))

  on('command.run', { command: COMMAND }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'close' || arg === 'stop') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return { text: 'session-chats closed' }
    }
    await reread($)
    try {
      await $.ui.open({ id: PANE, title: 'chats', focus: true, columns })
    } catch (err) {
      return { text: `session-chats: pane not opened: ${err}` }
    }
    isOpen = true
    timer?.cancel()
    // other sessions write their side while the pane is open
    timer = $.clock.every(20_000, () => {
      void reread($).then(() => $.ui.invalidate('ui.render'), () => undefined)
    })
    $.ui.invalidate('ui.render')
    const hint = e.presentation?.isFullscreen ? 'press 1–9 to select a session' : 'drawn above the prompt; /tui fullscreen docks it beside the transcript'
    const { g } = view()
    return { text: `${g.nodes.length} session${g.nodes.length === 1 ? '' : 's'} · ${g.edges.length} link${g.edges.length === 1 ? '' : 's'} · ${hint} · /${COMMAND} close` }
  })

  on('ui.close', async ($, e, next) => {
    if (e.id !== PANE) return next(e)
    const r = await next(e)
    isOpen = false
    timer?.cancel()
    timer = undefined
    return r
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    const r = await next(e)
    const key = e.element
    if (key === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return r
    }
    if (key === 'refresh') {
      note = undefined
      await reread($)
    } else if (key === 'filter:all' || key === 'filter:active') {
      isActive = key === 'filter:active'
    } else if (key.startsWith('node:')) {
      const n = view().g.nodes.find(x => hash(x.key) === key.slice(5))
      if (n) selected = n.key
      note = undefined
    } else if (key === 'open' || key === 'copy') {
      const side = view().sel?.side
      if (side && canResume(side)) {
        const cmd = resumeCommand(side)
        if (key === 'copy') {
          const { isCopied } = await $.ui.copy({ text: cmd }).catch(() => ({ isCopied: false }))
          note = isCopied ? `copied: ${cmd}` : `run in a terminal: ${cmd}`
        } else {
          const opened = await openTerminal($, how, side, cmd)
          if (opened) {
            note = `${label(side)} opened in ${opened}`
          } else {
            const { isCopied } = await $.ui.copy({ text: cmd }).catch(() => ({ isCopied: false }))
            note = `${isCopied ? 'no terminal to open here; command copied' : 'run in a terminal'}: ${cmd}`
          }
        }
        $.ui.toast(note)
      }
    }
    $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(32, e.props.bodyColumns - 1)
    const sp = spacer(e.surface)
    const noop = () => {}
    const now = await $.clock.now()
    const { g, rows, sel } = view()
    const links = g.edges.length

    const top = (
      <Box key="top" flexDirection="column" borderStyle="round" borderColor={LINE} paddingX={1} marginBottom={1}>
        <Text key="t">
          <Text color={ORANGE} bold>{'◆ '}</Text>
          <Text bold color={IVORY}>{'Session flow'}</Text>
          <Text color={DIM}>{sp(`   ${g.nodes.length} session${g.nodes.length === 1 ? '' : 's'} · ${links} link${links === 1 ? '' : 's'}`)}</Text>
        </Text>
        <Box key="f" flexDirection="row" columnGap={1}>
          <Button key="filter:all" label="All" dimColor={isActive} hover={{ color: ORANGE }} onPress={noop} />
          <Button key="filter:active" label="Active" dimColor={!isActive} hover={{ color: ORANGE }} onPress={noop} />
        </Box>
      </Box>
    )

    const body: RenderChildren[] = []
    if (g.nodes.length === 0) {
      body.push(
        <Box key="empty" flexDirection="column" marginBottom={1}>
          <Text key="a" color={IVORY}>{isActive && convs.length > 0 ? 'No running sessions in your conversations.' : 'No conversations yet.'}</Text>
          <Text key="b" color={DIM} wrap="wrap">
            {isActive && convs.length > 0
              ? 'Press All to see the sessions that have closed.'
              : 'When a session sends a message to another one (SendMessage), or gets one, both show up here and stay after they close.'}
          </Text>
        </Box>,
      )
    }

    // the tree: one row per session, and one per link to a session shown on another row
    const numbers = new Map<string, number>()
    for (const r of rows) if (!r.isRef && numbers.size < 9) numbers.set(r.node.key, numbers.size + 1)
    const lead = (r: Row) => Array.from(r.prefix).length + (r.arrow ? 2 : 0) + 2 + (numbers.has(r.node.key) && !r.isRef ? 3 : 0) + Array.from(label(r.node.side)).length
    const col = Math.min(Math.floor(width * 0.6), Math.max(0, ...rows.map(lead)) + 2)
    if (rows.length > 0) {
      body.push(
        <Box key="tree" flexDirection="column" marginBottom={1}>
          {rows.map((r, i) => {
            const n = r.node
            const isSel = n.key === sel?.key
            const touchesSel = !!r.edge && !!sel && (r.edge.from === sel.key || r.edge.to === sel.key)
            const e2 = r.edge
            const facts = r.isRef
              ? ['(above)', e2 && count(e2.count), e2 && ago(e2.lastAt, now)]
              : e2
                ? [n.isSelf ? 'this session' : n.sub, count(e2.count), ago(e2.lastAt, now), e2.isAnswered ? '' : 'no answer']
                : [n.isSelf ? 'this session' : n.sub]
            const pad = ' '.repeat(Math.max(2, col - lead(r)))
            const num = numbers.get(n.key)
            const bg = isSel && !r.isRef ? ROW_BG : undefined
            return (
              <Box key={`t${i}`} flexDirection="row" width={width} backgroundColor={bg}>
                <Text key="p" color={DIM} backgroundColor={bg}>{sp(r.prefix.slice(0, -2))}</Text>
                <Text key="b" color={touchesSel ? ORANGE : DIM} backgroundColor={bg}>{sp(r.prefix.slice(-2) + (r.arrow ? `${r.arrow} ` : ''))}</Text>
                {r.isRef ? (
                  <Text key="n" color={DIM}>{sp(`  ${label(n.side)}`)}</Text>
                ) : (
                  [
                    <Text key="d" color={n.isRunning ? ORANGE : DIM} backgroundColor={bg}>{n.isRunning ? '● ' : '○ '}</Text>,
                    <Button
                      key={`node:${hash(n.key)}`}
                      plain
                      hotkey={num !== undefined ? String(num) : undefined}
                      label={label(n.side)}
                      hover={{ color: ORANGE }}
                      onPress={noop}
                    />,
                  ]
                )}
                <Text key="f" color={isSel ? GRAY : DIM} backgroundColor={bg} wrap="truncate-end">{sp(pad + facts.filter(Boolean).join(' · '))}</Text>
              </Box>
            )
          })}
        </Box>,
      )
    }

    if (sel) body.push(detail(sel, g, now, width, sp, { Box, Text, Button }))

    return (
      <Box flexDirection="column">
        {top}
        {body}
        <Box key="foot" flexDirection="column">
          {note ? <Text key="note" color={ORANGE} wrap="wrap">{sp(note)}</Text> : null}
          <Box key="toolbar" flexDirection="row" columnGap={1}>
            <Button key="refresh" label="refresh" hotkey="r" onPress={noop} />
            <Button key="close" label="close" onPress={noop} />
          </Box>
          {numbers.size > 0 ? <Text key="hint" color={DIM}>{sp(fit(`${numbers.size === 1 ? '1' : `1–${numbers.size}`} select · → wrote first · ⇢ no answer · ↺ shown above`, width))}</Text> : null}
        </Box>
      </Box>
    )
  })
}

/** The graph the pane shows now, its tree rows, and the selected node (this session by default). */
function view(): { g: Graph; rows: Row[]; sel: GraphNode | undefined } {
  const g = buildGraph(convs, running, me.id, isActive)
  const rows = tree(g)
  const sel = g.nodes.find(n => n.key === selected) ?? g.nodes.find(n => n.isSelf) ?? rows[0]?.node
  return { g, rows, sel }
}

/** `3 msgs`, `1 msg`. */
function count(n: number): string {
  return `${n} msg${n === 1 ? '' : 's'}`
}

type Parts = Pick<ElementTable<'terminal'>, 'Box' | 'Text' | 'Button'>

/** The selected session: its links, the last message on each, and Open. */
function detail(n: GraphNode, g: Graph, now: number, width: number, sp: (s: string) => string, { Box, Text, Button }: Parts): RenderChildren {
  const noop = () => {}
  const s = n.side
  const mine = g.edges.filter(x => x.from === n.key || x.to === n.key).sort((x, y) => y.lastAt - x.lastAt)
  const byKey = new Map(g.nodes.map(x => [x.key, x]))
  const st = state(s)
  const where = shortPath(s.cwd, home, Math.max(8, width - 6))

  const rows: RenderChildren[] = [
    <Text key="n">
      <Text color={n.isRunning ? ORANGE : DIM}>{n.isRunning ? '● ' : '○ '}</Text>
      <Text color={IVORY} bold>{label(s)}</Text>
      <Text color={DIM}>{sp(`  ${n.isSelf ? 'this session' : st ?? 'closed'}`)}</Text>
    </Text>,
  ]
  if (s.cwd) rows.push(<Text key="p" color={DIM} wrap="truncate-end">{sp(where)}</Text>)

  mine.forEach((x, i) => {
    const isOut = x.from === n.key
    const other = byKey.get(isOut ? x.to : x.from)
    const last = x.conv.lines[x.conv.lines.length - 1]
    // conversations() puts this session on side a; any other node can be either
    const lastIsOther = last && (sideKey(last.by === 'a' ? x.conv.a : x.conv.b) !== n.key)
    const facts = `${x.count} message${x.count === 1 ? '' : 's'} · ${ago(x.lastAt, now)}${x.isAnswered ? '' : ' · not answered yet'}`
    rows.push(
      <Box key={`l${i}`} flexDirection="column" marginTop={i === 0 ? 1 : 0}>
        <Text key="h" wrap="truncate-end">
          <Text color={ORANGE}>{isOut ? '↗ ' : '↙ '}</Text>
          <Text color={IVORY}>{sp(`${isOut ? 'to' : 'from'} ${other ? label(other.side) : '?'}`)}</Text>
          <Text color={DIM}>{sp(`  ${facts}`)}</Text>
        </Text>
        {last ? (
          <Text key="m" wrap="truncate-end">
            <Text color={DIM}>{sp(`  ${lastIsOther ? `${other ? label(other.side) : '?'}: ` : ''}`)}</Text>
            <Text color={GRAY}>{sp(oneLine(last.text))}</Text>
          </Text>
        ) : null}
      </Box>,
    )
  })

  let actions: RenderChildren
  if (n.isSelf) {
    actions = null
  } else if (!canResume(s)) {
    actions = <Text key="x" color={DIM}>{s.address && !s.address.startsWith('uds:') ? 'remote session, not on this machine' : 'session id unknown: cannot reopen it'}</Text>
  } else if (st) {
    actions = [<Text key="x" color={DIM}>{sp('still running  ')}</Text>, <Button key="copy" label="copy command" hover={{ color: ORANGE }} onPress={noop} />]
  } else {
    actions = [<Button key="open" label={sp('Open ↗')} hotkey="o" hover={{ color: ORANGE }} onPress={noop} />, <Text key="g">{' '}</Text>, <Button key="copy" label="copy command" hover={{ color: ORANGE }} onPress={noop} />]
  }

  return (
    <Box key="detail" flexDirection="column" borderStyle="round" borderColor={ORANGE} paddingX={1} marginBottom={1}>
      {rows}
      {actions ? (
        <Box key="act" flexDirection="row" marginTop={1}>
          {actions}
        </Box>
      ) : null}
    </Box>
  )
}

/** Reads the registry and every session's log again. */
async function reread($: EngineInterface): Promise<void> {
  const [id, cwd, configDir, homeDir, profile] = await Promise.all([
    $.session.id(),
    $.session.cwd(),
    $.env.get('CLAUDE_CONFIG_DIR'),
    $.env.get('HOME'),
    $.env.get('USERPROFILE'),
  ])
  home = (homeDir ?? profile ?? '').replace(/\\/g, '/')
  const cfg = (configDir ?? `${home}/.claude`).replace(/\\/g, '/')
  const dir = `${cfg}/sessions`
  const entries = await $.fs.list(dir).catch(() => [])
  const texts = await Promise.all(
    entries.filter(f => f.kind === 'file' && f.name.endsWith('.json')).map(f => $.fs.read(`${dir}/${f.name}`).then(t => (typeof t === 'string' ? t : ''), () => '')),
  )
  live = parseRegistry(texts)
  const self = findSelf(live, id, cwd)
  me = self ? sideOf(self) : { id, cwd }

  const logs: [string, Log][] = []
  for (const k of await $.store.keys().catch(() => [] as string[])) {
    if (!k.startsWith(PREFIX)) continue
    const l = asLog(await $.store.get(k).catch(() => undefined))
    if (l) logs.push([k, l])
  }
  const now = await $.clock.now()
  const old = new Set(stale(logs, now, keepDays))
  for (const k of old) await $.store.delete(k).catch(() => undefined)
  convs = conversations(
    logs.filter(([k]) => !old.has(k)).map(([, l]) => l),
    id,
  )

  // a registry file outlives a crashed process: ask the pid
  const alive = new Set<string>()
  const ids = new Set(convs.flatMap(c => [c.a.id, c.b.id]).filter((x): x is string => !!x && x !== id))
  for (const l of live) {
    if (!ids.has(l.sessionId)) continue
    const ok = await $.process
      .run(['kill', '-0', String(l.pid)], { timeoutMs: 2000 })
      .then(res => res.exitCode === 0, () => true)
    if (ok) alive.add(l.sessionId)
  }
  running = alive
  // a resumed session gets a new name: show the one it has now
  for (const c of convs) {
    for (const side of [c.a, c.b]) {
      const row = side.id && alive.has(side.id) ? live.find(l => l.sessionId === side.id) : undefined
      if (row?.name) side.name = row.name
    }
  }
}

/** Appends to this session's log, one write at a time so a send and a reply never overwrite each other. */
async function write($: EngineInterface, peer: Side, from: 'self' | 'peer', text: string): Promise<void> {
  const id = await $.session.id()
  const now = await $.clock.now()
  const key = `${PREFIX}${id}`
  const turn = writing.then(async () => {
    const log = asLog(await $.store.get(key)) ?? emptyLog(me, now)
    await $.store.set(key, record(log, me, peer, { at: now, from, text }, now))
  })
  writing = turn.catch(() => undefined)
  await turn
  if (isOpen) {
    await reread($)
    $.ui.invalidate('ui.render')
  }
}

/** `running · idle`, `running · busy`, or undefined for a closed session. */
function state(s: Side): string | undefined {
  if (!s.id || !running.has(s.id)) return undefined
  const l = live.find(x => x.sessionId === s.id)
  return `running${l?.status ? ` · ${l.status}` : ''}${l?.tmux ? ` · tmux ${l.tmux.split(':')[0]}` : ''}`
}

/** Starts `cmd` in a new terminal the way `how` says; resolves where it did, or undefined. */
async function openTerminal(
  $: EngineInterface,
  how: How,
  side: Side & { id: string; cwd: string },
  cmd: string,
): Promise<string | undefined> {
  if (how === 'copy') return undefined
  try {
    if (how === 'tmux' || (how === 'auto' && (await $.env.get('TMUX')))) {
      const res = await $.process.run(['tmux', 'new-window', '-c', tmuxLiteral(side.cwd), '-n', windowName(label(side)), 'claude', '--resume', side.id])
      if (res.exitCode === 0) return 'a new tmux window'
      if (how === 'tmux') return undefined
    }
    const os = await $.process.run(['uname', '-s'])
    if (os.stdout.trim() !== 'Darwin') return undefined
    if (how === 'iTerm') {
      const res = await $.process.run([
        'osascript',
        '-e',
        'tell application "iTerm" to create window with default profile',
        '-e',
        `tell application "iTerm" to tell current session of current window to write text ${appleQuote(cmd)}`,
        '-e',
        'tell application "iTerm" to activate',
      ])
      return res.exitCode === 0 ? 'iTerm' : undefined
    }
    const res = await $.process.run(['osascript', '-e', `tell application "Terminal" to do script ${appleQuote(cmd)}`, '-e', 'tell application "Terminal" to activate'])
    return res.exitCode === 0 ? 'Terminal' : undefined
  } catch {
    return undefined
  }
}

/** Desktop and the remote surfaces collapse runs of spaces; keep them. */
function spacer(surface: RenderSurface): (s: string) => string {
  return surface === 'terminal' ? s => s : s => s.replace(/ /g, ' ')
}

// Run with: claude plugin test productivity/session-chats
import { describe, expect, test } from 'claude-code/testing'
import type { On } from 'claude-code'
import {
  bareAddress,
  canResume,
  conversations,
  emptyLog,
  findLive,
  findSelf,
  hash,
  label,
  looksLikeSession,
  parseEnvelope,
  parseRegistry,
  record,
  resumeCommand,
  sideOf,
  stale,
  tmuxLiteral,
  windowName,
} from '../hooks/chats.ts'
import type { Conversation, Log, Side } from '../hooks/chats.ts'
import { buildGraph, tree } from '../hooks/graph.ts'

const HOME = '/Users/me'
const A_ID = '0efbafed-9090-44a1-9bdc-dfb80fd148bd'
const B_ID = 'c10858a1-ef35-4665-82ee-1a124da101d7'

/** Two registry files as Claude Code 2.1.312 writes them (`~/.claude/sessions/<pid>.json`). */
const REG_A = JSON.stringify({ pid: 2263, sessionId: A_ID, cwd: `${HOME}/app`, kind: 'interactive', tmux: 'A:@0.%0', messagingSocketPath: '/tmp/cc-socks/2263.sock', name: 'app-d4', status: 'idle' })
const REG_B = JSON.stringify({ pid: 2266, sessionId: B_ID, cwd: `${HOME}/api`, kind: 'interactive', messagingSocketPath: '/tmp/cc-socks/2266.sock', name: 'api-f2', status: 'busy' })

const A: Side = { id: A_ID, name: 'app-d4', address: 'uds:/tmp/cc-socks/2263.sock', cwd: `${HOME}/app` }
const B: Side = { id: B_ID, name: 'api-f2', address: 'uds:/tmp/cc-socks/2266.sock', cwd: `${HOME}/api` }

describe('reading what the engine hands over', () => {
  test('a cross-session envelope gives the sender and the body', () => {
    const env = parseEnvelope('<cross-session-message from="uds:/tmp/cc-socks/2266.sock" from-name="api-f2" from-mode="prompting">\nlisto, el deploy pasó\n</cross-session-message>')
    expect(env).toEqual({ from: 'uds:/tmp/cc-socks/2266.sock', name: 'api-f2', body: 'listo, el deploy pasó' })
  })

  test('anything else is not a cross-session message', () => {
    expect(parseEnvelope('<task-notification>done</task-notification>')).toBeUndefined()
    expect(parseEnvelope('hola')).toBeUndefined()
  })

  test('the registry maps a name or a socket address to the session', () => {
    const live = parseRegistry([REG_A, REG_B, '{not json', '{"pid":1}'])
    expect(live.length).toBe(2)
    expect(findLive(live, 'api-f2')?.sessionId).toBe(B_ID)
    expect(findLive(live, 'api-f2 [d74acb]')?.sessionId).toBe(B_ID)
    expect(findLive(live, 'uds:/tmp/cc-socks/2263.sock')?.sessionId).toBe(A_ID)
    expect(findLive(live, 'researcher')).toBeUndefined()
    expect(sideOf(findSelf(live, A_ID, `${HOME}/app`)!)).toEqual(A)
  })

  test('a subagent name is not a session; an address or a live name is', () => {
    const live = parseRegistry([REG_A, REG_B])
    expect(looksLikeSession('researcher', live)).toBe(false)
    expect(looksLikeSession('api-f2', live)).toBe(true)
    expect(looksLikeSession('uds:/tmp/cc-socks/9.sock', [])).toBe(true)
    expect(looksLikeSession('session_01abc', [])).toBe(true)
    expect(bareAddress('api-f2 [d74acb]')).toBe('api-f2')
  })
})

describe('the record', () => {
  test('both sides logging the same exchange make one conversation, each message once', () => {
    let a: Log = emptyLog(A, 1000)
    a = record(a, A, B, { at: 1000, from: 'self', text: '¿corriste los tests?' }, 1000)
    a = record(a, A, B, { at: 5000, from: 'peer', text: 'sí, 42 verdes' }, 5000)
    let b: Log = emptyLog(B, 1000)
    b = record(b, B, A, { at: 1010, from: 'peer', text: '¿corriste los tests?' }, 1010)
    b = record(b, B, A, { at: 4990, from: 'self', text: 'sí, 42 verdes' }, 4990)

    const [c, ...rest] = conversations([a, b], A_ID)
    expect(rest.length).toBe(0)
    expect(c!.a.id).toBe(A_ID)
    expect(c!.b.id).toBe(B_ID)
    expect(c!.lines.map(l => `${l.by}:${l.text}`)).toEqual(['a:¿corriste los tests?', 'b:sí, 42 verdes'])

    // seen from B, B is side a
    const [fromB] = conversations([a, b], B_ID)
    expect(fromB!.a.id).toBe(B_ID)
    expect(fromB!.lines[0]!.by).toBe('b')
  })

  test('a peer known only by its socket joins the one the other log knows by id', () => {
    let a: Log = emptyLog(A, 0)
    a = record(a, A, { address: B.address, name: 'api-f2' }, { at: 10, from: 'self', text: 'hola' }, 10)
    let b: Log = emptyLog(B, 0)
    b = record(b, B, A, { at: 11, from: 'peer', text: 'hola' }, 11)
    const list = conversations([a, b], A_ID)
    expect(list.length).toBe(1)
    expect(list[0]!.b.cwd).toBe(`${HOME}/api`)
  })

  test('a long message is cut and old ones roll off', () => {
    let a: Log = emptyLog(A, 0)
    for (let i = 0; i < 50; i++) a = record(a, A, B, { at: i, from: 'self', text: `m${i}` }, i)
    a = record(a, A, B, { at: 99, from: 'self', text: 'x'.repeat(2000) }, 99)
    const c = a.chats[0]!
    expect(c.messages.length).toBe(40)
    expect(Array.from(c.messages[39]!.text).length).toBe(600)
  })

  test('a claimed name never merges two senders, and control sequences are dropped', () => {
    let a: Log = emptyLog(A, 0)
    a = record(a, A, B, { at: 1, from: 'peer', text: 'real' }, 1)
    a = record(a, A, { address: 'session_01remote', name: 'api-f2' }, { at: 2, from: 'peer', text: 'fake\x1b]0;title\x07 \x1b[31mred\x1b[0m\nline' }, 2)
    expect(a.chats.length).toBe(2)
    expect(a.chats[0]!.messages[0]!.text).toBe('fake red\nline')
  })

  test('a log not written for keepDays is stale', () => {
    const old = { ...emptyLog(A, 0), updatedAt: 0 }
    const fresh = { ...emptyLog(B, 0), updatedAt: 89 * 86_400_000 }
    expect(stale([['log:a', old], ['log:b', fresh]], 91 * 86_400_000, 90)).toEqual(['log:a'])
  })
})

