describe('the graph', () => {
  const C: Side = { id: '7d3c1f00-1111-4222-8333-444455556666', name: 'worker-72', cwd: `${HOME}/worker` }
  const conv = (a: Side, b: Side, by: ('a' | 'b')[], at: number): Conversation => ({
    key: [`id:${a.id}`, `id:${b.id}`].sort().join('|'),
    a,
    b,
    firstAt: at,
    lastAt: at + by.length,
    lines: by.map((x, i) => ({ at: at + i, by: x, text: `m${i}` })),
  })
  const convs = [conv(A, B, ['a', 'b'], 1), conv(B, C, ['a'], 5)]

  test('the first writer points at the other; an unanswered link is marked', () => {
    const g = buildGraph(convs, new Set([B_ID]), A_ID, false)
    expect(g.nodes.length).toBe(3)
    expect(g.edges.map(e => [e.from, e.to, e.isAnswered])).toEqual([
      [`id:${A_ID}`, `id:${B_ID}`, true],
      [`id:${B_ID}`, `id:${C.id}`, false],
    ])
    expect(g.nodes.find(n => n.isSelf)?.sub).toBe('this session')
    // newest first: a resumed session's new name wins over the one in an older conversation
    const renamed = buildGraph([conv(A, { ...B, name: 'api-9c' }, ['a'], 20), ...convs], new Set(), A_ID, false)
    expect(renamed.nodes.find(n => n.side.id === B_ID)?.side.name).toBe('api-9c')
  })

  test('Active keeps the running sessions and the links between them', () => {
    const g = buildGraph(convs, new Set([B_ID]), A_ID, true)
    expect(g.nodes.map(n => n.side.name).sort()).toEqual(['api-f2', 'app-d4'])
    expect(g.edges.length).toBe(1)
  })

  test('the tree starts at this session and draws each link once', () => {
    const rows = tree(buildGraph(convs, new Set(), A_ID, false))
    expect(rows.map(r => `${r.prefix}${r.arrow}${r.node.side.name}`)).toEqual(['app-d4', '└─→api-f2', '    └─⇢worker-72'])
  })

  test('a link to a session already in the tree is a reference, and other groups get their own root', () => {
    const D: Side = { id: '1d3c1f00-1111-4222-8333-444455556666', name: 'infra-3c', cwd: '/tmp/infra' }
    const E: Side = { id: '2d3c1f00-1111-4222-8333-444455556666', name: 'ci-88', cwd: '/tmp/ci' }
    const rows = tree(buildGraph([...convs, conv(C, A, ['a', 'b'], 9), conv(D, E, ['a', 'b'], 3)], new Set(), A_ID, false))
    const text = rows.map(r => `${r.prefix}${r.arrow}${r.node.side.name}`)
    expect(text[0]).toBe('app-d4')
    expect(text.filter(t => t.includes('↺')).length).toBe(1)
    expect(rows.filter(r => !r.isRef).map(r => r.node.side.name).sort()).toEqual(['api-f2', 'app-d4', 'ci-88', 'infra-3c', 'worker-72'])
    expect(text.slice(-2)).toEqual(['infra-3c', '└─→ci-88'])
    // every link appears exactly once
    expect(rows.filter(r => r.edge).length).toBe(4)
  })

  test('a peer name has no control bytes', () => {
    expect(label({ name: 'x\u0001\u001b[31my' })).toBe('xy')
  })
})

const PANE = {
  plugin: 'session-chats',
  component: 'Pane',
  requestId: 'session-chats',
  props: { title: 'chats', isFocused: false, bodyColumns: 72, placement: 'dock', scroll: { offset: 0, bodyRows: 40 }, view: {} },
} as const

/** The engine for one session of the mod: A, with B's registry file and a store kept in memory. */
function engine(on: On, files: Record<string, string>) {
  const store: Record<string, unknown> = {}
  const runs: string[][] = []
  on('session.id', () => ({ value: A_ID }))
  on('session.cwd', () => ({ value: `${HOME}/app` }))
  on('env.get', (_, e) => ({ value: e.name === 'HOME' ? HOME : e.name === 'TMUX' ? '/tmp/tmux-501/default,1,0' : undefined }))
  on('clock.now', () => ({ value: 10_000 }))
  on('fs.list', (_, e) => ({
    value: Object.keys(files)
      .filter(p => p.startsWith(e.path + '/'))
      .map(p => ({ name: p.slice(e.path.length + 1), kind: 'file', size: 1, mtimeMs: 0, isLink: false })),
  }))
  on('fs.read', (_, e) => ({ value: files[e.path] }))
  on('store.keys', () => ({ value: Object.keys(store) }))
  on('store.get', (_, e) => ({ value: store[e.key] }))
  on('store.set', (_, e) => {
    store[e.key] = JSON.parse(JSON.stringify(e.value))
    return { value: undefined }
  })
  on('store.delete', (_, e) => {
    delete store[e.key]
    return { value: undefined }
  })
  on('process.run', (_, e) => {
    runs.push([...e.argv])
    return { value: { exitCode: e.argv[0] === 'kill' ? 1 : 0, stdout: '', stderr: '', isStdoutTruncated: false, isStderrTruncated: false } }
  })
  on('command.register', () => ({ value: { command: 'chats' } }))
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('ui.copy', () => ({ value: { isCopied: true } }))
  on('ui.toast', () => ({ value: undefined }))
  on('session.send', () => ({ isDelivered: true }))
  on('session.receive', (_, e) => ({ text: e.text }))
  return { store, runs }
}

