/* @jsx h */
/**
 * session-time-machine — Claude Mod
 *
 * `/timemachine` opens a pane with the session's timeline: every prompt, tool
 * call and turn end, read from the session's own transcript. Press a point
 * (or run `/timemachine fork <n> <instruction>`) and the mod writes a copy of
 * the transcript cut at that point under a new session id, with the
 * `claude --resume <id> "<instruction>"` command that continues it, copied to
 * the clipboard. The original session is not touched.
 *
 * The mod API has no call that forks the live session, so the fork is a new
 * session you open yourself; see the README.
 *
 * Hooks: `session.start` registers the command, `command.run` opens the pane,
 * lists or forks, `turn.complete` re-reads the transcript,
 * `ui.render` on Pane draws it.
 *
 * Options:
 *   copyCommand: boolean  copy the resume command to the clipboard (default true)
 */
import type { Register } from 'claude-code'
import {
  buildTimeline,
  clip,
  mainChain,
  forkMessage,
  planFork,
  newSessionId,
  parseArgs,
  parseRows,
  transcriptPath,
  type Point,
  type Row,
} from './transcript.ts'
import { MUTATING, loadSnapshots, openInDesktop, openInTerminal, restoreWorktree, snapshotFor, takeSnapshot, type Run } from './snapshots.ts'

const PANE = 'time-machine'
const C = {
  accent: '#58a6ff',
  prompt: '#5eb1ff',
  turn: '#b392f0',
  ink: '#e6edf3',
  chip: '#2a313c',
  rail: '#4b5563',
  armed: '#1f3a5f',
  hover: '#2d3b52',
  bad: '#f85149',
  tool: { Bash: '#7ee787', Edit: '#f2cc60', Read: '#6cb6c9', Web: '#ff9d5c', Agent: '#f778ba', Mcp: '#d2a8ff', Other: '#8b949e' },
}

const toolColor = (name = ''): string =>
  /^(Edit|Write|MultiEdit|NotebookEdit)$/.test(name) ? C.tool.Edit
  : name === 'Bash' ? C.tool.Bash
  : /^(Read|Grep|Glob|LS)$/.test(name) ? C.tool.Read
  : /^Web/.test(name) ? C.tool.Web
  : /^(Agent|Task)$/.test(name) ? C.tool.Agent
  : name.startsWith('mcp__') ? C.tool.Mcp
  : C.tool.Other

let chain: Row[] = []
let points: Point[] = []
let armed: number | undefined
let offset = 0
let isExpanded = false
let forkResult: string | undefined
let snaps = new Map<string, string>()
let problem: string | undefined

const ingest = (text: string) => {
  problem = undefined
  chain = mainChain(parseRows(text))
  points = buildTimeline(chain)
  offset = Math.max(0, points.length - 12)
}

const fail = (err: unknown) => {
  problem = `cannot read the transcript (${err instanceof Error ? err.message : String(err)}); the read limit is 4 MiB`
}

export const register: Register = (on, options) => {
  const isCopying = options.copyCommand !== false
  const isSnapshotting = options.snapshots !== false
  const isOpening = options.openTerminal !== false

  /** What a helper needs from `$`, as plain values and closures: the engine refuses `$` itself passed to a function. */
  type Ctx = {
    cwd: string
    sid: string
    dir: string
    run: Run
    read: (path: string) => Promise<string>
    write: (path: string, text: string) => Promise<void>
    copy: (text: string) => Promise<boolean>
    repaint: () => void
  }

  const reread = async (c: Ctx) => {
    await c.read(transcriptPath(c.dir, c.cwd, c.sid)).then(ingest, fail)
    snaps = await loadSnapshots(c.run, c.cwd, c.sid)
  }
  const snapshot = async (c: Ctx, key: string) => {
    if (!isSnapshotting) return
    const id = await takeSnapshot(c.run, c.cwd, c.sid, key)
    if (id) snaps.set(key, id)
  }

  /** Forks at point `n`: restores the files into a git worktree when a snapshot exists, writes the cut session, opens it. */
  const forkAt = async (c: Ctx, n: number, instruction: string): Promise<string> => {
    const { cwd, dir, run } = c
    const newId = newSessionId()
    const commit = snapshotFor(points, n, snaps)
    const tree = commit ? await restoreWorktree(run, cwd, commit, newId.slice(0, 8)) : undefined
    const note = tree
      ? `⏱ Forked at point ${n}. Files are restored in this worktree (branch ${tree.branch}). Paths from earlier in this session point at the original checkout: use the matching path under the current directory instead.`
      : ''
    // an instruction has to reach the model, which only the resume command's message does; without one Desktop can take it
    const toDesktop = isOpening && !instruction.trim()
    const plan = planFork(chain, points, n, toDesktop ? '' : [note, instruction].filter(Boolean).join('\n\n'), tree?.path ?? cwd, dir, newId, toDesktop ? note : '')
    if ('error' in plan) {
      if (tree) await run(['git', 'worktree', 'remove', '--force', tree.path], { cwd }).catch(() => undefined)
      return `time machine: ${plan.error}`
    }
    await c.write(plan.file, plan.body)
    armed = undefined
    c.repaint()
    const inDesktop = toDesktop && (await openInDesktop(run, tree?.path ?? cwd, plan.newId))
    const inTerminal = !inDesktop && isOpening && (await openInTerminal(run, plan.command))
    const opened = inDesktop || inTerminal
    const copied = !opened && isCopying ? await c.copy(plan.command).catch(() => false) : false
    return [
      `Forked at point ${plan.n} (${plan.label}): ${plan.kept} rows kept.`,
      tree ? `Files restored in worktree ${tree.path} (branch ${tree.branch}); your checkout is untouched.` : commit === undefined ? 'No file snapshot for this point (not a git project, or taken before the mod was loaded): conversation only.' : 'Could not create the worktree: conversation only.',
      inDesktop ? 'Opened in Claude Desktop.' : inTerminal ? 'Opened in a new Terminal window.' : `New session ${plan.newId}${copied ? ', resume command copied' : ''}. In a new terminal:\n${plan.command}`,
    ].join('\n')
  }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'timemachine',
      description: 'Timeline of this session; fork it from any point with a new instruction',
    })
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    if (isSnapshotting && !e.text.trimStart().startsWith('/')) {
      const c: Ctx = {
        cwd: await $.session.cwd(),
        sid: await $.session.id(),
        dir: (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? '~'}/.claude`,
        run: (argv, init) => $.process.run(argv, init),
        read: path => $.fs.read(path),
        write: (path, text) => $.fs.write(path, text),
        copy: async text => (await $.ui.copy({ text })).isCopied === true,
        repaint: () => $.ui.invalidate('ui.render'),
      }
      await reread(c)
      await snapshot(c, `prompt-${points.filter(p => p.kind === 'prompt').length + 1}`)
    }
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    if (isSnapshotting && e.agentId === undefined && MUTATING.test(String(e.tool)) && e.tool_use_id) {
      const c: Ctx = {
        cwd: await $.session.cwd(),
        sid: await $.session.id(),
        dir: (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? '~'}/.claude`,
        run: (argv, init) => $.process.run(argv, init),
        read: path => $.fs.read(path),
        write: (path, text) => $.fs.write(path, text),
        copy: async text => (await $.ui.copy({ text })).isCopied === true,
        repaint: () => $.ui.invalidate('ui.render'),
      }
      await snapshot(c, `tool-${e.tool_use_id}`)
    }
    return result
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      const c: Ctx = {
        cwd: await $.session.cwd(),
        sid: await $.session.id(),
        dir: (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? '~'}/.claude`,
        run: (argv, init) => $.process.run(argv, init),
        read: path => $.fs.read(path),
        write: (path, text) => $.fs.write(path, text),
        copy: async text => (await $.ui.copy({ text })).isCopied === true,
        repaint: () => $.ui.invalidate('ui.render'),
      }
      await reread(c)
      await snapshot(c, `turn-${points.filter(p => p.kind === 'prompt').length}`)
      $.ui.status(points.length > 0 ? `⏱ ${points.length} points · /timemachine` : undefined)
      $.ui.invalidate('ui.render')
    }
    return next(e)
  })

  on('command.run', { command: 'timemachine' }, async ($, e) => {
    const args = parseArgs(e.args)
    if (args.kind === 'error') return { text: args.text }
    const c: Ctx = {
        cwd: await $.session.cwd(),
        sid: await $.session.id(),
        dir: (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? '~'}/.claude`,
        run: (argv, init) => $.process.run(argv, init),
        read: path => $.fs.read(path),
        write: (path, text) => $.fs.write(path, text),
        copy: async text => (await $.ui.copy({ text })).isCopied === true,
        repaint: () => $.ui.invalidate('ui.render'),
      }
    await reread(c)
    if (problem) return { text: `time machine: ${problem}` }

    if (args.kind === 'open') {
      await $.ui.open({ id: PANE, title: 'Time machine', focus: true })
      return { text: `Time machine: ${points.length} points. Press one to arm a fork, or /timemachine fork <n> <instruction>.` }
    }
    if (args.kind === 'list') {
      return { text: points.map(p => `${String(p.n).padStart(3)}  ${p.label}`).join('\n') || 'No points yet.' }
    }
    return { text: await forkAt(c, args.n, args.instruction) }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    // header, count chips, rule, footer bar and the paging row take 9 of the pane's rows
    const room = Math.max(3, Math.floor(((e.viewport?.rows ?? 24) - 9) / (isExpanded ? 2 : 1)))
    const last = Math.max(0, points.length - room)
    const start = Math.min(Math.max(offset, 0), last)
    const shown = points.slice(start, start + room)
    // the pane's own width: viewport.columns is the whole surface (95 reported for a 150-column terminal)
    const cols = e.props.bodyColumns || (e.viewport?.columns ?? 60)
    const wide = Math.max(16, cols - 12)
    const turns = points.filter(p => p.kind === 'prompt').length
    const tools = points.filter(p => p.kind === 'tool').length
    const pick = points.find(p => p.n === armed)
    const repaint = () => $.ui.invalidate('ui.render')
    const files = pick ? (snapshotFor(points, pick.n, snaps) ? 'Files: restored from a git snapshot into a new worktree.' : 'Files: no snapshot for this point, so the fork is conversation only.') : ''
    const preview = (
    <Box key="foot" flexDirection="column" marginTop={1} borderStyle="round" borderColor={pick ? C.accent : C.rail} paddingX={1}>
      {pick ? (
        <Box key="armed" flexDirection="column">
          <Text bold color={C.accent}>{`Fork from #${pick.n}`}</Text>
          <Text dimColor>{`${pick.kind === 'prompt' ? 'The session is cut before this prompt' : pick.kind === 'turn' ? 'The session is cut after this turn' : `The session is cut after this ${pick.tool ?? 'tool'} call`}:`}</Text>
          <Text color={C.ink} wrap="wrap">{clip(pick.full, 900)}</Text>
          <Text dimColor wrap="wrap">{files}</Text>
          <Box key="forkrow" flexDirection="row" marginTop={1}>
            <Button
              key="forknow"
              variant="primary"
              onPress={async () => {
                forkResult = 'Forking…'
                repaint()
                forkResult = await forkAt({
                  cwd: await $.session.cwd(),
                  sid: await $.session.id(),
                  dir: (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? '~'}/.claude`,
                  run: (argv, init) => $.process.run(argv, init),
                  read: path => $.fs.read(path),
                  write: (path, text) => $.fs.write(path, text),
                  copy: async text => (await $.ui.copy({ text })).isCopied === true,
                  repaint,
                }, pick.n, '')
                repaint()
              }}
            >
              ⎇ Fork here
            </Button>
          </Box>
          <Text dimColor>{`Fork here opens the new session for you; or type /timemachine fork ${pick.n} <instruction> to start it with a message`}</Text>
        </Box>
      ) : (
        <Text dimColor>Press any point to fork the session from there with a new instruction.</Text>
      )}
    </Box>
    )
    return (
      <Box key="tm" flexDirection="column">
        <Box key="head" flexDirection="row">
          <Text bold color={C.accent}>
            {'⏱ Time machine'}
          </Text>
        </Box>
        <Box key="chips" flexDirection="row" marginTop={1}>
          <Text color={C.ink} backgroundColor={C.chip}>{` ${points.length} points `}</Text>
          <Text>{' '}</Text>
          <Text color={C.prompt} backgroundColor={C.chip}>{` ${turns} prompts `}</Text>
          <Text>{' '}</Text>
          <Text color={C.tool.Bash} backgroundColor={C.chip}>{` ${tools} calls `}</Text>
        </Box>
        <Text color={C.rail}>{'─'.repeat(Math.max(10, cols - 2))}</Text>
        {forkResult && (
          <Box key="result" flexDirection="column" marginTop={1} borderStyle="round" borderColor={C.tool.Bash} paddingX={1}>
            <Text wrap="wrap" color={C.ink}>{forkResult}</Text>
            <Button
              key="dismiss"
              hover={{ color: C.bad }}
              onPress={() => {
                forkResult = undefined
                repaint()
              }}
            >
              ✕ dismiss
            </Button>
          </Box>
        )}
        {pick && preview}
        {problem && <Text color={C.bad}>{problem}</Text>}
        {points.length === 0 && !problem && <Text dimColor>Nothing recorded yet: send a prompt, then reload.</Text>}
        {shown.map(p => {
          const isArmed = armed === p.n
          const tint = p.kind === 'prompt' ? C.prompt : p.kind === 'turn' ? C.turn : toolColor(p.tool)
          const rail = p.kind === 'prompt' ? '┏' : p.kind === 'turn' ? '┗' : '┃'
          const glyph = p.kind === 'prompt' ? '●' : p.kind === 'turn' ? '■' : '◆'
          const kind = p.kind === 'prompt' ? `prompt ${p.turn}` : p.kind === 'turn' ? 'turn end' : (p.tool ?? 'tool')
          return (
            <Box key={`r${p.n}`} flexDirection="column" backgroundColor={isArmed ? C.armed : undefined}>
              <Box flexDirection="row">
                <Text dimColor>{String(p.n).padStart(3)} </Text>
                <Text color={C.rail}>{rail}</Text>
                <Text bold color={tint}>{` ${glyph} `}</Text>
                <Button
                  key={`p${p.n}`}
                  plain
                  hover={{ backgroundColor: C.hover, bold: true }}
                  onPress={() => {
                    armed = p.n
                    repaint()
                    void $.prompt.fill({ text: `/timemachine fork ${p.n} ` }).catch(() => undefined)
                  }}
                >
                  {clip(`${kind}  ${p.detail}`, wide)}
                </Button>
              </Box>
              {isExpanded && (
                <Box key={`d${p.n}`} flexDirection="row">
                  <Text>{'      '}</Text>
                  <Text color={C.rail}>{p.kind === 'tool' ? '┃ ' : '  '}</Text>
                  <Text dimColor wrap="wrap">{clip(p.full, wide * 3)}</Text>
                </Box>
              )}
            </Box>
          )
        })}
        {!pick && preview}
        <Box key="nav" flexDirection="row" marginTop={1}>
          <Button
            key="older"
            hover={{ color: C.accent }}
            onPress={() => {
              offset = Math.max(0, start - room)
              repaint()
            }}
          >
            ↑ older
          </Button>
          <Text>{'   '}</Text>
          <Button
            key="newer"
            hover={{ color: C.accent }}
            onPress={() => {
              offset = Math.min(last, start + room)
              repaint()
            }}
          >
            ↓ newer
          </Button>
          <Text>{'   '}</Text>
          <Button
            key="expand"
            hover={{ color: C.accent }}
            onPress={() => {
              isExpanded = !isExpanded
              repaint()
            }}
          >
            {isExpanded ? '⤡ collapse' : '⤢ expand'}
          </Button>
          <Text>{'   '}</Text>
          <Button
            key="reload"
            hover={{ color: C.accent }}
            onPress={async () => {
              await reread({
                cwd: await $.session.cwd(),
                sid: await $.session.id(),
                dir: (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? '~'}/.claude`,
                run: (argv, init) => $.process.run(argv, init),
                read: path => $.fs.read(path),
                write: (path, text) => $.fs.write(path, text),
                copy: async text => (await $.ui.copy({ text })).isCopied === true,
                repaint: () => $.ui.invalidate('ui.render'),
              })
              repaint()
            }}
          >
            ⟳ reload
          </Button>
          {pick && (
            <Button
              key="clear"
              hover={{ color: C.bad }}
              onPress={() => {
                armed = undefined
                repaint()
              }}
            >
              {'   ✕ clear'}
            </Button>
          )}
        </Box>
      </Box>
    )
  })
}

/**
 * Working-tree snapshots for session-time-machine.
 *
 * A snapshot is a git commit of the whole working tree (tracked, modified and
 * untracked files, .gitignore honored) built with a throwaway index, so the
 * person's index, branch and stash are never touched. Each one is pinned by a
 * ref under `refs/time-machine/<session-id>/`, which is also how a later run
 * finds them again: no state lives outside git.
 */
import type { Point } from './transcript.ts'

export type Run = (
  argv: readonly string[],
  init?: { cwd?: string; env?: Record<string, string>; timeoutMs?: number },
) => Promise<{ exitCode: number; stdout: string; stderr: string }>

/** Tools that can change files; the others leave the tree as the last snapshot had it. */
export const MUTATING = /^(Edit|Write|MultiEdit|NotebookEdit|Bash|PowerShell)$/

const IDENT = { GIT_AUTHOR_NAME: 'time-machine', GIT_AUTHOR_EMAIL: 'time-machine@localhost', GIT_COMMITTER_NAME: 'time-machine', GIT_COMMITTER_EMAIL: 'time-machine@localhost' }
const safe = (key: string): string => key.replace(/[^A-Za-z0-9_-]/g, '_')

export const refPrefix = (sessionId: string): string => `refs/time-machine/${safe(sessionId)}/`

/** The snapshot key of a point's own moment: before a prompt, after a tool call, after a turn. */
export function ownKey(p: Pick<Point, 'kind' | 'turn' | 'id'>): string | undefined {
  if (p.kind === 'prompt') return `prompt-${p.turn}`
  if (p.kind === 'turn') return `turn-${p.turn}`
  return p.id ? `tool-${safe(p.id)}` : undefined
}

/** The newest snapshot at or before a point: read-only tool calls take the last one that could have changed files. */
export function snapshotFor(points: readonly Point[], n: number, snaps: ReadonlyMap<string, string>): string | undefined {
  for (let i = points.findIndex(p => p.n === n); i >= 0; i--) {
    const key = ownKey(points[i]!)
    const hit = key ? snaps.get(key) : undefined
    if (hit) return hit
  }
  return undefined
}

/** Commits the working tree under `key`; resolves to the commit, or undefined outside a git repo or on any git failure. */
export async function takeSnapshot(run: Run, cwd: string, sessionId: string, key: string): Promise<string | undefined> {
  try {
    const top = await run(['git', 'rev-parse', '--show-toplevel'], { cwd })
    const dir = await run(['git', 'rev-parse', '--absolute-git-dir'], { cwd })
    if (top.exitCode !== 0 || dir.exitCode !== 0) return undefined
    const root = top.stdout.trim()
    const env = { ...IDENT, GIT_INDEX_FILE: `${dir.stdout.trim()}/time-machine-index` }
    const opts = { cwd: root, env, timeoutMs: 120_000 }
    const head = await run(['git', 'rev-parse', '-q', '--verify', 'HEAD'], { cwd: root })
    const parent = head.exitCode === 0 ? head.stdout.trim() : undefined
    if ((await run(parent ? ['git', 'read-tree', parent] : ['git', 'read-tree', '--empty'], opts)).exitCode !== 0) return undefined
    if ((await run(['git', 'add', '-A'], opts)).exitCode !== 0) return undefined
    const tree = await run(['git', 'write-tree'], opts)
    if (tree.exitCode !== 0) return undefined
    const commit = await run(['git', 'commit-tree', tree.stdout.trim(), ...(parent ? ['-p', parent] : []), '-m', `time-machine ${key}`], opts)
    const id = commit.stdout.trim()
    if (commit.exitCode !== 0 || !id) return undefined
    const ref = await run(['git', 'update-ref', `${refPrefix(sessionId)}${safe(key)}`, id], { cwd: root })
    return ref.exitCode === 0 ? id : undefined
  } catch {
    return undefined
  }
}

/** Every snapshot of the session, keyed as `takeSnapshot` named them. */
export async function loadSnapshots(run: Run, cwd: string, sessionId: string): Promise<Map<string, string>> {
  const out = new Map<string, string>()
  try {
    const prefix = refPrefix(sessionId)
    const res = await run(['git', 'for-each-ref', '--format=%(refname) %(objectname)', prefix], { cwd })
    if (res.exitCode !== 0) return out
    for (const line of res.stdout.split('\n')) {
      const [ref, id] = line.trim().split(' ')
      if (ref && id) out.set(ref.slice(prefix.length), id)
    }
  } catch {
    // not a repo: no snapshots
  }
  return out
}

export type Worktree = { path: string; branch: string }

/** A new worktree on its own branch at the snapshot, next to the project's other `.claude/worktrees`; undefined when git refuses. */
export async function restoreWorktree(run: Run, cwd: string, commit: string, tag: string): Promise<Worktree | undefined> {
  try {
    const top = await run(['git', 'rev-parse', '--show-toplevel'], { cwd })
    if (top.exitCode !== 0) return undefined
    const path = `${top.stdout.trim()}/.claude/worktrees/time-machine-${tag}`
    const branch = `time-machine/${tag}`
    const add = await run(['git', 'worktree', 'add', '-b', branch, path, commit], { cwd: top.stdout.trim() })
    return add.exitCode === 0 ? { path, branch } : undefined
  } catch {
    return undefined
  }
}

const appleQuote = (text: string): string => `"${text.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`

/** Opens `command` in a new Terminal window (macOS); resolves whether it did. */
export async function openInTerminal(run: Run, command: string): Promise<boolean> {
  try {
    const os = await run(['uname', '-s'])
    if (os.stdout.trim() !== 'Darwin') return false
    const res = await run(['osascript', '-e', `tell application "Terminal" to do script ${appleQuote(command)}`, '-e', 'tell application "Terminal" to activate'])
    return res.exitCode === 0
  } catch {
    return false
  }
}

/** Opens the saved session in Claude Desktop (`claude --desktop --resume`, which wants a terminal, so `script` gives it one); resolves whether Desktop took it. */
export async function openInDesktop(run: Run, cwd: string, sessionId: string): Promise<boolean> {
  try {
    const os = await run(['uname', '-s'])
    if (os.stdout.trim() !== 'Darwin') return false
    const res = await run(['script', '-q', '/dev/null', 'claude', '--desktop', '--resume', sessionId], { cwd, timeoutMs: 60_000 })
    return res.exitCode === 0 && /Opening session/.test(res.stdout)
  } catch {
    return false
  }
}

/**
 * Pure helpers for session-time-machine: no `$`, no I/O, so the tests run them
 * on plain strings. A Claude Code transcript is a JSONL file of rows chained by
 * `parentUuid`; the live conversation is the chain that ends at the last row
 * written. A fork keeps a prefix of that chain, which is why a "point in time"
 * here is just a count of chain rows to keep.
 */

export type Row = Record<string, any>

export type PointKind = 'prompt' | 'tool' | 'turn'

export type Point = {
  /** 1-based, as `/timemachine fork <n>` names it */
  n: number
  kind: PointKind
  /** 1-based number of the user prompt this point belongs to (0 before the first) */
  turn: number
  label: string
  /** the tool's name on a tool point, what colors its glyph */
  tool?: string
  /** the tool_use id of a tool point: the key of its working-tree snapshot */
  id?: string
  /** the label without its kind: the prompt's text, the call's argument, the turn's last reply */
  detail: string
  /** the whole text behind the label (a prompt, a command, a reply), capped at 2000 characters */
  full: string
  /** how many rows of the chain a fork from here keeps (before closing tool pairs) */
  keep: number
}

const CHAIN_TYPES = new Set(['user', 'assistant', 'system', 'attachment'])

export function parseRows(text: string): Row[] {
  const rows: Row[] = []
  for (const line of text.split('\n')) {
    if (!line.trim()) continue
    try {
      const row = JSON.parse(line)
      if (row && typeof row === 'object') rows.push(row)
    } catch {
      // a half-written last line while a turn streams
    }
  }
  return rows
}

/** The live conversation: the parentUuid chain back from the last row written, oldest first. */
export function mainChain(rows: readonly Row[]): Row[] {
  const byUuid = new Map<string, Row>()
  let leaf: Row | undefined
  for (const row of rows) {
    if (typeof row.uuid !== 'string' || !CHAIN_TYPES.has(row.type) || row.isSidechain === true) continue
    byUuid.set(row.uuid, row)
    leaf = row
  }
  const chain: Row[] = []
  const seen = new Set<string>()
  for (let row = leaf; row && !seen.has(row.uuid); row = byUuid.get(row.parentUuid)) {
    seen.add(row.uuid)
    chain.push(row)
  }
  return chain.reverse()
}

const blocks = (row: Row): any[] => (Array.isArray(row.message?.content) ? row.message.content : [])

/** The text a person typed, or undefined for a tool result, a meta row or an injected reminder. */
export function promptText(row: Row): string | undefined {
  if (row.type !== 'user' || row.isMeta === true) return undefined
  const content = row.message?.content
  let text: string
  if (typeof content === 'string') text = content
  else if (Array.isArray(content)) {
    if (content.some((b: any) => b?.type === 'tool_result')) return undefined
    text = content.filter((b: any) => b?.type === 'text').map((b: any) => String(b.text ?? '')).join('\n')
  } else return undefined
  text = text.trim()
  if (!text || /^<(system-reminder|local-command|command-name|command-message|task-notification)/.test(text)) return undefined
  return text
}

export const clip = (text: string, max: number): string => {
  const one = text.replace(/[`\s]+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, Math.max(1, max - 1))}…` : one
}

function toolLabel(block: any): string {
  const input = block.input ?? {}
  const arg = input.command ?? input.file_path ?? input.pattern ?? input.path ?? input.url ?? input.description ?? input.prompt
  return typeof arg === 'string' ? `${block.name} ${clip(arg, 60)}` : String(block.name)
}

function toolFull(block: any): string {
  const input = block.input ?? {}
  if (typeof input.command === 'string') return input.command
  if (typeof input.file_path === 'string' && typeof input.new_string === 'string') return `${input.file_path}\n- ${input.old_string ?? ''}\n+ ${input.new_string}`
  if (typeof input.file_path === 'string' && typeof input.content === 'string') return `${input.file_path}\n${input.content}`
  try {
    return JSON.stringify(input)
  } catch {
    return String(block.name)
  }
}

/** Prompts, tool calls and turn ends of the chain, in order, each with the prefix a fork keeps. */
export function buildTimeline(chain: readonly Row[]): Point[] {
  const points: Point[] = []
  const add = (kind: PointKind, turn: number, label: string, keep: number, detail = label, tool?: string, full = detail, id?: string) =>
    points.push({ n: points.length + 1, kind, turn, label, keep, detail, tool, id, full: full.trim().slice(0, 2000) })

  const resultAt = new Map<string, number>()
  chain.forEach((row, i) => {
    if (row.type !== 'user') return
    for (const b of blocks(row)) if (b?.type === 'tool_result' && typeof b.tool_use_id === 'string') resultAt.set(b.tool_use_id, i)
  })

  let turn = 0
  let lastText = ''
  const endTurn = (end: number) => {
    if (turn > 0) add('turn', turn, lastText ? `turn ${turn} ended: ${clip(lastText, 60)}` : `turn ${turn} ended`, end, clip(lastText, 90) || `turn ${turn} ended`, undefined, lastText || `turn ${turn} ended`)
  }
  chain.forEach((row, i) => {
    const text = promptText(row)
    if (text !== undefined) {
      endTurn(i)
      turn += 1
      lastText = ''
      add('prompt', turn, `before: ${clip(text, 70)}`, i, clip(text, 90), undefined, text)
      return
    }
    if (row.type !== 'assistant') return
    for (const b of blocks(row)) {
      if (b?.type === 'text' && String(b.text ?? '').trim()) lastText = String(b.text)
      else if (b?.type === 'tool_use') {
        const at = resultAt.get(b.id)
        if (at !== undefined) add('tool', turn, toolLabel(b), at + 1, toolLabel(b).slice(String(b.name).length).trim(), String(b.name), toolFull(b), String(b.id))
      }
    }
  })
  endTurn(chain.length)
  return points
}

/**
 * The prefix a fork keeps: grown until every tool_use in it that is answered
 * later in the chain has its tool_result, so the API accepts it. A call the
 * original never answered (an interrupted turn) stays as it was; Claude Code
 * closes those itself on resume.
 */
export function closePrefix(chain: readonly Row[], keep: number): number {
  const answeredAt = new Map<string, number>()
  chain.forEach((row, i) => {
    for (const b of blocks(row)) if (b?.type === 'tool_result') answeredAt.set(b.tool_use_id, i)
  })
  let n = Math.max(0, Math.min(keep, chain.length))
  // each row pulled in may itself hold a call answered further on
  for (let seen = 0; seen < n; seen++) {
    for (const b of blocks(chain[seen]!)) {
      if (b?.type !== 'tool_use') continue
      const at = answeredAt.get(b.id)
      if (at !== undefined) n = Math.max(n, at + 1)
    }
  }
  return n
}

/** The JSONL of a fork: the first `keep` chain rows, under `newId`, with their uuids and parents intact. */
export function forkTranscript(chain: readonly Row[], keep: number, newId: string, cwd?: string, note = ''): string {
  const n = closePrefix(chain, keep)
  const rows: unknown[] = chain.slice(0, n).map(row => ({ ...row, sessionId: newId, ...(cwd ? { cwd } : {}) }))
  const last = rows[n - 1] as Row | undefined
  // a closing user message: the model reads where its files are before the person says anything
  if (note && last) rows.push({ parentUuid: last.uuid, isSidechain: false, userType: 'external', cwd, sessionId: newId, version: last.version, type: 'user', message: { role: 'user', content: note }, uuid: newSessionId(), timestamp: new Date().toISOString() })
  return rows.map(r => JSON.stringify(r)).join('\n') + (n > 0 ? '\n' : '')
}

/** `/` and every other non-alphanumeric of the directory become `-`, as Claude Code names a project folder. */
export const projectSlug = (cwd: string): string => cwd.replace(/[^a-zA-Z0-9]/g, '-')

export const transcriptPath = (configDir: string, cwd: string, sessionId: string): string =>
  `${configDir.replace(/\/+$/, '')}/projects/${projectSlug(cwd)}/${sessionId}.jsonl`

export const shellQuote = (text: string): string => `'${text.replace(/'/g, `'\\''`)}'`

export function resumeCommand(cwd: string, newId: string, instruction: string): string {
  const base = `cd ${shellQuote(cwd)} && claude --resume ${newId}`
  return instruction.trim() ? `${base} ${shellQuote(instruction)}` : base
}

/** A random v4 uuid; the module has no crypto, so Math.random does (an id, not a secret). */
export function newSessionId(random: () => number = Math.random): string {
  const hex = (n: number) => Array.from({ length: n }, () => Math.floor(random() * 16).toString(16)).join('')
  return `${hex(8)}-${hex(4)}-4${hex(3)}-${'89ab'[Math.floor(random() * 4)]}${hex(3)}-${hex(12)}`
}

export type ForkArgs = { kind: 'open' } | { kind: 'list' } | { kind: 'fork'; n: number; instruction: string } | { kind: 'error'; text: string }

export function parseArgs(args: string): ForkArgs {
  const text = args.trim()
  if (!text) return { kind: 'open' }
  if (text === 'list') return { kind: 'list' }
  const m = /^fork\s+(\d+)(?:\s+([\s\S]+))?$/.exec(text)
  if (m) return { kind: 'fork', n: Number(m[1]), instruction: (m[2] ?? '').trim() }
  return { kind: 'error', text: 'usage: /timemachine · /timemachine list · /timemachine fork <n> [new instruction]' }
}

export type ForkPlan = { error: string } | { newId: string; file: string; body: string; kept: number; command: string; label: string; n: number }

/** Everything a fork needs short of writing the file: shared by the command and the pane's button. */
export function planFork(chain: readonly Row[], points: readonly Point[], n: number, instruction: string, cwd: string, configDir: string, newId = newSessionId(), note = ''): ForkPlan {
  const point = points.find(p => p.n === n)
  if (!point) return { error: `no point ${n} (1-${points.length}); /timemachine list shows them` }
  const body = forkTranscript(chain, point.keep, newId, cwd, note)
  const kept = body ? body.trimEnd().split('\n').length - (note ? 1 : 0) : 0
  if (kept === 0) return { error: 'nothing before that point to fork from' }
  return { newId, file: transcriptPath(configDir, cwd, newId), body, kept, command: resumeCommand(cwd, newId, instruction), label: clip(point.label, 60), n }
}

export const forkMessage = (plan: Extract<ForkPlan, { newId: string }>, copied: boolean): string =>
  [
    `Forked at point ${plan.n} (${plan.label}): ${plan.kept} rows kept.`,
    `New session ${plan.newId}${copied ? ', resume command copied' : ''}. In a new terminal:`,
    plan.command,
  ].join('\n')

// Run with: claude plugin test productivity/session-time-machine
import { describe, expect, test } from 'claude-code/testing'
import type { On } from 'claude-code'
import {
  buildTimeline,
  clip,
  closePrefix,
  forkTranscript,
  mainChain,
  newSessionId,
  parseArgs,
  parseRows,
  projectSlug,
  promptText,
  resumeCommand,
  shellQuote,
  transcriptPath,
} from '../hooks/transcript.ts'

let seq = 0
const row = (type: string, content: unknown, extra: Record<string, unknown> = {}, parent?: string) => {
  seq += 1
  return { type, uuid: `u${seq}`, parentUuid: parent ?? (seq > 1 ? `u${seq - 1}` : null), sessionId: 'old', message: { content }, ...extra }
}
const use = (id: string, name = 'Bash', input: unknown = { command: 'ls' }) => ({ type: 'tool_use', id, name, input })
const result = (id: string) => ({ type: 'tool_result', tool_use_id: id, content: 'ok' })

const session = () => {
  seq = 0
  return [
    row('user', 'first task'),
    row('assistant', [use('a', 'Bash', { command: 'npm test' })]),
    row('assistant', [use('b', 'Read', { file_path: 'src/x.ts' })]),
    row('user', [result('a')]),
    row('user', [result('b')]),
    row('assistant', [{ type: 'text', text: 'Tests pass.' }]),
    row('user', 'now refactor it'),
    row('assistant', [{ type: 'text', text: 'Done.' }]),
  ]
}

describe('the chain', () => {
  test('rows are parsed, a half-written last line is ignored', () => {
    expect(parseRows('{"a":1}\n\n{"b":2}\n{"c":').length).toBe(2)
  })

  test('the live conversation is the parent chain from the last row; a rewound branch and a sidechain drop out', () => {
    const rows = session()
    const dead = { ...row('user', 'abandoned', {}, 'u1'), uuid: 'dead' }
    const side = { ...row('assistant', 'agent', { isSidechain: true }, 'u3'), uuid: 'side' }
    rows.splice(2, 0, dead, side)
    const chain = mainChain([...rows, { type: 'last-prompt', sessionId: 'old' }])
    expect(chain.map(r => r.uuid)).not.toContain('dead')
    expect(chain.map(r => r.uuid)).not.toContain('side')
    expect(chain.length).toBe(session().length)
  })

  test('only typed prompts count: tool results, meta rows and injected reminders do not', () => {
    expect(promptText(row('user', 'hi'))).toBe('hi')
    expect(promptText(row('user', [result('a')]))).toBeUndefined()
    expect(promptText(row('user', 'x', { isMeta: true }))).toBeUndefined()
    expect(promptText(row('user', '<system-reminder>be good</system-reminder>'))).toBeUndefined()
    expect(promptText(row('user', [{ type: 'text', text: 'typed' }]))).toBe('typed')
