// @ts-nocheck: written for the Claude Code 2.1.296 types; this folder has the 2.1.283 declarations.
// The pure half of stacking the band over the tree a plugin beneath drew: the row estimate, the rows left, the column.
import { expect, test } from 'claude-code/testing'
import { BAND_ROWS, hasRows, isElement, rowsLeft, rowsOf, stacked } from './stack'

type N = { type: string; props?: Record<string, unknown>; children?: unknown[] }
const text = (...children: unknown[]): N => ({ type: 'Text', children })
const box = (flexDirection: string | undefined, ...children: unknown[]): N => ({
  type: 'Box',
  ...(flexDirection === undefined ? {} : { props: { flexDirection } }),
  children,
})
const col = (...children: unknown[]) => box('column', ...children)
const row = (...children: unknown[]) => box('row', ...children)
const button: N = { type: 'Button', props: { key: 'b', label: 'Go' } }

test('rowsOf: a Text is one row plus one per newline, inline Texts and numbers included', () => {
  const cases: [string, unknown, number][] = [
    ['plain Text', text('a'), 1],
    ['empty Text', text(), 1],
    ['two newlines', text('a\nb\nc'), 3],
    ['trailing newline', text('a\n'), 2],
    ['inline Text holding a newline', text('a', text('b\nc')), 2],
    ['a number child', text(7), 1],
    ['a bare string', 'x\ny', 2],
  ]

  for (const [name, tree, rows] of cases) {
    expect([name, rowsOf(tree)]).toEqual([name, rows])
  }
})

test('rowsOf: a column Box sums its children, a row Box takes the tallest, an empty one draws nothing', () => {
  const two = text('a\nb')
  const cases: [string, unknown, number][] = [
    ['column of 1 and 2 rows', col(text('a'), two), 3],
    ['column-reverse sums too', box('column-reverse', text('a'), two), 3],
    ['row of 1 and 2 rows', row(text('a'), two), 2],
    ['no direction is a row', box(undefined, text('a'), two), 2],
    ['a health row: Text then Button', row(text('health 68% '), button), 1],
    ['nested columns', col(col(text('a'), text('b')), col(text('c'))), 3],
    ['column holding bare strings', col('a', 'b\nc'), 3],
    ['a row beside a tall column', row(col(text('a'), text('b'), text('c')), text('x')), 3],
    ['an empty column', col(), 0],
    ['an empty row', row(), 0],
    ['no direction, no children', { type: 'Box' }, 0],
    ['a column of empty Boxes', col(col(), row()), 0],
  ]

  for (const [name, tree, rows] of cases) {
    expect([name, rowsOf(tree)]).toEqual([name, rows])
  }
})

test('rowsOf: any other element, or what is no element, is one row', () => {
  for (const tree of [button, { type: 'Image' }, { type: 'Input', props: { key: 'i' } }, {}, null, undefined, 42, true]) {
    expect(rowsOf(tree)).toBe(1)
  }

  expect(rowsOf(col(button, { type: 'Mystery' }, text('a')))).toBe(3)
})

test('isElement and hasRows: only an object naming a type that draws a row is a tree to stack on', () => {
  for (const x of [undefined, null, 'band', 42, true, {}, { type: 1 }, [], [text('a')]]) {
    expect(isElement(x)).toBe(false)
    expect(hasRows(x)).toBe(false)
  }

  expect(isElement(col())).toBe(true)
  expect(hasRows(col())).toBe(false)
  expect(hasRows(row(col()))).toBe(false)
  expect(hasRows(text('a'))).toBe(true)
  expect(hasRows(button)).toBe(true)
})

test('rowsLeft: the site less the band row, never under one', () => {
  const cases: [number, number][] = [
    [17, 16],
    [3, 2],
    [2, 1],
    [1, 1],
    [0, 1],
    [-4, 1],
  ]

  for (const [maxRows, left] of cases) {
    expect([maxRows, rowsLeft(maxRows)]).toEqual([maxRows, left])
  }

  expect(BAND_ROWS).toBe(1)
})

// A stand-in for the surface's Box constructor: the plain-data element it makes.
const Box = ((props: { children?: unknown[] } & Record<string, unknown>) => {
  const { children, ...rest } = props

  return { type: 'Box', props: rest, children }
}) as never

test('stacked: a column of the band, then the tree beneath; the band itself when there is nothing to draw', () => {
  const band = row(text('Tuner '), button) as never
  const below = row(text('health '), button)

  expect(stacked({ Box }, band, below)).toEqual({ type: 'Box', props: { flexDirection: 'column' }, children: [band, below] })

  for (const nothing of [undefined, null, 'x', 7, {}, col(), row(col())]) {
    expect(stacked({ Box }, band, nothing)).toBe(band)
  }
})

// @ts-nocheck: written for the Claude Code 2.1.296 types; this folder has the 2.1.283 declarations.
// The tuner's band over the tree a plugin beneath drew for the same site. Pure: no `$`.
//
// The AbovePrompt site draws one tree, so a hook that never calls `next(e)` hides every plugin beneath it.
// `next(e)` resolves to what those draw; the band is returned above it. (Adapted from session-healthbar's
// hooks/pure/stack.ts: plugins cannot import each other, so the few lines needed are copied here.)
import type { Elements, RenderElement } from 'claude-code'

type Els = Pick<Elements['terminal'] | Elements['desktop'], 'Box'>

/** The rows the band takes: it is one row (`height={1}` in view.tsx, held to it by a test). */
export const BAND_ROWS = 1

/** What `next(e)` gave, when it is a tree we can stack on: an object that names an element type. */
export const isElement = (x: unknown): x is RenderElement =>
  typeof x === 'object' && x !== null && typeof (x as { type?: unknown }).type === 'string'

const childrenOf = (el: RenderElement): readonly unknown[] => {
  const kids = (el as { children?: unknown }).children

  return Array.isArray(kids) ? kids.flat(Infinity) : []
}

const lineCount = (s: string): number => s.split('\n').length

/** The text a Text node holds: its strings, and the strings of the inline elements inside it. */
const textOf = (n: unknown): string => {
  if (typeof n === 'string') return n
  if (typeof n === 'number') return String(n)

  return isElement(n) ? childrenOf(n).map(textOf).join('') : ''
}

/**
 * How many rows a tree takes, estimated from its shape alone: a Text is one row plus one per newline; a
 * column Box the sum of its children, a row Box the tallest; any other element (a Button, an Input) one row.
 * Borders, padding and wrapping are not counted, so this can undercount.
 */
export const rowsOf = (tree: unknown): number => {
  if (typeof tree === 'string') return lineCount(tree)
  if (typeof tree === 'number') return 1
  if (!isElement(tree)) return 1
  if (tree.type === 'Text') return lineCount(textOf(tree))
  if (tree.type !== 'Box') return 1

  const rows = childrenOf(tree).map(rowsOf)
  const direction = String((tree.props as { flexDirection?: unknown } | undefined)?.flexDirection)
  const isColumn = direction === 'column' || direction === 'column-reverse'

  return isColumn ? rows.reduce((a, b) => a + b, 0) : Math.max(0, ...rows)
}

/** Whether `next(e)` gave a tree with something to draw: an empty Box is as good as nothing. */
export const hasRows = (below: unknown): below is RenderElement => isElement(below) && rowsOf(below) > 0

/** The rows the plugins beneath may take: what the site has, less the band's own; at least one. */
export const rowsLeft = (maxRows: number): number => Math.max(1, maxRows - BAND_ROWS)

/** The band over the tree beneath, one column; the band alone when nothing to draw came back. */
export const stacked = ({ Box }: Els, band: RenderElement, below: unknown): RenderElement =>
  hasRows(below) ? Box({ flexDirection: 'column', children: [band, below] }) : band

// @ts-nocheck: written for the Claude Code 2.1.296 types; this folder has the 2.1.283 declarations.
import type {
  SubagentTunerChoice as Choice,
  SubagentTunerMode as Mode,
  SubagentTunerPending as Pending,
  SubagentTunerQueue as Queue,
} from '../types'
import { EFFORTS, MODELS } from './recommend'

// Pure parsers and reducers. The module that hooks events holds every call on
// `$` and declares the atoms: the plugin loader follows `$`, and reads an
// atom's reference, only within one file.

export const DEFAULT_MODE: Mode = 'manual'
export const STORE_MODE = 'mode'
export const STORE_SAVED = 'saved'

export type Field = 'model' | 'effort'

export const parseMode = (value: unknown, fallback: Mode): Mode =>
  value === 'manual' || value === 'auto' ? value : fallback

const isOneOf = (list: readonly string[], value: unknown): boolean =>
  value === null || (typeof value === 'string' && list.includes(value))

/** A stored value that is not a choice over the known names counts as unset. */
export function parseChoice(value: unknown): Choice | null {
  if (typeof value !== 'object' || value === null) {
    return null
  }

  const { model, effort } = value as Record<string, unknown>

  if (!isOneOf(MODELS, model) || !isOneOf(EFFORTS, effort)) {
    return null
  }

  return { model: model as string | null, effort: effort as string | null }
}

/** A choice with neither field set is no default at all. */
export const asDefault = (choice: Choice | null): Choice | null =>
  choice !== null && (choice.model !== null || choice.effort !== null) ? choice : null

/** The next value of a field in its cycle: none, then each name in turn. */
export function cycled(current: string | null, names: readonly string[]): string | null {
  const at = current === null ? -1 : names.indexOf(current)

  return names[at + 1] ?? null
}

export function cycleField(saved: Choice | null, field: Field): Choice | null {
  const base = saved ?? { model: null, effort: null }

  return asDefault({ ...base, [field]: cycled(base[field], field === 'model' ? MODELS : EFFORTS) })
}

export const withPending = (q: Queue, item: Pending): Queue => ({ items: [...q.items, item] })

export const patched = (q: Queue, id: string, patch: Partial<Pending>): Queue => ({
  items: q.items.map(one => (one.id === id ? { ...one, ...patch } : one)),
})

export const without = (q: Queue, id: string): Queue => ({ items: q.items.filter(one => one.id !== id) })

// @ts-nocheck: written for the Claude Code 2.1.296 types; this folder has the 2.1.283 declarations.
import type { Elements } from 'claude-code'

import type { SubagentTunerChoice as Choice, SubagentTunerMode as Mode } from '../types'
import type { Field } from './state'

export type Actions = {
  setMode: (mode: Mode) => unknown
  cycle: (field: Field) => unknown
  reset: () => unknown
}

export type BandData = {
  ui: Elements['terminal'] | Elements['desktop']
  columns: number
  mode: Mode
  saved: Choice | null
  actions: Actions
}

/** Marks the active mode in words, for where colour alone would not tell. */
export const ACTIVE_MARK = '*'
/** Trails a plain (unbracketed) cycler, which would otherwise look like text. */
export const CYCLER_MARK = '>'

type Layout = {
  lead: string
  manual: string
  between: string
  isBracketed: boolean
  isShort: boolean
  reset: string | null
}

/**
 * Richest first, each giving up something other than the mode's words before the
 * next: the word `default`, then brackets and the full effort name, then the
 * lead and Reset. `Man` is the last resort.
 */
const LAYOUTS: readonly Layout[] = [
  { lead: 'Tuner  ', manual: 'Manual', between: ' · default ', isBracketed: true, isShort: false, reset: 'Reset' },
  { lead: 'Tuner ', manual: 'Manual', between: ' · ', isBracketed: true, isShort: false, reset: '×' },
  { lead: 'Tuner ', manual: 'Manual', between: ' ', isBracketed: false, isShort: true, reset: '×' },
  { lead: '', manual: 'Manual', between: ' ', isBracketed: false, isShort: true, reset: null },
  { lead: '', manual: 'Man', between: ' ', isBracketed: false, isShort: true, reset: null },
]

/** The width of the smallest layout in its worst case; narrower than this nothing is drawn. */
export const MIN_COLUMNS = 31

const NONE_LABEL = 'rec.'

const nameOf = (value: string | null, isShort: boolean): string =>
  value === null ? NONE_LABEL : isShort && value === 'medium' ? 'med' : value

const cyclerLabel = (layout: Layout, value: string | null): string =>
  `${nameOf(value, layout.isShort)}${layout.isBracketed ? '' : CYCLER_MARK}`

// A bracketed Button is its label plus 4 cells, a plain one its label alone
// (reference.md:127); the active mode carries one more cell for its mark.
const buttonWidth = (label: string, isBracketed: boolean): number => label.length + (isBracketed ? 4 : 0)

/** The cells the layout needs for what is to be drawn now: the labels it holds, not the worst they could be. */
function neededWidth(layout: Layout, mode: Mode, saved: Choice | null): number {
  const manual = `${mode === 'manual' ? ACTIVE_MARK : ''}${layout.manual}`
  const auto = `${mode === 'auto' ? ACTIVE_MARK : ''}Auto`
  const cyclers =
    buttonWidth(cyclerLabel(layout, saved?.model ?? null), layout.isBracketed) +
    1 +
    buttonWidth(cyclerLabel(layout, saved?.effort ?? null), layout.isBracketed)
  const reset = layout.reset === null || saved === null ? 0 : 1 + buttonWidth(layout.reset, layout.isBracketed)

  return layout.lead.length + buttonWidth(manual, true) + buttonWidth(auto, true) + layout.between.length + cyclers + reset
}

/** The richest layout whose needed width fits; the smallest where none does. */
const layoutFor = (columns: number, mode: Mode, saved: Choice | null): Layout =>
  LAYOUTS.find(layout => neededWidth(layout, mode, saved) <= columns) ?? LAYOUTS[LAYOUTS.length - 1]!

export function bandView({ ui, columns, mode, saved, actions }: BandData) {
  const { Box, Button, Text } = ui
  const layout = layoutFor(columns, mode, saved)
  const plain = layout.isBracketed ? undefined : true
  const field = (name: Field) => (
    <Button
      key={`default-${name}`}
      label={cyclerLabel(layout, saved?.[name] ?? null)}
      plain={plain}
      onPress={() => actions.cycle(name)}
    />
  )

  return (
    <Box height={1} overflow="hidden">
      {layout.lead === '' ? null : <Text dimColor>{layout.lead}</Text>}
      <Box>
        <Button
          key="mode-manual"
          label={mode === 'manual' ? `${ACTIVE_MARK}${layout.manual}` : layout.manual}
          variant={mode === 'manual' ? 'primary' : undefined}
          onPress={() => actions.setMode('manual')}
        />
        <Button
          key="mode-auto"
          label={mode === 'auto' ? `${ACTIVE_MARK}Auto` : 'Auto'}
          variant={mode === 'auto' ? 'primary' : undefined}
          onPress={() => actions.setMode('auto')}
        />
      </Box>
      <Text dimColor>{layout.between}</Text>
      {field('model')}
      <Text dimColor>/</Text>
      {field('effort')}
      {layout.reset === null || saved === null ? null : (
        <Box>
          <Text> </Text>
          <Button key="reset" label={layout.reset} plain={plain} onPress={() => actions.reset()} />
        </Box>
      )}
    </Box>
  )
}

