// ---------------------------------------------------------------- planning

export type Status = 'change' | 'same' | 'locked' | 'missing' | 'invalid'

export type PlanItem = {
  id: string
  layer: Step['layer']
  label: string
  from: string
  to: string
  why: string
  status: Status
}

export type Json = Record<string, unknown>

/** A row's value as the menu shows it equals the value a profile sets. */
export function sameValue(current: ConfigValue | undefined, wanted: ConfigValue): boolean {
  if (current === wanted) return true
  if (typeof current !== 'string' || typeof wanted !== 'string') return false
  const c = current.toLowerCase()
  const w = wanted.toLowerCase()
  // the menu shows `Default (recommended)` for the value `default`
  return c === w || c.startsWith(`${w} (`)
}

export const show = (v: unknown): string => {
  if (v === undefined || v === null || v === '') return 'unset'
  if (v === true) return 'on'
  if (v === false) return 'off'
  if (Array.isArray(v)) return v.length === 0 ? 'none' : `${v.length} rules`
  return String(v)
}

export function getPath(obj: Json, path: string): unknown {
  let cur: unknown = obj
  for (const part of path.split('.')) {
    if (cur === null || typeof cur !== 'object' || Array.isArray(cur)) return undefined
    cur = (cur as Json)[part]
  }
  return cur
}

/** A copy of `obj` with `path` set, or removed when `value` is undefined; empty parents are dropped. */
export function setPath(obj: Json, path: string, value: unknown): Json {
  const [head, ...rest] = path.split('.')
  const out: Json = { ...obj }
  if (rest.length === 0) {
    if (value === undefined) delete out[head!]
    else out[head!] = value
    return out
  }
  const child = out[head!]
  const base = child !== null && typeof child === 'object' && !Array.isArray(child) ? (child as Json) : {}
  const next = setPath(base, rest.join('.'), value)
  if (Object.keys(next).length === 0) delete out[head!]
  else out[head!] = next
  return out
}

const listAt = (obj: Json, path: string): string[] => {
  const v = getPath(obj, path)
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []
}

/**
 * What the engine last sent (the main loop's model id and effort, from
 * `turn.step`), and an activated effort still waiting for the next request.
 */
export type Live = { model?: string; effort?: string | number; pending?: string }

/**
 * Where a model's saved effort lives in settings.json. Undefined for an id with
 * a dot (a Bedrock or Vertex id), which a dotted path cannot name.
 */
export const effortPath = (model: string): string | undefined =>
  model.includes('.') || model.length === 0 ? undefined : `modelSettings.${model}.effortLevel`

/** The effort the model in use runs at: its saved level, else what the last request carried. */
export function currentEffort(user: Json, live: Live): string | undefined {
  if (live.pending !== undefined) return live.pending
  const path = live.model ? effortPath(live.model) : undefined
  const saved = path ? getPath(user, path) : undefined
  if (typeof saved === 'string') return saved
  return live.effort === undefined ? undefined : String(live.effort)
}

export function planFor(profile: Profile, rows: readonly Row[], user: Json, live: Live = {}): PlanItem[] {
  const modelStep = profile.steps.find((s): s is ConfigStep => s.layer === 'config' && s.key === 'model')
  const modelRow = rows.find(r => r.key === 'model')
  const switchesModel = modelStep !== undefined && modelRow !== undefined && !sameValue(modelRow.value, modelStep.value)
  return profile.steps.map(step => {
    if (step.layer === 'effort') {
      const current = live.pending ?? (switchesModel ? undefined : currentEffort(user, live))
      return {
        id: 'effort',
        layer: step.layer,
        label: 'Effort',
        from: current ?? 'default',
        to: step.value,
        why: `${step.why}; saved for the model in use at your next message`,
        status: current === step.value ? ('same' as const) : ('change' as const),
      }
    }
    if (step.layer === 'config') {
      const row = rows.find(r => r.key === step.key)
      const base = { id: `config:${step.key}`, layer: step.layer, why: step.why, to: show(step.value) }
      if (!row) return { ...base, label: step.key, from: '—', status: 'missing' as const }
      const item = { ...base, label: row.label, from: show(row.value) }
      if (row.isLocked) return { ...item, status: 'locked' as const }
      if (row.kind === 'choice' && typeof step.value === 'string' && row.options && !row.options.includes(step.value))
        return { ...item, status: 'invalid' as const }
      return { ...item, status: sameValue(row.value, step.value) ? ('same' as const) : ('change' as const) }
    }
    if (step.layer === 'settings') {
      const current = getPath(user, step.path)
      const same = (current ?? null) === step.value
      return {
        id: `settings:${step.path}`,
        layer: step.layer,
        label: step.label,
        from: show(current),
        to: show(step.value),
        why: step.why,
        status: same ? ('same' as const) : ('change' as const),
      }
    }
    const have = listAt(user, step.path)
    const missing = step.add.filter(x => !have.includes(x))
    return {
      id: `list:${step.path}`,
      layer: step.layer,
      label: step.label,
      from: show(have),
      to: missing.length === 0 ? show(have) : `+${missing.length} rules`,
      why: step.why,
      status: missing.length === 0 ? ('same' as const) : ('change' as const),
    }
  })
}

/** How much of a profile is already in force: applicable steps that match, of those that apply. */
export function matchOf(plan: PlanItem[]): { same: number; of: number } {
  const applicable = plan.filter(p => p.status === 'same' || p.status === 'change')
  return { same: applicable.filter(p => p.status === 'same').length, of: applicable.length }
}

/** A row's value as `$.config.set` takes it back: a choice's option, not the menu's label for it. */
export function restorable(row: Row): ConfigValue {
  if (row.kind === 'choice' && row.options) return row.options.find(o => sameValue(row.value, o)) ?? row.value
  return row.value
}

// ---------------------------------------------------------------- applying and undoing

export type BackupEntry =
  | { layer: 'config'; key: string; label: string; previous: ConfigValue }
  | { layer: 'settings'; path: string; label: string; previous: unknown; had: boolean }
  | { layer: 'list'; path: string; label: string; added: string[] }

/** Applies the profile's settings and list steps to the settings object; returns the new object and what to undo. */
export function applySettings(user: Json, steps: readonly (SettingsStep | ListStep)[]): { next: Json; entries: BackupEntry[] } {
  let next = user
  const entries: BackupEntry[] = []
  for (const step of steps) {
    if (step.layer === 'settings') {
      const had = getPath(next, step.path) !== undefined
      const previous = getPath(next, step.path)
      if ((previous ?? null) === step.value) continue
      next = setPath(next, step.path, step.value ?? undefined)
      entries.push({ layer: 'settings', path: step.path, label: step.label, previous: had ? previous : null, had })
    } else if (step.layer === 'list') {
      const have = listAt(next, step.path)
      const added = step.add.filter(x => !have.includes(x))
      if (added.length === 0) continue
      next = setPath(next, step.path, [...have, ...added])
      entries.push({ layer: 'list', path: step.path, label: step.label, added })
    }
  }
  return { next, entries }
}

/** Puts back what `applySettings` changed; a key the person changed since is restored too. */
export function revertSettings(user: Json, entries: BackupEntry[]): Json {
  let next = user
  for (const entry of [...entries].reverse()) {
    if (entry.layer === 'settings') next = setPath(next, entry.path, entry.had ? entry.previous : undefined)
    else if (entry.layer === 'list') {
      const kept = listAt(next, entry.path).filter(x => !entry.added.includes(x))
      next = setPath(next, entry.path, kept.length === 0 ? undefined : kept)
    }
  }
  return next
}

/** Whether the settings the engine has loaded hold `next`'s value at every path. */
export function inSync(loaded: Json, next: Json, paths: string[]): boolean {
  return paths.every(path => JSON.stringify(getPath(loaded, path) ?? null) === JSON.stringify(getPath(next, path) ?? null))
}

/** Where the user's settings file lives: `CLAUDE_CONFIG_DIR`, else `~/.claude`. */
export function userSettingsPath(configDir: string | undefined, home: string | undefined): string | undefined {
  const dir = configDir && configDir.length > 0 ? configDir : home ? `${home.replace(/[\\/]+$/, '')}/.claude` : undefined
  return dir === undefined ? undefined : `${dir.replace(/[\\/]+$/, '')}/settings.json`
}

/** Pads with non-breaking spaces so Desktop keeps the width (plain spaces collapse there). */
export const pad = (s: string, n: number): string => {
  const cut = [...s]
  return cut.length >= n ? `${cut.slice(0, Math.max(0, n - 2)).join('')}…\u00a0` : s + '\u00a0'.repeat(n - cut.length)
}
export const nb = (s: string): string => s.replace(/ /g, '\u00a0')

export const paneColumns = (v: unknown): number => {
  const n = typeof v === 'number' && Number.isFinite(v) ? Math.round(v) : 62
  return Math.min(100, Math.max(44, n))
}

/**
 * ultra-config — Claude Mod
 *
 * A side pane with five profiles (Token saver, Fast flow, Max quality,
 * Guarded, Autopilot) that set Claude Code up for one way of working in one
 * press. Each profile opens to show exactly what it sets, with one button to
 * activate it.
 *
 *   `/ultra-config` opens it · `/ultra-config <profile>` opens that profile ·
 *   `/ultra-config apply <profile>` activates it · `/ultra-config undo`
 *   reverts the last one · `/ultra-config close` closes the pane
 *
 * `/config` rows are written with `$.config.set`, the way the menu writes
 * them; effort, the subagent model, env caps and deny rules (keys with no
 * `/config` row) are written to ~/.claude/settings.json, after a copy of the
 * file is saved beside it as settings.json.ultra-config.bak. Each activated
 * profile is kept in the plugin's store so `undo` puts back exactly what it
 * changed.
 *
 * Needs Claude Code >= 2.1.287 (mods on by default); every UI prop it uses
 * is in that version's API, so the Desktop app's bundled engine draws it too.
 *
 * Options (pluginConfigs["ultra-config@skills-dir"].options):
 *   columns: number   width asked for the docked pane (default 62)
 */
import { atom, read, update } from 'claude-code'
import type { ConfigRow, EngineInterface, Register } from 'claude-code'

import type {
  UltraConfigBackup as Backup,
  UltraConfigEntry,
  UltraConfigLive,
  UltraConfigPending,
  UltraConfigSnapshot as Snapshot,
  UltraConfigUi,
} from '../types'
import {
  PROFILES,
  applySettings,
  currentEffort,
  effortPath,
  inSync,
  matchOf,
  nb,
  pad,
  paneColumns,
  planFor,
  profileById,
  restorable,
  revertSettings,
  show,
  userSettingsPath,
} from './profiles.ts'
import type { Effort, Json, ListStep, Live, PlanItem, Profile, SettingsStep } from './profiles.ts'

const PANE = 'ultra-config'
const COMMAND = 'ultra-config'
const STORE_HISTORY = 'history'
const KEEP = 20
/** How long a write waits for the engine to reload it, twice at most: 20 × 150 ms. */
const RELOAD_TRIES = 20
const RELOAD_STEP_MS = 150
const INK = '#141414'
const ACCENT = '#d97757'

type Host = EngineInterface

const ui = atom({ plugin: 'ultra-config', key: 'ui' } as const, {
  selected: null,
  notice: null,
  isBusy: false,
} satisfies UltraConfigUi)
const snapshot = atom({ plugin: 'ultra-config', key: 'snapshot' } as const, {
  rows: [],
  user: {},
  path: null,
  error: null,
} satisfies Snapshot)
const history = atom({ plugin: 'ultra-config', key: 'history' } as const, [] as Backup[])
/** The main loop's model id and effort, as the last request carried them. */
const live = atom({ plugin: 'ultra-config', key: 'live' } as const, {} as UltraConfigLive)
/** An activated effort waiting for the next request to learn the model id it is saved under. */
const pending = atom({ plugin: 'ultra-config', key: 'pending' } as const, null as UltraConfigPending | null)
const STORE_PENDING = 'pendingEffort'

const message = (err: unknown): string => (err instanceof Error ? err.message : String(err))

// This module holds every call on `$`; profiles.ts is pure.

/** Reads the settings file, or says why it can't be trusted for a write. */
async function readUser($: Host, path: string | null): Promise<{ user: Json; text: string | null; error: string | null }> {
  if (path === null) return { user: {}, text: null, error: 'no home directory to find settings.json in' }
  let text: string
  try {
    text = await $.fs.read(path)
  } catch {
    // no file yet is fine; a file the engine reads but we can't is not
    const loaded = await $.settings.read({ source: 'user' }).catch(() => ({}))
    return Object.keys(loaded).length === 0
      ? { user: {}, text: null, error: null }
      : { user: { ...loaded }, text: null, error: `cannot read ${path}` }
  }
  if (text.trim() === '') return { user: {}, text, error: null }
  try {
    const parsed: unknown = JSON.parse(text)
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed))
      return { user: {}, text, error: 'settings.json is not a JSON object' }
    return { user: parsed as Json, text, error: null }
  } catch (err) {
    return { user: {}, text, error: `settings.json is not valid JSON (${message(err)})` }
  }
}

async function settingsPath($: Host): Promise<string | null> {
  const dir = await $.env.get('CLAUDE_CONFIG_DIR')
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE'))
  return userSettingsPath(dir, home) ?? null
}

async function refresh($: Host): Promise<Snapshot> {
  const rows = await $.config.list().catch(() => [] as ConfigRow[])
  const path = await settingsPath($)
  const { user, error } = await readUser($, path)
  const next: Snapshot = { rows: [...rows], user, path, error }
  await update($, snapshot, () => next)
  return next
}

async function notify($: Host, text: string, tone: 'success' | 'warning' | 'error'): Promise<void> {
  await update($, ui, s => ({ ...s, notice: { text, tone } }))
}

async function saveHistory($: Host, list: Backup[]): Promise<void> {
  await update($, history, () => list)
  await $.store.set(STORE_HISTORY, list).catch(err => $.ui.log(`ultra-config: history not saved: ${message(err)}`))
}

/**
 * Writes the settings object, keeping a copy of the file as it was, and
 * resolves once the engine has loaded it (false if it never did).
 *
 * The engine writes /config rows from the settings it holds in memory, so a
 * `$.config.set` before it reloads would put back what this write changed.
 * And it does not reload a write that lands just after one of its own: then
 * the file is written again, once, which it does pick up.
 */
async function writeUser($: Host, path: string, before: string | null, next: Json, paths: string[]): Promise<boolean> {
  if (before !== null) await $.fs.write(`${path}.ultra-config.bak`, before)
  const text = `${JSON.stringify(next, null, 2)}\n`
  for (const body of [text, text.trimEnd()]) {
    await $.fs.write(path, body)
    for (let i = 0; i < RELOAD_TRIES; i++) {
      const loaded = await $.settings.read({ source: 'user' }).catch(() => undefined)
      if (loaded && inSync(loaded, next, paths)) return true
      await $.clock.sleep(RELOAD_STEP_MS)
    }
  }
  $.ui.log(`ultra-config: Claude Code did not reload ${path}`)
  return false
}

const NOT_RELOADED = 'Claude Code did not reload settings.json; restart the session, then apply again'

/** The model and effort in use, with an effort waiting for the next request. */
async function liveNow($: Host): Promise<Live> {
  const want = await read($, pending)
  return { ...(await read($, live)), ...(want ? { pending: want.value } : {}) }
}

async function setPending($: Host, value: UltraConfigPending | null): Promise<void> {
  await update($, pending, () => value)
  await $.store.set(STORE_PENDING, value).catch(err => $.ui.log(`ultra-config: pending effort not saved: ${message(err)}`))
}

/**
 * Saves an activated effort under the model id this request names, and adds
 * that write to the activation's history entry so undo puts it back. Returns
 * false when it could not be written (the request then still gets the effort).
 */
async function saveEffort($: Host, model: string, want: UltraConfigPending): Promise<boolean> {
  const path = await settingsPath($)
  const at = effortPath(model)
  if (path === null || at === undefined) {
    $.ui.log(`ultra-config: effort not saved for ${model} (no settings.json, or a model id with a dot)`)
    return false
  }
  const { user, text, error } = await readUser($, path)
  if (error !== null) {
    $.ui.log(`ultra-config: effort not saved: ${error}`)
    return false
  }
  const { next, entries } = applySettings(user, [{ layer: 'settings', path: at, label: 'Effort', value: want.value, why: '' }])
  if (entries.length === 0) return true
  const list = await read($, history)
  await saveHistory($, list.map(b => (b.id === want.backupId ? { ...b, entries: [...b.entries, ...entries] } : b)))
  return writeUser($, path, text, next, [at])
}

async function applyProfile($: Host, profile: Profile): Promise<Backup> {
  const snap = await refresh($)
  const plan = planFor(profile, snap.rows, snap.user, await liveNow($))
  const entries: UltraConfigEntry[] = []
  const refused: { label: string; reason: string }[] = []
  let isSynced = true

  // settings.json first: the /config writes below then start from it
  const fileSteps = profile.steps.filter((s): s is SettingsStep | ListStep => s.layer === 'settings' || s.layer === 'list')
  if (fileSteps.length > 0) {
    const { user, text, error } = await readUser($, snap.path)
    if (error !== null || snap.path === null) {
      for (const s of fileSteps) refused.push({ label: s.label, reason: error ?? 'settings.json not found' })
    } else {
      const { next, entries: written } = applySettings(user, fileSteps)
      if (written.length > 0) {
        // recorded before the write: a write that fails halfway can still be undone
        entries.push(...written)
        try {
          isSynced = await writeUser($, snap.path, text, next, written.flatMap(w => (w.layer === 'config' ? [] : [w.path])))
        } catch (err) {
          isSynced = false
          for (const w of written) refused.push({ label: w.label, reason: `may not be written: ${message(err)}` })
        }
      }
    }
  }

  for (const step of profile.steps) {
    if (step.layer !== 'config') continue
    const item = plan.find(p => p.id === `config:${step.key}`)!
    if (item.status === 'same') continue
    if (item.status !== 'change') {
      refused.push({ label: item.label, reason: SKIP[item.status] })
      continue
    }
    if (!isSynced) {
      refused.push({ label: item.label, reason: NOT_RELOADED })
      continue
    }
    const row = snap.rows.find(r => r.key === step.key)!
    const r = await $.config.set({ key: step.key, value: step.value }).catch(err => ({ deny: message(err) }))
    if (r.deny !== undefined) refused.push({ label: item.label, reason: r.deny })
    else entries.push({ layer: 'config', key: step.key, label: row.label, previous: restorable(row) })
  }

  // effort is saved per model, under the id the next request names
  const effortStep = profile.steps.find(s => s.layer === 'effort')
  const effortItem = plan.find(p => p.id === 'effort')
  const effort: Effort | undefined = effortStep && effortItem?.status === 'change' ? effortStep.value : undefined

  const backup: Backup = {
    id: `${Date.now()}`,
    profile: profile.id,
    name: profile.name,
    at: new Date().toISOString(),
    entries,
    refused,
    ...(effort ? { effort } : {}),
  }
  if (entries.length > 0 || effort) await saveHistory($, [backup, ...(await read($, history))].slice(0, KEEP))
  if (effort) await setPending($, { value: effort, backupId: backup.id })
  await refresh($)
  return backup
}

async function undoLast($: Host): Promise<{ text: string; tone: 'success' | 'warning' | 'error' }> {
  const [last, ...rest] = await read($, history)
  if (!last) return { text: 'Nothing to undo', tone: 'warning' }
  // an effort not yet saved for any model is simply dropped
  if ((await read($, pending))?.backupId === last.id) await setPending($, null)
  const failed: string[] = []
  let isSynced = true
  // settings.json first, as when applying
  const fileEntries = last.entries.filter(e => e.layer !== 'config')
  if (fileEntries.length > 0) {
    const path = await settingsPath($)
    const { user, text, error } = await readUser($, path)
    if (error !== null || path === null) failed.push(`settings.json (${error ?? 'not found'})`)
    else
      isSynced = await writeUser($, path, text, revertSettings(user, fileEntries), fileEntries.map(f => f.path)).catch(err => {
        failed.push(`settings.json (${message(err)})`)
        return true
      })
  }
  for (const entry of [...last.entries].reverse()) {
    if (entry.layer !== 'config') continue
    if (!isSynced) {
      failed.push(`${entry.label} (${NOT_RELOADED})`)
      continue
    }
    const r = await $.config.set({ key: entry.key, value: entry.previous }).catch(err => ({ deny: message(err) }))
    if (r.deny !== undefined) failed.push(`${entry.label} (${r.deny})`)
  }
  // a settings.json that could not be restored keeps the entry, so undo can be tried again
  const fileFailed = failed.some(f => f.startsWith('settings.json'))
  if (!fileFailed) await saveHistory($, rest)
  await refresh($)
  if (fileFailed) return { text: `Not undone: ${failed.join(', ')}. Fix it and run /ultra-config undo again`, tone: 'error' }
  return failed.length === 0
    ? { text: `Undid ${last.name}: ${last.entries.length} setting${last.entries.length === 1 ? '' : 's'} restored`, tone: 'success' }
    : { text: `Undid ${last.name}, except ${failed.join(', ')}`, tone: 'warning' }
}

const SKIP: Record<'locked' | 'missing' | 'invalid', string> = {
  locked: 'locked by your organization',
  missing: 'not in this Claude Code version',
  invalid: 'value not offered here',
}

const summary = (b: Backup): string => {
  const n = b.entries.length + (b.effort ? 1 : 0)
  const head = n === 0 ? `${b.name}: already in place` : `${b.name} activated: ${n} setting${n === 1 ? '' : 's'} changed`
  const tail = b.effort ? ` (effort ${b.effort} from your next message)` : ''
  return b.refused.length === 0 ? `${head}${tail}` : `${head}${tail}, ${b.refused.length} skipped`
}

function planText(profile: Profile, plan: PlanItem[]): string {
  const lines = [`${profile.icon} ${profile.name}: ${profile.tagline}`]
  for (const p of plan) {
    const mark = p.status === 'change' ? '●' : p.status === 'same' ? '✓' : '⊘'
    const tail = p.status === 'change' ? `${p.from} → ${p.to}  (${p.why})` : p.status === 'same' ? p.to : SKIP[p.status]
    lines.push(`  ${mark} ${p.label}: ${tail}`)
  }
  lines.push(`/ultra-config apply ${profile.id} to apply`)
  return lines.join('\n')
}

export const register: Register = (on, options) => {
  const columns = paneColumns(options.columns)

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await $.command
      .register({
        name: COMMAND,
        description: 'Setting profiles: token saver, fast flow, max quality, guarded, autopilot',
        argumentHint: '[profile | apply <profile> | undo | close]',
      })
      .catch(err => $.ui.log(`ultra-config: /${COMMAND} not registered: ${message(err)}`))
    const stored = await $.store.get(STORE_HISTORY).catch(() => undefined)
    if (Array.isArray(stored)) await update($, history, () => stored as Backup[])
    const want = await $.store.get(STORE_PENDING).catch(() => undefined)
    if (want && typeof want === 'object') await update($, pending, () => want as UltraConfigPending)
    return r
  })

  // The main loop's requests: learn the model id and effort in use, and save
  // an activated effort under that id (and send it with this request).
  on('turn.step', async function* ($, e, next) {
    if (e.agentId) return yield* next(e)
    const want = await read($, pending)
    if (!want) {
      await update($, live, () => ({ model: e.model, effort: e.effort }))
      return yield* next(e)
    }
    await setPending($, null)
    await saveEffort($, e.model, want).catch(err => {
      $.ui.log(`ultra-config: effort not saved: ${message(err)}`)
      return false
    })
    await update($, live, () => ({ model: e.model, effort: want.value }))
    await refresh($).catch(() => undefined)
    return yield* next({ ...e, effort: want.value })
  })

  // keep the cards in step with changes made in /config itself
  on('config.set', async ($, e, next) => {
    const r = await next(e)
    if (r.deny === undefined) await refresh($).catch(() => undefined)
    return r
  }).catch(($, e, next) => next(e))

  on('command.run', { command: COMMAND }, async ($, e) => {
    const [verb = '', arg = ''] = e.args.trim().split(/\s+/)
    const word = verb.toLowerCase()
    if (word === 'close' || word === 'stop') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return { text: 'ultra-config closed' }
    }
    if (word === 'undo') {
      const { text, tone } = await undoLast($)
      await notify($, text, tone)
      return { text }
    }
    if (word === 'apply') {
      const profile = profileById(arg)
      if (!profile) return { text: `Unknown profile "${arg}". Profiles: ${PROFILES.map(p => p.id).join(', ')}` }
      const b = await applyProfile($, profile)
      const text = summary(b)
      await notify($, text, b.refused.length === 0 ? 'success' : 'warning')
      const skipped = b.refused.map(x => `\n  ⊘ ${x.label}: ${x.reason}`).join('')
      return { text: `${text}${skipped}\n/ultra-config undo reverts it` }
    }
    const profile = word === '' ? undefined : profileById(word)
    if (word !== '' && !profile)
      return { text: `Unknown argument "${word}". Try a profile (${PROFILES.map(p => p.id).join(', ')}), apply, undo or close.` }
    const snap = await refresh($)
    await update($, ui, s => ({
      ...s,
      selected: profile ? profile.id : s.selected,
      notice: null,
    }))
    let placed = true
    try {
      placed = (await $.ui.open({ id: PANE, title: 'ultra config', focus: true, columns })).isPlaced
    } catch (err) {
      placed = false
      $.ui.log(`ultra-config: pane not opened: ${message(err)}`)
    }
    if (profile) {
      const plan = planFor(profile, snap.rows, snap.user, await liveNow($))
      if (!placed) return { text: planText(profile, plan) }
      const n = plan.filter(p => p.status === 'change').length
      return { text: `${profile.icon} ${profile.name}: ${n} change${n === 1 ? '' : 's'}, shown in the pane · /ultra-config apply ${profile.id}` }
    }
    if (!placed) return { text: PROFILES.map(p => `${p.icon} ${p.id}: ${p.tagline}`).join('\n') }
    // a Desktop session reports isFullscreen false too, so the reply names no layout
    return { text: 'ultra-config opened · press a profile to see what it sets · /ultra-config close' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const W = Math.max(40, (e.props.bodyColumns ?? columns) - 1)
    const state = await read($, ui)
    const snap = await read($, snapshot)
    const now = await liveNow($)
    const set = (patch: Partial<UltraConfigUi>) => update($, ui, s => ({ ...s, ...patch }))

    const effort = currentEffort(snap.user, now)
    const model = snap.rows.find(r => r.key === 'model')
    const mode = snap.rows.find(r => r.key === 'permissionMode')
    const facts = [show(model?.value).replace(/ \(.*\)$/, '').toLowerCase(), `${effort === undefined ? 'default' : show(effort)} effort`, `${show(mode?.value)} mode`]

    // one profile is always open; the first until another is pressed
    const open = (state.selected ? profileById(state.selected) : undefined) ?? PROFILES[0]!
    const labelW = Math.min(27, Math.max(14, Math.floor(W * 0.44)))

    const activate = async (p: (typeof PROFILES)[number]) => {
      if ((await read($, ui)).isBusy) return
      await set({ isBusy: true })
      try {
        const b = await applyProfile($, p)
        await set({ notice: { text: `${summary(b)} · /ultra-config undo reverts it`, tone: b.refused.length === 0 ? 'success' : 'warning' } })
        $.ui.toast(`${p.icon} ${summary(b)}`)
      } catch (err) {
        await set({ notice: { text: `Not activated: ${message(err)}`, tone: 'error' } })
      } finally {
        await set({ isBusy: false })
      }
    }

    const detail = (p: (typeof PROFILES)[number]) => {
      const plan = planFor(p, snap.rows, snap.user, now)
      const changes = plan.filter(x => x.status === 'change').length
      // every step, so Activate never applies one that was not shown; the pane scrolls
      const lines = []
      for (const x of plan) {
        if (x.status === 'change')
          lines.push(
            <Box key={`chg:${x.id}`} flexDirection="column">
              <Text wrap="truncate-end">
                <Text color={p.color}>● </Text>
                <Text>{pad(x.label, labelW)}</Text>
                {/* drop the menu hint, e.g. "Opus (default)" -> "Opus", so the old -> new row fits a narrow pane */}
                <Text dimColor strikethrough>{x.from.replace(/ \(.*\)$/, '')}</Text>
                <Text dimColor>{nb(' → ')}</Text>
                <Text color={p.color} bold>{x.to}</Text>
              </Text>
              <Text color="#8a8a8a" wrap="truncate-end">{nb(`  ${x.why}`)}</Text>
            </Box>,
          )
        else if (x.status === 'same')
          lines.push(
            <Text key={`same:${x.id}`} wrap="truncate-end">
              <Text color="success">✓ </Text>
              <Text dimColor>{pad(x.label, labelW)}{x.to}</Text>
            </Text>,
          )
        else
          lines.push(
            <Text key={`skip:${x.id}`} color="warning" wrap="truncate-end">
              ⊘ <Text dimColor>{`${x.label}: ${SKIP[x.status]}`}</Text>
            </Text>,
          )
      }
      return (
        <Box key={`detail:${p.id}`} flexDirection="column" borderStyle="round" borderColor={p.color} paddingX={1} width={W}>
          {lines}
          <Box flexDirection="row" marginTop={1}>
            {changes > 0 ? (
              <Button
                key={`activate:${p.id}`}
                variant="primary"
                hotkey="a"
                autoFocus
                label={state.isBusy ? 'Activating…' : `Activate ${p.name}`}
                onPress={() => activate(p)}
              />
            ) : (
              <Text color="success" bold>✓ Active: nothing to change</Text>
            )}
          </Box>
        </Box>
      )
    }

    const cards = PROFILES.map(p => {
      const plan = planFor(p, snap.rows, snap.user, now)
      const { same, of } = matchOf(plan)
      const isActive = of > 0 && same === of
      const isOpen = p.id === open.id
      const meter = 10
      const lit = of === 0 ? 0 : Math.round((same / of) * meter)
      return (
        <Box key={`card:${p.id}`} flexDirection="column" width={W}>
          <Box flexDirection="row" justifyContent="space-between" width={W}>
            <Box flexDirection="row">
              <Text>
                <Text color={isOpen ? p.color : '#5a5a5a'}>{isOpen ? '▾ ' : '▸ '}</Text>
                <Text backgroundColor={p.color} color={INK} bold>{nb(` ${p.icon} `)}</Text>
                <Text>{'\u00a0'}</Text>
              </Text>
              {/* a label string, not rich children: Claude Code 2.1.287 (and the Desktop build) skips the whole render on those */}
              <Button key={`pick:${p.id}`} plain dimColor={!isOpen} label={p.name} onPress={() => set({ selected: p.id, notice: null })} />
            </Box>
            <Text>
              <Text color={p.color}>{'■'.repeat(lit)}</Text>
              <Text color="#3a3a3a">{'■'.repeat(meter - lit)}</Text>
              <Text color={isActive ? 'success' : undefined} dimColor={!isActive}>
                {nb(isActive ? '  ✓ active' : ` ${String(same).padStart(2)}/${of}`.padEnd(10))}
              </Text>
            </Text>
          </Box>
          <Text dimColor wrap="truncate-end">{nb(`      ${p.tagline}`)}</Text>
          {isOpen && detail(p)}
        </Box>
      )
    })

    return (
      <Box flexDirection="column" width={W} gap={1}>
        <Box key="head" flexDirection="column" width={W}>
          <Box flexDirection="row" justifyContent="space-between" width={W}>
            <Text>
              <Text backgroundColor={ACCENT} color={INK} bold>{nb(' ⚙ ULTRA ')}</Text>
              <Text backgroundColor="#3a2a24" color="#f4ece6" bold>{nb(' CONFIG ')}</Text>
            </Text>
            <Text dimColor>{nb(facts.join(' · '))}</Text>
          </Box>
          <Text color="#3a3a3a">{'─'.repeat(W)}</Text>
          {state.notice && (
            <Text color={state.notice.tone}>{state.notice.tone === 'success' ? '✓ ' : '! '}{state.notice.text}</Text>
          )}
          {snap.error && <Text color="warning">! {snap.error}: effort, env and deny rules are left alone</Text>}
        </Box>
        {cards}
      </Box>
    )
  })
}

// Run with: claude plugin test productivity/ultra-config
import { describe, expect, test } from 'claude-code/testing'
import type { Engine, On } from 'claude-code'

import {
  PROFILES,
  applySettings,
  effortPath,
  matchOf,
  planFor,
  restorable,
  revertSettings,
  sameValue,
  setPath,
  userSettingsPath,
} from '../hooks/profiles.ts'
import type { Live, Row } from '../hooks/profiles.ts'

const row = (key: string, label: string, kind: Row['kind'], value: Row['value'], options?: string[], isLocked = false): Row => ({
  key,
  label,
  kind,
  value,
  options,
  isLocked,
})

/** The rows Claude Code 2.1.301 lists, trimmed to what the profiles touch. */
const ROWS = (): Row[] => [
  row('model', 'Model', 'choice', 'Default (recommended)', ['default', 'sonnet', 'opus', 'haiku', 'best']),
  row('fast', 'Fast mode (Opus 5.5)', 'boolean', false),
  row('thinking', 'Thinking mode', 'boolean', true, undefined, true),
  row('outputStyle', 'Output style', 'choice', 'default', ['default', 'Proactive', 'Concise', 'Explanatory', 'Learning']),
  row('promptSuggestionEnabled', 'Prompt suggestions', 'boolean', true),
  row('recap', 'Session recap', 'boolean', true),
  row('autoCompact', 'Auto-compact', 'boolean', true),
  row('workflowSizeGuideline', 'Dynamic workflow size', 'choice', 'medium', ['unrestricted', 'small', 'medium', 'large']),
  row('workflowKeywordTriggerEnabled', 'Ultracode keyword trigger', 'boolean', true),
  row('workflows', 'Dynamic workflows', 'boolean', true),
  row('permissionMode', 'Default permission mode', 'choice', 'default', ['default', 'plan', 'acceptEdits', 'auto', 'dontAsk']),
  row('useAutoModeDuringPlan', 'Use auto mode during plan', 'boolean', true),
  row('checkpoints', 'Rewind code (checkpoints)', 'boolean', true),
  row('verbose', 'Verbose output', 'boolean', false),
  row('turnDuration', 'Show turn duration', 'boolean', true),
  row('progressBar', 'Terminal progress bar', 'boolean', false),
  row('agentPushNotifEnabled', 'Push when Claude decides', 'boolean', false),
  row('inputNeededNotifEnabled', 'Push when actions required', 'boolean', false),
]

const saver = PROFILES.find(p => p.id === 'saver')!
const guarded = PROFILES.find(p => p.id === 'guarded')!

describe('profiles', () => {
  test('there are five, each with a distinct id, color and at least seven steps', () => {
    expect(PROFILES.map(p => p.id)).toEqual(['saver', 'flow', 'quality', 'guarded', 'autopilot'])
    expect(new Set(PROFILES.map(p => p.color)).size).toBe(5)
    for (const p of PROFILES) expect(p.steps.length).toBeGreaterThanOrEqual(7)
  })

  test('every config step names a row Claude Code 2.1.301 has, with a value that row offers', () => {
    const rows = ROWS()
    for (const p of PROFILES)
      for (const s of p.steps) {
        if (s.layer !== 'config') continue
        const r = rows.find(x => x.key === s.key)
        expect(r).toBeDefined()
        if (r!.kind === 'boolean') expect(typeof s.value).toBe('boolean')
        if (r!.kind === 'choice') expect(r!.options).toContain(s.value as string)
      }
  })

  test('the plan says what changes, what is already set and what cannot be', () => {
    const rows = ROWS().filter(r => r.key !== 'workflowKeywordTriggerEnabled')
    const plan = planFor(saver, rows, { env: { MAX_MCP_OUTPUT_TOKENS: '10000' } })
    const by = (id: string) => plan.find(p => p.id === id)!
    expect(by('config:model')).toMatchObject({ status: 'change', from: 'Default (recommended)', to: 'sonnet' })
    expect(by('config:autoCompact').status).toBe('same')
    expect(by('config:workflowKeywordTriggerEnabled').status).toBe('missing')
    expect(by('effort')).toMatchObject({ status: 'change', from: 'default', to: 'low' })
    expect(by('settings:env.MAX_MCP_OUTPUT_TOKENS').status).toBe('same')
    const { same, of } = matchOf(plan)
    expect(of).toBe(plan.length - 1)
    expect(same).toBe(3)
  })

  test('effort is compared per model: the saved level for the model in use, unless the profile switches model', () => {
    const auto = PROFILES.find(p => p.id === 'autopilot')!
    const user = { effortLevel: 'high', modelSettings: { 'claude-sonnet-5-5': { effortLevel: 'medium' } } }
    const at = (live: Live) => planFor(auto, ROWS(), user, live).find(p => p.id === 'effort')!
    // a top-level effortLevel is ignored by current models, so it does not count
    expect(at({ model: 'claude-sonnet-5-5' })).toMatchObject({ status: 'change', from: 'medium', to: 'high' })
    expect(at({ model: 'claude-opus-5-5', effort: 'high' }).status).toBe('same')
    expect(at({ pending: 'high' }).status).toBe('same')
    // saver switches the model, so the current model's level says nothing
    const s = planFor(saver, ROWS(), { modelSettings: { 'claude-sonnet-5-5': { effortLevel: 'low' } } }, { model: 'claude-sonnet-5-5' })
    expect(s.find(p => p.id === 'effort')!.status).toBe('change')
    expect(effortPath('claude-sonnet-5-5')).toBe('modelSettings.claude-sonnet-5-5.effortLevel')
    expect(effortPath('us.anthropic.claude-sonnet-5-5-v1:0')).toBeUndefined()
  })

  test('a locked row and a value the row does not offer are skipped, not written', () => {
    const rows = ROWS().map(r => (r.key === 'permissionMode' ? { ...r, options: ['default', 'plan'] } : r))
    const auto = PROFILES.find(p => p.id === 'autopilot')!
    expect(planFor(auto, rows, {}).find(p => p.id === 'config:permissionMode')!.status).toBe('invalid')
    const locked = ROWS().map(r => (r.key === 'model' ? { ...r, isLocked: true } : r))
    expect(planFor(saver, locked, {}).find(p => p.id === 'config:model')!.status).toBe('locked')
  })

  test("the menu's label for a value counts as that value", () => {
    expect(sameValue('Default (recommended)', 'default')).toBe(true)
    expect(sameValue('Default (recommended)', 'sonnet')).toBe(false)
    expect(sameValue(true, true)).toBe(true)
    expect(restorable(row('model', 'Model', 'choice', 'Default (recommended)', ['default', 'sonnet']))).toBe('default')
  })

  test('settings steps write, undo restores exactly, and other keys are untouched', () => {
    const before = {
      model: 'opus',
      env: { KEEP: '1', CLAUDE_CODE_SUBAGENT_MODEL: 'sonnet' },
      permissions: { deny: ['Read(./.env)', 'Bash(curl:*)'] },
    }
    const steps = [...saver.steps, ...guarded.steps]
    const { next, entries } = applySettings(before, steps)
    // effort is saved per model at the next request, never as the top-level key current models ignore
    expect(next.effortLevel).toBeUndefined()
    expect((next.env as Record<string, string>).CLAUDE_CODE_SUBAGENT_MODEL).toBe('haiku')
    expect((next.env as Record<string, string>).KEEP).toBe('1')
    const deny = (next.permissions as { deny: string[] }).deny
    expect(deny.filter(d => d === 'Read(./.env)').length).toBe(1)
    expect(deny).toContain('Bash(curl:*)')
    expect(deny).toContain('Read(~/.ssh/**)')
    expect((next.permissions as Record<string, string>).disableBypassPermissionsMode).toBe('disable')
    expect(revertSettings(next, entries)).toEqual(before)
  })

  test('undo removes keys and parents the profile created', () => {
    const { next, entries } = applySettings({}, guarded.steps)
    expect(Object.keys(next)).toEqual(['permissions'])
    expect(revertSettings(next, entries)).toEqual({})
  })

  test('a null value removes the key', () => {
    const quality = PROFILES.find(p => p.id === 'quality')!
    const { next } = applySettings({ env: { CLAUDE_CODE_SUBAGENT_MODEL: 'haiku' } }, quality.steps)
    expect(next.env).toBeUndefined()
    expect(setPath({ a: { b: 1 } }, 'a.b', undefined)).toEqual({})
  })

  test('settings.json is found through CLAUDE_CONFIG_DIR, else the home directory', () => {
    expect(userSettingsPath('/cfg/', '/home/me')).toBe('/cfg/settings.json')
    expect(userSettingsPath(undefined, '/home/me')).toBe('/home/me/.claude/settings.json')
    expect(userSettingsPath(undefined, undefined)).toBeUndefined()
  })
})

// ---------------------------------------------------------------- against the engine

type World = {
  rows: Row[]
  file: string | null
  writes: { path: string; text: string }[]
  sets: { key: string; value: unknown }[]
  log: string[]
  denied: Set<string>
  efforts: unknown[]
}

let w0: World | undefined

function world(on: On, file: string | null = '{\n  "model": "opus"\n}\n', isPlaced = true): World {
  const w: World = { rows: ROWS(), file, writes: [], sets: [], log: [], denied: new Set(), efforts: [] }
  w0 = w
  const store = new Map<string, unknown>()
  on('env.get', (_$, e) => ({ value: e.name === 'HOME' ? '/home/me' : undefined }))
  on('config.list', () => ({ value: w.rows.map(r => ({ ...r, provider: { plugin: 'engine', tier: 'core' } })) }) as never)
  on('config.set', (_$, e) => {
    const r = w.rows.find(x => x.key === e.key)
    if (!r) return { deny: 'no such row' }
    if (w.denied.has(e.key)) return { deny: `${r.label} can only be turned on from the /config panel.` }
    w.log.push(`set ${e.key}`)
    w.sets.push({ key: e.key, value: e.value })
    r.value = e.value as Row['value']
    return { value: e.value }
  })
  on('fs.read', (_$, e) => {
    if (e.path === '/home/me/.claude/settings.json' && w.file !== null) return { value: w.file }
    throw new Error('ENOENT')
  })
  on('fs.write', (_$, e) => {
    w.writes.push({ path: e.path, text: e.text })
    w.log.push(`write ${e.path.split('/').pop()}`)
    if (e.path === '/home/me/.claude/settings.json') w.file = e.text
    return { value: undefined }
  })
  // the engine's loaded copy follows the file, as it does once it reloads
  on('settings.read', () => ({ value: w.file ? (JSON.parse(w.file) as object) : {} }) as never)
  on('store.get', (_$, e) => ({ value: store.get(e.key) }))
  on('store.set', (_$, e) => {
    store.set(e.key, e.value)
    return { value: undefined }
  })
  on('command.register', () => ({ value: undefined }) as never)
  on('ui.open', () => ({ value: { isPlaced } }) as never)
  on('ui.close', () => ({ value: undefined }))
  on('ui.toast', () => ({ value: undefined }))
  on('ui.log', () => ({ value: undefined }))
  on('ui.invalidate', () => ({ value: undefined }))
  on('session.start', (_$, e) => ({ cwd: e.cwd }) as never)
  on('turn.step', async function* (_$, e) {
    w.efforts.push(e.effort)
    return { turnId: e.turnId, index: e.index, answer: '', toolUses: [], stopReason: 'end_turn' } as never
  })
  return w
}

/** One main-loop request; resolves to the effort it was sent with. */
async function step($: Engine, model: string, effort?: string) {
  const stream = $.turn.step({ turnId: 't1', index: 0, model, messageCount: 3, ...(effort ? { effort } : {}) } as never)
  for (;;) if ((await stream.next()).done) break
  return w0!.efforts.at(-1)
}

const run = (args: string) =>
  ({ command: 'ultra-config', args, origin: { kind: 'composer' }, presentation: { isFullscreen: true, columns: 160 } }) as never

const PANE = { title: 'ultra config', isFocused: true, bodyColumns: 62, placement: 'dock' as const, scroll: { offset: 0, bodyRows: 40 }, view: {} }

describe('the command', () => {
  test('apply writes the config rows, then settings.json with a backup, and undo puts both back', async ($, on) => {
    const w = world(on)
    await $.session.start({ cwd: '/work', surface: 'terminal', isInteractive: true } as never)
    const out = (await $.command.run(run('apply saver'))) as { text: string }
    expect(out.text).toMatch(/Token saver activated: \d+ settings changed/)
    expect(w.sets).toContainEqual({ key: 'model', value: 'sonnet' })
    expect(w.sets).toContainEqual({ key: 'outputStyle', value: 'Concise' })
    expect(w.writes[0]).toEqual({ path: '/home/me/.claude/settings.json.ultra-config.bak', text: '{\n  "model": "opus"\n}\n' })
    const written = JSON.parse(w.file!)
    expect(written).toMatchObject({ model: 'opus', env: { CLAUDE_CODE_SUBAGENT_MODEL: 'haiku', MAX_MCP_OUTPUT_TOKENS: '10000' } })
    expect(written.effortLevel).toBeUndefined()

    // the next request names the model: the effort is saved under it and sent with it
    expect(await step($, 'claude-sonnet-5-5')).toBe('low')
    expect(JSON.parse(w.file!).modelSettings).toEqual({ 'claude-sonnet-5-5': { effortLevel: 'low' } })
    // once saved, later requests are left as the engine made them
    expect(await step($, 'claude-sonnet-5-5', 'medium')).toBe('medium')

    w.sets.length = 0
    const undone = (await $.command.run(run('undo'))) as { text: string }
    expect(undone.text).toMatch(/Undid Token saver/)
    expect(w.sets).toContainEqual({ key: 'model', value: 'default' })
    expect(w.sets).toContainEqual({ key: 'outputStyle', value: 'default' })
    expect(JSON.parse(w.file!)).toEqual({ model: 'opus' })
    expect(((await $.command.run(run('undo'))) as { text: string }).text).toBe('Nothing to undo')
  })

  test('settings.json is written before any /config row, so the engine writes rows from the new file', async ($, on) => {
    const w = world(on)
    await $.session.start({ cwd: '/work', surface: 'terminal', isInteractive: true } as never)
    await $.command.run(run('apply saver'))
    const firstSet = w.log.findIndex(l => l.startsWith('set '))
    expect(w.log.lastIndexOf('write settings.json')).toBeLessThan(firstSet)
    w.log.length = 0
    await $.command.run(run('undo'))
    expect(w.log.lastIndexOf('write settings.json')).toBeLessThan(w.log.findIndex(l => l.startsWith('set ')))
  })

  test('a row the engine refuses is reported and left out of the undo', async ($, on) => {
    const w = world(on)
    w.denied.add('permissionMode')
    await $.session.start({ cwd: '/work', surface: 'terminal', isInteractive: true } as never)
    const out = (await $.command.run(run('apply autopilot'))) as { text: string }
    expect(out.text).toMatch(/⊘ Default permission mode: Default permission mode can only be turned on from the \/config panel\./)
    w.sets.length = 0
    await $.command.run(run('undo'))
    expect(w.sets.map(s => s.key)).not.toContain('permissionMode')
  })

  test('a settings.json that is not JSON is never overwritten', async ($, on) => {
    const w = world(on, '{ "model": "opus", // a comment\n}')
    await $.session.start({ cwd: '/work', surface: 'terminal', isInteractive: true } as never)
    const out = (await $.command.run(run('apply saver'))) as { text: string }
    expect(out.text).toMatch(/skipped/)
    expect(out.text).toMatch(/Subagent model: settings.json is not valid JSON/)
    expect(w.writes.filter(x => x.path.endsWith('settings.json'))).toEqual([])
    expect(w.sets.length).toBeGreaterThan(0)
  })

  test('a profile name alone opens its detail in the pane without writing anything', async ($, on) => {
    const w = world(on)
    await $.session.start({ cwd: '/work', surface: 'terminal', isInteractive: true } as never)
    const out = (await $.command.run(run('guarded'))) as { text: string }
    expect(out.text).toBe('▣ Guarded: 5 changes, shown in the pane · /ultra-config apply guarded')
    expect(w.sets).toEqual([])
    expect(w.writes).toEqual([])
  })

  test('where no pane can be placed, the profile detail is the command output', async ($, on) => {
    const w = world(on, '{}', false)
    await $.session.start({ cwd: '/work', surface: 'terminal', isInteractive: true } as never)
    const out = (await $.command.run(run('guarded'))) as { text: string }
    expect(out.text).toMatch(/▣ Guarded/)
    expect(out.text).toMatch(/Deny rules: none → \+5 rules/)
    expect(out.text).toMatch(/\/ultra-config apply guarded/)
    expect(w.sets).toEqual([])
    expect(w.writes).toEqual([])
  })

  test('an unknown profile is named, not guessed', async ($, on) => {
    world(on)
    await $.session.start({ cwd: '/work', surface: 'terminal', isInteractive: true } as never)
    const out = (await $.command.run(run('apply cheap'))) as { text: string }
    expect(out.text).toMatch(/Unknown profile "cheap"/)
  })
})

