{
  "description": "Short-circuits repeated WebFetch calls for the same URL and prompt within a session, answering { result } from cache without a network round trip. A tool.call hook with TTL and size limits.",
  "modules": [
    "./webfetch-cache.ts"
  ]
}

/**
 * webfetch-cache — Claude Mod
 *
 * Short-circuits repeated WebFetch calls for the same URL + prompt within a
 * session. On a cache hit the hook answers `{ result }` itself without calling
 * `next` (no network call); on a miss it awaits the real fetch, stores the
 * tool's record and returns what came back.
 *
 * Only the tool's own record (`result`) is cached, never core's `ref`: that
 * number names the messages core produced for one specific call and must not
 * be replayed on another.
 *
 * Needs Claude Code >= 2.1.287. Typed
 * against Anthropic's declarations: https://github.com/anthropics/claude-code/tree/main/mods
 *
 * Options:
 *   ttlSeconds: number  how long an entry stays fresh (default 900)
 *   maxEntries: number  cache size (default 200)
 */
import type { Register, ToolCallResult } from 'claude-code'

type WebFetchRecord = Extract<ToolCallResult<'WebFetch'>, { result: unknown }>['result']

interface Entry { result: WebFetchRecord; storedAt: number }

// Module state lives for the session (a plugin's module is one worker).
const cache = new Map<string, Entry>()

export const register: Register = (on, options) => {
  const ttlMs = (typeof options.ttlSeconds === 'number' ? options.ttlSeconds : 900) * 1000
  const maxEntries = typeof options.maxEntries === 'number' ? options.maxEntries : 200

  on('tool.call', { tool: 'WebFetch' }, async ($, e, next) => {
    if (!e.url) return next(e)
    // WebFetch reads a long page in pieces (`offset`, Claude Code 2.1.290+): each piece is its own entry,
    // or a read past the first page would get the first page back. Not in the typings until they are regenerated (TODO: drop the cast then).
    const offset = (e as { offset?: unknown }).offset
    const key = `${e.url}\n${e.prompt}\n${typeof offset === 'number' ? offset : 0}`
    const now = Date.now()

    const hit = cache.get(key)
    if (hit && now - hit.storedAt < ttlMs) {
      const age = Math.round((now - hit.storedAt) / 1000)
      $.ui.log(`[webfetch-cache] hit for ${e.url} (${age}s old)`)
      // Nothing below this hook runs: no network call.
      return {
        result: hit.result,
        context: [`webfetch-cache served this result from a ${age}s-old cache entry for the same URL, prompt and offset.`],
      }
    }

    const outcome = await next(e)

    // Do not cache a denial or an errored fetch.
    if (outcome.deny === undefined && !outcome.isError) {
      if (cache.size >= maxEntries) {
        const oldest = cache.keys().next().value
        if (oldest !== undefined) cache.delete(oldest)
      }
      cache.set(key, { result: outcome.result, storedAt: now })
    }
    return outcome
  })
}

// Run with: claude plugin test productivity/webfetch-cache
import { describe, expect, test } from 'claude-code/testing'
import type { Engine } from 'claude-code/testing'
import type { On } from 'claude-code'

type World = { fetched: number[] }

function fakeEngine(on: On, w: World) {
  on('ui.log', () => ({ value: undefined }))
  on('tool.call', async ($, e) => {
    const offset = (e as unknown as { offset?: number }).offset ?? 0
    w.fetched.push(offset)
    return { result: { text: `page at ${offset}` } } as never
  })
}

const fetch = async ($: Engine, offset?: number) =>
  (await $.tool.call({ tool: 'WebFetch', url: 'https://example.com/long', prompt: 'summarize', ...(offset === undefined ? {} : { offset }) } as never)) as {
    result?: { text: string }
  }

describe('webfetch-cache', () => {
  test('a repeated fetch is served from the cache', async ($, on) => {
    const w: World = { fetched: [] }
    fakeEngine(on, w)
    await fetch($)
    const again = await fetch($)
    expect(w.fetched).toEqual([0])
    expect(again.result?.text).toBe('page at 0')
  })

  test('a read further down the page is not answered with the first page', async ($, on) => {
    const w: World = { fetched: [] }
    fakeEngine(on, w)
    await fetch($)
    const next = await fetch($, 100_000)
    expect(w.fetched).toEqual([0, 100_000])
    expect(next.result?.text).toBe('page at 100000')
    // and that piece is cached on its own
    await fetch($, 100_000)
    expect(w.fetched).toEqual([0, 100_000])
  })
})

{
  "name": "block-destructive-commands",
  "version": "0.2.0",
  "description": "Denies Bash commands that match destructive patterns (recursive rm on roots, force push, hard reset, destructive SQL, disk formatting) before they run. A tool.call hook with a Bash matcher that returns { deny } without calling next.",
  "author": {
    "name": "claude-code-templates",
    "url": "https://www.aitmpl.com"
  },
  "repository": "https://github.com/davila7/claude-code-templates",
  "license": "MIT",
  "keywords": [
    "mod",
    "function-hooks",
    "security"
  ],
  "userConfig": {
    "patterns": {
      "type": "string",
      "title": "Extra patterns",
      "description": "Comma-separated regex sources to deny on top of the built-in rules, e.g. \\bkubectl\\s+delete\\b",
      "default": ""
    }
  }
}

/**
 * block-destructive-commands — Claude Mod
 *
 * Denies Bash commands that match destructive patterns before they run.
 * A `tool.call` hook under a `{ tool: "Bash" }` matcher: on a match it returns
 * `{ deny }` without calling `next`, so nothing beneath (other plugins,
 * PreToolUse shell hooks, the tool itself) runs; otherwise it passes through.
 *
 * Needs Claude Code >= 2.1.287. Typed
 * against Anthropic's declarations: https://github.com/anthropics/claude-code/tree/main/mods
 *
 * Options (plugin.json "userConfig" / hooks module options):
 *   patterns: string  extra regex sources, comma-separated, e.g. "\\bkubectl\\s+delete\\b"
 */
import type { Register } from 'claude-code'

/** A list option: a string[] or a comma-separated string (what a manifest's `userConfig` string field holds); empty means unset. */
function strings(value: unknown): string[] | undefined {
  const list = Array.isArray(value)
    ? value.filter((v): v is string => typeof v === 'string')
    : typeof value === 'string'
      ? value.split(',').map((s) => s.trim()).filter(Boolean)
      : []
  return list.length > 0 ? list : undefined
}

interface Rule { pattern: RegExp; reason: string }

const DEFAULT_RULES: readonly Rule[] = [
  // rm with a recursive flag anywhere in its arguments (-r, -rf, -r -f, --recursive, -fR ...)
  // and a root/home/cwd target, optionally quoted or with a trailing slash ("~/", "$HOME/", "/").
  // The target may be quoted in whole or in part ("$HOME"/., '~'/) and end in "/" or "/.".
  { pattern: /\brm\s+(?=(?:\S+\s+)*?(?:-[a-z]*r[a-z]*|--recursive)\b)(?:\S+\s+)*?["']?(?:\/|~|\$HOME|\$\{HOME\}|\.\.?)["']?(?:\/\.?)?["']?(?:\s|$|;|&|\|)/i, reason: 'recursive delete of a root, home or working directory' },
  { pattern: /\brm\s+.*--no-preserve-root\b/i, reason: 'rm with --no-preserve-root' },
  // -f alone or inside a short-option cluster (-fu, -uf); --force-with-lease is the safe form
  { pattern: /\bgit\s+push\b(?!.*--force-with-lease).*(--force\b|\s-[a-zA-Z]*f[a-zA-Z]*\b)/, reason: 'force push' },
  { pattern: /\bgit\s+(reset\s+--hard|clean\s+(?:-[a-zA-Z]*f|.*--force\b))/, reason: 'history or working-tree destruction' },
  { pattern: /\b(DROP|TRUNCATE)\s+(TABLE|DATABASE|SCHEMA)\b/i, reason: 'destructive SQL' },
  { pattern: /\bmkfs(\.|\s)/, reason: 'filesystem format' },
  { pattern: /\bdd\s+.*\bof=["']?\/dev\//, reason: 'raw disk write' },
  { pattern: /\bchmod\s+(-R\s+)?777\b/, reason: 'world-writable permissions' },
]

export const register: Register = (on, options) => {
  // a custom pattern that does not compile is skipped, never a reason to lose the built-in rules
  const custom: Rule[] = []
  for (const p of strings(options.patterns) ?? []) {
    try {
      custom.push({ pattern: new RegExp(p), reason: `custom pattern ${p}` })
    } catch {
      // ignored: the defaults still apply
    }
  }
  const rules = [...DEFAULT_RULES, ...custom]

  on('tool.call', { tool: 'Bash' }, ($, e, next) => {
    for (const { pattern, reason } of rules) {
      if (pattern.test(e.command)) {
        $.ui.log(`[block-destructive-commands] denied Bash call: ${reason}`)
        // The model receives this text as the tool's error result.
        return {
          deny:
            `Blocked by block-destructive-commands (${reason}). ` +
            'If this is intentional, ask the user to run it manually.',
        }
      }
    }

    // Nothing matched: let the rest of the chain (and the real tool) run.
    return next(e)
  }).catch(async ($, e, next) => {
    // The check had passed and the command ran: hand back its result (replayed, nothing runs twice).
    if (next.called) {
      try {
        return await next(e)
      } catch {
        return { deny: 'The Bash call failed.' }
      }
    }
    // A failed check never lets the command through unchecked (fail closed).
    $.ui.log(`[block-destructive-commands] check failed (${next.error.kind}); denied Bash call`)
    return {
      deny:
        `block-destructive-commands could not check this command (${next.error.kind}), so it was not run. ` +
        'Ask the user to run it manually.',
    }
  })
}

