    expect(evaluate(cfg, toolAction('Agent', { subagent_type: 'Explore', prompt: 'x' }), ctx).source).toBe('fallback')
    expect(evaluate(cfg, toolAction('Agent', { subagent_type: 'Explore', prompt: 'x' }, 'sub-1'), ctx).source).toBe('rule')
