  "keywords": [
    "mod",
    "function-hooks",
    "security"
  ],
  "userConfig": {
    "protect": {
      "type": "string",
      "title": "Extra protected globs",
      "description": "Comma-separated globs to protect on top of the defaults",
      "default": ""
    },
    "allow": {
      "type": "string",
      "title": "Always-allowed globs",
      "description": "Comma-separated globs that are always allowed (checked first)",
