{
  "description": "Denies Edit, Write and NotebookEdit calls on sensitive paths (.env files, lockfiles, CI workflows, git internals, private keys) with a glob allowlist override. A tool.call hook with an array matcher.",
  "modules": [
    "./protected-paths-guard.ts"
  ]
}

/**
 * protected-paths-guard — Claude Mod
 *
 * Denies Edit / Write / NotebookEdit calls that target sensitive files
 * (.env, lockfiles, CI workflows, git internals, private keys) unless the path
 * is allowlisted. A `tool.call` hook under an array matcher (any of the named
 * tools); on a match it returns `{ deny }` without calling `next`.
 *
 * Needs Claude Code >= 2.1.287. Typed
 * against Anthropic's declarations: https://github.com/anthropics/claude-code/tree/main/mods
 *
 * Options:
 *   protect: string  extra globs to protect, comma-separated
 *   allow:   string  globs that are always allowed (checked first), comma-separated
 */
import type { Register } from 'claude-code'

// Minimal glob support: "**" = any depth, "*" = any chars except "/". One pass over the glob, so
// the regex a wildcard produces is never rewritten by a later replacement.
function globToRegExp(glob: string): RegExp {
  const source = glob.replace(/\*\*\/|\*\*|\*|[.+^${}()|[\]\\]/g, (m) =>
    m === '**/' ? '(?:.*/)?' : m === '**' ? '.*' : m === '*' ? '[^/]*' : `\\${m}`,
  )
  return new RegExp(`(^|/)${source}$`)
}

const DEFAULT_PROTECTED: readonly string[] = [
  '.env',
  '.env.*',
  '**/.git/**',
  'package-lock.json',
  'pnpm-lock.yaml',
  'yarn.lock',
  'Cargo.lock',
  'poetry.lock',
  '.github/workflows/*.yml',
  '.github/workflows/*.yaml',
  '**/*.pem',
  '**/*.key',
  '**/id_rsa*',
]

/** A list option: a string[] or a comma-separated string (what a manifest's `userConfig` string field holds); empty means unset. */
function strings(value: unknown): string[] | undefined {
  const list = Array.isArray(value)
    ? value.filter((v): v is string => typeof v === 'string')
    : typeof value === 'string'
      ? value.split(',').map((s) => s.trim()).filter(Boolean)
      : []
  return list.length > 0 ? list : undefined
}

export const register: Register = (on, options) => {
  const protectedGlobs = [...DEFAULT_PROTECTED, ...(strings(options.protect) ?? [])]
  const allowGlobs = strings(options.allow) ?? []
  const protectedRes = protectedGlobs.map(globToRegExp)
  const allowRes = allowGlobs.map(globToRegExp)

  // An array in a matcher matches when any element matches.
  on('tool.call', { tool: ['Edit', 'Write', 'NotebookEdit'] }, ($, e, next) => {
    const rawPath = e.tool === 'NotebookEdit' ? e.notebook_path : e.file_path
    const filePath = rawPath.replace(/\\/g, '/')
    if (!filePath) return next(e)

    if (allowRes.some((re) => re.test(filePath))) return next(e)

    const hit = protectedRes.findIndex((re) => re.test(filePath))
    if (hit !== -1) {
      const rule = protectedGlobs[hit]
      $.ui.log(`[protected-paths-guard] denied ${e.tool} on ${filePath} (rule: ${rule})`)
      return {
        deny:
          `${filePath} is protected by protected-paths-guard (rule "${rule}"). ` +
          'Ask the user to edit it manually or add the path to the plugin\'s "allow" option.',
      }
    }

    return next(e)
  }).catch(async ($, e, next) => {
    // The check had passed and the write ran: hand back its result (replayed, nothing runs twice).
    if (next.called) {
      try {
        return await next(e)
      } catch {
        return { deny: `The ${e.tool} on ${e.tool === 'NotebookEdit' ? e.notebook_path : e.file_path} failed.` }
      }
    }
    // A failed check never lets the write through unchecked (fail closed).
    $.ui.log(`[protected-paths-guard] check failed (${next.error.kind}); denied ${e.tool}`)
    return { deny: `protected-paths-guard could not check this path (${next.error.kind}), so the ${e.tool} was not run. Ask the user to make the change manually.` }
  })
}

{
  "name": "secret-redactor",
  "version": "0.2.0",
  "description": "Redacts API keys, tokens, JWTs, private keys and connection strings from every tool result before the model reads them, notes the redaction through context, and refuses to echo a redacted placeholder back into a Bash command. A tool.call hook in the after placement.",
  "author": {
    "name": "claude-code-templates",
    "url": "https://www.aitmpl.com"
  },
  "repository": "https://github.com/davila7/claude-code-templates",
  "license": "MIT",
  "keywords": [
    "mod",
    "function-hooks",
    "security"
  ],
  "userConfig": {
    "patterns": {
      "type": "string",
      "title": "Extra patterns",
      "description": "Comma-separated regex sources to redact on top of the built-in credential patterns",
      "default": ""
    }
  }
}

{
  "description": "Redacts API keys, tokens, JWTs, private keys and connection strings from every tool result before the model reads them, notes the redaction through context, and refuses to echo a redacted placeholder back into a Bash command. A tool.call hook in the after placement.",
  "modules": [
    "./secret-redactor.ts"
  ]
}

/**
 * secret-redactor — Claude Mod
 *
 * Replaces credential-shaped strings in every tool result before the model
 * reads it, and refuses to echo a redacted placeholder back into a Bash
 * command. One `tool.call` hook: it awaits `next(e)` (the "after" placement),
 * deep-replaces every string in what came back and tells the model, through
 * `context`, that a redaction happened so it is not confused by placeholders.
 *
 * This is the shape the engine's author gives for a redactor:
 *   on("tool.call", async ($, e, next) => recursiveStrReplace(await next(e), ...))
 * Seat it as low as possible (an org appends it in managed settings) so no
 * plugin above ever sees the raw value on the way up.
 *
 * Needs Claude Code >= 2.1.287. Typed
 * against Anthropic's declarations: https://github.com/anthropics/claude-code/tree/main/mods
 *
 * Options:
 *   patterns: string  extra regex sources, comma-separated (global flag is added)
 */
import type { Register } from 'claude-code'

/** A list option: a string[] or a comma-separated string (what a manifest's `userConfig` string field holds); empty means unset. */
function strings(value: unknown): string[] | undefined {
  const list = Array.isArray(value)
    ? value.filter((v): v is string => typeof v === 'string')
    : typeof value === 'string'
      ? value.split(',').map((s) => s.trim()).filter(Boolean)
      : []
  return list.length > 0 ? list : undefined
}

interface Pattern { name: string; re: RegExp }

const DEFAULT_PATTERNS: readonly Pattern[] = [
  { name: 'aws-access-key', re: /\bAKIA[0-9A-Z]{16}\b/g },
  { name: 'anthropic-api-key', re: /\bsk-ant-api\d{2}-[A-Za-z0-9_-]{20,}\b/g },
  { name: 'openai-api-key', re: /\bsk-(?:proj-|svcacct-|admin-)?[A-Za-z0-9_-]{20,}\b/g },
  { name: 'github-token', re: /\b(?:gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{22,})\b/g },
  { name: 'google-api-key', re: /\bAIza[0-9A-Za-z_-]{35}\b/g },
  { name: 'stripe-key', re: /\b[sr]k_(live|test)_[0-9A-Za-z]{24,}\b/g },
  { name: 'slack-token', re: /\bxox[abpr]-[0-9A-Za-z-]{10,}\b/g },
  { name: 'jwt', re: /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g },
  { name: 'private-key-block', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g },
  { name: 'connection-string', re: /\b(postgres(ql)?|mysql|mongodb(\+srv)?|redis):\/\/[^:\s]+:[^@\s]+@/gi },
]

function redactString(input: string, patterns: readonly Pattern[], hits: Set<string>): string {
  let out = input
  for (const { name, re } of patterns) {
    out = out.replace(re, () => {
      hits.add(name)
      return `[REDACTED:${name}]`
    })
  }
  return out
}

/** Walk any JSON-ish value and redact every string inside it. */
function redactDeep<T>(value: T, patterns: readonly Pattern[], hits: Set<string>): T {
  if (typeof value === 'string') return redactString(value, patterns, hits) as T
  if (Array.isArray(value)) return value.map((v) => redactDeep(v, patterns, hits)) as T
  if (value && typeof value === 'object') {
    const copy: Record<string, unknown> = {}
    for (const [k, v] of Object.entries(value)) copy[k] = redactDeep(v, patterns, hits)
    return copy as T
  }
  return value
}

export const register: Register = (on, options) => {
  // a custom pattern that does not compile is skipped, never a reason to lose the built-in ones
  const custom: Pattern[] = []
  for (const p of strings(options.patterns) ?? []) {
    try {
      custom.push({ name: 'custom', re: new RegExp(p, 'g') })
    } catch {
      // reported once the hook runs, where $.ui.log exists
    }
  }
  const patterns: readonly Pattern[] = [...DEFAULT_PATTERNS, ...custom]

  on('tool.call', async ($, e, next) => {
    // 1. Never let a redacted placeholder travel back into a shell command.
    if (e.tool === 'Bash' && e.command.includes('[REDACTED:')) {
      return {
        deny:
          'The command contains a redacted secret placeholder. ' +
          'Read the value from an environment variable instead of pasting it.',
      }
    }

    // 2. Redact the result (or a denial's reason) before it enters the transcript.
    const outcome = await next(e)
    const hits = new Set<string>()
    const cleaned = redactDeep(outcome, patterns, hits)
    if (hits.size === 0) return outcome
    if (cleaned.deny !== undefined) {
      $.ui.log(`[secret-redactor] redacted ${[...hits].join(', ')} from a denial of ${e.tool}`)
      return cleaned
    }

    const kinds = [...hits].join(', ')
    $.ui.log(`[secret-redactor] redacted ${kinds} from ${e.tool} output`)
    return {
      ...cleaned,
      context: [
        ...(cleaned.context ?? []),
        `secret-redactor replaced ${hits.size} kind(s) of secret (${kinds}) with [REDACTED:*] placeholders before you read this result. Never paste a placeholder into a command.`,
      ],
    }
  }).catch(async ($, e, next) => {
    // Fail closed: nothing reaches the transcript that was not scanned.
    if (!next.called) {
      $.ui.log(`[secret-redactor] check failed (${next.error.kind}); denied ${e.tool}`)
      return { deny: `secret-redactor could not check this ${e.tool} call (${next.error.kind}), so it was not run.` }
    }
    try {
      await next(e) // replayed: what the tool settled to, nothing runs again
    } catch {
      // The call itself failed; its error text is not passed on, since it was never scanned.
      $.ui.log(`[secret-redactor] ${e.tool} failed; its error was withheld unscanned`)
      return { deny: `The ${e.tool} call failed, and secret-redactor withheld its error unscanned.` }
    }
    // The tool ran and its output could not be scanned: its effects stand, only the output is kept back.
    $.ui.log(`[secret-redactor] redaction failed (${next.error.kind}); withheld the ${e.tool} output`)
    return {
      deny: `secret-redactor could not scan the ${e.tool} output for secrets (${next.error.kind}), so it was withheld. The tool did run. Ask the user to check the output themselves.`,
    }
  })
}

// Run with: claude plugin test security/secret-redactor
import { describe, expect, test } from 'claude-code/testing'
import type { On } from 'claude-code'

const KEY = 'AKIAABCDEFGHIJKLMNOP'

function fakeEngine(on: On, answer: () => unknown) {
  on('ui.log', () => ({ value: undefined }))
  on('tool.call', async () => answer() as never)
}

describe('secret-redactor', () => {
  test('redacts a secret in a tool result', async ($, on) => {
    fakeEngine(on, () => ({ result: { stdout: `key=${KEY}` } }))
    const r = (await $.tool.call({ tool: 'Bash', command: 'cat .env' } as never)) as { result?: { stdout: string } }
    expect(r.result?.stdout).toBe('key=[REDACTED:aws-access-key]')
  })

  test('a failure while handling the result withholds it instead of passing it on unredacted', async ($, on) => {
    fakeEngine(on, () => {
      throw new Error('boom')
    })
    const r = (await $.tool.call({ tool: 'Bash', command: 'cat .env' } as never)) as { deny?: string; result?: unknown }
    expect(r.result).toBeUndefined()
    expect(r.deny).toBe('The Bash call failed, and secret-redactor withheld its error unscanned.')
  })

  test('a redacted placeholder never travels back into a command', async ($, on) => {
    fakeEngine(on, () => ({ result: { stdout: 'ran' } }))
    const r = (await $.tool.call({ tool: 'Bash', command: 'echo [REDACTED:aws-access-key]' } as never)) as { deny?: string }
    expect(r.deny).toContain('redacted secret placeholder')
  })
})

{
  "name": "agent-flow",
  "version": "0.1.0",
  "description": "A side pane that draws the session's agent flow live: the main loop's context window, every subagent it spawns as a tree, and for each one the context handed down (its prompt, or the whole parent context for a fork), what it did with it (steps, tools, context size) and the answer it handed back up. Docked beside the transcript in the fullscreen layout, above the prompt otherwise.",
  "author": {
    "name": "claude-code-templates",
    "url": "https://www.aitmpl.com"
  },
  "repository": "https://github.com/davila7/claude-code-templates",
  "license": "MIT",
  "keywords": ["mod", "function-hooks", "ui", "agents", "subagents", "context", "sidebar"],
  "userConfig": {
    "columns": {
      "type": "number",
      "title": "Pane width",
      "description": "Columns asked for the docked pane in the fullscreen layout (32-120); a width you drag it to wins",
      "default": 52
    },
    "maxAgents": {
      "type": "number",
      "title": "Agents kept",
      "description": "How many subagents the flow keeps, oldest finished ones dropped first",
      "default": 60
    },
    "openOnStart": {
      "type": "boolean",
      "title": "Open on start",
      "description": "Open the pane when the session starts; the engine keeps an unasked pane hidden below 144 columns",
      "default": false
    }
  }
}

/**
 * agent-flow — Claude Mod
 *
 * A side pane that draws the session's agents as they run: the main loop and
 * its context window on top, then every subagent as a tree in spawn order.
 * Select an agent (click, or Tab and Enter) to see the context it was handed
 * (its prompt, or the parent's whole context for a fork), what it did with it
 * (steps, tool calls, how full its own window got) and the answer it handed
 * back up. Select the main loop for the /context breakdown of the session.
 *
 *   `/agent-flow` opens it · `/agent-flow clear` forgets finished agents ·
 *   `/agent-flow stop` closes it
 *
 * It only observes: every hook passes its event on unchanged, and the only
 * engine reads are `$.agent.list()` and `$.session.usage()`. The flow is
 * recorded from session start whether the pane is open or not.
 *
 * Needs Claude Code >= 2.1.287.
 *
 * Options (pluginConfigs["agent-flow@skills-dir"].options):
 *   columns: number      width asked for the docked pane (default 52)
 *   maxAgents: number    subagents kept, oldest finished dropped first (default 60)
 *   openOnStart: boolean open the pane when the session starts (default false)
 */
import type { ContextCategory, Register } from 'claude-code'
import {
  MAIN,
  STATUS_MARK,
  bar,
  completed,
  counts,
  createFlow,
  estimateTokens,
  excerpt,
  fit,
  fmtDuration,
  fmtTokens,
  mainTurn,
  maxAgents,
  paneColumns,
  rows,
  spawned,
  stepped,
  synced,
  toolLabel,
  toolRan,
  trimmed,
} from './flow.ts'
import type { Flow, FlowNode, Status } from './flow.ts'

const PANE = 'agent-flow'
const COMMAND = 'agent-flow'
const KEY = 'ag:'

let flow: Flow = createFlow()
let isOpen = false
let selected: string | undefined
let breakdown: ContextCategory[] | undefined

const STATUS_COLOR: Record<Status, string> = { running: 'yellow', done: 'green', failed: 'red', aborted: 'gray' }

function statusText(): string | undefined {
  if (!isOpen) return undefined
  const c = counts(flow)
  const parts = [`${c.running} running`, `${c.done} done`]
  if (c.failed) parts.push(`${c.failed} failed`)
  const ctx = flow.percent !== undefined ? ` · ctx ${flow.percent}%` : ''
  return `agents: ${parts.join(' · ')}${ctx}`
}

/** Tokens handed down to a node's children and handed back up by them. */
function exchanged(node: FlowNode): { down: number; up: number; kids: number } {
  let down = 0
  let up = 0
  let kids = 0
  for (const n of flow.nodes.values()) {
    if (n.parentId !== node.id) continue
    kids += 1
    down += n.fork ? (node.contextTokens ?? 0) : estimateTokens(n.prompt)
    up += estimateTokens(n.answer)
  }
  return { down, up, kids }
}

export const register: Register = (on, options) => {
  const columns = paneColumns(options.columns)
  const keep = maxAgents(options.maxAgents)
  const openOnStart = options.openOnStart === true

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    flow = createFlow(Date.now())
    selected = undefined
    breakdown = undefined
    await $.command
      .register({
        name: COMMAND,
        description: 'Live tree of the session’s agents and the context passed between them (clear|stop)',
        argumentHint: '[clear|stop]',
        immediate: true,
      })
      .catch(err => $.ui.log(`agent-flow: /${COMMAND} not registered: ${err}`))
    $.ui.log(`agent-flow loaded: /${COMMAND} opens the pane`, { to: 'debug' })
    if (openOnStart) {
      isOpen = true
      await $.ui.open({ id: PANE, title: 'agents', columns }).catch(err => {
        isOpen = false
        $.ui.log(`agent-flow: pane not opened: ${err}`)
      })
      $.ui.status(statusText())
    }
    return r
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'stop' || arg === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      isOpen = false
      $.ui.status(undefined)
      return { text: 'agent-flow closed' }
    }
    if (arg === 'clear') {
      trimmed(flow, counts(flow).running)
      selected = undefined
      if (isOpen) {
        $.ui.status(statusText())
        $.ui.invalidate('ui.render')
      }
      return { text: 'agent-flow: finished agents cleared' }
    }
    synced(flow, await $.agent.list().catch(() => []))
    try {
      await $.ui.open({ id: PANE, title: 'agents', focus: true, columns })
    } catch (err) {
      isOpen = false
      return { text: `agent-flow: pane not opened: ${err}` }
    }
    isOpen = true
    $.ui.status(statusText())
    $.ui.invalidate('ui.render')
    const c = counts(flow)
    const hint = e.presentation.isFullscreen
      ? 'click an agent, or Tab and Enter'
      : 'drawn above the prompt; /tui fullscreen docks it beside the transcript'
    return { text: `${c.running + c.done + c.failed} agents so far · ${hint} · /${COMMAND} stop closes` }
  })

  on('turn.start', async ($, e, next) => {
    // Since Claude Code 2.1.299 a subagent's or teammate's turn starts here too (its prompt in `e.text`).
    // Subagents enter the flow through agent.spawn.
    if (e.agentId !== undefined) return next(e)
    mainTurn(flow, e.text, Date.now())
    if (isOpen) {
      $.ui.status(statusText())
      $.ui.invalidate('ui.render')
    }
    return next(e)
  })

  // the context handed down: the Agent call's prompt, known before the subagent runs
  on('agent.spawn', async ($, e, next) => {
    const r = await next(e)
    if (r.agentId) {
      spawned(
        flow,
        {
          agentId: r.agentId,
          parentAgentId: e.parentAgentId,
          description: e.description,
          subagentType: e.subagentType,
          prompt: e.prompt,
          fork: e.fork,
          background: e.background,
          model: r.model,
          resumed: e.resume !== undefined,
        },
        Date.now(),
      )
      trimmed(flow, keep)
      if (isOpen) {
        $.ui.status(statusText())
        $.ui.invalidate('ui.render')
      }
    }
    return r
  })

  // each model request: how full that loop's window is now
  on('turn.step', async function* ($, e, next) {
    const r = yield* next(e)
    stepped(flow, e.agentId, r.usage, Date.now())
    if (isOpen) {
      $.ui.status(statusText())
      $.ui.invalidate('ui.render')
    }
    return r
  })

  on('tool.call', async ($, e, next) => {
    const use = { tool: e.tool, label: toolLabel(e.tool, e as unknown as Record<string, unknown>) }
    toolRan(flow, e.agentId, use, Date.now())
    if (isOpen) {
      $.ui.status(statusText())
      $.ui.invalidate('ui.render')
    }
    const r = await next(e)
    if (r.deny !== undefined || r.isError) {
      Object.assign(use, { isError: true })
      if (isOpen) {
        $.ui.status(statusText())
        $.ui.invalidate('ui.render')
      }
    }
    return r
  })

  // the context handed back up: a subagent's final answer
  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    completed(
      flow,
      e.agentId,
      { answer: e.answer, reason: e.reason, durationMs: e.durationMs, model: e.usage?.model },
      Date.now(),
    )
    if (!e.agentId) synced(flow, await $.agent.list().catch(() => []))
    if (isOpen) {
      $.ui.status(statusText())
      $.ui.invalidate('ui.render')
    }
    return r
  })

  on('session.measure', async ($, e, next) => {
    const r = await next(e)
    flow.window = e.context.window
    flow.percent = e.context.percent
    const main = flow.nodes.get(MAIN)
    if (main && e.context.tokens !== undefined) main.contextTokens = e.context.tokens
    if (isOpen) {
      $.ui.status(statusText())
      $.ui.invalidate('ui.render')
    }
    return r
  })

  on('ui.close', async ($, e, next) => {
    if (e.id !== PANE) return next(e)
    const r = await next(e)
    isOpen = false
    $.ui.status(undefined)
    return r
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    const r = await next(e)
    const key = e.element
    if (key === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return r
    }
    if (key === 'clear') {
      trimmed(flow, counts(flow).running)
      if (selected && !flow.nodes.has(selected)) selected = undefined
    } else if (key === 'refresh') {
      synced(flow, await $.agent.list().catch(() => []))
    } else if (key.startsWith(KEY)) {
      const id = key.slice(KEY.length)
      selected = selected === id ? undefined : id
    }
    if (selected === MAIN && (key === 'refresh' || key === `${KEY}${MAIN}`)) {
      const usage = await $.session.usage({ breakdown: 'summary', columns }).catch(() => undefined)
      breakdown = usage?.context.breakdown?.categories
    }
    if (isOpen) {
      $.ui.status(statusText())
      $.ui.invalidate('ui.render')
    }
    return r
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(24, e.props.bodyColumns - 1)
    const noop = () => {}
    const main = flow.nodes.get(MAIN)!
    const tree = rows(flow)
    const c = counts(flow)
    const chosen = selected ? flow.nodes.get(selected) : undefined

    const agentRow = (node: FlowNode, prefix: string) => {
      const ctx = node.contextTokens !== undefined ? fmtTokens(node.contextTokens) : ''
      const tools = node.toolCount ? `${node.toolCount}⚒` : ''
      const right = [ctx, tools].filter(Boolean).join(' ')
      const room = width - prefix.length - 2 - (right ? right.length + 1 : 0)
      const name = node.id === MAIN ? 'main' : `${node.type}${node.fork ? ' (fork)' : ''}  ${node.description}`
      return (
        <Box key={`row:${node.id}`} flexDirection="row">
          {prefix ? <Text dimColor>{prefix}</Text> : null}
          <Text color={STATUS_COLOR[node.status]}>{`${STATUS_MARK[node.status]} `}</Text>
          <Button
            key={`${KEY}${node.id}`}
            plain
            dimColor={selected !== node.id && (node.unlisted || node.status !== 'running')}
            label={fit(name, Math.max(4, room))}
            onPress={noop}
          />
          {right ? <Text color="magenta">{` ${right}`}</Text> : null}
        </Box>
      )
    }

    const header = (
      <Box key="head" flexDirection="column">
        <Text bold>{fit(`Session · turn ${flow.turn}`, width)}</Text>
        <Text>
          <Text color="cyan">{'context '}</Text>
          {`${fmtTokens(main.contextTokens)}${flow.window ? `/${fmtTokens(flow.window)}` : ''}`}
          {flow.percent !== undefined ? <Text dimColor>{` ${flow.percent}%`}</Text> : null}
        </Text>
        {flow.percent !== undefined ? (
          <Text color={flow.percent > 80 ? 'red' : flow.percent > 60 ? 'yellow' : 'green'}>
            {bar(flow.percent, Math.min(width, 40))}
          </Text>
        ) : null}
        {main.prompt ? <Text dimColor wrap="truncate-end">{`› ${main.prompt.replace(/\s+/g, ' ')}`}</Text> : null}
      </Box>
    )

    const detail = chosen ? (
      <Box key="detail" flexDirection="column" marginTop={1} borderStyle="round" borderDimColor paddingX={1}>
        {chosen.id === MAIN ? mainDetail(chosen) : agentDetail(chosen)}
      </Box>
    ) : null

    function mainDetail(node: FlowNode) {
      const w = width - 4
      const x = exchanged(node)
      const used = (breakdown ?? []).filter(cat => cat.kind === 'used' && cat.tokens > 0)
      used.sort((a, b) => b.tokens - a.tokens)
      return [
        <Text key="t" bold>{fit(`main loop · ${node.steps} requests · ${node.model ?? ''}`, w)}</Text>,
        <Text key="x" dimColor>
          {fit(`${x.kids} subagents · ↓ ${fmtTokens(x.down)} handed down · ↑ ${fmtTokens(x.up)} back`, w)}
        </Text>,
        <Text key="ch" color="cyan" bold>{'context by category'}</Text>,
        ...(used.length
          ? used.slice(0, 8).map((cat, i) => (
              <Text key={`cat:${i}`}>
                {fit(cat.name, w - 8).padEnd(Math.max(1, w - 8))}
                <Text color="magenta">{fmtTokens(cat.tokens).padStart(7)}</Text>
              </Text>
            ))
          : [<Text key="nb" dimColor>{'press refresh to read the breakdown'}</Text>]),
      ]
    }

    function agentDetail(node: FlowNode) {
      const w = width - 4
      const parent = node.parentId === MAIN ? 'main' : flow.nodes.get(node.parentId ?? '')?.type ?? 'parent'
      const parentCtx = flow.nodes.get(node.parentId ?? MAIN)?.contextTokens
      const meta = [node.model, node.status, fmtDuration(node.durationMs), node.background ? 'background' : '']
      const out = [
        <Text key="t" bold>{fit(`${node.type}  ${node.description}`, w)}</Text>,
        <Text key="m" dimColor>{fit(meta.filter(Boolean).join(' · '), w)}</Text>,
        <Text key="in" color="cyan" bold>
          {fit(
            node.fork
              ? `↓ in from ${parent}: its whole context (~${fmtTokens(parentCtx)}) + ${fmtTokens(estimateTokens(node.prompt))}`
              : node.unlisted
                ? '↓ in: not seen (a loop no Agent call announced)'
                : `↓ in from ${parent}: prompt ${fmtTokens(estimateTokens(node.prompt))} tok`,
            w,
          )}
        </Text>,
        ...excerpt(node.prompt, 4, w - 2).map((l, i) => <Text key={`p:${i}`} dimColor>{`  ${l}`}</Text>),
        <Text key="w" color="yellow" bold>
          {fit(
            `⚙ ${node.steps} requests · ctx ${fmtTokens(node.contextTokens)} (peak ${fmtTokens(node.peakContext)}) · out ${fmtTokens(node.outputTokens)}`,
            w,
          )}
        </Text>,
        ...node.tools.slice(-5).map((u, i) => (
          <Text key={`u:${i}`} color={u.isError ? 'red' : undefined} dimColor={!u.isError}>
            {fit(`  ${u.tool} ${u.label}`, w)}
          </Text>
        )),
        node.toolCount > 5 ? <Text key="more" dimColor>{`  … ${node.toolCount} tool calls in all`}</Text> : null,
        <Text key="o" color="green" bold>
          {fit(
            node.answer !== undefined
              ? `↑ out to ${parent}: answer ${fmtTokens(estimateTokens(node.answer))} tok`
              : `↑ out to ${parent}: still working`,
            w,
          )}
        </Text>,
        ...(node.answer ? excerpt(node.answer, 4, w - 2) : []).map((l, i) => (
          <Text key={`a:${i}`} dimColor>{`  ${l}`}</Text>
        )),
      ]
      const kids = exchanged(node)
      if (kids.kids) {
        out.push(
          <Text key="k" dimColor>
            {fit(`${kids.kids} subagents · ↓ ${fmtTokens(kids.down)} · ↑ ${fmtTokens(kids.up)}`, w)}
          </Text>,
        )
      }
      return out
    }

    return (
      <Box flexDirection="column">
        {header}
        <Box key="ag-head" marginTop={1}>
          <Text bold color="cyan">
            {fit(`Agents (${c.running} running · ${c.done} done${c.failed ? ` · ${c.failed} failed` : ''})`, width)}
          </Text>
        </Box>
        {agentRow(main, '')}
        {tree.map(r => agentRow(r.node, r.prefix))}
        {tree.length === 0 ? <Text dimColor>{fit('  no subagents yet', width)}</Text> : null}
        {detail}
        <Box key="foot" marginTop={1} flexDirection="column">
          <Box key="toolbar" flexDirection="row" columnGap={1}>
            <Button key="refresh" label="refresh" hotkey="r" onPress={noop} />
            <Button key="clear" label="clear" onPress={noop} />
            <Button key="close" label="close" onPress={noop} />
          </Box>
          <Text dimColor>{fit('◐ running ● done ✗ failed ○ stopped · ctx ⚒ tools', width)}</Text>
        </Box>
      </Box>
    )
  })
}

// The agent flow as plain data: the main loop, the subagents it spawned, and
// what context crossed between them. No engine calls here, so the tests drive
// it directly and the pane only reads it.

export const MAIN = 'main'

export type Status = 'running' | 'done' | 'failed' | 'aborted'

export type Usage = {
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

export type ToolUse = { tool: string; label: string; isError?: boolean }

export type FlowNode = {
  /** the loop's agent id; `main` for the main loop */
  id: string
  /** the loop that spawned it; undefined on main */
  parentId?: string
  /** agent type (`Explore`, `general-purpose`, `fork`, ...) */
  type: string
  /** the Agent call's short description */
  description: string
  model?: string
  status: Status
  /** inherits the parent's whole context instead of starting from a prompt */
  fork: boolean
  background: boolean
  /** context handed down: the prompt it was given */
  prompt: string
  /** context handed back up: its final answer */
  answer?: string
  /** input tokens of its latest request: how full its window is now */
  contextTokens?: number
  peakContext?: number
  outputTokens: number
  steps: number
  toolCount: number
  /** the most recent tool calls, newest last */
  tools: ToolUse[]
  startedAt: number
  durationMs?: number
  /** a teammate between turns: drawn as done, but kept by trimming until it ends */
  idle?: boolean
  /** the main-loop turn it was spawned in (1-based) */
  turn: number
  /** a loop the flow saw work but no spawn for (a workflow's agent, an engine fork) */
  unlisted?: boolean
}

export type Flow = {
  nodes: Map<string, FlowNode>
  /** spawn order, main first */
  order: string[]
  turn: number
  /** the main loop's window, from session.measure */
  window?: number
  percent?: number
}

export const KEEP_TOOLS = 8

export function createFlow(now = 0): Flow {
  const main: FlowNode = {
    id: MAIN,
    type: 'main',
    description: 'main loop',
    status: 'done',
    fork: false,
    background: false,
    prompt: '',
    outputTokens: 0,
    steps: 0,
    toolCount: 0,
    tools: [],
    startedAt: now,
    turn: 0,
  }
  return { nodes: new Map([[MAIN, main]]), order: [MAIN], turn: 0 }
}

export const loopId = (agentId: string | undefined) => agentId ?? MAIN

/** Rough tokens of a text: 4 characters each, as the engine's own estimates count. */
export function estimateTokens(text: string | undefined): number {
  return text ? Math.ceil(text.length / 4) : 0
}

/** What a request was answered over: uncached, cache-written and cache-read input together. */
export function contextOf(usage: Usage): number {
  return usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens
}

export function mainTurn(flow: Flow, text: string, now: number): void {
  const main = flow.nodes.get(MAIN)!
  flow.turn += 1
  main.turn = flow.turn
  main.status = 'running'
  main.startedAt = now
  main.durationMs = undefined
  // a continuation carries no typed prompt: keep the one before
  if (text) main.prompt = text
}

export type SpawnFacts = {
  agentId: string
  parentAgentId?: string
  description: string
  subagentType: string
  prompt: string
  fork: boolean
  background: boolean
  model?: string
  /** A resumed subagent or a teammate back from disk (2.1.299): same node, its prompt is a message. */
  resumed?: boolean
}

export function spawned(flow: Flow, s: SpawnFacts, now: number): FlowNode {
  const known = flow.nodes.get(s.agentId)
  const parentId =
    s.resumed && known ? known.parentId : s.parentAgentId && flow.nodes.has(s.parentAgentId) ? s.parentAgentId : MAIN
  const node: FlowNode = {
    ...(known ?? {
      outputTokens: 0,
      steps: 0,
      toolCount: 0,
      tools: [],
      startedAt: now,
    }),
    id: s.agentId,
    parentId,
    type: s.subagentType,
    description: s.description,
    model: s.model ?? known?.model,
    status: s.resumed ? 'running' : (known?.status ?? 'running'),
    // a resumed node is working again: its last answer and duration are no longer current
    ...(s.resumed ? { answer: undefined, durationMs: undefined, idle: undefined } : {}),
    fork: s.fork,
    background: s.background,
    // a resume's prompt is the message that woke it, not its task: keep the task
    // (a node trimmed or never seen keeps only the message, marked as one)
    prompt: s.resumed ? (known ? known.prompt : `(resumed) ${s.prompt}`) : s.prompt,
    turn: flow.turn,
    unlisted: false,
  }
  flow.nodes.set(s.agentId, node)
  if (!known) flow.order.push(s.agentId)
  return node
}

/** The node an event's loop maps to, made on the spot for a loop no spawn announced. */
export function nodeFor(flow: Flow, agentId: string | undefined, now: number): FlowNode {
  const id = loopId(agentId)
  const known = flow.nodes.get(id)
  if (known) return known
  const node: FlowNode = {
    id,
    parentId: MAIN,
    type: 'loop',
    description: `loop ${id.slice(0, 8)}`,
    status: 'running',
    fork: false,
    background: false,
    prompt: '',
    outputTokens: 0,
    steps: 0,
    toolCount: 0,
    tools: [],
    startedAt: now,
    turn: flow.turn,
    unlisted: true,
  }
  flow.nodes.set(id, node)
  flow.order.push(id)
  return node
}

export function stepped(flow: Flow, agentId: string | undefined, usage: Usage | null, now: number): void {
  const node = nodeFor(flow, agentId, now)
  node.steps += 1
  if (node.id !== MAIN && node.status !== 'running') node.status = 'running'
  node.idle = undefined
  if (!usage) return
  const ctx = contextOf(usage)
  node.contextTokens = ctx
  node.peakContext = Math.max(node.peakContext ?? 0, ctx)
  node.outputTokens += usage.output_tokens
}

export function toolRan(flow: Flow, agentId: string | undefined, use: ToolUse, now: number): void {
  const node = nodeFor(flow, agentId, now)
  node.toolCount += 1
  node.tools.push(use)
  if (node.tools.length > KEEP_TOOLS) node.tools.splice(0, node.tools.length - KEEP_TOOLS)
}

export type CompleteFacts = {
  answer: string
  reason: 'answer' | 'aborted' | 'refusal' | 'error'
  durationMs: number
  model?: string
}

export function completed(flow: Flow, agentId: string | undefined, c: CompleteFacts, now: number): void {
  const node = nodeFor(flow, agentId, now)
  node.status = c.reason === 'answer' ? 'done' : c.reason === 'aborted' ? 'aborted' : 'failed'
  node.answer = c.answer
  node.durationMs = c.durationMs
  if (c.model) node.model = c.model
}

/** Folds `$.agent.list()` statuses in: a background agent killed outside our view, a name. */
export function synced(flow: Flow, list: readonly { id: string; status: string; type: string; description: string }[]): void {
  for (const info of list) {
    const node = flow.nodes.get(info.id)
    if (!node) continue
    if (node.unlisted) {
      node.unlisted = false
      node.type = info.type
      node.description = info.description
    }
    if (node.status === 'running') {
      if (info.status === 'completed') node.status = 'done'
      else if (info.status === 'failed') node.status = 'failed'
      else if (info.status === 'killed') node.status = 'aborted'
      // a teammate between turns: its turn is done; the next step it takes marks it running again
      else if (info.status === 'idle') {
        node.status = 'done'
        node.idle = true
      }
    }
  }
}

/** Drops the oldest finished subagents past `max`, and their subtrees with them. */
export function trimmed(flow: Flow, max: number): void {
  const subs = flow.order.filter(id => id !== MAIN)
  let over = subs.length - max
  for (const id of subs) {
    if (over <= 0) break
    if (!flow.nodes.has(id)) continue
    const branch = subtree(flow, id)
    if (branch.some(x => flow.nodes.get(x)?.status === 'running' || flow.nodes.get(x)?.idle)) continue
    for (const gone of branch) {
      flow.nodes.delete(gone)
      flow.order = flow.order.filter(x => x !== gone)
      over -= 1
    }
  }
}

export function children(flow: Flow, id: string): FlowNode[] {
  return flow.order.map(x => flow.nodes.get(x)!).filter(n => n && n.parentId === id)
}

export function subtree(flow: Flow, id: string): string[] {
  return [id, ...children(flow, id).flatMap(c => subtree(flow, c.id))]
}

export type Row = { node: FlowNode; depth: number; prefix: string }

/** The tree in spawn order, depth first, with its box-drawing prefix. */
export function rows(flow: Flow): Row[] {
  const out: Row[] = []
  const walk = (id: string, depth: number, lead: string) => {
    const kids = children(flow, id)
    kids.forEach((kid, i) => {
      const last = i === kids.length - 1
      out.push({ node: kid, depth, prefix: `${lead}${last ? '└─' : '├─'}` })
      walk(kid.id, depth + 1, `${lead}${last ? '  ' : '│ '}`)
    })
  }
  walk(MAIN, 1, '')
  return out
}

export function counts(flow: Flow): { running: number; done: number; failed: number } {
  let running = 0
  let done = 0
  let failed = 0
  for (const n of flow.nodes.values()) {
    if (n.id === MAIN) continue
    if (n.status === 'running') running += 1
    else if (n.status === 'done') done += 1
    else failed += 1
  }
  return { running, done, failed }
}

const str = (v: unknown) => (typeof v === 'string' ? v : '')

/** One line saying what a tool call touched: the command, the path, the pattern. */
export function toolLabel(tool: string, input: Record<string, unknown>): string {
  const pick =
    str(input.description) && tool === 'Agent'
      ? str(input.description)
      : str(input.command) ||
        str(input.file_path) ||
        str(input.path) ||
        str(input.pattern) ||
        str(input.url) ||
        str(input.query) ||
        str(input.prompt) ||
        str(input.description)
  return pick.replace(/\s+/g, ' ').trim()
}

export function fmtTokens(n: number | undefined): string {
  if (n === undefined) return '–'
  if (n < 1000) return String(n)
  if (n < 100_000) return `${(n / 1000).toFixed(1)}k`
  if (n < 1_000_000) return `${Math.round(n / 1000)}k`
  return `${(n / 1_000_000).toFixed(1)}M`
}

export function fmtDuration(ms: number | undefined): string {
  if (ms === undefined) return ''
  if (ms < 1000) return `${ms}ms`
  const s = ms / 1000
  if (s < 60) return `${s.toFixed(1)}s`
  return `${Math.floor(s / 60)}m${String(Math.round(s % 60)).padStart(2, '0')}s`
}

/** `████░░░░` for a percentage, `width` cells. */
export function bar(percent: number | undefined, width: number): string {
  const w = Math.max(1, Math.floor(width))
  const p = Math.min(100, Math.max(0, percent ?? 0))
  const full = Math.round((p / 100) * w)
  return '█'.repeat(full) + '░'.repeat(w - full)
}

/** Cuts `text` to `width` cells with an ellipsis; never below 1. */
export function fit(text: string, width: number): string {
  const w = Math.max(1, Math.floor(width))
  const chars = Array.from(text)
  if (chars.length <= w) return text
  return chars.slice(0, Math.max(0, w - 1)).join('') + '…'
}

/** The first `lines` non-empty lines of `text`, each fitted to `width`; `…` when cut. */
export function excerpt(text: string, lines: number, width: number): string[] {
  const all = text.split('\n').map(l => l.trimEnd()).filter(l => l.trim() !== '')
  const shown = all.slice(0, lines).map(l => fit(l, width))
  if (all.length > lines) shown.push(fit(`… ${all.length - lines} more lines`, width))
  return shown
}

export const STATUS_MARK: Record<Status, string> = { running: '◐', done: '●', failed: '✗', aborted: '○' }

export function paneColumns(value: unknown): number {
  const n = typeof value === 'number' && Number.isFinite(value) ? Math.floor(value) : 52
  return Math.min(120, Math.max(32, n))
}

export function maxAgents(value: unknown): number {
  const n = typeof value === 'number' && Number.isFinite(value) ? Math.floor(value) : 60
  return Math.min(500, Math.max(1, n))
}

