/**
 * turn-inspector — Claude Mod
 *
 * A side pane that draws every model request of the session as a "turn", the
 * way Anthropic's context-window diagram does: each turn's input (system
 * prompt and tools, every earlier turn, what is new) stacked above its output
 * (thinking, text, tool use), and a bar showing how much of the context
 * window it fills. Click a turn (or Tab and Enter) to expand its blocks.
 *
 *   `/turns` opens it · `/turns clear` forgets the turns so far ·
 *   `/turns stop` closes it
 *
 * Totals are the API's own `usage` per request; the split of a total across
 * its blocks is an estimate (about 4 characters a token), marked `~`.
 * It only observes: every hook passes its event on unchanged.
 *
 * Needs Claude Code >= 2.1.287.
 *
 * Options (pluginConfigs["turn-inspector@skills-dir"].options):
 *   columns: number      width asked for the docked pane (default 56)
 *   maxTurns: number     turns kept, oldest dropped first (default 200)
 *   openOnStart: boolean open the pane when the session starts (default false)
 */
import type { Register, RenderChildren, RenderSurface } from 'claude-code'
import {
  barCells,
  cell,
  chunk,
  contextAfter,
  createLedger,
  fit,
  fmtTokens,
  gist,
  inputStack,
  maxTurns,
  paneColumns,
  promptStarted,
  stepEnded,
  stepStarted,
  systemTokens,
  toolAnswered,
} from './turns.ts'
import type { Block, BlockKind, Ledger, Turn } from './turns.ts'

const PANE = 'turn-inspector'
const COMMAND = 'turns'
const KEY = 'turn:'

/** The diagram's palette: input in terracotta, output in grey, thinking near-black. */
const INK = '#f4ece6'
const STYLE: Record<BlockKind, { icon: string; bg: string; fg: string }> = {
  system: { icon: '⚙', bg: '#4a2a1d', fg: '#e8cbb8' },
  history: { icon: '↺', bg: '#6b3d2a', fg: INK },
  user: { icon: '❯', bg: '#9a5a3e', fg: INK },
  tool_result: { icon: '⇠', bg: '#9a5a3e', fg: INK },
  thinking: { icon: '✻', bg: '#151515', fg: '#d6d6d6' },
  text: { icon: '¶', bg: '#5e5e5e', fg: INK },
  tool_use: { icon: '⚒', bg: '#5e5e5e', fg: INK },
  truncated: { icon: '✂', bg: '#2b2b2b', fg: '#9a9a9a' },
}
const INPUT_RAIL = '#c8734f'
const OUTPUT_RAIL = '#8c8c8c'
const BAR = { system: '#4a2a1d', history: '#8a4f37', added: '#d9875f', output: '#9a9a9a', free: '#3a3a3a' }

let ledger: Ledger = createLedger()
let live: Turn | undefined
let isOpen = false
let follow = true
const expanded = new Set<number>()

export const register: Register = (on, options) => {
  const columns = paneColumns(options.columns)
  const keep = maxTurns(options.maxTurns)
  const openOnStart = options.openOnStart === true

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    ledger = createLedger()
    live = undefined
    expanded.clear()
    follow = true
    await $.command
      .register({
        name: COMMAND,
        description: 'Turn-by-turn view of the context window: each request’s input and output blocks (clear|stop)',
        argumentHint: '[clear|stop]',
        immediate: true,
      })
      .catch(err => $.ui.log(`turn-inspector: /${COMMAND} not registered: ${err}`))
    const usage = await $.session.usage().catch(() => undefined)
    if (usage) ledger.window = usage.context.window
    // a fresh session's first request measures what every request carries
    ledger.isFresh = (await $.session.messages().catch(() => [1])).length === 0
    if (openOnStart) {
      isOpen = true
      await $.ui.open({ id: PANE, title: 'turns', columns }).catch(err => {
        isOpen = false
        $.ui.log(`turn-inspector: pane not opened: ${err}`)
      })
    }
    return r
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'stop' || arg === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      isOpen = false
      return { text: 'turn-inspector closed' }
    }
    if (arg === 'clear') {
      const window = ledger.window
      const { system, baseline } = ledger
      ledger = Object.assign(createLedger(), { window, system, baseline })
      live = undefined
      expanded.clear()
      if (isOpen) $.ui.invalidate('ui.render')
      return { text: 'turn-inspector: turns cleared' }
    }
    const usage = await $.session.usage({ breakdown: 'summary', columns }).catch(() => undefined)
    if (usage) {
      ledger.window = usage.context.window
      const system = systemTokens(usage.context.breakdown?.categories ?? [])
      if (system !== undefined) ledger.system = system
    }
    try {
      await $.ui.open({ id: PANE, title: 'turns', focus: true, columns })
    } catch (err) {
      isOpen = false
      return { text: `turn-inspector: pane not opened: ${err}` }
    }
    isOpen = true
    $.ui.invalidate('ui.render')
    const hint = e.presentation.isFullscreen
      ? 'click a turn, or Tab and Enter, to expand it'
      : 'drawn above the prompt; /tui fullscreen docks it beside the transcript'
    return { text: `${ledger.turns.length} turns so far · ${hint} · /${COMMAND} stop closes` }
  })

  on('turn.start', async ($, e, next) => {
    // Since Claude Code 2.1.299 a subagent's or teammate's turn starts here too (its prompt in `e.text`).
    if (e.agentId !== undefined) return next(e)
    promptStarted(ledger, e.turnId, e.text)
    return next(e)
  })

  // a tool's answer is new input for the next request
  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId !== undefined) return r
    const text = r.deny ?? r.text ?? (r.result === undefined ? '' : safeJson(r.result))
    toolAnswered(ledger, e.tool, text.length, r.deny !== undefined || r.isError === true)
    return r
  })

  // each request of the main loop is a turn; its stream gives the output blocks
  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) return yield* next(e)
    const turn = stepStarted(ledger, e.turnId, e.index, e.model, keep)
    live = turn
    if (follow) {
      expanded.clear()
      expanded.add(turn.n)
    }
    if (isOpen) $.ui.invalidate('ui.render')
    const names = new Map<number, string>()
    const stream = next(e)
    for await (const c of stream) {
      let isNew = false
      if (c.kind === 'thinking') isNew = chunk(turn, c.index, 'thinking', c.text)
      else if (c.kind === 'text') isNew = chunk(turn, c.index, 'text', c.text)
      else if (c.kind === 'tool') {
        names.set(c.index, c.name)
        isNew = chunk(turn, c.index, 'tool_use', c.name, c.name)
      } else if (c.kind === 'input') isNew = chunk(turn, c.index, 'tool_use', c.json, names.get(c.index))
      if (isNew && isOpen) $.ui.invalidate('ui.render')
      yield c
    }
    const r = await stream.result
    stepEnded(ledger, turn, r.usage, r.stopReason)
    if (live === turn) live = undefined
    if (isOpen) $.ui.invalidate('ui.render')
    return r
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId === undefined && isOpen) {
      const usage = await $.session.usage({ breakdown: 'summary', columns }).catch(() => undefined)
      const system = systemTokens(usage?.context.breakdown?.categories ?? [])
      if (system !== undefined) ledger.system = system
      if (isOpen) $.ui.invalidate('ui.render')
    }
    return r
  })

  on('session.measure', async ($, e, next) => {
    const r = await next(e)
    if (e.context.window !== ledger.window) {
      ledger.window = e.context.window
      if (isOpen) $.ui.invalidate('ui.render')
    }
    return r
  })

  on('ui.close', async ($, e, next) => {
    if (e.id !== PANE) return next(e)
    const r = await next(e)
    isOpen = false
    return r
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    const r = await next(e)
    const key = e.element
    if (key === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      return r
    }
    if (key === 'follow') {
      follow = !follow
      const last = ledger.turns.at(-1)
      if (follow && last) {
        expanded.clear()
        expanded.add(last.n)
      }
    } else if (key === 'collapse') {
      expanded.clear()
      follow = false
    } else if (key.startsWith(KEY)) {
      const n = Number(key.slice(KEY.length))
      if (expanded.has(n)) {
        expanded.delete(n)
        if (n === ledger.turns.at(-1)?.n) follow = false
      } else expanded.add(n)
    }
    if (isOpen) $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(30, e.props.bodyColumns - 1)
    const sp = spacer(e.surface)
    const noop = () => {}
    const window = ledger.window
    const last = ledger.turns.at(-1)
    const lastDone = [...ledger.turns].reverse().find(t => t.input !== undefined)
    const used = lastDone ? contextAfter(lastDone) : undefined
    const pct = used !== undefined && window ? Math.round((used / window) * 100) : undefined

    /** Bar cells for a turn: system, earlier, new input, output, then free. */
    const turnBar = (t: Turn, w: number, key: string) => {
      if (!window || t.input === undefined) return <Text key={key} color={BAR.free}>{'░'.repeat(w)}</Text>
      const stack = inputStack(ledger, t)
      const sum = (kinds: BlockKind[]) => stack.filter(b => kinds.includes(b.kind)).reduce((s, b) => s + b.tokens, 0)
      const segs = [sum(['system']), sum(['history']), sum(['user', 'tool_result']), t.output ?? 0]
      const cells = barCells(segs, window, w)
      const free = Math.max(0, w - cells.reduce((s, c) => s + c, 0))
      const colors = [BAR.system, BAR.history, BAR.added, BAR.output]
      return (
        <Text key={key}>
          {cells.map((c, i) => (c ? <Text key={`s${i}`} color={colors[i]}>{'█'.repeat(c)}</Text> : null))}
          <Text key="free" color={BAR.free}>{'░'.repeat(free)}</Text>
        </Text>
      )
    }

    const chip = (b: Block, w: number, key: string) => {
      const s = STYLE[b.kind]
      const tok = b.kind === 'truncated' ? '' : `${b.isEstimate ? '~' : ''}${fmtTokens(b.tokens)}`
      const labelW = Math.max(4, w - tok.length - 5)
      const text = ` ${s.icon} ${cell(b.label, labelW)} ${tok.padStart(tok.length)} `
      return (
        <Box key={key} width={w} height={1} flexShrink={0}>
          <Text backgroundColor={s.bg} color={b.isError ? '#ff8f80' : s.fg} italic={b.kind === 'truncated'}>
            {sp(cell(text, w))}
          </Text>
        </Box>
      )
    }

    const section = (title: string, rail: string, blocks: Block[], w: number, key: string) => (
      <Box key={key} flexDirection="column">
        <Text key="t">
          <Text color={rail}>{'┃ '}</Text>
          <Text color={rail} bold>{title}</Text>
        </Text>
        {blocks.map((b, i) => (
          <Box key={`b${i}`} flexDirection="row">
            <Text color={rail}>{sp('┃ ')}</Text>
            {chip(b, w - 2, `c${i}`)}
          </Box>
        ))}
      </Box>
    )

    const detail = (t: Turn) => {
      const w = width - 3
      const stack = inputStack(ledger, t)
      const cached = t.cacheRead ? ` · ${fmtTokens(t.cacheRead)} cached` : ''
      const inTitle = t.input !== undefined ? `INPUT  ${fmtTokens(t.input)}${cached}` : 'INPUT  sending…'
      const outTitle =
        t.status === 'streaming' ? 'OUTPUT  streaming…' : t.output !== undefined ? `OUTPUT  +${fmtTokens(t.output)}` : 'OUTPUT  none'
      const answer = t.answer.length ? t.answer : []
      return (
        <Box key={`d${t.n}`} flexDirection="column" marginLeft={2} marginBottom={1}>
          {section(inTitle, INPUT_RAIL, stack, w, 'in')}
          {section(outTitle, OUTPUT_RAIL, answer, w, 'out')}
          <Text key="meta" dimColor>
            {fit(
              [t.model, t.stopReason ?? '', t.isCompacted ? 'compacted before this turn' : '']
                .filter(Boolean)
                .join(' · '),
              w,
            )}
          </Text>
        </Box>
      )
    }

    const row = (t: Turn) => {
      const isOpenRow = expanded.has(t.n)
      const after = contextAfter(t)
      const right = after !== undefined ? fmtTokens(after) : '…'
      const barW = Math.max(6, Math.min(18, Math.floor(width / 4)))
      const labelW = Math.max(6, width - barW - 15)
      const label = `#${t.n} ${gist(t)}`
      const mark = t.status === 'failed' ? '✗' : isOpenRow ? '▾' : '▸'
      const markColor = t.status === 'failed' ? 'red' : t === live ? 'yellow' : INPUT_RAIL
      return (
        <Box key={`r${t.n}`} flexDirection="row">
          <Text key="m" color={markColor}>{sp(`${mark} `)}</Text>
          <Button
            key={`${KEY}${t.n}`}
            plain
            dimColor={!isOpenRow && t !== live}
            label={sp(cell(label, labelW))}
            onPress={noop}
          />
          <Text key="g">{sp(' ')}</Text>
          {turnBar(t, barW, 'bar')}
          <Text key="n" color="#c9c9c9">{sp(` ${right.padStart(6)}`)}</Text>
        </Box>
      )
    }

    const body: RenderChildren[] = []
    let prompt: string | undefined
    for (const t of ledger.turns) {
      if (t.step === 0 || t.prompt !== prompt) {
        prompt = t.prompt
        body.push(
          <Box key={`p${t.n}`} marginTop={body.length ? 1 : 0}>
            <Text color={INPUT_RAIL} bold wrap="truncate-end">
              {fit(`❯ ${t.prompt ? t.prompt.replace(/\s+/g, ' ') : '(continuation)'}`, width)}
            </Text>
          </Box>,
        )
      }
      body.push(row(t))
      if (expanded.has(t.n)) body.push(detail(t))
    }

    const legend = (
      <Text key="legend">
        <Text color={BAR.system}>{'■'}</Text>
        <Text dimColor>{sp(' system  ')}</Text>
        <Text color={BAR.history}>{'■'}</Text>
        <Text dimColor>{sp(' earlier  ')}</Text>
        <Text color={BAR.added}>{'■'}</Text>
        <Text dimColor>{sp(' new  ')}</Text>
        <Text color={BAR.output}>{'■'}</Text>
        <Text dimColor>{sp(' output')}</Text>
      </Text>
    )

    return (
      <Box flexDirection="column">
        <Text key="h" bold>
          <Text color={INPUT_RAIL}>{'Context window  '}</Text>
          {sp(`${fmtTokens(used)} / ${fmtTokens(window)}`)}
          {pct !== undefined ? <Text color={pct > 80 ? 'red' : pct > 60 ? 'yellow' : 'green'}>{sp(`  ${pct}%`)}</Text> : null}
        </Text>
        {last ? turnBar(lastDone ?? last, width, 'big') : <Text key="big" color={BAR.free}>{'░'.repeat(width)}</Text>}
        {legend}
        <Box key="list" flexDirection="column" marginTop={1}>
          {ledger.turns.length === 0 ? (
            <Text dimColor>{fit('No turns yet: send a prompt and each request shows up here.', width)}</Text>
          ) : (
            body
          )}
        </Box>
        <Box key="foot" marginTop={1} flexDirection="column">
          <Box key="toolbar" flexDirection="row" columnGap={1}>
            <Button key="follow" label={follow ? 'following' : 'follow'} hotkey="f" onPress={noop} />
            <Button key="collapse" label="collapse" onPress={noop} />
            <Button key="close" label="close" onPress={noop} />
          </Box>
          <Text dimColor>{fit('▸ expand a turn · ~ estimated split of a real total', width)}</Text>
        </Box>
      </Box>
    )
  })
}

/** Desktop and the remote surfaces collapse runs of spaces; keep them. */
function spacer(surface: RenderSurface): (s: string) => string {
  return surface === 'terminal' ? s => s : s => s.replace(/ /g, '\u00a0')
}

function safeJson(v: unknown): string {
  try {
    return typeof v === 'string' ? v : (JSON.stringify(v) ?? '')
  } catch {
    return ''
  }
}

/**
 * turn-inspector: the session's model requests ("turns") as plain data.
 *
 * A turn is one request to the model, as in Anthropic's context-window
 * diagram: its input is everything sent (system prompt and tools, every
 * earlier turn, and what is new since the last one: the user's message or
 * the tool results), its output the blocks the model answered with (thinking,
 * text, tool use). Every token total here is the API's own `usage`; only the
 * split of a total across its blocks is estimated (about 4 characters a
 * token), and every such figure is flagged `isEstimate`.
 */

export type BlockKind =
  | 'system'
  | 'history'
  | 'user'
  | 'tool_result'
  | 'thinking'
  | 'text'
  | 'tool_use'
  | 'truncated'

export type Block = {
  kind: BlockKind
  label: string
  tokens: number
  isEstimate: boolean
  isError?: boolean
  /** Characters seen, the basis of an estimate. */
  chars: number
  /** The response's content block it streamed in, for output blocks. */
  index?: number
}

export type TurnStatus = 'streaming' | 'done' | 'failed'

export type Turn = {
  /** 1-based, across the session. */
  n: number
  turnId: string
  /** The request's position inside its prompt's turn, from 0. */
  step: number
  /** The user prompt the request answers ('' for a continuation). */
  prompt: string
  model?: string
  status: TurnStatus
  stopReason?: string | null
  /** Input tokens in all: uncached + cache read + cache write. */
  input?: number
  cacheRead?: number
  cacheWrite?: number
  output?: number
  /** What was new in this request's input (user message, tool results). */
  added: Block[]
  /** The response's blocks, by stream index. */
  answer: Block[]
  /** The input shrank against the turn before: a compaction ran between. */
  isCompacted: boolean
  /** The request carried no conversation before its new input. */
  isFirst: boolean
}

export type Usage = {
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
  model?: string
}

export type Ledger = {
  turns: Turn[]
  /** Blocks that arrived since the last request; the next request carries them. */
  pending: Block[]
  /** The prompt of the turn in progress. */
  prompt: string
  turnId?: string
  /** Context window in tokens, when the engine has said. */
  window?: number
  /** System prompt + tools + memory etc., from the /context breakdown (an estimate). */
  system?: number
  /**
   * The same, measured: the input of a request that carried nothing but the
   * first user message, less that message. Preferred over `system`.
   */
  baseline?: number
  /** The session started with an empty conversation (not resumed). */
  isFresh: boolean
  nextN: number
}

export const CHARS_PER_TOKEN = 4

export function createLedger(): Ledger {
  return { turns: [], pending: [], prompt: '', nextN: 1, isFresh: false }
}

export function estimate(chars: number): number {
  return chars <= 0 ? 0 : Math.max(1, Math.round(chars / CHARS_PER_TOKEN))
}

export function inputTotal(u: Usage): number {
  return u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens
}

function block(kind: BlockKind, label: string, chars: number, isError?: boolean): Block {
  return { kind, label, chars, tokens: estimate(chars), isEstimate: true, ...(isError ? { isError } : {}) }
}

/** A prompt was submitted: its text is the next request's new input. */
export function promptStarted(l: Ledger, turnId: string, text: string): void {
  l.turnId = turnId
  l.prompt = text
  if (text) l.pending.push(block('user', 'User message', text.length))
}

/** A tool answered: its result goes back to the model with the next request. */
export function toolAnswered(l: Ledger, tool: string, chars: number, isError: boolean): void {
  l.pending.push(block('tool_result', `Tool result · ${tool}`, chars, isError))
}

/** A request is about to be sent. */
export function stepStarted(l: Ledger, turnId: string, step: number, model: string, keep: number): Turn {
  if (l.turnId !== turnId) {
    l.turnId = turnId
    if (step === 0) l.prompt = ''
  }
  const turn: Turn = {
    n: l.nextN,
    turnId,
    step,
    prompt: l.prompt,
    model,
    status: 'streaming',
    added: l.pending,
    answer: [],
    isCompacted: false,
    isFirst: l.isFresh && l.nextN === 1 && step === 0 && l.pending.length === 1 && l.pending[0]!.kind === 'user',
  }
  l.nextN += 1
  l.pending = []
  l.turns.push(turn)
  if (l.turns.length > keep) l.turns.splice(0, l.turns.length - keep)
  return turn
}

/** A piece of the response streamed in: grows the block at `index`. */
export function chunk(turn: Turn, index: number, kind: 'thinking' | 'text' | 'tool_use', piece: string, name?: string): boolean {
  let b = turn.answer.find(x => x.index === index)
  const isNew = !b
  if (!b) {
    const label = kind === 'thinking' ? 'Thinking' : kind === 'text' ? 'Text response' : `Tool use · ${name ?? 'tool'}`
    b = { ...block(kind, label, 0), index }
    turn.answer.push(b)
  }
  b.chars += piece.length
  b.tokens = estimate(b.chars)
  return isNew
}

/**
 * The response is whole: record the API's usage, then split the real totals
 * across the blocks.
 *
 * Output: text and tool use keep their character estimate; thinking takes
 * what is left, since the stream shows a summary of it at most. With no
 * thinking block the estimates are scaled to the real total.
 *
 * Input: what is new since the turn before is the real growth (this input
 * less the last input and output), split across the new blocks by size.
 */
export function stepEnded(l: Ledger, turn: Turn, usage: Usage | null, stopReason: string | null): void {
  turn.stopReason = stopReason
  if (!usage) {
    turn.status = 'failed'
    return
  }
  turn.status = 'done'
  if (usage.model) turn.model = usage.model
  turn.input = inputTotal(usage)
  turn.cacheRead = usage.cache_read_input_tokens
  turn.cacheWrite = usage.cache_creation_input_tokens
  turn.output = usage.output_tokens

  const thinking = turn.answer.filter(b => b.kind === 'thinking')
  const rest = turn.answer.filter(b => b.kind !== 'thinking')
  const restSum = rest.reduce((s, b) => s + b.tokens, 0)
  if (thinking.length && restSum <= usage.output_tokens) {
    split(thinking, usage.output_tokens - restSum)
  } else {
    split(turn.answer, usage.output_tokens)
  }
  if (stopReason === 'max_tokens' || stopReason === 'model_context_window_exceeded') {
    const why = stopReason === 'max_tokens' ? 'Cut off: max output tokens' : 'Cut off: context window full'
    turn.answer.push({ kind: 'truncated', label: why, tokens: 0, chars: 0, isEstimate: false })
  }

  if (turn.isFirst) l.baseline = Math.max(0, turn.input - turn.added[0]!.tokens)

  const prev = previous(l, turn)
  if (prev && prev.input !== undefined && prev.output !== undefined) {
    const grown = turn.input - prev.input - prev.output
    if (turn.input < prev.input) turn.isCompacted = true
    else if (grown >= 0 && turn.added.length) split(turn.added, grown)
  }
}

/**
 * What every request carries before the conversation: the /context
 * breakdown's used rows (system prompt, tools, MCP tools, memory files,
 * skills, agents) less its `Messages` row.
 */
export function systemTokens(categories: readonly { name: string; tokens: number; kind: string }[]): number | undefined {
  const used = categories.filter(c => c.kind === 'used' && c.name !== 'Messages')
  return used.length ? used.reduce((s, c) => s + c.tokens, 0) : undefined
}

/** Spreads `total` over `blocks` by their current weights; exact sum. */
function split(blocks: Block[], total: number): void {
  if (!blocks.length) return
  const weights = blocks.map(b => Math.max(1, b.chars))
  const sum = weights.reduce((s, w) => s + w, 0)
  let left = total
  blocks.forEach((b, i) => {
    const t = i === blocks.length - 1 ? left : Math.round((total * weights[i]!) / sum)
    b.tokens = Math.max(0, t)
    left -= b.tokens
  })
}

export function previous(l: Ledger, turn: Turn): Turn | undefined {
  const i = l.turns.indexOf(turn)
  return i > 0 ? l.turns[i - 1] : undefined
}

/**
 * The input stack of a turn as the diagram draws it: system & tools, then
 * every earlier turn folded into one block, then what is new.
 */
export function inputStack(l: Ledger, turn: Turn): Block[] {
  const added = turn.added
  const addedSum = added.reduce((s, b) => s + b.tokens, 0)
  if (turn.input === undefined) return added
  const known = l.baseline ?? l.system
  const system = Math.min(known ?? 0, Math.max(0, turn.input - addedSum))
  const history = Math.max(0, turn.input - system - addedSum)
  const earlier = turn.n - (l.turns[0]?.n ?? turn.n)
  const out: Block[] = []
  if (system) {
    out.push({ kind: 'system', label: 'System, tools & memory', tokens: system, chars: 0, isEstimate: l.baseline === undefined })
  }
  if (history) {
    const label = turn.isCompacted
      ? 'Compacted summary & history'
      : known === undefined
        ? 'System, tools & history'
        : earlier > 0
          ? `Earlier turns (${earlier})`
          : 'Earlier context'
    out.push({ kind: 'history', label, tokens: history, chars: 0, isEstimate: l.baseline === undefined && known !== undefined })
  }
  return [...out, ...added]
}

/** Context in use after a turn: what it sent plus what it answered. */
export function contextAfter(turn: Turn): number | undefined {
  if (turn.input === undefined) return undefined
  return turn.input + (turn.output ?? 0)
}

/** A short summary of what the turn answered with, for its row. */
export function gist(turn: Turn): string {
  if (turn.status === 'streaming') return 'streaming…'
  if (turn.status === 'failed') return 'no response'
  const tools = turn.answer.filter(b => b.kind === 'tool_use')
  if (tools.length) {
    const names = [...new Set(tools.map(b => b.label.replace('Tool use · ', '')))]
    return `${tools.length}× ${names.slice(0, 2).join(', ')}${names.length > 2 ? '…' : ''}`
  }
  if (turn.answer.some(b => b.kind === 'truncated')) return 'cut off'
  if (turn.answer.some(b => b.kind === 'text')) return 'answer'
  return turn.answer.some(b => b.kind === 'thinking') ? 'thinking only' : 'empty'
}

export function fmtTokens(n: number | undefined): string {
  if (n === undefined) return '–'
  if (n < 1000) return String(n)
  if (n < 100_000) return `${(n / 1000).toFixed(1)}k`
  if (n < 1_000_000) return `${Math.round(n / 1000)}k`
  return `${(n / 1_000_000).toFixed(1)}M`
}

/** Cuts `text` to `width` cells with an ellipsis. */
export function fit(text: string, width: number): string {
  const w = Math.max(1, Math.floor(width))
  const chars = Array.from(text)
  if (chars.length <= w) return text
  return chars.slice(0, Math.max(0, w - 1)).join('') + '…'
}

/** `text` cut or padded to exactly `width` cells. */
export function cell(text: string, width: number, align: 'left' | 'right' = 'left'): string {
  const t = fit(text, width)
  const pad = ' '.repeat(Math.max(0, width - Array.from(t).length))
  return align === 'left' ? t + pad : pad + t
}

/**
 * The cells of a context bar: `segments` tokens each, against `window`,
 * `width` cells wide. Every segment that has tokens gets at least one cell
 * while room lasts; the rest of the bar is free space.
 */
export function barCells(segments: number[], window: number, width: number): number[] {
  const w = Math.max(1, Math.floor(width))
  const cells = segments.map(t => (t > 0 && window > 0 ? Math.max(1, Math.round((t / window) * w)) : 0))
  let over = cells.reduce((s, c) => s + c, 0) - w
  for (let i = cells.length - 1; over > 0 && i >= 0; i--) {
    const cut = Math.min(over, Math.max(0, cells[i]! - 1))
    cells[i]! -= cut
    over -= cut
  }
  return cells
}

export function paneColumns(v: unknown): number {
  const n = typeof v === 'number' && Number.isFinite(v) ? Math.round(v) : 56
  return Math.min(120, Math.max(36, n))
}

export function maxTurns(v: unknown): number {
  const n = typeof v === 'number' && Number.isFinite(v) ? Math.round(v) : 200
  return Math.min(2000, Math.max(10, n))
}

// Run with: claude plugin test ui/turn-inspector
import { describe, expect, test } from 'claude-code/testing'
import type { Engine } from 'claude-code/testing'
import type { On } from 'claude-code'
import {
  barCells,
  cell,
  chunk,
  contextAfter,
  createLedger,
  gist,
  inputStack,
  promptStarted,
  stepEnded,
  stepStarted,
  systemTokens,
  toolAnswered,
} from '../hooks/turns.ts'

const usage = (input: number, cached: number, output: number) => ({
  input_tokens: input,
  output_tokens: output,
  cache_read_input_tokens: cached,
  cache_creation_input_tokens: 0,
  model: 'claude-opus-5-5',
})

describe('turns.ts', () => {
  test('a prompt, a tool round trip and an answer make two turns with real totals', () => {
    const l = createLedger()
    l.system = 9000
    promptStarted(l, 't1', 'find the auth bug')
    const one = stepStarted(l, 't1', 0, 'm', 100)
    expect(one.added.map(b => b.kind)).toEqual(['user'])
    chunk(one, 0, 'thinking', 'x'.repeat(40))
    chunk(one, 1, 'text', 'Let me look.')
    chunk(one, 2, 'tool_use', 'Read', 'Read')
    chunk(one, 2, 'tool_use', '{"file_path":"src/auth.ts"}')
    stepEnded(l, one, usage(200, 9000, 300), 'tool_use')
    expect(one.input).toBe(9200)
    expect(one.output).toBe(300)
    // thinking takes what text and tool use do not account for
    const sum = one.answer.reduce((s, b) => s + b.tokens, 0)
    expect(sum).toBe(300)
    expect(one.answer.find(b => b.kind === 'thinking')!.tokens).toBeGreaterThan(250)
    expect(gist(one)).toBe('1× Read')

    toolAnswered(l, 'Read', 4000, false)
    const two = stepStarted(l, 't1', 1, 'm', 100)
    expect(two.prompt).toBe('find the auth bug')
    expect(two.added.map(b => b.kind)).toEqual(['tool_result'])
    chunk(two, 0, 'text', 'Found it.')
    stepEnded(l, two, usage(1100, 9400, 20), 'end_turn')
    // new input is the real growth: 10500 - 9200 - 300
    expect(two.added[0]!.tokens).toBe(1000)
    const stack = inputStack(l, two)
    expect(stack.map(b => b.kind)).toEqual(['system', 'history', 'tool_result'])
    expect(stack.reduce((s, b) => s + b.tokens, 0)).toBe(10_500)
    expect(stack[1]!.label).toBe('Earlier turns (1)')
    expect(contextAfter(two)).toBe(10_520)
    expect(gist(two)).toBe('answer')
  })

  test('truncation, failure and compaction are said, not hidden', () => {
    const l = createLedger()
    promptStarted(l, 't1', 'go')
    const a = stepStarted(l, 't1', 0, 'm', 100)
    chunk(a, 0, 'thinking', 'hmm')
    stepEnded(l, a, usage(100, 50_000, 8000), 'max_tokens')
    expect(a.answer.at(-1)!.kind).toBe('truncated')
    expect(gist(a)).toBe('cut off')
    const b = stepStarted(l, 't1', 1, 'm', 100)
    stepEnded(l, b, null, null)
    expect(b.status).toBe('failed')
    expect(gist(b)).toBe('no response')
    const c = stepStarted(l, 't2', 0, 'm', 100)
    stepEnded(l, c, usage(500, 4000, 10), 'end_turn')
    const d = stepStarted(l, 't2', 1, 'm', 100)
    stepEnded(l, d, usage(100, 1000, 10), 'end_turn')
    expect(d.isCompacted).toBe(true)
  })

  test('the ledger keeps only maxTurns, and helpers size cells exactly', () => {
    const l = createLedger()
    for (let i = 0; i < 15; i++) stepStarted(l, `t${i}`, 0, 'm', 10)
    expect(l.turns.length).toBe(10)
    expect(l.turns[0]!.n).toBe(6)
    expect(barCells([10_000, 50_000, 1000, 500], 200_000, 20)).toEqual([1, 5, 1, 1])
    expect(barCells([300_000, 0, 0, 0], 200_000, 10)).toEqual([10, 0, 0, 0])
    expect(cell('abc', 5)).toBe('abc  ')
    expect(cell('abcdef', 4)).toBe('abc…')
    expect(cell('7', 3, 'right')).toBe('  7')
    expect(
      systemTokens([
        { name: 'System prompt', tokens: 3000, kind: 'used' },
        { name: 'System tools', tokens: 12_000, kind: 'used' },
        { name: 'Messages', tokens: 40_000, kind: 'used' },
        { name: 'Free space', tokens: 100_000, kind: 'free' },
      ]),
    ).toBe(15_000)
  })
})

// The engine beneath the plugin: a model that thinks, calls Read, then answers.
function fakeEngine(on: On) {
  on('turn.step', async function* ($, e) {
    if (e.index === 0) {
      yield { kind: 'thinking' as const, index: 0, text: 'The bug is probably in the token refresh.' }
      yield { kind: 'tool' as const, index: 1, id: 'tu_1', name: 'Read' }
      yield { kind: 'input' as const, index: 1, json: '{"file_path":"src/auth.ts"}' }
      return {
        turnId: e.turnId,
        index: e.index,
        answer: '',
        toolUses: [{ name: 'Read', input: { file_path: 'src/auth.ts' } }],
        stopReason: 'tool_use' as const,
        usage: usage(300, 14_000, 120),
      }
    }
    yield { kind: 'text' as const, index: 0, text: 'The refresh timer never resets.' }
    return {
      turnId: e.turnId,
      index: e.index,
      answer: 'The refresh timer never resets.',
      toolUses: [],
      stopReason: 'end_turn' as const,
      usage: usage(2300, 14_300, 40),
    }
  })
  on('tool.call', async () => ({ result: 'x'.repeat(8000), text: 'x'.repeat(8000) }) as never)
  on('turn.start', async ($, e) => ({ turnId: e.turnId }))
  on('turn.complete', async ($, e) => ({ text: e.answer }))
  on('session.usage', () => ({
    value: {
      startedAt: 0,
      context: {
        window: 200_000,
        breakdown: {
          categories: [
            { name: 'System prompt', tokens: 3000, color: 'x', isDeferred: false, kind: 'used' },
            { name: 'System tools', tokens: 11_000, color: 'x', isDeferred: false, kind: 'used' },
            { name: 'Messages', tokens: 300, color: 'x', isDeferred: false, kind: 'used' },
          ],
        },
      },
      rateLimits: [],
    },
  }) as never)
  on('ui.open', () => ({ value: undefined }))
  on('ui.close', () => ({ value: undefined }))
  on('ui.invalidate', () => ({ value: undefined }))
  on('ui.log', () => ({ value: undefined }))
}

const PANE_PROPS = {
  title: 'turns',
  isFocused: true,
  bodyColumns: 60,
  placement: 'dock' as const,
  scroll: { offset: 0, bodyRows: 60 },
  view: {},
}

async function step($: Engine, index: number) {
  const s = $.turn.step({ turnId: 't1', index, model: 'claude-opus-5-5', messageCount: 1 + index * 2 })
  for (;;) {
    const x = await s.next()
    if (x.done) return x.value
  }
}

describe('the pane', () => {
  for (const surface of ['terminal', 'desktop'] as const) {
    test(`draws each request as a turn and expands its blocks (${surface})`, async ($, on) => {
      fakeEngine(on)
      const opened = await $.command.run({
        command: 'turns',
        args: '',
        origin: { kind: 'composer' },
        presentation: { isFullscreen: true, columns: 200 },
      })
      expect(opened.text).toContain('0 turns so far')

      await $.turn.start({ text: 'why does auth log me out?', turnId: 't1' })
      const first = await step($, 0)
      expect(first?.stopReason).toBe('tool_use')
      await $.tool.call({ tool: 'Read', file_path: 'src/auth.ts' } as never)
      await step($, 1)
      await $.turn.complete({ answer: 'The refresh timer never resets.', durationMs: 4200, isAborted: false, turnId: 't1', reason: 'answer' })

      const ui = await $.ui.mount({ plugin: 'turn-inspector', surface, component: 'Pane', requestId: 'turn-inspector', props: PANE_PROPS })
      const nb = (s: string) => (surface === 'terminal' ? s : s.replace(/ /g, ' '))
      expect((await ui.find({ key: 'turn:1' }))?.text).toContain(nb('#1 1× Read'))
      expect((await ui.find({ key: 'turn:2' }))?.text).toContain(nb('#2 answer'))
      expect(await ui.find({ type: 'Text', text: /why does auth log me out/ })).toBeDefined()
      expect(await ui.find({ type: 'Text', text: /8%/ })).toBeDefined()

      // following: the newest turn is open, with the diagram's stack
      expect(await ui.find({ type: 'Text', text: /INPUT {2}16\.6k · 14\.3k cached/ })).toBeDefined()
      expect(await ui.find({ type: 'Text', text: new RegExp(nb('System, tools & memory')) })).toBeDefined()
      expect(await ui.find({ type: 'Text', text: new RegExp(nb('Earlier turns \\(1\\)')) })).toBeDefined()
      expect(await ui.find({ type: 'Text', text: new RegExp(nb('Tool result · Read')) })).toBeDefined()
      expect(await ui.find({ type: 'Text', text: new RegExp(nb('Text response')) })).toBeDefined()

      await ui.press({ key: 'turn:1' })
      await ui.redraw()
      expect(await ui.find({ type: 'Text', text: new RegExp(nb('User message')) })).toBeDefined()
      expect(await ui.find({ type: 'Text', text: new RegExp(nb('Thinking')) })).toBeDefined()
      expect(await ui.find({ type: 'Text', text: new RegExp(nb('Tool use · Read')) })).toBeDefined()

      await ui.press({ key: 'collapse' })
      await ui.redraw()
      expect(await ui.find({ type: 'Text', text: /INPUT/ })).toBeUndefined()
      await ui.unmount()
    })
  }
})
